function updateDepartureDateTimeInput() {
    const input = document.getElementById('departureDateTimeInput');
    if (!input) return;
    input.value = `${departureDate}T${normalizeHourTime(departureTime)}`;
}

function normalizeDateTimeLocalValue(value) {
    const raw = String(value || '').trim();
    if (!raw) return '';
    const isoLikeMatch = raw.match(/^(\d{4}-\d{2}-\d{2})[T\s](\d{2}:\d{2})(?::\d{2}(?:\.\d+)?)?(?:Z|[+-]\d{2}:?\d{2})?$/);
    if (isoLikeMatch) {
        return `${isoLikeMatch[1]}T${isoLikeMatch[2]}`;
    }

    const parsed = new Date(raw);
    if (Number.isNaN(parsed.getTime())) return '';

    return [
        String(parsed.getFullYear()).padStart(4, '0'),
        String(parsed.getMonth() + 1).padStart(2, '0'),
        String(parsed.getDate()).padStart(2, '0')
    ].join('-') + `T${String(parsed.getHours()).padStart(2, '0')}:${String(parsed.getMinutes()).padStart(2, '0')}`;
}

function parseOptionalCoordinate(value, min, max) {
    if (value === null || value === undefined) return null;
    const raw = String(value).trim();
    if (!raw) return null;
    const numeric = Number(raw);
    if (!Number.isFinite(numeric)) return null;
    if (Number.isFinite(min) && numeric < min) return null;
    if (Number.isFinite(max) && numeric > max) return null;
    return numeric;
}

function parseDateTimeLocalValue(value) {
    const normalized = normalizeDateTimeLocalValue(value);
    if (!normalized) return null;
    const parsed = new Date(normalized);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function formatDateTimeLocalLabel(value) {
    const parsed = value instanceof Date ? value : parseDateTimeLocalValue(value);
    if (!parsed) return t('Non planifié', 'Sin planificar', 'Unscheduled');
    return parsed.toLocaleString(getCurrentLocale(), {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
    });
}

function formatDateTimeLocalInputValue(value) {
    const parsed = value instanceof Date ? value : parseDateTimeLocalValue(value);
    if (!parsed) return '';
    return [
        String(parsed.getFullYear()).padStart(4, '0'),
        String(parsed.getMonth() + 1).padStart(2, '0'),
        String(parsed.getDate()).padStart(2, '0')
    ].join('-') + `T${String(parsed.getHours()).padStart(2, '0')}:${String(parsed.getMinutes()).padStart(2, '0')}`;
}

function formatDateInputValue(value) {
    const normalized = normalizeDateTimeLocalValue(value);
    return normalized ? normalized.slice(0, 10) : '';
}

function formatTimeInputValue(value) {
    const normalized = normalizeDateTimeLocalValue(value);
    return normalized ? normalizeHourTime(normalized.slice(11, 16)) : '08:00';
}

function formatAgendaEventReadableDate(value) {
    const parsed = value instanceof Date ? value : parseDateTimeLocalValue(`${String(value || '').trim()}T00:00`);
    if (!(parsed instanceof Date) || Number.isNaN(parsed.getTime())) return '';
    return parsed.toLocaleDateString(getCurrentLocale(), {
        weekday: 'long',
        day: '2-digit',
        month: 'long'
    });
}

function composeDateTimeLocalValue(dateValue, timeValue) {
    const safeDate = String(dateValue || '').trim();
    if (!safeDate) return '';
    return normalizeDateTimeLocalValue(`${safeDate}T${normalizeHourTime(timeValue || '08:00')}`);
}

function buildAgendaEventTimeSelectOptions(selectedValue) {
    const selectedTime = normalizeHourTime(selectedValue || '08:00');
    const options = [];
    for (let hour = 0; hour < 24; hour += 1) {
        for (let minute = 0; minute < 60; minute += 30) {
            const optionValue = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
            options.push(`<option value="${optionValue}"${optionValue === selectedTime ? ' selected' : ''}>${optionValue}</option>`);
        }
    }
    return options.join('');
}

function sanitizeSharedWithValue(value) {
    return String(value || '')
        .split(',')
        .map(item => item.trim())
        .filter(Boolean)
        .join(', ');
}

function calculateRouteDistanceFromPoints(points) {
    const safePoints = Array.isArray(points) ? points : [];
    let totalDistanceNm = 0;
    for (let index = 0; index < safePoints.length - 1; index += 1) {
        const start = safePoints[index];
        const end = safePoints[index + 1];
        totalDistanceNm += distanceNm(
            Number(start?.lat),
            Number(start?.lon ?? start?.lng),
            Number(end?.lat),
            Number(end?.lon ?? end?.lng)
        );
    }
    return totalDistanceNm;
}

function getDraftRouteDistanceNm() {
    if (Number.isFinite(lastComputedReportData?.metrics?.totalDistanceNm)) {
        return Number(lastComputedReportData.metrics.totalDistanceNm);
    }
    if (routePoints.length > 1) {
        return calculateRouteDistanceFromPoints(routePoints.map(point => ({
            lat: Number(point?.lat),
            lon: Number(point?.lng ?? point?.lon)
        })));
    }
    return null;
}

function getSavedRouteDistanceNm(route) {
    const storedDistance = Number(route?.totalDistanceNm);
    if (Number.isFinite(storedDistance)) return storedDistance;
    const points = Array.isArray(route?.points) ? route.points : [];
    if (points.length < 2) return null;
    return calculateRouteDistanceFromPoints(points);
}

function getSavedRouteStartCoordinates(route) {
    const firstPoint = Array.isArray(route?.points) ? route.points[0] : null;
    const lat = Number(firstPoint?.lat);
    const lng = Number(firstPoint?.lng ?? firstPoint?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    return { lat, lng };
}

function getSavedRouteEndCoordinates(route) {
    const points = Array.isArray(route?.points) ? route.points : [];
    const lastPoint = points.length ? points[points.length - 1] : null;
    const lat = Number(lastPoint?.lat);
    const lng = Number(lastPoint?.lng ?? lastPoint?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    return { lat, lng };
}

function isSavedRouteVisibleInCurrentMapZone(route, bounds) {
    if (!bounds || typeof bounds.contains !== 'function') return true;
    const start = getSavedRouteStartCoordinates(route);
    const end = getSavedRouteEndCoordinates(route);
    return (start && bounds.contains([start.lat, start.lng]))
        || (end && bounds.contains([end.lat, end.lng]));
}

function getSavedRoutesVisibleInCurrentMapZone() {
    if (!map || typeof map.getBounds !== 'function') {
        return getSavedRoutes();
    }

    const visibleBounds = map.getBounds();
    return getSavedRoutes().filter(route => isSavedRouteVisibleInCurrentMapZone(route, visibleBounds));
}

function getVoyagePlanSelectionAnchor(plan) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    const timeline = computeVoyagePlanTimeline(safePlan);
    let previousAnchor = null;

    timeline.forEach(entry => {
        const directAnchor = getVoyageEntryAnchorPoint(entry);
        if (directAnchor) {
            previousAnchor = directAnchor;
        }
    });

    return previousAnchor;
}

function getRouteDistanceToVoyageSelectionAnchor(route, anchor) {
    if (!anchor) return Number.POSITIVE_INFINITY;
    const start = getSavedRouteStartCoordinates(route);
    if (!start) return Number.POSITIVE_INFINITY;
    return distanceNm(anchor.lat, anchor.lng, start.lat, start.lng);
}

function getWaypointDistanceToVoyageSelectionAnchor(entry, anchor) {
    if (!anchor) return Number.POSITIVE_INFINITY;
    const safeEntry = normalizeWaypointPhotoEntry(entry);
    if (!safeEntry) return Number.POSITIVE_INFINITY;
    return distanceNm(anchor.lat, anchor.lng, safeEntry.lat, safeEntry.lng);
}

function getSavedRoutesForVoyagePlanSelection(plan = null, selectedRouteId = '') {
    const allRoutes = getSavedRoutes();
    if (!allRoutes.length) return [];

    const visibleRoutes = getSavedRoutesVisibleInCurrentMapZone();
    const selectedPlan = sanitizeVoyagePlan(plan || {}, 0);
    const selectionAnchor = getVoyagePlanSelectionAnchor(selectedPlan);
    const requiredRouteIds = new Set(
        [String(selectedRouteId || '').trim()]
            .concat((Array.isArray(selectedPlan?.items) ? selectedPlan.items : [])
                .filter(item => item?.type === 'route')
                .map(item => String(item?.routeId || '').trim()))
            .filter(Boolean)
    );

    const nearbyRoutes = selectionAnchor
        ? allRoutes.filter(route => {
            const routeId = String(route?.id || '').trim();
            if (requiredRouteIds.has(routeId)) return true;
            const distanceToAnchorNm = getRouteDistanceToVoyageSelectionAnchor(route, selectionAnchor);
            return Number.isFinite(distanceToAnchorNm) && distanceToAnchorNm <= VOYAGE_ROUTE_SELECTION_RADIUS_NM;
        })
        : [];

    const baseRoutes = nearbyRoutes.length
        ? nearbyRoutes
        : (visibleRoutes.length ? visibleRoutes : allRoutes);
    const mergedRoutes = [...baseRoutes];
    allRoutes.forEach(route => {
        const routeId = String(route?.id || '').trim();
        if (!requiredRouteIds.has(routeId)) return;
        if (mergedRoutes.some(existing => String(existing?.id || '').trim() === routeId)) return;
        mergedRoutes.push(route);
    });

    return mergedRoutes.sort((a, b) => {
        if (selectionAnchor) {
            const distanceA = getRouteDistanceToVoyageSelectionAnchor(a, selectionAnchor);
            const distanceB = getRouteDistanceToVoyageSelectionAnchor(b, selectionAnchor);
            if (Number.isFinite(distanceA) && Number.isFinite(distanceB) && distanceA !== distanceB) {
                return distanceA - distanceB;
            }
            if (Number.isFinite(distanceA) !== Number.isFinite(distanceB)) {
                return Number.isFinite(distanceA) ? -1 : 1;
            }
        }
        return compareSavedRoutesByStartCoordinates(a, b, routesSortOrder);
    });
}

