function getCurrentLoadedSavedRoute() {
    const saved = getSavedRoutes();
    return Number.isInteger(currentLoadedRouteIndex) && currentLoadedRouteIndex >= 0 && currentLoadedRouteIndex < saved.length
        ? saved[currentLoadedRouteIndex]
        : null;
}

function normalizeRoutePointsForLlm(route) {
    return (Array.isArray(route?.points) ? route.points : [])
        .map(point => ({
            lat: Number(point?.lat),
            lon: Number(point?.lon ?? point?.lng)
        }))
        .filter(point => Number.isFinite(point.lat) && Number.isFinite(point.lon));
}

function collectNearbySavedWaypointHighlightsForRoute(route, maxCount = 6, maxDistanceToRouteNm = 8) {
    const routePoints = normalizeRoutePointsForLlm(route);
    if (routePoints.length < 2) return [];

    const sampledRoutePoints = densifyPolylineForWeather(routePoints, 4);
    const candidates = waypointPhotoEntries
        .map(normalizeWaypointPhotoEntry)
        .filter(Boolean)
        .map(entry => {
            let minDistanceToRouteNm = Number.POSITIVE_INFINITY;
            sampledRoutePoints.forEach(routePoint => {
                const dist = distanceNm(routePoint.lat, routePoint.lon, entry.lat, entry.lng);
                if (Number.isFinite(dist) && dist < minDistanceToRouteNm) {
                    minDistanceToRouteNm = dist;
                }
            });

            return {
                id: entry.id,
                placeName: String(entry.placeName || '').trim(),
                lat: Number(entry.lat),
                lng: Number(entry.lng),
                rating: Number(entry.rating),
                depthMeters: Number(entry.depthMeters),
                comment: String(entry.comment || '').trim(),
                protection: formatProtectionList(entry.protection),
                minDistanceToRouteNm
            };
        })
        .filter(entry => Number.isFinite(entry.minDistanceToRouteNm) && entry.minDistanceToRouteNm <= maxDistanceToRouteNm)
        .sort((a, b) => {
            if (a.minDistanceToRouteNm !== b.minDistanceToRouteNm) return a.minDistanceToRouteNm - b.minDistanceToRouteNm;
            return (Number(b.rating) || 0) - (Number(a.rating) || 0);
        });

    const deduped = [];
    const seen = new Set();
    candidates.forEach(entry => {
        const key = `${entry.placeName.toLowerCase()}|${entry.lat.toFixed(4)}|${entry.lng.toFixed(4)}`;
        if (seen.has(key)) return;
        seen.add(key);
        deduped.push(entry);
    });

    return deduped.slice(0, maxCount);
}

async function buildRouteGuideWeatherContext(route) {
    const points = normalizeRoutePointsForLlm(route);
    if (!points.length) return null;

    const departureDateTime = new Date(`${departureDate}T${departureTime}:00`);
    if (Number.isNaN(departureDateTime.getTime())) return null;

    const totalDistance = Number.isFinite(getSavedRouteDistanceNm(route)) ? getSavedRouteDistanceNm(route) : calculateRouteDistanceFromPoints(points);
    const estimatedDurationHours = Math.max(2, Math.min(48, (Number(totalDistance) || 0) / 5.5));
    const arrivalDateTime = new Date(departureDateTime.getTime() + estimatedDurationHours * 60 * 60 * 1000);

    const start = points[0];
    const end = points[points.length - 1];
    const startWeather = await getWeatherAtDateHour(
        start.lat,
        start.lon,
        departureDateTime.toISOString().slice(0, 10),
        `${String(departureDateTime.getHours()).padStart(2, '0')}:00`
    ).catch(() => null);
    const endWeather = await getWeatherAtDateHour(
        end.lat,
        end.lon,
        arrivalDateTime.toISOString().slice(0, 10),
        `${String(arrivalDateTime.getHours()).padStart(2, '0')}:00`
    ).catch(() => null);

    return {
        departureDateTime,
        arrivalDateTime,
        startWeather,
        endWeather,
        estimatedDurationHours
    };
}

function formatRouteGuideWeatherLine(label, weather) {
    if (!weather) return `${label}: ${t('météo indisponible', 'meteo no disponible', 'weather unavailable')}`;
    const wind = Number(weather.windSpeed);
    const gust = Number(weather.windGust);
    const wave = Number(weather.waveHeight);
    const text = [
        Number.isFinite(wind) ? `${t('vent', 'viento', 'wind')} ${wind.toFixed(0)} kn` : '',
        Number.isFinite(gust) ? `${t('rafales', 'rachas', 'gusts')} ${gust.toFixed(0)} kn` : '',
        Number.isFinite(wave) ? `${t('vagues', 'olas', 'waves')} ${wave.toFixed(1)} m` : ''
    ].filter(Boolean).join(' · ');
    return `${label}: ${text || t('météo partielle', 'meteo parcial', 'partial weather')}`;
}

function buildRouteGuidePrompt(route, options = {}) {
    const points = normalizeRoutePointsForLlm(route);
    const totalDistance = Number.isFinite(getSavedRouteDistanceNm(route)) ? getSavedRouteDistanceNm(route) : calculateRouteDistanceFromPoints(points);
    const start = points[0] || null;
    const end = points[points.length - 1] || null;
    const nearbyHighlights = Array.isArray(options.nearbyHighlights) ? options.nearbyHighlights : [];
    const weatherContext = options.weatherContext || null;
    const language = normalizeLanguage(currentLanguage);
    const languageLabel = language === 'es' ? 'espanol' : language === 'en' ? 'english' : 'francais';
    const keyPoints = points.slice(0, 8).map((point, index) => `${index + 1}. ${point.lat.toFixed(4)}, ${point.lon.toFixed(4)}`).join('\n');
    const highlightLines = nearbyHighlights.length
        ? nearbyHighlights.map((entry, index) => {
            const comment = entry.comment ? ` · note: ${entry.comment.slice(0, 120)}` : '';
            const protection = entry.protection ? ` · protection: ${entry.protection}` : '';
            const rating = Number.isFinite(entry.rating) ? ` · note utilisateur: ${entry.rating}/5` : '';
            return `${index + 1}. ${entry.placeName || t('Mouillage', 'Fondeo', 'Anchorage')} · ${entry.minDistanceToRouteNm.toFixed(1)} NM de la route${rating}${protection}${comment}`;
        }).join('\n')
        : t('Aucun mouillage enregistré proche de la route.', 'No hay fondeos guardados cerca de la ruta.', 'No saved anchorages near the route.');

    const weatherLines = weatherContext
        ? [
            formatRouteGuideWeatherLine(t('Départ', 'Salida', 'Departure'), weatherContext.startWeather),
            formatRouteGuideWeatherLine(t('Arrivée estimée', 'Llegada estimada', 'Estimated arrival'), weatherContext.endWeather)
        ].join('\n')
        : t('Contexte météo indisponible.', 'Contexto meteo no disponible.', 'Weather context unavailable.');

    return [
        `Réponds en ${languageLabel}.`,
        'Tu es un copilote de croisière côtière prudent et utile. Tu n\'inventes aucun lieu ni donnée absente du contexte.',
        'Ta mission: guider le skipper sur une route déjà tracée et l\'aider à ne pas louper de beaux endroits.',
        'Retour attendu: texte clair, concret et détaillé, sans markdown lourd, avec 6 sections développées.',
        'Sois plus bavard que d\'habitude: vise environ 12 à 20 phrases utiles, avec du contexte pratique et des recommandations directement exploitables.',
        'Pour chaque section, rédige au moins 2 idées complètes quand le contexte le permet.',
        '1. Résumé de la route',
        '2. Vigilances',
        '3. Beaux arrêts / détours potentiels / lieux immanquables',
        '4. Ajustements conseillés',
        '5. Questions utiles à vérifier avant départ',
        '6. Petit plan de navigation conseillé du départ à l\'arrivée',
        'Quand c\'est pertinent, propose aussi 3 à 7 idées de visite, calas, ports, villages, restaurants marins, balades ou points de vue intéressants dans la zone ou à faible détour.',
        'Si une suggestion vient de ta connaissance générale de la zone plutôt que du contexte fourni, marque-la explicitement comme « à vérifier sur carte / guide nautique ».',
        'Si les données sont insuffisantes, dis-le explicitement sans inventer.',
        '',
        `Nom route: ${String(route?.name || '').trim() || t('Sans nom', 'Sin nombre', 'Unnamed')}`,
        `Distance estimée: ${Number(totalDistance || 0).toFixed(1)} NM`,
        `Nombre de waypoints: ${points.length}`,
        start ? `Départ: ${start.lat.toFixed(4)}, ${start.lon.toFixed(4)}` : '',
        end ? `Arrivée: ${end.lat.toFixed(4)}, ${end.lon.toFixed(4)}` : '',
        '',
        'Points de route principaux:',
        keyPoints || '-',
        '',
        'Météo résumée:',
        weatherLines,
        '',
        'Mouillages / beaux endroits enregistrés proches de la route:',
        highlightLines
    ].filter(Boolean).join('\n');
}

async function requestRouteGuideWithGemini(prompt) {
    const llmSettings = readDocumentRagLlmSettingsFromUi();
    const apiKey = String(llmSettings?.apiKey || '').trim();
    if (!apiKey) {
        throw new Error(t('Clé API Gemini absente (onglet Documents > configuration IA).', 'Falta la clave API de Gemini (pestana Documentos > configuracion IA).', 'Missing Gemini API key (Documents tab > AI configuration).'));
    }

    const requestedModel = String(llmSettings?.model || '').trim();
    const modelCandidates = [requestedModel, 'gemini-2.5-flash', 'gemini-2.5-flash-lite', 'gemini-1.5-flash']
        .map(item => normalizeGeminiModelName(item))
        .filter((item, index, list) => item && list.indexOf(item) === index);
    let payload = null;
    let lastError = '';

    for (let index = 0; index < modelCandidates.length; index += 1) {
        const model = modelCandidates[index];
        const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent?key=${encodeURIComponent(apiKey)}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                contents: [{ role: 'user', parts: [{ text: prompt }] }],
                generationConfig: {
                    temperature: 0.35,
                    maxOutputTokens: 1800
                }
            })
        });

        if (response.ok) {
            payload = await response.json();
            break;
        }

        const body = await response.text();
        const message = `${response.status} ${body}`;
        lastError = message;
        if (!(isGeminiModelUnavailableErrorMessage(message) && index < modelCandidates.length - 1)) {
            throw new Error(message);
        }
    }

    if (!payload) {
        throw new Error(lastError || t('Aucune réponse Gemini.', 'Sin respuesta de Gemini.', 'No Gemini response.'));
    }

    const answer = extractGeminiTextAnswer(payload);
    if (!answer) {
        throw new Error(t('Réponse Gemini vide.', 'Respuesta de Gemini vacia.', 'Empty Gemini response.'));
    }
    return answer;
}

async function requestRouteGuideWithLocalLlm(prompt) {
    const llmSettings = readDocumentRagLlmSettingsFromUi();
    const response = await fetch(`${LOCAL_RAG_API_URL}/query-llm`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            question: prompt,
            top_k: 0,
            language: normalizeLanguage(currentLanguage),
            backend: 'faiss',
            mode: 'local',
            provider: llmSettings.provider,
            response_style: 'detailed',
            max_tokens: 1800,
            model: llmSettings.model || undefined,
            api_key: llmSettings.apiKey || undefined
        })
    });

    if (!response.ok) {
        throw new Error(`${response.status} ${await response.text()}`);
    }

    const payload = await response.json();
    const answer = String(payload?.answer || '').trim();
    if (!answer) {
        throw new Error(t('Réponse IA locale vide.', 'Respuesta IA local vacia.', 'Empty local AI response.'));
    }
    return answer;
}

function buildDeterministicRouteGuide(route, options = {}) {
    const points = normalizeRoutePointsForLlm(route);
    const totalDistance = Number.isFinite(getSavedRouteDistanceNm(route)) ? getSavedRouteDistanceNm(route) : calculateRouteDistanceFromPoints(points);
    const nearbyHighlights = Array.isArray(options.nearbyHighlights) ? options.nearbyHighlights : [];
    const weatherContext = options.weatherContext || null;
    const estimatedDurationHours = Number(weatherContext?.estimatedDurationHours);
    const startWeather = weatherContext?.startWeather || null;
    const endWeather = weatherContext?.endWeather || null;
    const windStart = Number(startWeather?.windSpeed);
    const waveStart = Number(startWeather?.waveHeight);
    const windEnd = Number(endWeather?.windSpeed);
    const waveEnd = Number(endWeather?.waveHeight);

    const summaryLines = [
        t('1. Résumé de la route', '1. Resumen de la ruta', '1. Route summary'),
        `${String(route?.name || '').trim() || t('Route sans nom', 'Ruta sin nombre', 'Unnamed route')} · ${Number(totalDistance || 0).toFixed(1)} NM · ${points.length} WP`
    ];
    if (Number.isFinite(estimatedDurationHours)) {
        summaryLines.push(`${t('Durée estimée', 'Duracion estimada', 'Estimated duration')}: ${formatDurationHours(estimatedDurationHours)}`);
    }

    const vigilanceItems = [];
    if (Number.isFinite(windStart) && windStart >= RECOMMENDED_MAX_WIND_KN) {
        vigilanceItems.push(t(`Départ venté (${windStart.toFixed(0)} kn): vérifier si le créneau de départ peut être décalé.`, `Salida ventosa (${windStart.toFixed(0)} kn): verificar si puede desplazarse la hora de salida.`, `Windy departure (${windStart.toFixed(0)} kn): check whether departure can be delayed.`));
    }
    if (Number.isFinite(windEnd) && windEnd >= RECOMMENDED_MAX_WIND_KN) {
        vigilanceItems.push(t(`Arrivée exposée (${windEnd.toFixed(0)} kn): valider le plan B d'abri.`, `Llegada expuesta (${windEnd.toFixed(0)} kn): validar el plan B de abrigo.`, `Exposed arrival (${windEnd.toFixed(0)} kn): validate your shelter fallback.`));
    }
    if (Number.isFinite(waveStart) && waveStart >= 1.8) {
        vigilanceItems.push(t(`Mer formée au départ (${waveStart.toFixed(1)} m): surveiller le confort équipage.`, `Mar formada en la salida (${waveStart.toFixed(1)} m): vigilar el confort de la tripulacion.`, `Sea state at departure (${waveStart.toFixed(1)} m): monitor crew comfort.`));
    }
    if (Number.isFinite(totalDistance) && totalDistance > 35) {
        vigilanceItems.push(t('Étape assez longue: vérifier ravitaillement, heure réelle d’arrivée et mouillage de repli.', 'Etapa bastante larga: verificar avituallamiento, hora real de llegada y fondeo alternativo.', 'Fairly long leg: verify supplies, real arrival time, and fallback anchorage.'));
    }
    if (!vigilanceItems.length) {
        vigilanceItems.push(t('Pas de point rouge évident avec les données locales actuelles, mais la route mérite une vérification météo avant départ.', 'No se ve un punto rojo evidente con los datos locales actuales, pero la ruta merece una verificacion meteo antes de salir.', 'No obvious red flag from current local data, but the route still deserves a weather check before departure.'));
    }

    const detourItems = nearbyHighlights.length
        ? nearbyHighlights.slice(0, 3).map(entry => {
            const rating = Number.isFinite(entry.rating) ? ` · ${t('note', 'nota', 'rating')} ${entry.rating}/5` : '';
            const protection = entry.protection ? ` · ${entry.protection}` : '';
            return `- ${entry.placeName || t('Mouillage', 'Fondeo', 'Anchorage')} · ${entry.minDistanceToRouteNm.toFixed(1)} NM${rating}${protection}`;
        })
        : [`- ${t('Aucun mouillage enregistré proche de cette route pour le moment.', 'Todavia no hay fondeos guardados cerca de esta ruta.', 'No saved anchorage close to this route yet.')}`];

    const adjustmentItems = [];
    if (nearbyHighlights.length) {
        adjustmentItems.push(t('Si tu veux rendre la route plus “plaisir”, regarde surtout les 1 à 2 premiers mouillages proposés ci-dessous.', 'Si quieres hacer la ruta mas “placer”, mira sobre todo los 1 o 2 primeros fondeos propuestos abajo.', 'If you want a more scenic route, focus first on the first 1 or 2 anchorages suggested below.'));
    }
    if (Number.isFinite(windStart) && windStart >= 16) {
        adjustmentItems.push(t('Revalider le départ 3 h plus tôt ou plus tard pour voir si le vent baisse.', 'Revalidar la salida 3 h antes o despues para ver si baja el viento.', 'Re-check departure 3 hours earlier or later to see if wind eases.'));
    }
    if (Number.isFinite(totalDistance) && totalDistance > 30) {
        adjustmentItems.push(t('Prévoir un arrêt intermédiaire ou un abri de repli à mi-parcours.', 'Prever una parada intermedia o un abrigo alternativo a mitad de trayecto.', 'Plan an intermediate stop or fallback shelter around mid-route.'));
    }
    if (!adjustmentItems.length) {
        adjustmentItems.push(t('La route paraît cohérente telle quelle; l’optimisation utile est surtout dans le choix du meilleur arrêt / beau spot.', 'La ruta parece coherente tal como esta; la optimizacion util es sobre todo elegir la mejor parada / bonito lugar.', 'The route looks coherent as-is; the main optimization is choosing the best stop / scenic spot.'));
    }

    const questionItems = [
        `- ${t('Le mouillage d’arrivée reste-t-il confortable avec le vent et la houle prévus ?', '¿El fondeo de llegada sigue siendo comodo con el viento y la mar previstos?', 'Does the arrival anchorage remain comfortable with the forecast wind and sea state?')}`,
        `- ${t('As-tu un plan B simple si l’arrivée se fait plus tard que prévu ?', '¿Tienes un plan B sencillo si la llegada se retrasa?', 'Do you have a simple fallback if arrival is later than expected?')}`,
        `- ${t('Le plus beau stop proposé vaut-il le petit détour en NM et en horaire ?', '¿Vale la pena el mejor stop propuesto por el pequeno desvio en NM y horario?', 'Is the best suggested stop worth the small detour in NM and timing?')}`
    ];

    return [
        summaryLines.join('\n'),
        '',
        t('2. Vigilances', '2. Vigilancias', '2. Watch-outs'),
        ...vigilanceItems.map(item => `- ${item}`),
        '',
        t('3. Beaux arrêts / détours potentiels', '3. Paradas bonitas / desvíos potenciales', '3. Scenic stops / possible detours'),
        ...detourItems,
        '',
        t('4. Ajustements conseillés', '4. Ajustes aconsejados', '4. Suggested adjustments'),
        ...adjustmentItems.map(item => `- ${item}`),
        '',
        t('5. Questions utiles à vérifier avant départ', '5. Preguntas utiles antes de salir', '5. Useful checks before departure'),
        ...questionItems
    ].join('\n');
}

async function analyzeSelectedRouteWithLlm() {
    const button = document.getElementById('routeLlmGuideBtn');
    const route = getCurrentLoadedSavedRoute();
    if (!route) {
        setRouteLlmGuideStatus(t('Charge d\'abord une route depuis la liste.', 'Carga primero una ruta desde la lista.', 'Load a route from the list first.'), true);
        setRouteLlmGuideAnswer(t('Aucune route active pour l\'analyse.', 'No hay ruta activa para analizar.', 'No active route to analyze.'));
        return;
    }

    if (button) button.disabled = true;
    isRouteGuideDockVisible = true;
    updateMapWorkspaceLayoutState();
    setRouteLlmGuideStatus(t('Analyse IA de la route en cours...', 'Analisis IA de la ruta en curso...', 'AI route guide in progress...'));
    setRouteLlmGuideAnswer(t('Préparation du contexte de navigation...', 'Preparando el contexto de navegacion...', 'Preparing navigation context...'));

    try {
        const { nearbyHighlights, weatherContext, prompt } = await buildRouteGuidePackage(route);
        setRouteGuidePromptText(prompt);
        const llmSettings = readDocumentRagLlmSettingsFromUi();
        const hasGeminiKey = !!String(llmSettings.apiKey || '').trim();
        const requestedMode = String(llmSettings.mode || '').toLowerCase();
        const backends = requestedMode === 'local'
            ? ['local', ...(hasGeminiKey ? ['gemini'] : [])]
            : [...(hasGeminiKey ? ['gemini'] : []), 'local'];

        let answer = '';
        let lastError = '';
        for (const backend of backends) {
            try {
                answer = backend === 'gemini'
                    ? await requestRouteGuideWithGemini(prompt)
                    : await requestRouteGuideWithLocalLlm(prompt);
                if (answer) break;
            } catch (error) {
                lastError = String(error?.message || error || '').trim();
            }
        }

        if (!answer) {
            answer = buildDeterministicRouteGuide(route, { nearbyHighlights, weatherContext });
            const networkFailure = /failed to fetch|networkerror|load failed/i.test(lastError);
            setRouteLlmGuideStatus(
                networkFailure
                    ? t('Guide IA réseau indisponible: version locale simplifiée affichée.', 'Guia IA de red no disponible: se muestra una version local simplificada.', 'Network AI guide unavailable: showing simplified local guide.')
                    : t('Guide IA indisponible: version locale simplifiée affichée.', 'Guia IA no disponible: se muestra una version local simplificada.', 'AI guide unavailable: showing simplified local guide.'),
                true
            );
            setRouteLlmGuideAnswer(answer);
            return;
        }

        setRouteLlmGuideAnswer(answer);
        setRouteLlmGuideStatus(t(`Guide IA prêt pour la route « ${String(route?.name || '').trim() || t('sans nom', 'sin nombre', 'unnamed')} ».`, `Guia IA lista para la ruta « ${String(route?.name || '').trim() || t('sin nombre', 'sin nombre', 'unnamed')} ».`, `AI guide ready for route “${String(route?.name || '').trim() || t('unnamed', 'sin nombre', 'unnamed')}”.`));
    } catch (error) {
        const reason = String(error?.message || error || '').trim();
        const quotaInfo = parseGeminiQuotaErrorDetails(reason);
        if (quotaInfo) {
            setRouteLlmGuideAnswer(t('Quota Gemini dépassé. Vérifie ta facturation ou réessaie plus tard.', 'Cuota Gemini excedida. Revisa tu facturacion o reintenta mas tarde.', 'Gemini quota exceeded. Check billing or retry later.'));
            setRouteLlmGuideStatus(t('Échec du guide IA: quota Gemini atteint.', 'Fallo de la guia IA: cuota Gemini alcanzada.', 'AI guide failed: Gemini quota reached.'), true);
        } else {
            const nearbyHighlights = collectNearbySavedWaypointHighlightsForRoute(route);
            const weatherContext = await buildRouteGuideWeatherContext(route).catch(() => null);
            setRouteLlmGuideAnswer(buildDeterministicRouteGuide(route, { nearbyHighlights, weatherContext }));
            setRouteLlmGuideStatus(t('Guide IA indisponible: version locale simplifiée affichée.', 'Guia IA no disponible: se muestra una version local simplificada.', 'AI guide unavailable: showing simplified local guide.'), true);
        }
    } finally {
        if (button) button.disabled = false;
    }
}

function compareSavedRoutesByStartCoordinates(routeA, routeB, sortOrder = 'asc') {
    const startA = getSavedRouteStartCoordinates(routeA);
    const startB = getSavedRouteStartCoordinates(routeB);
    const direction = sortOrder === 'desc' ? -1 : 1;

    if (startA && startB) {
        if (startA.lat !== startB.lat) {
            return (startA.lat - startB.lat) * direction;
        }
        if (startA.lng !== startB.lng) {
            return (startA.lng - startB.lng) * direction;
        }
    } else if (startA || startB) {
        return startA ? -1 : 1;
    }

    const nameA = String(routeA?.name || '').toLowerCase();
    const nameB = String(routeB?.name || '').toLowerCase();
    return nameA.localeCompare(nameB) * direction;
}

function getRoutePlanningFormValues() {
    return {
        voyageName: String(document.getElementById('voyageNameInput')?.value || '').trim(),
        voyageLeg: String(document.getElementById('voyageLegInput')?.value || '').trim(),
        agendaDepartureDateTime: normalizeDateTimeLocalValue(document.getElementById('voyageDepartureInput')?.value),
        agendaArrivalDateTime: normalizeDateTimeLocalValue(document.getElementById('voyageArrivalInput')?.value),
        sharedWith: sanitizeSharedWithValue(document.getElementById('voyageSharedWithInput')?.value),
        agendaNotes: String(document.getElementById('voyageNotesInput')?.value || '').trim()
    };
}

function applyRoutePlanningForm(route) {
    const safeRoute = route || {};
    const voyageNameInput = document.getElementById('voyageNameInput');
    const voyageLegInput = document.getElementById('voyageLegInput');
    const voyageDepartureInput = document.getElementById('voyageDepartureInput');
    const voyageArrivalInput = document.getElementById('voyageArrivalInput');
    const voyageSharedWithInput = document.getElementById('voyageSharedWithInput');
    const voyageNotesInput = document.getElementById('voyageNotesInput');

    if (voyageNameInput) voyageNameInput.value = String(safeRoute.voyageName || '');
    if (voyageLegInput) voyageLegInput.value = String(safeRoute.voyageLeg || '');
    if (voyageDepartureInput) voyageDepartureInput.value = normalizeDateTimeLocalValue(safeRoute.agendaDepartureDateTime || '');
    if (voyageArrivalInput) voyageArrivalInput.value = normalizeDateTimeLocalValue(safeRoute.agendaArrivalDateTime || '');
    if (voyageSharedWithInput) voyageSharedWithInput.value = String(safeRoute.sharedWith || '');
    if (voyageNotesInput) voyageNotesInput.value = String(safeRoute.agendaNotes || '');
}

function formatSignedDurationHours(totalHours) {
    if (!Number.isFinite(totalHours)) return 'N/A';
    const sign = totalHours < 0 ? '-' : '+';
    return `${sign}${formatDurationHours(Math.abs(totalHours))}`;
}

function computeRoutePlanningSnapshot(route, referenceDateTime = new Date()) {
    const safeRoute = route || {};
    const departure = parseDateTimeLocalValue(safeRoute.agendaDepartureDateTime || '');
    const arrival = parseDateTimeLocalValue(safeRoute.agendaArrivalDateTime || '');
    const distanceNm = getSavedRouteDistanceNm(safeRoute);
    const baselineSpeedKn = getPlanningReferenceSpeedKn();
    const estimatedHours = Number.isFinite(distanceNm)
        ? distanceNm / Math.max(4.5, baselineSpeedKn)
        : null;
    const plannedDurationHours = departure && arrival
        ? Math.max(0, (arrival.getTime() - departure.getTime()) / (60 * 60 * 1000))
        : null;
    const slackHours = Number.isFinite(plannedDurationHours) && Number.isFinite(estimatedHours)
        ? plannedDurationHours - estimatedHours
        : null;
    const recommendedDeparture = arrival && Number.isFinite(estimatedHours)
        ? new Date(arrival.getTime() - estimatedHours * 60 * 60 * 1000)
        : null;
    const deltaToRecommendedDepartureHours = recommendedDeparture
        ? (recommendedDeparture.getTime() - referenceDateTime.getTime()) / (60 * 60 * 1000)
        : null;

    let statusKey = 'idle';
    let statusLabel = t('Agenda libre', 'Agenda libre', 'Open schedule');

    if (recommendedDeparture && Number.isFinite(deltaToRecommendedDepartureHours)) {
        if (deltaToRecommendedDepartureHours < -0.5) {
            statusKey = 'late';
            statusLabel = t('Retard potentiel', 'Retraso potencial', 'Potential delay');
        } else if (deltaToRecommendedDepartureHours <= 12) {
            statusKey = 'warning';
            statusLabel = t('Fenêtre proche', 'Ventana próxima', 'Upcoming window');
        } else {
            statusKey = 'ok';
            statusLabel = t('Marge planning', 'Margen de planning', 'Schedule margin');
        }
    } else if (departure || arrival) {
        statusKey = 'warning';
        statusLabel = t('Agenda partiel', 'Agenda parcial', 'Partial schedule');
    }

    const detailParts = [];
    if (departure) detailParts.push(`${t('Départ', 'Salida', 'Departure')}: ${formatDateTimeLocalLabel(departure)}`);
    if (arrival) detailParts.push(`${t('Arrivée', 'Llegada', 'Arrival')}: ${formatDateTimeLocalLabel(arrival)}`);
    if (Number.isFinite(estimatedHours)) detailParts.push(`${t('Route estimée', 'Ruta estimada', 'Estimated route')}: ${formatDurationHours(estimatedHours)}`);
    if (Number.isFinite(slackHours)) detailParts.push(`${t('Marge', 'Margen', 'Buffer')}: ${formatSignedDurationHours(slackHours)}`);
    if (recommendedDeparture) {
        const leadText = Number.isFinite(deltaToRecommendedDepartureHours)
            ? (deltaToRecommendedDepartureHours < 0
                ? `${t('dépassé de', 'superado por', 'missed by')} ${formatDurationHours(Math.abs(deltaToRecommendedDepartureHours))}`
                : `${t('dans', 'en', 'in')} ${formatDurationHours(deltaToRecommendedDepartureHours)}`)
            : '';
        detailParts.push(`${t('Départ conseillé', 'Salida recomendada', 'Recommended departure')}: ${formatDateTimeLocalLabel(recommendedDeparture)}${leadText ? ` (${leadText})` : ''}`);
    }

    return {
        departure,
        arrival,
        estimatedHours,
        slackHours,
        recommendedDeparture,
        deltaToRecommendedDepartureHours,
        statusKey,
        statusLabel,
        detailLabel: detailParts.join(' · ')
    };
}

function updateVoyagePlanningSummary(routeOverride = null) {
    const summaryNode = document.getElementById('voyagePlanningSummary');
    if (!summaryNode) return;

    const planningValues = getRoutePlanningFormValues();
    const routeDraft = routeOverride || {
        ...planningValues,
        date: departureDate,
        time: departureTime,
        agendaDepartureDateTime: planningValues.agendaDepartureDateTime || `${departureDate}T${normalizeHourTime(departureTime)}`,
        totalDistanceNm: getDraftRouteDistanceNm(),
        points: routePoints.map(point => ({ lat: point.lat, lon: point.lng ?? point.lon }))
    };
    const planning = computeRoutePlanningSnapshot(routeDraft);

    summaryNode.classList.remove('is-late', 'is-warning', 'is-ok');
    if (planning.statusKey === 'late') summaryNode.classList.add('is-late');
    if (planning.statusKey === 'warning') summaryNode.classList.add('is-warning');
    if (planning.statusKey === 'ok') summaryNode.classList.add('is-ok');

    const headerBits = [planning.statusLabel];
    if (routeDraft.voyageName) headerBits.push(String(routeDraft.voyageName));
    if (routeDraft.sharedWith) headerBits.push(`${t('Partagé', 'Compartido', 'Shared')}: ${String(routeDraft.sharedWith)}`);

    summaryNode.textContent = [headerBits.join(' · '), planning.detailLabel]
        .filter(Boolean)
        .join(' — ');
}

function sanitizeVoyagePlanItem(item, fallbackIndex = 0) {
    const type = item?.type === 'stop' ? 'stop' : 'route';
    const waypointLat = type === 'stop' ? parseOptionalCoordinate(item?.waypointLat, -90, 90) : null;
    const waypointLng = type === 'stop' ? parseOptionalCoordinate(item?.waypointLng, -180, 180) : null;
    return {
        id: String(item?.id || generateClientUuid()),
        type,
        routeId: type === 'route' ? String(item?.routeId || '').trim() : '',
        departureDateTime: type === 'route' ? normalizeDateTimeLocalValue(item?.departureDateTime || '') : '',
        startDateTime: type === 'stop' ? normalizeDateTimeLocalValue(item?.startDateTime || '') : '',
        stopDepartureDateTime: type === 'stop' ? normalizeDateTimeLocalValue(item?.stopDepartureDateTime || '') : '',
        stopName: type === 'stop' ? String(item?.stopName || `${t('Mouillage', 'Fondeo', 'Anchorage')} ${fallbackIndex + 1}`).trim() : '',
        durationDays: type === 'stop' ? Math.max(VOYAGE_STOP_MIN_DURATION_DAYS, Number(item?.durationDays || 1) || 1) : 0,
        waypointPhotoId: type === 'stop' ? String(item?.waypointPhotoId || '').trim() : '',
        waypointLat,
        waypointLng,
        notes: String(item?.notes || '').trim()
    };
}

function sanitizeCrewDietaryProfile(profile) {
    const safeDietType = CREW_DIET_TYPES.includes(String(profile?.dietType || '').trim())
        ? String(profile.dietType).trim()
        : 'omnivore';
    return {
        dietType: safeDietType,
        allergiesText: String(profile?.allergiesText || profile?.allergies || '').trim(),
        dislikesText: String(profile?.dislikesText || profile?.dislikes || '').trim(),
        breakfastText: String(profile?.breakfastText || profile?.breakfast || '').trim(),
        galleyNotes: String(profile?.galleyNotes || profile?.notes || '').trim()
    };
}

function normalizeVoyageMealDayType(value) {
    return VOYAGE_MEAL_DAY_TYPES.includes(String(value || '').trim())
        ? String(value).trim()
        : 'navigation';
}

function sanitizeVoyageMealIngredient(entry, fallbackIndex = 0) {
    return {
        id: String(entry?.id || `voyage-meal-ingredient-${Date.now()}-${fallbackIndex}`),
        name: String(entry?.name || '').trim(),
        category: String(entry?.category || 'pantry').trim(),
        unit: String(entry?.unit || 'pieces').trim(),
        quantity: Math.max(0, Number(entry?.quantity || 0) || 0)
    };
}

function sanitizeVoyageMealEntry(entry, fallbackIndex = 0) {
    return {
        id: String(entry?.id || `voyage-meal-${Date.now()}-${fallbackIndex}`),
        date: String(entry?.date || '').trim(),
        dayType: normalizeVoyageMealDayType(entry?.dayType),
        middayTitle: String(entry?.middayTitle || '').trim(),
        middayNotes: String(entry?.middayNotes || '').trim(),
        middayIngredients: Array.isArray(entry?.middayIngredients)
            ? entry.middayIngredients.map((item, index) => sanitizeVoyageMealIngredient(item, index)).filter(item => item.name)
            : [],
        eveningTitle: String(entry?.eveningTitle || '').trim(),
        eveningNotes: String(entry?.eveningNotes || '').trim(),
        eveningIngredients: Array.isArray(entry?.eveningIngredients)
            ? entry.eveningIngredients.map((item, index) => sanitizeVoyageMealIngredient(item, index)).filter(item => item.name)
            : [],
        notes: String(entry?.notes || '').trim()
    };
}

function normalizeVoyageProvisioningScope(value) {
    return VOYAGE_PROVISIONING_SCOPES.includes(String(value || '').trim())
        ? String(value).trim()
        : 'voyage_food';
}

function normalizeVoyageProvisioningStage(value) {
    return VOYAGE_PROVISIONING_STAGES.includes(String(value || '').trim())
        ? String(value).trim()
        : 'predeparture';
}

function sanitizeVoyageProvisioningItem(entry, fallbackIndex = 0) {
    return {
        id: String(entry?.id || `voyage-provisioning-${Date.now()}-${fallbackIndex}`),
        name: String(entry?.name || '').trim(),
        category: String(entry?.category || 'pantry').trim(),
        scope: normalizeVoyageProvisioningScope(entry?.scope),
        quantity: Math.max(0, Number(entry?.quantity || 0) || 0),
        unit: String(entry?.unit || 'pieces').trim(),
        stage: normalizeVoyageProvisioningStage(entry?.stage),
        source: String(entry?.source || 'manual').trim() === 'auto' ? 'auto' : 'manual',
        checked: !!entry?.checked,
        notes: String(entry?.notes || '').trim()
    };
}

function normalizeVoyageBudgetScope(value) {
    return VOYAGE_BUDGET_SCOPES.includes(String(value || '').trim())
        ? String(value).trim()
        : 'voyage_food';
}

function normalizeVoyageBudgetCategory(value) {
    return VOYAGE_BUDGET_CATEGORIES.includes(String(value || '').trim())
        ? String(value).trim()
        : 'other';
}

function sanitizeVoyageBudgetItem(entry, fallbackIndex = 0) {
    const today = new Date().toISOString().slice(0, 10);
    return {
        id: String(entry?.id || `voyage-budget-${Date.now()}-${fallbackIndex}`),
        date: String(entry?.date || today).trim() || today,
        label: String(entry?.label || '').trim(),
        scope: normalizeVoyageBudgetScope(entry?.scope),
        category: normalizeVoyageBudgetCategory(entry?.category),
        amount: Math.max(0, Number(entry?.amount || 0) || 0),
        currency: String(entry?.currency || 'EUR').trim() || 'EUR',
        payer: String(entry?.payer || '').trim(),
        notes: String(entry?.notes || '').trim()
    };
}

function sanitizeVoyageDocumentEntry(entry, fallbackIndex = 0) {
    const nowIso = new Date().toISOString();
    const fileName = String(entry?.fileName || entry?.file_name || '').trim();
    const title = String(entry?.title || fileName || `${t('Document', 'Documento', 'Document')} ${fallbackIndex + 1}`).trim();
    return {
        id: String(entry?.id || generateClientUuid()),
        title,
        fileName,
        mimeType: String(entry?.mimeType || entry?.mime_type || 'application/octet-stream').trim() || 'application/octet-stream',
        sizeBytes: Math.max(0, Number(entry?.sizeBytes || entry?.size_bytes || 0) || 0),
        description: String(entry?.description || '').trim(),
        githubPath: String(entry?.githubPath || entry?.github_path || entry?.path || '').trim().replace(/^\/+/, ''),
        downloadUrl: String(entry?.downloadUrl || entry?.download_url || '').trim(),
        htmlUrl: String(entry?.htmlUrl || entry?.html_url || '').trim(),
        sha: String(entry?.sha || '').trim(),
        createdAt: String(entry?.createdAt || entry?.created_at || nowIso),
        updatedAt: String(entry?.updatedAt || entry?.updated_at || nowIso)
    };
}

function buildVoyageDocumentEntryFromDocumentEntry(entry, fallbackIndex = 0) {
    const safe = sanitizeDocumentEntry(entry, fallbackIndex);
    return sanitizeVoyageDocumentEntry({
        id: safe.id,
        title: safe.title,
        fileName: safe.fileName,
        mimeType: safe.mimeType,
        sizeBytes: safe.sizeBytes,
        description: safe.description,
        githubPath: safe.storagePath,
        downloadUrl: safe.publicUrl,
        sha: safe.externalSha,
        createdAt: safe.createdAt,
        updatedAt: safe.updatedAt
    }, fallbackIndex);
}

function buildDocumentEntryFromVoyageDocument(planId, entry, options = {}) {
    const safe = sanitizeVoyageDocumentEntry(entry, 0);
    return sanitizeDocumentEntry({
        id: safe.id,
        title: safe.title,
        fileName: safe.fileName,
        mimeType: safe.mimeType,
        sizeBytes: safe.sizeBytes,
        category: 'voyage',
        subcategory: 'attachment',
        description: safe.description,
        creatorEmail: options.creatorEmail || getCurrentCloudUserEmail() || '',
        creatorName: options.creatorName || cloudUserProfile?.name || '',
        voyagePlanId: String(planId || '').trim(),
        externalProvider: 'github',
        externalSha: safe.sha,
        storagePath: safe.githubPath,
        publicUrl: safe.downloadUrl || safe.htmlUrl || '',
        createdAt: safe.createdAt,
        updatedAt: safe.updatedAt
    });
}

function getVoyageDocumentEntries(planOrId) {
    const planId = typeof planOrId === 'string'
        ? String(planOrId || '').trim()
        : String(sanitizeVoyagePlan(planOrId || {}, 0).id || '').trim();
    if (!planId) return [];
    const syncedDocuments = documentEntries
        .filter(entry => String(entry?.voyagePlanId || '').trim() === planId)
        .map((entry, index) => buildVoyageDocumentEntryFromDocumentEntry(entry, index));

    return syncedDocuments
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
}

function getVoyageDocumentDraft(planId = '') {
    const safePlanId = String(planId || '').trim();
    if (!safePlanId || voyageDocumentDraft.planId !== safePlanId) {
        return { planId: safePlanId, file: null, title: '', description: '' };
    }
    return {
        planId: safePlanId,
        file: voyageDocumentDraft.file || null,
        title: String(voyageDocumentDraft.title || ''),
        description: String(voyageDocumentDraft.description || '')
    };
}

function setVoyageDocumentDraft(nextDraft) {
    const safePlanId = String(nextDraft?.planId || '').trim();
    voyageDocumentDraft = {
        planId: safePlanId,
        file: nextDraft?.file instanceof File ? nextDraft.file : null,
        title: String(nextDraft?.title || ''),
        description: String(nextDraft?.description || '')
    };
    return getVoyageDocumentDraft(safePlanId);
}

function clearVoyageDocumentDraft(planId = '') {
    const safePlanId = String(planId || '').trim();
    if (!safePlanId || voyageDocumentDraft.planId === safePlanId) {
        voyageDocumentDraft = { planId: '', file: null, title: '', description: '' };
    }
}

function readVoyageDocumentDraftFromDom(planId = '') {
    const safePlanId = String(planId || '').trim();
    const fileInput = document.getElementById('voyageDocumentFileInput');
    const titleInput = document.getElementById('voyageDocumentTitleInput');
    const descriptionInput = document.getElementById('voyageDocumentDescriptionInput');
    const previous = getVoyageDocumentDraft(safePlanId);
    return setVoyageDocumentDraft({
        planId: safePlanId,
        file: fileInput?.files?.[0] || previous.file || null,
        title: String(titleInput?.value || previous.title || ''),
        description: String(descriptionInput?.value || previous.description || '')
    });
}

function applyVoyageDocumentDraftToDom(planId = '') {
    const safePlanId = String(planId || '').trim();
    const draft = getVoyageDocumentDraft(safePlanId);
    if (!safePlanId || draft.planId !== safePlanId) return;

    const titleInput = document.getElementById('voyageDocumentTitleInput');
    const descriptionInput = document.getElementById('voyageDocumentDescriptionInput');
    const fileInput = document.getElementById('voyageDocumentFileInput');

    if (titleInput && !titleInput.value && draft.title) {
        titleInput.value = draft.title;
    }
    if (descriptionInput && !descriptionInput.value && draft.description) {
        descriptionInput.value = draft.description;
    }
    if (fileInput && draft.file instanceof File) {
        try {
            const dataTransfer = new DataTransfer();
            dataTransfer.items.add(draft.file);
            fileInput.files = dataTransfer.files;
        } catch (_error) {
            // Ignore browsers that forbid programmatic file restoration.
        }
    }
}

function renderVoyageDocumentsStatsHtml(planOrId) {
    const documents = getVoyageDocumentEntries(planOrId);
    return `<span>${escapeHtml(t('Documents', 'Documentos', 'Documents'))}: <strong>${documents.length}</strong></span>`;
}

function renderVoyageDocumentsListHtml(planOrId) {
    const safePlan = typeof planOrId === 'string'
        ? sanitizeVoyagePlan(voyagePlans.find(entry => entry.id === String(planOrId || '').trim()) || {}, 0)
        : sanitizeVoyagePlan(planOrId || {}, 0);
    const documents = getVoyageDocumentEntries(safePlan.id);

    return documents.length ? documents.map(entry => `
        <article class="voyage-doc-entry">
            <div>
                <div class="voyage-doc-entry__title">${escapeHtml(entry.title || entry.fileName || t('Document sans titre', 'Documento sin título', 'Untitled document'))}</div>
                <div class="voyage-doc-entry__meta">${escapeHtml(entry.fileName || '')}${entry.sizeBytes ? ` · ${escapeHtml(formatDocumentSize(entry.sizeBytes))}` : ''}${entry.updatedAt ? ` · ${escapeHtml(formatDateTimeLocalLabel(entry.updatedAt))}` : ''}</div>
                ${entry.description ? `<div class="voyage-doc-entry__desc">${escapeHtml(entry.description)}</div>` : ''}
                ${entry.githubPath ? `<div class="voyage-doc-entry__path">${escapeHtml(entry.githubPath)}</div>` : ''}
            </div>
            <div class="voyage-ops-inline-actions">
                <button type="button" data-voyage-document-action="open" data-voyage-plan-id="${escapeHtml(safePlan.id)}" data-voyage-document-id="${escapeHtml(entry.id)}">${escapeHtml(t('Voir', 'Ver', 'View'))}</button>
                <button type="button" data-voyage-document-action="delete" data-voyage-plan-id="${escapeHtml(safePlan.id)}" data-voyage-document-id="${escapeHtml(entry.id)}">${escapeHtml(t('Supprimer', 'Eliminar', 'Delete'))}</button>
            </div>
        </article>
    `).join('') : `<div class="voyage-ops-empty">${escapeHtml(t('Aucun document rattaché à ce voyage.', 'No hay documentos vinculados a este viaje.', 'No documents attached to this trip.'))}</div>`;
}

function refreshVoyageDocumentsSectionDom(planId) {
    const safePlanId = String(planId || '').trim();
    if (!safePlanId) return false;

    const statsNode = document.getElementById(`voyageDocumentsStats-${safePlanId}`);
    const listNode = document.getElementById(`voyageDocumentsList-${safePlanId}`);
    if (!statsNode && !listNode) return false;

    if (statsNode) {
        const countNode = statsNode.querySelector('[data-voyage-doc-stat="count"]');
        if (countNode) {
            countNode.outerHTML = renderVoyageDocumentsStatsHtml(safePlanId);
        } else {
            statsNode.innerHTML = `${renderVoyageDocumentsStatsHtml(safePlanId)}${statsNode.innerHTML}`;
        }
    }
    if (listNode) {
        listNode.innerHTML = renderVoyageDocumentsListHtml(safePlanId);
    }
    return true;
}

function sanitizeCrewMember(entry, fallbackIndex = 0) {
    const firstName = String(entry?.prenom || entry?.firstName || '').trim();
    const lastName = String(entry?.nom || entry?.lastName || '').trim();
    const normalizedEmail = normalizeEmailForCompare(entry?.email || '');
    const nowIso = new Date().toISOString();

    return {
        id: String(entry?.id || generateClientUuid()),
        nom: lastName,
        prenom: firstName,
        email: normalizedEmail,
        telephone: normalizePhoneValue(entry?.telephone || entry?.phone || ''),
        commentaire: String(entry?.commentaire || entry?.comment || '').trim(),
        dietaryProfile: sanitizeCrewDietaryProfile(entry?.dietaryProfile || entry?.dietary_profile || entry?.foodProfile || {}),
        creatorEmail: normalizeEmailForCompare(entry?.creatorEmail || ''),
        creatorName: String(entry?.creatorName || '').trim(),
        createdAt: String(entry?.createdAt || nowIso),
        updatedAt: String(entry?.updatedAt || nowIso),
        sortLabel: `${lastName} ${firstName}`.trim() || normalizedEmail || `${t('Équipier', 'Tripulante', 'Crew member')} ${fallbackIndex + 1}`
    };
}

function getCrewMemberDisplayName(entry) {
    const safeEntry = sanitizeCrewMember(entry || {}, 0);
    const fullName = `${safeEntry.prenom} ${safeEntry.nom}`.trim();
    return fullName || safeEntry.email || t('Équipier sans nom', 'Tripulante sin nombre', 'Unnamed crew member');
}

function formatCrewDietaryProfileLabel(profile) {
    const safeProfile = sanitizeCrewDietaryProfile(profile || {});
    const dietLabels = {
        omnivore: t('Omnivore', 'Omnívoro', 'Omnivore'),
        pescatarian: t('Pescetarien', 'Pescetariano', 'Pescatarian'),
        vegetarian: t('Vegetarien', 'Vegetariano', 'Vegetarian'),
        vegan: t('Vegan', 'Vegano', 'Vegan'),
        glutenfree: t('Sans gluten', 'Sin gluten', 'Gluten free'),
        custom: t('Autre profil', 'Otro perfil', 'Custom profile')
    };
    const parts = [dietLabels[safeProfile.dietType] || dietLabels.omnivore];
    if (safeProfile.allergiesText) parts.push(`${t('Allergies', 'Alergias', 'Allergies')}: ${safeProfile.allergiesText}`);
    if (safeProfile.dislikesText) parts.push(`${t('Evite', 'Evita', 'Avoids')}: ${safeProfile.dislikesText}`);
    return parts.join(' · ');
}

function normalizeVoyagePlanStatus(value) {
    const normalized = String(value || '').trim().toLowerCase();
    if (!normalized) return VOYAGE_PLAN_STATUS_PLANNED;
    if (['planned', 'planifie', 'planifié', 'prevu', 'prévu'].includes(normalized)) {
        return VOYAGE_PLAN_STATUS_PLANNED;
    }
    if (['completed', 'realise', 'réalisé', 'realizado', 'done'].includes(normalized)) {
        return VOYAGE_PLAN_STATUS_COMPLETED;
    }
    if (['cancelled', 'canceled', 'annule', 'annulé', 'cancelado'].includes(normalized)) {
        return VOYAGE_PLAN_STATUS_CANCELLED;
    }
    return VOYAGE_PLAN_STATUS_PLANNED;
}

function getVoyagePlanStatusLabel(status) {
    const normalized = normalizeVoyagePlanStatus(status);
    if (normalized === VOYAGE_PLAN_STATUS_COMPLETED) {
        return t('Réalisé', 'Realizado', 'Completed');
    }
    if (normalized === VOYAGE_PLAN_STATUS_CANCELLED) {
        return t('Annulé', 'Cancelado', 'Cancelled');
    }
    return t('Planifié', 'Planificado', 'Planned');
}

function sanitizeVoyagePlan(plan, fallbackIndex = 0) {
    const nowIso = new Date().toISOString();
    const crewMemberIds = Array.isArray(plan?.crewMemberIds)
        ? Array.from(new Set(plan.crewMemberIds.map(value => String(value || '').trim()).filter(Boolean)))
        : [];
    return {
        id: String(plan?.id || generateClientUuid()),
        name: String(plan?.name || `${t('Voyage', 'Viaje', 'Trip')} ${fallbackIndex + 1}`).trim(),
        description: String(plan?.description || '').trim(),
        status: normalizeVoyagePlanStatus(plan?.status),
        crewMemberIds,
        items: Array.isArray(plan?.items) ? plan.items.map((item, index) => sanitizeVoyagePlanItem(item, index)) : [],
        mealPlan: Array.isArray(plan?.mealPlan || plan?.meal_plan)
            ? (plan.mealPlan || plan.meal_plan).map((entry, index) => sanitizeVoyageMealEntry(entry, index)).filter(entry => entry.date)
            : [],
        provisioningItems: Array.isArray(plan?.provisioningItems || plan?.provisioning_items)
            ? (plan.provisioningItems || plan.provisioning_items).map((entry, index) => sanitizeVoyageProvisioningItem(entry, index)).filter(entry => entry.name)
            : [],
        budgetItems: Array.isArray(plan?.budgetItems || plan?.budget_items)
            ? (plan.budgetItems || plan.budget_items).map((entry, index) => sanitizeVoyageBudgetItem(entry, index)).filter(entry => entry.label || entry.amount > 0)
            : [],
        createdAt: String(plan?.createdAt || nowIso),
        updatedAt: String(plan?.updatedAt || nowIso)
    };
}

function getDefaultAgendaEventDraft() {
    const startDate = snapDateTimeToAgendaSlot(new Date(Date.now() + agendaEventDefaultDurationMs)) || new Date();
    const endDate = new Date(startDate.getTime() + agendaEventDefaultDurationMs);
    return {
        id: '',
        title: '',
        startDateTime: formatDateTimeLocalInputValue(startDate),
        endDateTime: formatDateTimeLocalInputValue(endDate),
        comment: ''
    };
}

function sanitizeAgendaEvent(event, fallbackIndex = 0) {
    const nowIso = new Date().toISOString();
    const defaultDraft = getDefaultAgendaEventDraft();
    const parsedStart = parseDateTimeLocalValue(event?.startDateTime || defaultDraft.startDateTime) || parseDateTimeLocalValue(defaultDraft.startDateTime) || new Date();
    const parsedEndSource = parseDateTimeLocalValue(event?.endDateTime || defaultDraft.endDateTime);
    const parsedEnd = parsedEndSource && parsedEndSource.getTime() > parsedStart.getTime()
        ? parsedEndSource
        : new Date(parsedStart.getTime() + agendaEventDefaultDurationMs);
    return {
        id: String(event?.id || generateClientUuid()),
        title: String(event?.title || `${t('Évènement', 'Evento', 'Event')} ${fallbackIndex + 1}`).trim(),
        startDateTime: formatDateTimeLocalInputValue(parsedStart),
        endDateTime: formatDateTimeLocalInputValue(parsedEnd),
        comment: String(event?.comment || '').trim(),
        createdAt: String(event?.createdAt || nowIso),
        updatedAt: String(event?.updatedAt || nowIso)
    };
}

function loadAgendaEvents() {
    try {
        agendaEvents = loadArrayFromStorage(AGENDA_EVENTS_STORAGE_KEY)
            .map((entry, index) => sanitizeAgendaEvent(entry, index))
            .sort((a, b) => String(a.startDateTime).localeCompare(String(b.startDateTime)));
    } catch (_error) {
        agendaEvents = [];
    }
    if (!selectedAgendaEventId || !agendaEvents.some(entry => entry.id === selectedAgendaEventId)) {
        selectedAgendaEventId = '';
    }
}

function normalizeAgendaEventDefaultDurationMs(value) {
    const parsed = Number(value);
    return AGENDA_EVENT_DURATION_OPTIONS_MS.includes(parsed)
        ? parsed
        : AGENDA_EVENT_DEFAULT_DURATION_MS;
}

function loadAgendaEventPreferences() {
    try {
        agendaEventDefaultDurationMs = normalizeAgendaEventDefaultDurationMs(localStorage.getItem(AGENDA_EVENT_DEFAULT_DURATION_STORAGE_KEY));
    } catch (_error) {
        agendaEventDefaultDurationMs = AGENDA_EVENT_DEFAULT_DURATION_MS;
    }
}

function setAgendaEventDefaultDurationMs(value, { persistLocal = true } = {}) {
    agendaEventDefaultDurationMs = normalizeAgendaEventDefaultDurationMs(value);
    if (!persistLocal) return;
    try {
        localStorage.setItem(AGENDA_EVENT_DEFAULT_DURATION_STORAGE_KEY, String(agendaEventDefaultDurationMs));
    } catch (_error) {
        // Ignore local persistence errors for this UI preference.
    }
}

function focusAgendaEventTitleInput() {
    requestAnimationFrame(() => {
        const titleInput = document.getElementById('agendaEventTitleInput');
        if (!(titleInput instanceof HTMLInputElement)) return;
        titleInput.focus();
        titleInput.select();
    });
}

function clearAgendaEventCalendarPrefillTimer() {
    if (!agendaEventCalendarPrefillTimer) return;
    clearTimeout(agendaEventCalendarPrefillTimer);
    agendaEventCalendarPrefillTimer = null;
}

function setAgendaEvents(list, { persistLocal = true, markCloudDirty = false } = {}) {
    agendaEvents = (Array.isArray(list) ? list : [])
        .map((entry, index) => sanitizeAgendaEvent(entry, index))
        .sort((a, b) => String(a.startDateTime).localeCompare(String(b.startDateTime)));
    if (!selectedAgendaEventId || !agendaEvents.some(entry => entry.id === selectedAgendaEventId)) {
        selectedAgendaEventId = '';
    }
    if (persistLocal) {
        saveArrayToStorage(AGENDA_EVENTS_STORAGE_KEY, agendaEvents);
    }
    if (markCloudDirty) {
        agendaEventsCloudDirty = true;
        agendaEventsCloudRevision += 1;
        tryFlushPendingCloudDataPush();
    }
}

function getSelectedAgendaEvent() {
    return agendaEvents.find(entry => entry.id === selectedAgendaEventId) || null;
}

function clearAgendaEventDraft() {
    agendaEventDraftState = null;
}

function getAgendaEventEditorState() {
    if (agendaEventDraftState) {
        return {
            ...getDefaultAgendaEventDraft(),
            ...agendaEventDraftState
        };
    }
    const selected = getSelectedAgendaEvent();
    if (selected) {
        return {
            id: selected.id,
            title: selected.title,
            startDateTime: selected.startDateTime,
            endDateTime: selected.endDateTime,
            comment: selected.comment
        };
    }
    return getDefaultAgendaEventDraft();
}

function setAgendaEventStatus(message, isError = false) {
    agendaEventStatusState = {
        message: String(message || ''),
        isError: !!isError
    };
    const node = document.getElementById('agendaEventStatus');
    if (!node) return;
    node.textContent = agendaEventStatusState.message;
    node.classList.toggle('is-late', agendaEventStatusState.isError);
    node.classList.toggle('is-ok', !!agendaEventStatusState.message && !agendaEventStatusState.isError);
}

function readAgendaEventEditorDraftFromDom() {
    const startDateValue = String(document.getElementById('agendaEventStartDateInput')?.value || '').trim();
    const startTimeValue = String(document.getElementById('agendaEventStartTimeInput')?.value || '').trim();
    const endDateValue = String(document.getElementById('agendaEventEndDateInput')?.value || '').trim();
    const endTimeValue = String(document.getElementById('agendaEventEndTimeInput')?.value || '').trim();
    return {
        id: String(selectedAgendaEventId || ''),
        title: String(document.getElementById('agendaEventTitleInput')?.value || '').trim(),
        startDateTime: composeDateTimeLocalValue(startDateValue, startTimeValue),
        endDateTime: composeDateTimeLocalValue(endDateValue, endTimeValue),
        comment: String(document.getElementById('agendaEventCommentInput')?.value || '').trim()
    };
}

function getAgendaEventDurationMsFromDraft(draft) {
    const startDate = parseDateTimeLocalValue(draft?.startDateTime || '');
    const endDate = parseDateTimeLocalValue(draft?.endDateTime || '');
    if (startDate instanceof Date && endDate instanceof Date && endDate > startDate) {
        return endDate.getTime() - startDate.getTime();
    }
    return agendaEventDefaultDurationMs;
}

function setAgendaEventEditorDateTimeInputs(prefix, value) {
    const date = value instanceof Date ? value : parseDateTimeLocalValue(value);
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return false;
    const dateInput = document.getElementById(`agendaEvent${prefix}DateInput`);
    const timeInput = document.getElementById(`agendaEvent${prefix}TimeInput`);
    if (!dateInput || !timeInput) return false;
    dateInput.value = formatDateInputValue(date);
    timeInput.value = formatTimeInputValue(date);
    return true;
}

function syncAgendaEventEndWithStartEditor() {
    const previousDraft = getAgendaEventEditorState();
    const durationMs = Math.max(VOYAGE_AGENDA_TIME_STEP_MINUTES * 60 * 1000, getAgendaEventDurationMsFromDraft(previousDraft));
    const currentDraft = readAgendaEventEditorDraftFromDom();
    const startDate = parseDateTimeLocalValue(currentDraft.startDateTime);
    if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime())) return false;
    return setAgendaEventEditorDateTimeInputs('End', new Date(startDate.getTime() + durationMs));
}

function shiftAgendaEventEditorDateTime(prefix, deltaMinutes) {
    const draft = readAgendaEventEditorDraftFromDom();
    const key = prefix === 'Start' ? 'startDateTime' : 'endDateTime';
    const baseDate = parseDateTimeLocalValue(draft[key] || '');
    if (!(baseDate instanceof Date) || Number.isNaN(baseDate.getTime())) return false;

    const nextDate = new Date(baseDate.getTime() + Number(deltaMinutes || 0) * 60 * 1000);
    if (!setAgendaEventEditorDateTimeInputs(prefix, nextDate)) return false;
    if (prefix === 'Start') {
        syncAgendaEventEndWithStartEditor();
    }
    agendaEventDraftState = readAgendaEventEditorDraftFromDom();
    return true;
}

function upsertAgendaEventFromEditor() {
    const draft = readAgendaEventEditorDraftFromDom();
    if (!draft.title) {
        setAgendaEventStatus(t('L’intitulé de l’évènement est obligatoire.', 'El título del evento es obligatorio.', 'Event title is required.'), true);
        return false;
    }
    const startDate = parseDateTimeLocalValue(draft.startDateTime || '');
    const endDate = parseDateTimeLocalValue(draft.endDateTime || '');
    if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime()) || !(endDate instanceof Date) || Number.isNaN(endDate.getTime())) {
        setAgendaEventStatus(t('Renseigne une date de début et de fin valides.', 'Introduce fechas de inicio y fin válidas.', 'Enter valid start and end dates.'), true);
        return false;
    }
    if (endDate.getTime() <= startDate.getTime()) {
        setAgendaEventStatus(t('La fin doit être après le début.', 'La fecha de fin debe ser posterior al inicio.', 'End time must be after start time.'), true);
        return false;
    }

    const existing = getSelectedAgendaEvent();
    const nextEvent = sanitizeAgendaEvent({
        id: existing?.id || generateClientUuid(),
        title: draft.title,
        startDateTime: draft.startDateTime,
        endDateTime: draft.endDateTime,
        comment: draft.comment,
        createdAt: existing?.createdAt,
        updatedAt: new Date().toISOString()
    });
    const nextList = existing
        ? agendaEvents.map(entry => (entry.id === existing.id ? nextEvent : entry))
        : agendaEvents.concat(nextEvent);
    setAgendaEvents(nextList, { markCloudDirty: true });
    selectedAgendaEventId = nextEvent.id;
    clearAgendaEventDraft();
    renderVoyageAgendaPanel();
    setAgendaEventStatus(t('Évènement enregistré.', 'Evento guardado.', 'Event saved.'));
    return true;
}

function resetAgendaEventEditor() {
    selectedAgendaEventId = '';
    agendaEventDraftState = getDefaultAgendaEventDraft();
    renderVoyageAgendaPanel();
    setAgendaEventStatus(t('Nouvel évènement prêt.', 'Nuevo evento listo.', 'New event ready.'));
}

function prefillAgendaEventDraftFromDate(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return false;
    const startDate = snapDateTimeToAgendaSlot(date) || date;
    const nextEnd = new Date(startDate.getTime() + agendaEventDefaultDurationMs);

    selectedAgendaEventId = '';
    agendaEventDraftState = {
        id: '',
        title: '',
        startDateTime: formatDateTimeLocalInputValue(startDate),
        endDateTime: formatDateTimeLocalInputValue(nextEnd),
        comment: ''
    };
    renderVoyageAgendaPanel();
    setAgendaEventStatus(t('Date reprise depuis le calendrier. Complète l’intitulé puis enregistre.', 'Fecha recuperada del calendario. Completa el título y guarda.', 'Date taken from the calendar. Add a title, then save.'));
    return true;
}

function createAgendaEventFromDate(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return false;
    const startDate = snapDateTimeToAgendaSlot(date) || date;
    const endDate = new Date(startDate.getTime() + agendaEventDefaultDurationMs);
    const nextEvent = sanitizeAgendaEvent({
        id: generateClientUuid(),
        title: '',
        startDateTime: formatDateTimeLocalInputValue(startDate),
        endDateTime: formatDateTimeLocalInputValue(endDate),
        comment: '',
        updatedAt: new Date().toISOString()
    }, agendaEvents.length);
    setAgendaEvents(agendaEvents.concat(nextEvent), { markCloudDirty: true });
    selectedAgendaEventId = nextEvent.id;
    clearAgendaEventDraft();
    renderVoyageAgendaPanel();
    focusAgendaEventTitleInput();
    setAgendaEventStatus(t('Évènement créé. Tu peux maintenant le renommer ou le compléter.', 'Evento creado. Ahora puedes renombrarlo o completarlo.', 'Event created. You can now rename it or complete it.'));
    return true;
}

function deleteSelectedAgendaEvent() {
    const selected = getSelectedAgendaEvent();
    if (!selected) {
        setAgendaEventStatus(t('Aucun évènement sélectionné.', 'Ningún evento seleccionado.', 'No event selected.'), true);
        return false;
    }
    setAgendaEvents(agendaEvents.filter(entry => entry.id !== selected.id), { markCloudDirty: true });
    selectedAgendaEventId = '';
    agendaEventDraftState = getDefaultAgendaEventDraft();
    renderVoyageAgendaPanel();
    setAgendaEventStatus(t('Évènement supprimé.', 'Evento eliminado.', 'Event deleted.'));
    return true;
}

function updateAgendaEventTiming(eventId, startDate, endDate) {
    if (!eventId || !(startDate instanceof Date) || Number.isNaN(startDate.getTime()) || !(endDate instanceof Date) || Number.isNaN(endDate.getTime()) || endDate <= startDate) {
        return false;
    }
    const nextList = agendaEvents.map(entry => {
        if (entry.id !== eventId) return entry;
        return sanitizeAgendaEvent({
            ...entry,
            startDateTime: formatDateTimeLocalInputValue(startDate),
            endDateTime: formatDateTimeLocalInputValue(endDate),
            updatedAt: new Date().toISOString()
        });
    });
    setAgendaEvents(nextList, { markCloudDirty: true });
    return true;
}

function loadCrewDirectory() {
    try {
        crewDirectory = loadArrayFromStorage(CREW_DIRECTORY_STORAGE_KEY)
            .map((entry, index) => sanitizeCrewMember(entry, index))
            .sort((a, b) => a.sortLabel.localeCompare(b.sortLabel));
    } catch (_error) {
        crewDirectory = [];
    }

    if (isCrewEditorDraftActive() && !selectedCrewMemberId) {
        return;
    }

    if (!selectedCrewMemberId || !crewDirectory.some(entry => entry.id === selectedCrewMemberId)) {
        selectedCrewMemberId = String(crewDirectory[0]?.id || '');
    }
}

function setCrewDirectory(list, { persistLocal = true, markCloudDirty = false } = {}) {
    crewDirectory = (Array.isArray(list) ? list : [])
        .map((entry, index) => sanitizeCrewMember(entry, index))
        .sort((a, b) => a.sortLabel.localeCompare(b.sortLabel));

    if (isCrewEditorDraftActive() && !selectedCrewMemberId) {
        // Preserve new-member draft mode during background refreshes.
    } else if (!selectedCrewMemberId || !crewDirectory.some(entry => entry.id === selectedCrewMemberId)) {
        selectedCrewMemberId = String(crewDirectory[0]?.id || '');
    }

    if (persistLocal) {
        saveArrayToStorage(CREW_DIRECTORY_STORAGE_KEY, crewDirectory);
    }
    if (markCloudDirty) {
        crewDirectoryCloudDirty = true;
        crewDirectoryCloudRevision += 1;
        tryFlushPendingCloudDataPush();
    }
}

function getSelectedCrewMember() {
    return crewDirectory.find(entry => entry.id === selectedCrewMemberId) || null;
}

function loadVoyagePlans() {
    try {
        voyagePlans = loadArrayFromStorage(VOYAGE_PLANS_STORAGE_KEY).map((plan, index) => normalizeVoyagePlanScheduleOverrides(plan, index));
    } catch (_error) {
        voyagePlans = [];
    }
    if (isVoyagePlanEditorDraftActive() && !selectedVoyagePlanId) {
        return;
    }
    if (!selectedVoyagePlanId || !voyagePlans.some(plan => plan.id === selectedVoyagePlanId)) {
        selectedVoyagePlanId = String(voyagePlans[0]?.id || '');
    }
}

function setVoyagePlans(list, { persistLocal = true, markCloudDirty = false } = {}) {
    voyagePlans = (Array.isArray(list) ? list : []).map((plan, index) => normalizeVoyagePlanScheduleOverrides(plan, index));
    if (isVoyagePlanEditorDraftActive() && !selectedVoyagePlanId) {
        // Preserve new-trip draft mode during background refreshes.
    } else if (!selectedVoyagePlanId || !voyagePlans.some(plan => plan.id === selectedVoyagePlanId)) {
        selectedVoyagePlanId = String(voyagePlans[0]?.id || '');
    }
    if (persistLocal) {
        saveArrayToStorage(VOYAGE_PLANS_STORAGE_KEY, voyagePlans);
    }
    if (markCloudDirty) {
        voyagePlansCloudDirty = true;
        voyagePlansCloudRevision += 1;
        tryFlushPendingCloudDataPush();
    }
}

function getSelectedVoyagePlan() {
    return voyagePlans.find(plan => plan.id === selectedVoyagePlanId) || null;
}

function setVoyagePlanStatus(message, isError = false) {
    const node = document.getElementById('voyagePlanStatus');
    if (!node) return;
    node.textContent = String(message || '');
    node.classList.toggle('is-late', !!isError);
    node.classList.toggle('is-ok', !isError && !!message);
}

function clearVoyagePlanEditorDraft() {
    voyagePlanEditorDraftState = null;
}

function isVoyagePlanEditorDraftActive() {
    return !!voyagePlanEditorDraftState;
}

function captureVoyagePlanEditorDraftFromInputs() {
    const name = String(document.getElementById('voyagePlanNameInput')?.value || '').trim();
    const description = String(document.getElementById('voyagePlanDescriptionInput')?.value || '').trim();
    const status = normalizeVoyagePlanStatus(document.getElementById('voyagePlanStatusInput')?.value || '');
    if (!name && !description && status === VOYAGE_PLAN_STATUS_PLANNED) {
        voyagePlanEditorDraftState = null;
        return;
    }
    voyagePlanEditorDraftState = {
        values: {
            name,
            description,
            status
        }
    };
}

function setVoyageCrewStatus(message, isError = false) {
    const node = document.getElementById('voyageCrewStatus');
    if (!node) return;
    node.textContent = String(message || '');
    node.classList.toggle('is-late', !!isError);
    node.classList.toggle('is-ok', !isError && !!message);
}

function clearCrewEditorDraft() {
    crewEditorDraftState = null;
}

function isCrewEditorDraftActive() {
    return !!crewEditorDraftState;
}

function isVoyageCrewEditorFocused() {
    const panel = document.getElementById('voyageAgendaPanel');
    const activeElement = document.activeElement;
    if (!panel || !activeElement) return false;
    if (!(activeElement instanceof HTMLElement)) return false;
    return panel.contains(activeElement) && (
        activeElement.id === 'voyageCrewDirectorySelectInput'
        || activeElement.id === 'voyageCrewFirstNameInput'
        || activeElement.id === 'voyageCrewLastNameInput'
        || activeElement.id === 'voyageCrewEmailInput'
        || activeElement.id === 'voyageCrewPhoneInput'
        || activeElement.id === 'voyageCrewDietTypeInput'
        || activeElement.id === 'voyageCrewAllergiesInput'
        || activeElement.id === 'voyageCrewDislikesInput'
        || activeElement.id === 'voyageCrewBreakfastInput'
        || activeElement.id === 'voyageCrewCommentInput'
    );
}

function captureCrewEditorDraftFromInputs() {
    crewEditorDraftState = {
        memberId: String(selectedCrewMemberId || ''),
        values: {
            prenom: String(document.getElementById('voyageCrewFirstNameInput')?.value || ''),
            nom: String(document.getElementById('voyageCrewLastNameInput')?.value || ''),
            email: String(document.getElementById('voyageCrewEmailInput')?.value || ''),
            telephone: String(document.getElementById('voyageCrewPhoneInput')?.value || ''),
            commentaire: String(document.getElementById('voyageCrewCommentInput')?.value || ''),
            dietaryProfile: sanitizeCrewDietaryProfile({
                dietType: document.getElementById('voyageCrewDietTypeInput')?.value || 'omnivore',
                allergiesText: document.getElementById('voyageCrewAllergiesInput')?.value || '',
                dislikesText: document.getElementById('voyageCrewDislikesInput')?.value || '',
                breakfastText: document.getElementById('voyageCrewBreakfastInput')?.value || ''
            })
        }
    };
}

function refreshVoyageCrewEditorUi({ rerenderAgenda = false } = {}) {
    syncCrewDirectorySelectOptions();
    syncCrewEditorUi();
    renderVoyageAssignedCrewList(getSelectedVoyagePlan());
    if (rerenderAgenda) {
        renderVoyageAgendaPanel();
    }
}

function getVoyageAssignedCrewMembers(plan) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    return safePlan.crewMemberIds
        .map(id => crewDirectory.find(entry => entry.id === id) || null)
        .filter(Boolean);
}

function syncCrewDirectorySelectOptions() {
    const select = document.getElementById('voyageCrewDirectorySelectInput');
    if (!select) return;

    const previousValue = String(selectedCrewMemberId || select.value || '').trim();
    const placeholderOptions = isCrewEditorDraftActive()
        ? [`<option value="">${escapeHtml(t('Nouvel équipier en cours', 'Nuevo tripulante en curso', 'New crew member in progress'))}</option>`]
        : [];
    select.innerHTML = crewDirectory.length
        ? placeholderOptions.concat(crewDirectory.map(entry => `<option value="${escapeHtml(entry.id)}">${escapeHtml(getCrewMemberDisplayName(entry))}${entry.email ? ` · ${escapeHtml(entry.email)}` : ''}</option>`)).join('')
        : `<option value="">${escapeHtml(isCrewEditorDraftActive() ? t('Nouvel équipier en cours', 'Nuevo tripulante en curso', 'New crew member in progress') : t('Aucun équipier enregistré', 'Ningún tripulante guardado', 'No saved crew member'))}</option>`;

    if (isCrewEditorDraftActive() && !selectedCrewMemberId) {
        select.value = '';
    } else if (previousValue && crewDirectory.some(entry => entry.id === previousValue)) {
        select.value = previousValue;
        selectedCrewMemberId = previousValue;
    } else if (crewDirectory.length > 0) {
        selectedCrewMemberId = crewDirectory[0].id;
        select.value = selectedCrewMemberId;
    }
}

function renderVoyageAssignedCrewList(plan) {
    const container = document.getElementById('voyagePlanCrewList');
    if (!container) return;

    const assigned = getVoyageAssignedCrewMembers(plan);
    if (!assigned.length) {
        container.innerHTML = `<div class="voyage-crew-empty">${escapeHtml(t('Aucun équipier affecté à ce voyage.', 'Ningún tripulante asignado a este viaje.', 'No crew assigned to this trip.'))}</div>`;
        return;
    }

    container.innerHTML = assigned.map(entry => `
        <div class="voyage-crew-chip">
            <div>
                <strong>${escapeHtml(getCrewMemberDisplayName(entry))}</strong>
                <div class="voyage-crew-chip__meta">${escapeHtml(entry.email || entry.telephone || t('Sans contact', 'Sin contacto', 'No contact'))}</div>
                <div class="voyage-crew-chip__meta">${escapeHtml(formatCrewDietaryProfileLabel(entry.dietaryProfile))}</div>
            </div>
            <div class="voyage-crew-chip__actions">
                <button type="button" data-voyage-crew-action="edit-member" data-crew-member-id="${escapeHtml(entry.id)}">${escapeHtml(t('Éditer', 'Editar', 'Edit'))}</button>
                <button type="button" data-voyage-crew-action="remove-member" data-crew-member-id="${escapeHtml(entry.id)}" data-voyage-plan-id="${escapeHtml(String(plan?.id || ''))}">${escapeHtml(t('Retirer', 'Retirar', 'Remove'))}</button>
            </div>
        </div>`).join('');
}

function syncCrewEditorUi() {
    const draftValues = crewEditorDraftState?.values || null;
    const selected = draftValues ? null : getSelectedCrewMember();
    const firstNameInput = document.getElementById('voyageCrewFirstNameInput');
    const lastNameInput = document.getElementById('voyageCrewLastNameInput');
    const emailInput = document.getElementById('voyageCrewEmailInput');
    const phoneInput = document.getElementById('voyageCrewPhoneInput');
    const dietTypeInput = document.getElementById('voyageCrewDietTypeInput');
    const allergiesInput = document.getElementById('voyageCrewAllergiesInput');
    const dislikesInput = document.getElementById('voyageCrewDislikesInput');
    const breakfastInput = document.getElementById('voyageCrewBreakfastInput');
    const commentInput = document.getElementById('voyageCrewCommentInput');
    const foodProfile = sanitizeCrewDietaryProfile(draftValues?.dietaryProfile ?? selected?.dietaryProfile ?? {});

    if (firstNameInput) firstNameInput.value = String((draftValues?.prenom ?? selected?.prenom) || '');
    if (lastNameInput) lastNameInput.value = String((draftValues?.nom ?? selected?.nom) || '');
    if (emailInput) emailInput.value = String((draftValues?.email ?? selected?.email) || '');
    if (phoneInput) phoneInput.value = String((draftValues?.telephone ?? selected?.telephone) || '');
    if (dietTypeInput) dietTypeInput.value = String(foodProfile.dietType || 'omnivore');
    if (allergiesInput) allergiesInput.value = String(foodProfile.allergiesText || '');
    if (dislikesInput) dislikesInput.value = String(foodProfile.dislikesText || '');
    if (breakfastInput) breakfastInput.value = String(foodProfile.breakfastText || '');
    if (commentInput) commentInput.value = String((draftValues?.commentaire ?? selected?.commentaire) || '');
}

function formatVoyageWaypointOptionLabel(entry, anchor = null) {
    const safeEntry = normalizeWaypointPhotoEntry(entry);
    if (!safeEntry) return '';
    const title = String(safeEntry.placeName || t('Mouillage sans nom', 'Fondeo sin nombre', 'Unnamed anchorage')).trim();
    const distanceToAnchorNm = anchor ? getWaypointDistanceToVoyageSelectionAnchor(safeEntry, anchor) : Number.NaN;
    const distanceLabel = Number.isFinite(distanceToAnchorNm)
        ? ` · ${distanceToAnchorNm.toFixed(1)} NM`
        : '';
    return `${title}${distanceLabel} · ${safeEntry.lat.toFixed(4)}, ${safeEntry.lng.toFixed(4)}`;
}

function sortWaypointEntriesForVoyageSelection(entries, anchor = null) {
    return [...(Array.isArray(entries) ? entries : [])].sort((a, b) => {
        if (anchor) {
            const distanceA = getWaypointDistanceToVoyageSelectionAnchor(a, anchor);
            const distanceB = getWaypointDistanceToVoyageSelectionAnchor(b, anchor);
            if (Number.isFinite(distanceA) && Number.isFinite(distanceB) && distanceA !== distanceB) {
                return distanceA - distanceB;
            }
            if (Number.isFinite(distanceA) !== Number.isFinite(distanceB)) {
                return Number.isFinite(distanceA) ? -1 : 1;
            }
        }
        return formatVoyageWaypointOptionLabel(a).localeCompare(formatVoyageWaypointOptionLabel(b));
    });
}

function getWaypointEntriesForVoyagePlanSelection(plan = null, selectedWaypointId = '') {
    const allEntries = waypointPhotoEntries
        .map(normalizeWaypointPhotoEntry)
        .filter(Boolean);
    if (!allEntries.length) return [];

    const selectionAnchor = getVoyagePlanSelectionAnchor(plan);
    const visibleBounds = map && typeof map.getBounds === 'function'
        ? map.getBounds()
        : null;
    const visibleEntries = allEntries.filter(entry => !visibleBounds || typeof visibleBounds.contains !== 'function' || visibleBounds.contains([entry.lat, entry.lng]));
    const nearbyEntries = selectionAnchor
        ? allEntries.filter(entry => {
            const distanceToAnchorNm = getWaypointDistanceToVoyageSelectionAnchor(entry, selectionAnchor);
            return Number.isFinite(distanceToAnchorNm) && distanceToAnchorNm <= VOYAGE_WAYPOINT_SELECTION_RADIUS_NM;
        })
        : [];
    const baseEntries = nearbyEntries.length ? nearbyEntries : (visibleEntries.length ? visibleEntries : allEntries);
    const safeSelectedWaypointId = String(selectedWaypointId || '').trim();
    if (!safeSelectedWaypointId) {
        return sortWaypointEntriesForVoyageSelection(baseEntries, selectionAnchor);
    }

    const selectedEntry = allEntries.find(entry => String(entry?.id || '').trim() === safeSelectedWaypointId);
    if (!selectedEntry || baseEntries.some(entry => String(entry?.id || '').trim() === safeSelectedWaypointId)) {
        return sortWaypointEntriesForVoyageSelection(baseEntries, selectionAnchor);
    }

    return sortWaypointEntriesForVoyageSelection([...baseEntries, selectedEntry], selectionAnchor);
}

function syncVoyagePlanWaypointSelectOptions() {
    const waypointSelect = document.getElementById('voyagePlanWaypointSelectInput');
    if (!waypointSelect) return;

    const previousValue = String(waypointSelect.value || '').trim();
    const safeEntries = getWaypointEntriesForVoyagePlanSelection(getSelectedVoyagePlan(), previousValue);

    waypointSelect.innerHTML = safeEntries.length
        ? [`<option value="">${escapeHtml(t('Choisir un waypoint enregistré', 'Elegir un waypoint guardado', 'Choose a saved waypoint'))}</option>`]
            .concat(safeEntries.map(entry => `<option value="${escapeHtml(entry.id)}">${escapeHtml(formatVoyageWaypointOptionLabel(entry, getVoyagePlanSelectionAnchor(getSelectedVoyagePlan())))}</option>`))
            .join('')
        : `<option value="">${escapeHtml(t('Aucun waypoint enregistré', 'No hay waypoints guardados', 'No saved waypoints'))}</option>`;

    if (previousValue && safeEntries.some(entry => entry.id === previousValue)) {
        waypointSelect.value = previousValue;
    }
}

function applySelectedVoyageWaypointToStopDraft() {
    const waypointSelect = document.getElementById('voyagePlanWaypointSelectInput');
    const stopNameInput = document.getElementById('voyagePlanStopNameInput');
    if (!waypointSelect || !stopNameInput) return;

    const waypointId = String(waypointSelect.value || '').trim();
    if (!waypointId) return;

    const selectedWaypoint = waypointPhotoEntries.find(entry => String(entry?.id || '') === waypointId) || null;
    if (!selectedWaypoint) return;

    stopNameInput.value = String(selectedWaypoint.placeName || '').trim()
        || `${selectedWaypoint.lat.toFixed(4)}, ${selectedWaypoint.lng.toFixed(4)}`;
}

function syncVoyagePlanEditorUi() {
    const nameInput = document.getElementById('voyagePlanNameInput');
    const descriptionInput = document.getElementById('voyagePlanDescriptionInput');
    const statusInput = document.getElementById('voyagePlanStatusInput');
    const routeSelect = document.getElementById('voyagePlanRouteSelectInput');
    const waypointSelect = document.getElementById('voyagePlanWaypointSelectInput');
    const activeDisplay = document.getElementById('voyagePlanActiveDisplay');
    const builderNode = document.querySelector('.voyage-agenda-builder');

    const selectedPlan = getSelectedVoyagePlan();
    const draftValues = !selectedPlan && isVoyagePlanEditorDraftActive()
        ? voyagePlanEditorDraftState?.values || null
        : null;
    if (nameInput) nameInput.value = String((draftValues?.name ?? selectedPlan?.name) || '');
    if (descriptionInput) descriptionInput.value = String((draftValues?.description ?? selectedPlan?.description) || '');
    if (statusInput) statusInput.value = normalizeVoyagePlanStatus(draftValues?.status ?? selectedPlan?.status);
    if (builderNode) {
        builderNode.classList.toggle('is-new-voyage', !selectedPlan);
    }
    if (activeDisplay) {
        activeDisplay.textContent = selectedPlan
            ? `${t('Voyage actif', 'Viaje activo', 'Active trip')}: ${selectedPlan.name} · ${getVoyagePlanStatusLabel(selectedPlan.status)}`
            : `${t('Nouveau voyage', 'Nuevo viaje', 'New trip')} · ${t('NOUVEAU', 'NUEVO', 'NEW')}`;
    }

    const routeDepartureInput = document.getElementById('voyagePlanRouteDepartureInput');
    if (routeDepartureInput) {
        const selectedPlanId = String(selectedPlan?.id || '').trim();
        const previousPlanId = String(routeDepartureInput.dataset.planId || '').trim();
        const previousDepartureValue = normalizeDateTimeLocalValue(String(routeDepartureInput.value || '').trim());
        const nextStart = getVoyagePlanNextDepartureDateTime(selectedPlan);
        routeDepartureInput.value = previousDepartureValue && previousPlanId && previousPlanId === selectedPlanId
            ? previousDepartureValue
            : formatDateTimeLocalInputValue(nextStart);
        routeDepartureInput.dataset.planId = selectedPlanId;
    }

    if (routeSelect) {
        const previousRouteId = String(routeSelect.value || '').trim();
        const routes = getSavedRoutesForVoyagePlanSelection(selectedPlan, previousRouteId);
        routeSelect.innerHTML = routes.length
            ? routes.map(route => `<option value="${escapeHtml(route.id)}">${escapeHtml(route.name)}${Number.isFinite(getSavedRouteDistanceNm(route)) ? ` · ${escapeHtml(getSavedRouteDistanceNm(route).toFixed(1))} NM` : ''}</option>`).join('')
            : `<option value="">${escapeHtml(t('Aucune route sauvegardée', 'No hay rutas guardadas', 'No saved routes'))}</option>`;
        if (previousRouteId && routes.some(route => String(route?.id || '').trim() === previousRouteId)) {
            routeSelect.value = previousRouteId;
        }
    }

    if (waypointSelect) {
        syncVoyagePlanWaypointSelectOptions();
    }

    syncCrewDirectorySelectOptions();
    syncCrewEditorUi();
    renderVoyageAssignedCrewList(selectedPlan);
}

function renderVoyagesSidebar(planEntries) {
    const container = document.getElementById('voyagesSidebarList');
    if (!container) return;

    if (!planEntries.length) {
        container.innerHTML = `<div class="voyage-agenda-empty" style="min-height:120px;">${escapeHtml(t('Aucun voyage créé pour le moment.', 'No hay viajes creados por ahora.', 'No trips created yet.'))}</div>`;
        return;
    }

    container.innerHTML = planEntries.map(({ plan, timeline }) => {
        const nextDeparture = timeline.find(entry => entry.departure)?.departure || null;
        const totalStops = timeline.filter(entry => entry.type === 'stop').length;
        const totalCrew = sanitizeVoyagePlan(plan, 0).crewMemberIds.length;
        const isActive = plan.id === selectedVoyagePlanId;
        const statusLabel = getVoyagePlanStatusLabel(plan.status);
        return `
            <button type="button" class="voyages-sidebar-item ${isActive ? 'is-active' : ''}" data-voyage-plan-action="select" data-voyage-plan-id="${escapeHtml(plan.id)}" style="${escapeHtml(getVoyageAccentStyle(plan))}">
                <div class="voyages-sidebar-item__title">${escapeHtml(plan.name)}</div>
                <div class="voyages-sidebar-item__status">${escapeHtml(statusLabel)}</div>
                <div class="voyages-sidebar-item__meta">${timeline.length} ${escapeHtml(t('étape(s)', 'etapa(s)', 'item(s)'))} · ${totalStops} ${escapeHtml(t('mouillage(s)', 'fondeo(s)', 'stop(s)'))} · ${totalCrew} ${escapeHtml(t('équipier(s)', 'tripulante(s)', 'crew'))}</div>
                <div class="voyages-sidebar-item__meta">${escapeHtml(nextDeparture ? formatDateTimeLocalLabel(nextDeparture) : t('Aucune date de départ', 'Sin fecha de salida', 'No departure date'))}</div>
            </button>`;
    }).join('');
}

function computeVoyagePlanTimeline(plan) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    const routesById = new Map(getSavedRoutes().map(route => [String(route.id || ''), route]));
    const editableRouteItemId = getEditableVoyageRouteItemId(safePlan);
    let cursor = null;

    return safePlan.items.map((item, index) => {
        if (item.type === 'route') {
            const route = routesById.get(item.routeId) || null;
            const distanceNm = route ? (getSavedRouteDistanceNm(route) || 0) : 0;
            const planningSpeedKn = getPlanningReferenceSpeedKn();
            const estimatedHours = Number.isFinite(distanceNm) && distanceNm > 0
                ? distanceNm / Math.max(4.5, planningSpeedKn)
                : null;
            const explicitDeparture = item.id === editableRouteItemId ? parseDateTimeLocalValue(item.departureDateTime || '') : null;
            const departure = explicitDeparture || cursor;
            const arrival = departure && Number.isFinite(estimatedHours)
                ? new Date(departure.getTime() + estimatedHours * 60 * 60 * 1000)
                : null;
            cursor = arrival || cursor;
            return {
                id: item.id,
                type: 'route',
                item,
                route,
                routeIndex: getSavedRoutes().findIndex(savedRoute => String(savedRoute.id || '') === String(route?.id || '')),
                title: route?.voyageLeg || route?.name || t('Route manquante', 'Ruta faltante', 'Missing route'),
                subtitle: route?.name || t('Route supprimée ou indisponible', 'Ruta eliminada o no disponible', 'Deleted or unavailable route'),
                departure,
                arrival,
                distanceNm,
                estimatedHours,
                timelineLabel: departure && arrival
                    ? `${formatDateTimeLocalLabel(departure)} -> ${formatDateTimeLocalLabel(arrival)}`
                    : t('Départ à fixer pour calculer l\'arrivée.', 'Fijar salida para calcular la llegada.', 'Set departure to calculate arrival.'),
                statusLabel: arrival ? t('ETA calculée', 'ETA calculada', 'ETA computed') : t('À planifier', 'Por planificar', 'To plan'),
                statusKey: arrival ? 'ok' : 'warning'
            };
        }

        const start = cursor;
        const explicitDeparture = parseDateTimeLocalValue(item.stopDepartureDateTime || '');
        const computedDurationDays = Math.max(VOYAGE_STOP_MIN_DURATION_DAYS, Number(item.durationDays || 1) || 1);
        const end = start
            ? (explicitDeparture && explicitDeparture.getTime() > start.getTime()
                ? explicitDeparture
                : getAnchorageEndDateTime(start, computedDurationDays))
            : null;
        const durationDays = start && end
            ? Math.max(VOYAGE_STOP_MIN_DURATION_DAYS, (end.getTime() - start.getTime()) / (24 * 60 * 60 * 1000))
            : computedDurationDays;
        cursor = end || cursor;
        return {
            id: item.id,
            type: 'stop',
            item,
            title: item.stopName || t('Mouillage', 'Fondeo', 'Anchorage'),
            subtitle: t('Étape mouillage', 'Etapa fondeo', 'Anchorage leg'),
            departure: start,
            arrival: end,
            durationDays,
            timelineLabel: start && end
                ? `${formatDateTimeLocalLabel(start)} -> ${formatDateTimeLocalLabel(end)}`
                : t('Se cale après la dernière route datée.', 'Se coloca después de la última ruta fechada.', 'Fits after the last dated route.'),
            statusLabel: `${durationDays.toFixed(1)} ${t('jour(s)', 'día(s)', 'day(s)')}`,
            statusKey: end ? 'ok' : 'warning'
        };
    });
}

function startOfLocalDay(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    const next = new Date(date.getTime());
    next.setHours(0, 0, 0, 0);
    return next;
}

function addDays(date, days) {
    const next = new Date(date.getTime());
    next.setDate(next.getDate() + days);
    return next;
}

function getStartOfLocalWeek(date) {
    const base = startOfLocalDay(date);
    if (!base) return null;
    const dayIndex = base.getDay();
    const mondayOffset = dayIndex === 0 ? -6 : 1 - dayIndex;
    return addDays(base, mondayOffset);
}

function getStartOfLocalMonth(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    return new Date(date.getFullYear(), date.getMonth(), 1);
}

function getEndOfLocalMonth(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

function formatVoyageAgendaDayLabel(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    return date.toLocaleDateString(getCurrentLocale(), {
        weekday: 'short',
        day: '2-digit',
        month: 'short'
    });
}

function formatVoyageAgendaWeekLabel(weekStart) {
    if (!(weekStart instanceof Date) || Number.isNaN(weekStart.getTime())) return '';
    const weekEnd = addDays(weekStart, 6);
    return `${weekStart.toLocaleDateString(getCurrentLocale(), { day: '2-digit', month: 'short' })} - ${weekEnd.toLocaleDateString(getCurrentLocale(), { day: '2-digit', month: 'short' })}`;
}

function formatVoyageAgendaMonthLabel(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    return date.toLocaleDateString(getCurrentLocale(), {
        month: 'long',
        year: 'numeric'
    });
}

function formatVoyageAgendaTimeLabel(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    return date.toLocaleTimeString(getCurrentLocale(), {
        hour: '2-digit',
        minute: '2-digit'
    });
}

function setVoyageAgendaProvisioningStatus(message, isError = false) {
    const node = document.getElementById('voyageAgendaProvisioningStatus');
    if (!node) return;
    node.textContent = String(message || '');
    node.classList.toggle('is-error', !!isError);
    node.classList.toggle('is-ok', !!message && !isError);
}

function getFilteredVoyagePlanEntries() {
    const planEntries = voyagePlans.map(plan => ({
        plan,
        timeline: computeVoyagePlanTimeline(plan)
    }));

    return planEntries.filter(({ plan, timeline }) => {
        if (voyagePlanStatusFilter !== 'all' && normalizeVoyagePlanStatus(plan.status) !== voyagePlanStatusFilter) {
            return false;
        }
        const crewNames = getVoyageAssignedCrewMembers(plan).map(entry => getCrewMemberDisplayName(entry)).join(' ');
        const haystack = [
            plan.name,
            plan.description,
            plan.status,
            getVoyagePlanStatusLabel(plan.status),
            crewNames,
            ...timeline.map(entry => `${entry.title} ${entry.subtitle} ${entry.item?.notes || ''}`)
        ].join(' ').toLowerCase();
        return !voyageAgendaSearchTerm.trim() || haystack.includes(voyageAgendaSearchTerm.toLowerCase().trim());
    });
}

function updateVoyageCalendarHandleLabel(handleNode, date) {
    if (!handleNode) return;
    const timeLabel = formatVoyageAgendaTimeLabel(date) || '--:--';
    handleNode.textContent = timeLabel;
    handleNode.setAttribute('data-handle-time', timeLabel);
}

function hashVoyageAccentKey(value) {
    const source = String(value || '').trim().toLowerCase();
    let hash = 0;
    for (let index = 0; index < source.length; index += 1) {
        hash = ((hash << 5) - hash) + source.charCodeAt(index);
        hash |= 0;
    }
    return Math.abs(hash);
}

function getVoyageAccentColors(planOrKey) {
    const key = typeof planOrKey === 'string'
        ? planOrKey
        : String(planOrKey?.id || planOrKey?.name || 'voyage');
    return VOYAGE_ACCENT_PALETTE[hashVoyageAccentKey(key) % VOYAGE_ACCENT_PALETTE.length];
}

function getVoyageAccentStyle(planOrKey) {
    const accent = getVoyageAccentColors(planOrKey);
    return [
        `--voyage-accent-start:${accent.start}`,
        `--voyage-accent-end:${accent.end}`,
        `--voyage-accent-surface:${accent.surface}`,
        `--voyage-accent-soft:${accent.soft}`,
        `--voyage-accent-text:${accent.text}`
    ].join(';');
}

function buildVoyageAgendaWeeksForRange(timeline, firstWeekStart, lastWeekStart, editableItemId = '') {
    const scheduledEntries = (timeline || []).filter(entry => entry.departure instanceof Date && entry.arrival instanceof Date);
    if (!(firstWeekStart instanceof Date) || Number.isNaN(firstWeekStart.getTime()) || !(lastWeekStart instanceof Date) || Number.isNaN(lastWeekStart.getTime())) {
        return [];
    }

    const weeks = [];
    const weekDurationMs = 7 * 24 * 60 * 60 * 1000;

    for (let weekStart = new Date(firstWeekStart.getTime()); weekStart <= lastWeekStart; weekStart = addDays(weekStart, 7)) {
        const weekEnd = addDays(weekStart, 7);
        const days = Array.from({ length: 7 }, (_, dayOffset) => addDays(weekStart, dayOffset));
        const items = scheduledEntries
            .filter(entry => entry.arrival > weekStart && entry.departure < weekEnd)
            .map(entry => {
                const clippedStart = entry.departure > weekStart ? entry.departure : weekStart;
                const clippedEnd = entry.arrival < weekEnd ? entry.arrival : weekEnd;
                const leftPct = ((clippedStart.getTime() - weekStart.getTime()) / weekDurationMs) * 100;
                const widthPct = Math.max(((clippedEnd.getTime() - clippedStart.getTime()) / weekDurationMs) * 100, 2.2);
                const popupLabel = `${entry.title} · ${formatVoyageAgendaTimeLabel(entry.departure)} - ${formatVoyageAgendaTimeLabel(entry.arrival)}${entry.subtitle ? ` · ${entry.subtitle}` : ''}`;
                return {
                    id: entry.id,
                    type: entry.type,
                    title: entry.title,
                    subtitle: entry.subtitle,
                    isDerived: entry.type === 'route' ? !entry.item?.departureDateTime : false,
                    isScheduleEditable: entry.id === editableItemId,
                    canResizeDeparture: entry.type === 'stop' && entry.arrival >= weekStart && entry.arrival < weekEnd,
                    startLabel: formatVoyageAgendaTimeLabel(entry.departure),
                    endLabel: formatVoyageAgendaTimeLabel(entry.arrival),
                    dragHandleLabel: formatVoyageAgendaTimeLabel(entry.departure),
                    resizeHandleLabel: formatVoyageAgendaTimeLabel(entry.arrival),
                    leftPct,
                    widthPct,
                    isCompact: widthPct <= 7.5,
                    popupLabel,
                    planId: entry.planId || '',
                    eventId: entry.eventId || ''
                };
            });

        weeks.push({
            weekStart,
            label: formatVoyageAgendaWeekLabel(weekStart),
            days,
            items
        });
    }

    return weeks;
}

function buildVoyageAgendaWeeks(timeline, editableItemId = '') {
    const scheduledEntries = (timeline || []).filter(entry => entry.departure instanceof Date && entry.arrival instanceof Date);
    if (!scheduledEntries.length) return [];

    const firstDeparture = scheduledEntries.reduce((minValue, entry) => !minValue || entry.departure < minValue ? entry.departure : minValue, null);
    const lastArrival = scheduledEntries.reduce((maxValue, entry) => !maxValue || entry.arrival > maxValue ? entry.arrival : maxValue, null);
    const firstWeekStart = getStartOfLocalWeek(firstDeparture);
    const lastWeekStart = getStartOfLocalWeek(lastArrival);
    return buildVoyageAgendaWeeksForRange(scheduledEntries, firstWeekStart, lastWeekStart, editableItemId);
}

function buildVoyageAgendaSequentialWeeks(timeline, referenceDate, weekCount, editableItemId = '') {
    const referenceWeekStart = getStartOfLocalWeek(referenceDate);
    const safeWeekCount = Math.max(1, Number(weekCount || 0) || 1);
    if (!referenceWeekStart) return [];
    const lastWeekStart = addDays(referenceWeekStart, (safeWeekCount - 1) * 7);
    return buildVoyageAgendaWeeksForRange(timeline, referenceWeekStart, lastWeekStart, editableItemId);
}

function renderVoyageScheduleCalendar(timeline, editableItemId = '') {
    const weeks = buildVoyageAgendaWeeks(timeline, editableItemId);
    const todayDateKey = formatLocalDateKey(startOfLocalDay(new Date()));
    if (!weeks.length) {
        return `
            <section class="voyage-calendar-card">
                <div class="voyage-calendar-card__header">
                    <div>
                        <div class="voyage-agenda-voyage__stat-label">${escapeHtml(t('Agenda du voyage', 'Agenda del viaje', 'Trip agenda'))}</div>
                        <div class="voyage-agenda-voyage__timeline-note">${escapeHtml(t('La vue calendrier s’active dès qu’au moins une étape est datée.', 'La vista calendario aparece cuando al menos una etapa tiene fecha.', 'The calendar view appears once at least one leg is dated.'))}</div>
                    </div>
                </div>
                <div class="voyage-calendar-card__empty">${escapeHtml(t('Ajoute une date de départ pour voir le voyage comme un agenda.', 'Añade una fecha de salida para ver el viaje como agenda.', 'Add a departure date to see the trip as a calendar.'))}</div>
            </section>`;
    }

    return `
        <section class="voyage-calendar-card">
            <div class="voyage-calendar-card__header">
                <div>
                    <div class="voyage-agenda-voyage__stat-label">${escapeHtml(t('Agenda du voyage', 'Agenda del viaje', 'Trip agenda'))}</div>
                    <div class="voyage-agenda-voyage__timeline-note">${escapeHtml(t('Vue semaine inspirée d’un calendrier pour lire rapidement routes et mouillages.', 'Vista semanal inspirada en un calendario para leer rápido rutas y fondeos.', 'Week view inspired by a calendar for quickly reading routes and anchorages.'))}</div>
                </div>
            </div>
            <div class="voyage-calendar-weeks">
                ${weeks.map(week => `
                    <section class="voyage-calendar-week">
                        <div class="voyage-calendar-week__title">${escapeHtml(week.label)}</div>
                        <div class="voyage-calendar-week__header">
                            ${week.days.map(day => `<div class="voyage-calendar-week__day${formatLocalDateKey(day) === todayDateKey ? ' is-current-day' : ''}">${escapeHtml(formatVoyageAgendaDayLabel(day))}</div>`).join('')}
                        </div>
                        <div class="voyage-calendar-week__body" data-voyage-week-start="${escapeHtml(formatDateTimeLocalInputValue(week.weekStart).slice(0, 10))}">
                            <div class="voyage-calendar-grid">
                                ${Array.from({ length: 7 }, (_, index) => `<div class="voyage-calendar-grid__col" style="left:${(index / 7) * 100}%; width:${100 / 7}%;"></div>`).join('')}
                            </div>
                            <div class="voyage-calendar-items">
                                ${week.items.map(item => `
                                    <div class="voyage-calendar-row">
                                        <article class="voyage-calendar-item voyage-calendar-item--${escapeHtml(item.type)}${item.isDerived ? ' is-derived' : ''}${item.isScheduleEditable ? ' is-schedule-editable' : ''}${item.isCompact ? ' is-compact' : ''}${activeVoyageMapItemId === item.id ? ' is-active' : ''}" data-voyage-map-item-id="${escapeHtml(item.id)}"${item.isScheduleEditable ? ' draggable="true"' : ''}${item.isCompact ? ` data-compact-popup="${escapeHtml(item.popupLabel || item.title || '')}" tabindex="0" title="${escapeHtml(item.popupLabel || item.title || '')}"` : ''} style="left:${escapeHtml(item.leftPct.toFixed(2))}%; width:${escapeHtml(item.widthPct.toFixed(2))}%;">
                                            ${item.isScheduleEditable ? `<div class="voyage-calendar-item__drag-handle" title="${escapeHtml(t('Glisser pour déplacer le départ', 'Arrastra para mover la salida', 'Drag to move departure'))}" data-handle-time="${escapeHtml(item.dragHandleLabel || '--:--')}">${escapeHtml(item.dragHandleLabel || '--:--')}</div>` : ''}
                                            ${item.isCompact ? `<div class="voyage-calendar-item__compact-marker" aria-hidden="true">+</div>` : ''}
                                            <div class="voyage-calendar-item__title">${escapeHtml(item.title)}</div>
                                            <div class="voyage-calendar-item__meta">${escapeHtml(item.startLabel)} - ${escapeHtml(item.endLabel)}</div>
                                            ${item.canResizeDeparture ? `<button type="button" class="voyage-calendar-item__resize-handle" data-voyage-resize-handle="true" aria-label="${escapeHtml(t('Modifier le départ du mouillage', 'Modificar salida del fondeo', 'Adjust anchorage departure'))}" title="${escapeHtml(t('Tirer pour modifier le départ du mouillage', 'Tira para modificar la salida del fondeo', 'Drag to adjust anchorage departure'))}" data-handle-time="${escapeHtml(item.resizeHandleLabel || '--:--')}">${escapeHtml(item.resizeHandleLabel || '--:--')}</button>` : ''}
                                        </article>
                                    </div>`).join('')}
                            </div>
                        </div>
                    </section>`).join('')}
            </div>
        </section>`;
}

function buildPlannedVoyageOverviewEntries(planEntries) {
    return (Array.isArray(planEntries) ? planEntries : []).flatMap(({ plan, timeline }) => {
        if (normalizeVoyagePlanStatus(plan?.status) !== VOYAGE_PLAN_STATUS_PLANNED) return [];
        const scheduledEntries = (Array.isArray(timeline) ? timeline : []).filter(entry => entry.departure instanceof Date && entry.arrival instanceof Date);
        if (!scheduledEntries.length) return [];

        const firstDeparture = scheduledEntries.reduce((minValue, entry) => !minValue || entry.departure < minValue ? entry.departure : minValue, null);
        const lastArrival = scheduledEntries.reduce((maxValue, entry) => !maxValue || entry.arrival > maxValue ? entry.arrival : maxValue, null);
        if (!(firstDeparture instanceof Date) || !(lastArrival instanceof Date)) return [];

        const routeCount = scheduledEntries.filter(entry => entry.type === 'route').length;
        const stopCount = scheduledEntries.filter(entry => entry.type === 'stop').length;
        return [{
            id: `voyage-overview-${plan.id}`,
            planId: String(plan.id || ''),
            type: 'route',
            title: String(plan.name || '').trim() || t('Voyage sans nom', 'Viaje sin nombre', 'Unnamed trip'),
            subtitle: `${routeCount} ${t('route(s)', 'ruta(s)', 'route(s)')} · ${stopCount} ${t('escale(s)', 'escala(s)', 'stop(s)')}`,
            departure: firstDeparture,
            arrival: lastArrival,
            item: null
        }];
    });
}

function buildAgendaEventTimelineEntries() {
    return agendaEvents.map((entry, index) => {
        const safeEvent = sanitizeAgendaEvent(entry, index);
        return {
            id: safeEvent.id,
            eventId: safeEvent.id,
            planId: '',
            type: 'event',
            title: safeEvent.title,
            subtitle: safeEvent.comment || t('Évènement simple', 'Evento simple', 'Simple event'),
            departure: parseDateTimeLocalValue(safeEvent.startDateTime),
            arrival: parseDateTimeLocalValue(safeEvent.endDateTime),
            item: { comment: safeEvent.comment }
        };
    }).filter(entry => entry.departure instanceof Date && entry.arrival instanceof Date && entry.arrival > entry.departure);
}

