function resolveVoyageOverviewReferenceDate(overviewEntries) {
    const safeEntries = Array.isArray(overviewEntries) ? overviewEntries : [];
    const selectedEntry = safeEntries.find(entry => entry.planId === selectedVoyagePlanId && entry.departure instanceof Date);
    if (selectedEntry?.departure instanceof Date) {
        return selectedEntry.departure;
    }

    const today = startOfLocalDay(new Date()) || new Date();
    const currentMonthStart = getStartOfLocalMonth(today);
    const currentMonthEnd = getEndOfLocalMonth(today);
    if (currentMonthStart && currentMonthEnd && safeEntries.some(entry => entry.departure <= addDays(currentMonthEnd, 1) && entry.arrival >= currentMonthStart)) {
        return today;
    }

    return safeEntries.find(entry => entry.departure instanceof Date)?.departure || today;
}

function renderVoyagesOverviewCalendar(planEntries) {
    const overviewEntries = buildPlannedVoyageOverviewEntries(planEntries);
    const agendaEventEntries = buildAgendaEventTimelineEntries();
    const calendarEntries = overviewEntries.concat(agendaEventEntries);
    if (!calendarEntries.length) {
        return `
            <section class="voyage-calendar-card voyages-overview-calendar">
                <div class="voyage-calendar-card__header">
                    <div>
                        <div class="voyage-agenda-voyage__stat-label">${escapeHtml(t('Calendrier des voyages planifiés', 'Calendario de viajes planificados', 'Planned trips calendar'))}</div>
                        <div class="voyage-agenda-voyage__timeline-note">${escapeHtml(t('Vue synthétique des grandes lignes des voyages planifiés.', 'Vista sintética de las grandes líneas de los viajes planificados.', 'High-level overview of planned trips.'))}</div>
                    </div>
                </div>
                <div class="voyage-calendar-card__empty">${escapeHtml(t('Aucun voyage planifié avec dates pour le moment.', 'Aún no hay viajes planificados con fechas.', 'No planned trips with dates yet.'))}</div>
            </section>
            ${renderAgendaEventManager()}`;
    }

    const referenceDate = voyageOverviewReferenceDate instanceof Date && !Number.isNaN(voyageOverviewReferenceDate.getTime())
        ? voyageOverviewReferenceDate
        : resolveVoyageOverviewReferenceDate(calendarEntries);
    const visibleMonthStart = getStartOfLocalMonth(referenceDate);
    const visibleMonthEnd = getEndOfLocalMonth(referenceDate);
    const firstWeekStart = getStartOfLocalWeek(visibleMonthStart);
    const lastWeekStart = getStartOfLocalWeek(visibleMonthEnd);
    const visibleWeekCount = Math.max(1, Math.round((lastWeekStart.getTime() - firstWeekStart.getTime()) / (7 * 24 * 60 * 60 * 1000)) + 1);
    const weeks = buildVoyageAgendaSequentialWeeks(calendarEntries, referenceDate, visibleWeekCount, '');
    const monthLabel = formatVoyageAgendaMonthLabel(referenceDate);
    const currentWeekStart = getStartOfLocalWeek(new Date());
    const todayDateKey = formatLocalDateKey(startOfLocalDay(new Date()));

    return `
        <section class="voyage-calendar-card voyages-overview-calendar">
            <div class="voyage-calendar-card__header">
                <div>
                    <div class="voyage-agenda-voyage__stat-label">${escapeHtml(t('Calendrier des voyages planifiés', 'Calendario de viajes planificados', 'Planned trips calendar'))}</div>
                    <div class="voyage-agenda-voyage__timeline-note">${escapeHtml(monthLabel)} · ${escapeHtml(t('Semaines affichées à partir de la date visible.', 'Semanas mostradas a partir de la fecha visible.', 'Weeks shown starting from the visible date.'))}</div>
                </div>
                <div class="voyage-calendar-nav" aria-label="${escapeHtml(t('Navigation du calendrier', 'Navegación del calendario', 'Calendar navigation'))}">
                    <button type="button" class="voyage-calendar-nav__btn" data-voyage-overview-nav="prev-week">${escapeHtml(t('Semaine précédente', 'Semana anterior', 'Previous week'))}</button>
                    <button type="button" class="voyage-calendar-nav__btn" data-voyage-overview-nav="today">${escapeHtml(t('Aujourd\'hui', 'Hoy', 'Today'))}</button>
                    <button type="button" class="voyage-calendar-nav__btn" data-voyage-overview-nav="next-week">${escapeHtml(t('Semaine suivante', 'Semana siguiente', 'Next week'))}</button>
                </div>
            </div>
            <div class="voyage-calendar-weeks">
                ${weeks.map(week => `
                    <section class="voyage-calendar-week${currentWeekStart && week.weekStart.getTime() === currentWeekStart.getTime() ? ' is-current-week' : ''}">
                        <div class="voyage-calendar-week__title">${escapeHtml(week.label)}</div>
                        <div class="voyage-calendar-week__header">
                            ${week.days.map(day => `<div class="voyage-calendar-week__day${formatLocalDateKey(day) === todayDateKey ? ' is-current-day' : ''}">${escapeHtml(formatVoyageAgendaDayLabel(day))}</div>`).join('')}
                        </div>
                        <div class="voyage-calendar-week__body" data-voyage-week-start="${escapeHtml(formatDateTimeLocalInputValue(week.weekStart).slice(0, 10))}">
                            <div class="voyage-calendar-grid">
                                ${Array.from({ length: 7 }, (_, index) => `<div class="voyage-calendar-grid__col" style="left:${(index / 7) * 100}%; width:${100 / 7}%;"></div>`).join('')}
                            </div>
                            <div class="voyage-calendar-items">
                                ${week.items.map(item => `
                                    <div class="voyage-calendar-row">
                                        <article class="voyage-calendar-item voyage-calendar-item--${escapeHtml(item.type === 'event' ? 'event' : 'route')}${item.isCompact ? ' is-compact' : ''}${selectedVoyagePlanId === item.planId ? ' is-active' : ''}${item.type === 'event' && item.eventId === selectedAgendaEventId ? ' is-active' : ''} voyages-overview-calendar__item${item.type === 'event' ? ' is-schedule-editable' : ''}" ${item.type === 'event' ? `data-agenda-event-action="edit" data-agenda-event-id="${escapeHtml(item.eventId || '')}" draggable="true"` : `data-voyage-plan-action="select" data-voyage-plan-id="${escapeHtml(item.planId || '')}"`}${item.isCompact ? ` data-compact-popup="${escapeHtml(item.popupLabel || item.title || '')}" tabindex="0" title="${escapeHtml(item.popupLabel || item.title || '')}"` : ''} style="left:${escapeHtml(item.leftPct.toFixed(2))}%; width:${escapeHtml(item.widthPct.toFixed(2))}%; ${escapeHtml(item.type === 'event' ? '--voyage-accent-start:#2f80ed;--voyage-accent-end:#1366d6;--voyage-accent-surface:rgba(47,128,237,0.18);--voyage-accent-soft:rgba(47,128,237,0.28);--voyage-accent-text:#e8f3ff' : getVoyageAccentStyle(item.planId || item.id || 'voyage'))}">
                                            ${item.isCompact ? `<div class="voyage-calendar-item__compact-marker" aria-hidden="true">+</div>` : ''}
                                            <div class="voyage-calendar-item__title">${escapeHtml(item.title)}</div>
                                            <div class="voyage-calendar-item__meta">${escapeHtml(item.startLabel)} - ${escapeHtml(item.endLabel)}${item.subtitle ? ` · ${escapeHtml(item.subtitle)}` : ''}</div>
                                        </article>
                                    </div>`).join('')}
                            </div>
                        </div>
                    </section>`).join('')}
            </div>
        </section>
        ${renderAgendaEventManager()}`;
}

function getVoyageWeatherIcon(weatherCode) {
    const safeCode = Number(weatherCode);
    if (!Number.isFinite(safeCode)) return '◌';
    if (safeCode >= 95) return '⛈';
    if (safeCode >= 80) return '🌦';
    if (safeCode >= 71) return '❄️';
    if (safeCode >= 61) return '🌧';
    if (safeCode >= 45) return '🌫';
    if (safeCode === 0) return '☀️';
    if (safeCode <= 3) return '⛅';
    return '☁️';
}

function formatVoyageAgendaHalfDayLabel(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    const label = date.getHours() < 12
        ? t('Matin', 'Mañana', 'Morning')
        : t('Après-midi', 'Tarde', 'Afternoon');
    return `${formatVoyageAgendaDayLabel(date)} · ${label}`;
}

function buildVoyageAgendaWeatherSlots(timeline) {
    const scheduledEntries = (timeline || []).filter(entry => entry.departure instanceof Date && entry.arrival instanceof Date);
    if (!scheduledEntries.length) return [];

    const anchors = new Map();
    let lastKnownAnchor = null;
    scheduledEntries.forEach(entry => {
        if (entry.type === 'route') {
            const anchor = getVoyageEntryAnchorPoint(entry);
            if (anchor) {
                lastKnownAnchor = anchor;
            }
        }
        if (lastKnownAnchor) {
            anchors.set(entry.id, lastKnownAnchor);
        }
    });

    const firstDeparture = scheduledEntries.reduce((minValue, entry) => !minValue || entry.departure < minValue ? entry.departure : minValue, null);
    const lastArrival = scheduledEntries.reduce((maxValue, entry) => !maxValue || entry.arrival > maxValue ? entry.arrival : maxValue, null);
    const firstDay = startOfLocalDay(firstDeparture);
    const lastDay = startOfLocalDay(lastArrival);
    if (!firstDay || !lastDay) return [];

    const slots = [];
    for (let dayCursor = new Date(firstDay.getTime()); dayCursor <= lastDay; dayCursor = addDays(dayCursor, 1)) {
        [8, 16].forEach(hour => {
            const slotDate = new Date(dayCursor.getTime());
            slotDate.setHours(hour, 0, 0, 0);
            if (slotDate < firstDeparture || slotDate > lastArrival) return;

            const activeEntry = scheduledEntries.find(entry => slotDate >= entry.departure && slotDate < entry.arrival)
                || [...scheduledEntries].reverse().find(entry => slotDate >= entry.departure)
                || scheduledEntries[0];
            const anchor = activeEntry ? anchors.get(activeEntry.id) || null : null;
            if (!anchor) return;

            slots.push({
                key: `${slotDate.toISOString()}|${activeEntry.id}`,
                label: formatVoyageAgendaHalfDayLabel(slotDate),
                slotDate,
                entryId: activeEntry.id,
                entryTitle: activeEntry.title,
                anchor
            });
        });
    }

    return slots;
}

function renderVoyageWeatherCardHtml(slot, weather, options = {}) {
    const { error = null, loading = false } = options;
    if (loading) {
        return `
            <article class="voyage-weather-card is-loading" data-voyage-weather-slot="${escapeHtml(slot.key)}">
                <div class="voyage-weather-card__topline">${escapeHtml(slot.label)}</div>
                <div class="voyage-weather-card__body">
                    <div class="voyage-weather-card__icon">…</div>
                    <div>
                        <div class="voyage-weather-card__title">${escapeHtml(slot.entryTitle)}</div>
                        <div class="voyage-weather-card__meta">${escapeHtml(t('Chargement météo…', 'Cargando meteo…', 'Loading weather…'))}</div>
                    </div>
                </div>
            </article>`;
    }

    if (error || !weather) {
        return `
            <article class="voyage-weather-card voyage-weather-card--unavailable" data-voyage-weather-slot="${escapeHtml(slot.key)}">
                <div class="voyage-weather-card__topline">${escapeHtml(slot.label)}</div>
                <div class="voyage-weather-card__body">
                    <div class="voyage-weather-card__icon">◌</div>
                    <div>
                        <div class="voyage-weather-card__title">${escapeHtml(slot.entryTitle)}</div>
                        <div class="voyage-weather-card__meta">${escapeHtml(t('Prévision indisponible', 'Previsión no disponible', 'Forecast unavailable'))}</div>
                    </div>
                </div>
            </article>`;
    }

    const impact = computeWeatherImpactLabel(weather);
    const impactClassName = String(impact.className || '').replace(/\bweather-card\b/g, '').trim();
    const windLabel = Number.isFinite(weather.windSpeed) ? `${weather.windSpeed.toFixed(0)} kn` : 'N/A';
    const waveLabel = Number.isFinite(weather.waveHeight) ? `${weather.waveHeight.toFixed(1)} m` : 'N/A';
    const tempLabel = Number.isFinite(weather.temperature) ? `${weather.temperature.toFixed(0)}°C` : 'N/A';
    const rainLabel = Number.isFinite(weather.precipitation) ? `${weather.precipitation.toFixed(1)} mm` : 'N/A';
    const directionLabel = Number.isFinite(weather.windDirection) ? `${Math.round(weather.windDirection)}° ${degreesToCardinalFr(weather.windDirection)}` : 'N/A';
    const summaryLabel = weatherCodeToLabel(weather.weatherCode);

    return `
        <article class="voyage-weather-card ${escapeHtml(impactClassName)}" data-voyage-weather-slot="${escapeHtml(slot.key)}">
            <div class="voyage-weather-card__topline">${escapeHtml(slot.label)}</div>
            <div class="voyage-weather-card__body">
                <div class="voyage-weather-card__icon">${escapeHtml(getVoyageWeatherIcon(weather.weatherCode))}</div>
                <div>
                    <div class="voyage-weather-card__title">${escapeHtml(slot.entryTitle)}</div>
                    <div class="voyage-weather-card__meta">${escapeHtml(summaryLabel)} · ${escapeHtml(impact.text)} · ${escapeHtml(directionLabel)}</div>
                </div>
            </div>
            <div class="voyage-weather-card__metrics">
                <span>${escapeHtml(t('Vent', 'Viento', 'Wind'))}: <strong>${escapeHtml(windLabel)}</strong></span>
                <span>${escapeHtml(t('Vagues', 'Olas', 'Waves'))}: <strong>${escapeHtml(waveLabel)}</strong></span>
                <span>${escapeHtml(t('Air', 'Aire', 'Air'))}: <strong>${escapeHtml(tempLabel)}</strong></span>
                <span>${escapeHtml(t('Pluie', 'Lluvia', 'Rain'))}: <strong>${escapeHtml(rainLabel)}</strong></span>
            </div>
        </article>`;
}

function renderVoyageAgendaWeatherSummary(timeline) {
    const slots = buildVoyageAgendaWeatherSlots(timeline);
    if (!slots.length) return '';

    return `
        <section class="voyage-weather-summary-card">
            <div class="voyage-weather-summary-card__header">
                <div>
                    <div class="voyage-agenda-voyage__stat-label">${escapeHtml(t('Météo du voyage', 'Meteo del viaje', 'Trip weather'))}</div>
                    <div class="voyage-agenda-voyage__timeline-note">${escapeHtml(t('Résumé prévu par demi-journée le long du voyage.', 'Resumen previsto por medias jornadas a lo largo del viaje.', 'Half-day forecast summary along the trip.'))}</div>
                </div>
            </div>
            <div id="voyageAgendaWeatherSummary" class="voyage-weather-summary-grid">
                ${slots.map(slot => renderVoyageWeatherCardHtml(slot, null, { loading: true })).join('')}
            </div>
        </section>`;
}

async function hydrateVoyageAgendaWeatherSummary(timeline, hydrationToken) {
    const container = document.getElementById('voyageAgendaWeatherSummary');
    if (!container) return;

    const slots = buildVoyageAgendaWeatherSlots(timeline);
    if (!slots.length) return;

    const results = await Promise.all(slots.map(async slot => {
        try {
            const date = `${slot.slotDate.getFullYear()}-${String(slot.slotDate.getMonth() + 1).padStart(2, '0')}-${String(slot.slotDate.getDate()).padStart(2, '0')}`;
            const hour = `${String(slot.slotDate.getHours()).padStart(2, '0')}:00`;
            const weather = await getWeatherAtDateHour(slot.anchor.lat, slot.anchor.lng, date, hour);
            return { slot, weather, error: null };
        } catch (error) {
            return { slot, weather: null, error };
        }
    }));

    if (hydrationToken !== voyageAgendaWeatherHydrationToken) return;
    container.innerHTML = results.map(result => renderVoyageWeatherCardHtml(result.slot, result.weather, { error: result.error })).join('');
}

function getVoyageEntryAnchorPoint(entry) {
    if (entry?.type === 'stop') {
        const lat = parseOptionalCoordinate(entry?.item?.waypointLat, -90, 90);
        const lng = parseOptionalCoordinate(entry?.item?.waypointLng, -180, 180);
        if (Number.isFinite(lat) && Number.isFinite(lng)) {
            return { lat, lng };
        }
    }
    if (entry?.type === 'route') {
        const points = Array.isArray(entry?.route?.points) ? entry.route.points : [];
        const lastPoint = points[points.length - 1];
        const lat = Number(lastPoint?.lat);
        const lng = Number(lastPoint?.lon ?? lastPoint?.lng);
        if (Number.isFinite(lat) && Number.isFinite(lng)) {
            return { lat, lng };
        }
    }
    return null;
}

function buildVoyagePreviewGeometry(timeline) {
    const segments = [];
    const markers = [];
    let previousAnchor = null;

    timeline.forEach((entry, index) => {
        if (entry.type === 'route') {
            const points = Array.isArray(entry?.route?.points) ? entry.route.points : [];
            const latlngs = points
                .map(point => {
                    const lat = Number(point?.lat);
                    const lng = Number(point?.lon ?? point?.lng);
                    return Number.isFinite(lat) && Number.isFinite(lng) ? [lat, lng] : null;
                })
                .filter(Boolean);

            if (latlngs.length >= 2) {
                const arrivalLabel = entry.arrival ? formatDateTimeLocalLabel(entry.arrival) : '';
                segments.push({
                    latlngs,
                    title: entry.title,
                    detailLabel: arrivalLabel,
                    type: 'route',
                    itemId: entry.id,
                    isDerived: !entry.item?.departureDateTime
                });
                if (index === 0) {
                    markers.push({
                        latlng: latlngs[0],
                        label: `D1`,
                        title: entry.title,
                        detailLabel: entry.departure ? formatDateTimeLocalLabel(entry.departure) : '',
                        itemId: entry.id,
                        kind: 'departure'
                    });
                }
                const endPoint = latlngs[latlngs.length - 1];
                markers.push({
                    latlng: endPoint,
                    label: `E${index + 1}`,
                    title: entry.title,
                    detailLabel: arrivalLabel,
                    itemId: entry.id,
                    kind: 'arrival'
                });
                previousAnchor = { lat: endPoint[0], lng: endPoint[1] };
            }
            return;
        }

        const stopAnchor = getVoyageEntryAnchorPoint(entry) || previousAnchor;
        if (stopAnchor) {
            markers.push({
                latlng: [stopAnchor.lat, stopAnchor.lng],
                label: `M${index + 1}`,
                title: entry.title,
                detailLabel: entry.arrival ? formatDateTimeLocalLabel(entry.arrival) : '',
                itemId: entry.id,
                kind: 'stop'
            });
            previousAnchor = { lat: stopAnchor.lat, lng: stopAnchor.lng };
        }
    });

    return { segments, markers };
}

function renderVoyagePreviewMap(timeline) {
    const mapNode = document.getElementById('voyageAgendaMap');
    const emptyNode = document.getElementById('voyageAgendaMapEmpty');
    if (!mapNode || !emptyNode) return;

    const geometry = buildVoyagePreviewGeometry(timeline || []);
    const currentPlanId = String(selectedVoyagePlanId || '').trim();
    const currentFocusItemId = String(activeVoyageMapItemId || '').trim();
    const geometrySignature = geometry.segments.map(segment => {
        const firstPoint = segment.latlngs[0] || null;
        const lastPoint = segment.latlngs[segment.latlngs.length - 1] || null;
        return [
            'segment',
            String(segment.itemId || ''),
            segment.latlngs.length,
            firstPoint ? `${Number(firstPoint.lat).toFixed(4)},${Number(firstPoint.lng).toFixed(4)}` : '',
            lastPoint ? `${Number(lastPoint.lat).toFixed(4)},${Number(lastPoint.lng).toFixed(4)}` : ''
        ].join(':');
    }).concat(geometry.markers.map(marker => [
        'marker',
        String(marker.itemId || ''),
        marker.kind,
        `${Number(marker.latlng?.lat).toFixed(4)},${Number(marker.latlng?.lng).toFixed(4)}`
    ].join(':'))).join('|');
    const hasGeometry = geometry.segments.length > 0 || geometry.markers.length > 0;
    emptyNode.style.display = hasGeometry ? 'none' : 'flex';

    if (!hasGeometry) {
        if (voyagePreviewOverlayLayer && voyagePreviewMap) {
            voyagePreviewMap.removeLayer(voyagePreviewOverlayLayer);
            voyagePreviewOverlayLayer = null;
        }
        voyagePreviewLastGeometrySignature = '';
        voyagePreviewLastFocusItemId = currentFocusItemId;
        voyagePreviewLastPlanId = currentPlanId;
        return;
    }

    const shouldPreserveView = !!voyagePreviewLastViewState
        && voyagePreviewLastPlanId === currentPlanId
        && voyagePreviewLastFocusItemId === currentFocusItemId
        && voyagePreviewLastGeometrySignature === geometrySignature;

    if (voyagePreviewMap && voyagePreviewMapContainer !== mapNode) {
        const center = typeof voyagePreviewMap.getCenter === 'function' ? voyagePreviewMap.getCenter() : null;
        const zoom = typeof voyagePreviewMap.getZoom === 'function' ? voyagePreviewMap.getZoom() : null;
        voyagePreviewLastViewState = center && Number.isFinite(zoom)
            ? { center, zoom }
            : null;
        voyagePreviewMap.remove();
        voyagePreviewMap = null;
        voyagePreviewOverlayLayer = null;
        voyagePreviewMapContainer = null;
    }

    if (!voyagePreviewMap) {
        voyagePreviewMap = L.map(mapNode, {
            zoomControl: true,
            attributionControl: false
        }).setView([39.5, 2.8], 6);
        voyagePreviewMapContainer = mapNode;

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap',
            crossOrigin: true
        }).addTo(voyagePreviewMap);
    }

    if (voyagePreviewOverlayLayer && voyagePreviewMap.hasLayer(voyagePreviewOverlayLayer)) {
        voyagePreviewMap.removeLayer(voyagePreviewOverlayLayer);
    }

    const layers = [];
    const focusLayers = [];
    geometry.segments.forEach(segment => {
        const isFocused = activeVoyageMapItemId && segment.itemId === activeVoyageMapItemId;
        const routeTooltip = segment.detailLabel ? `${segment.title} · ${segment.detailLabel}` : segment.title;
        const routeLayer = L.polyline(segment.latlngs, {
            color: isFocused ? '#fff1a6' : (segment.isDerived ? '#f6c66e' : '#8fe7ff'),
            weight: isFocused ? 6 : (segment.isDerived ? 3 : 4),
            opacity: 0.9,
            dashArray: segment.isDerived ? '8 6' : null
        }).bindTooltip(routeTooltip, {
            permanent: true,
            direction: 'center',
            className: 'voyage-map-route-tooltip'
        });
        layers.push(routeLayer);
        if (isFocused) focusLayers.push(routeLayer);
    });

    geometry.markers.forEach(marker => {
        const isFocused = activeVoyageMapItemId && marker.itemId === activeVoyageMapItemId;
        const fillColor = marker.kind === 'stop'
            ? '#ff9a3a'
            : (marker.kind === 'departure' ? '#6ee7a8' : '#7cc9ff');
        const markerTooltip = marker.detailLabel
            ? `${marker.label} · ${marker.title} · ${marker.detailLabel}`
            : `${marker.label} · ${marker.title}`;
        const markerLayer = L.circleMarker(marker.latlng, {
            radius: isFocused ? 9 : 7,
            color: isFocused ? '#fff1a6' : '#ffffff',
            weight: isFocused ? 3 : 2,
            fillColor,
            fillOpacity: 0.95
        }).bindTooltip(markerTooltip, {
            permanent: true,
            direction: marker.kind === 'stop' ? 'top' : 'right',
            className: marker.kind === 'stop' ? 'voyage-map-stop-tooltip' : 'voyage-map-marker-tooltip'
        });
        layers.push(markerLayer);
        if (isFocused) focusLayers.push(markerLayer);
    });

    voyagePreviewOverlayLayer = L.layerGroup(layers).addTo(voyagePreviewMap);

    if (shouldPreserveView && voyagePreviewLastViewState?.center && Number.isFinite(voyagePreviewLastViewState?.zoom)) {
        voyagePreviewMap.setView(voyagePreviewLastViewState.center, voyagePreviewLastViewState.zoom, { animate: false });
    } else if (focusLayers.length > 0) {
        const focusBounds = L.latLngBounds([]);
        focusLayers.forEach(layer => {
            if (typeof layer.getBounds === 'function') {
                focusBounds.extend(layer.getBounds());
                return;
            }
            if (typeof layer.getLatLng === 'function') {
                focusBounds.extend(layer.getLatLng());
            }
        });
        if (focusBounds.isValid()) {
            voyagePreviewMap.fitBounds(focusBounds, { padding: [36, 36], maxZoom: 11 });
        }
    } else {
        const boundsPoints = [];
        geometry.segments.forEach(segment => boundsPoints.push(...segment.latlngs));
        geometry.markers.forEach(marker => boundsPoints.push(marker.latlng));
        if (boundsPoints.length > 0) {
            voyagePreviewMap.fitBounds(boundsPoints, { padding: [24, 24], animate: false });
        }
    }

    const finalCenter = typeof voyagePreviewMap.getCenter === 'function' ? voyagePreviewMap.getCenter() : null;
    const finalZoom = typeof voyagePreviewMap.getZoom === 'function' ? voyagePreviewMap.getZoom() : null;
    voyagePreviewLastViewState = finalCenter && Number.isFinite(finalZoom)
        ? { center: finalCenter, zoom: finalZoom }
        : null;
    voyagePreviewLastPlanId = currentPlanId;
    voyagePreviewLastFocusItemId = currentFocusItemId;
    voyagePreviewLastGeometrySignature = geometrySignature;

    window.setTimeout(() => {
        try {
            voyagePreviewMap.invalidateSize(false);
        } catch (_error) {
            // Ignore transient map sizing errors during rerender.
        }
    }, 0);
}

function formatLocalDateKey(date) {
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
    return `${String(date.getFullYear()).padStart(4, '0')}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

function formatVoyageMealDateLabel(dateKey) {
    const parsed = parseDateTimeLocalValue(`${String(dateKey || '').trim()}T12:00`);
    if (!(parsed instanceof Date) || Number.isNaN(parsed.getTime())) return String(dateKey || '');
    return parsed.toLocaleDateString(getCurrentLocale(), {
        weekday: 'short',
        day: '2-digit',
        month: 'short'
    });
}

function splitFoodTerms(rawText) {
    return String(rawText || '')
        .toLowerCase()
        .split(/[;,/\n]+/)
        .map(item => item.trim())
        .filter(Boolean);
}

function getVoyageMealPlanningDays(timeline) {
    const scheduledEntries = (Array.isArray(timeline) ? timeline : []).filter(entry => entry.departure instanceof Date || entry.arrival instanceof Date);
    const firstEntry = scheduledEntries.find(entry => entry.departure instanceof Date || entry.arrival instanceof Date) || null;
    const lastEntry = [...scheduledEntries].reverse().find(entry => entry.arrival instanceof Date || entry.departure instanceof Date) || null;
    const firstDate = startOfLocalDay(firstEntry?.departure || firstEntry?.arrival || null);
    const lastDate = startOfLocalDay(lastEntry?.arrival || lastEntry?.departure || null);
    if (!(firstDate instanceof Date) || !(lastDate instanceof Date)) return [];

    const days = [];
    for (let cursor = new Date(firstDate.getTime()); cursor <= lastDate; cursor = addDays(cursor, 1)) {
        const dayStart = new Date(cursor.getTime());
        const dayEnd = addDays(dayStart, 1);
        const hasNavigation = scheduledEntries.some(entry => entry.type === 'route'
            && entry.departure instanceof Date
            && entry.arrival instanceof Date
            && entry.arrival > dayStart
            && entry.departure < dayEnd);
        days.push({
            date: formatLocalDateKey(dayStart),
            dayType: hasNavigation ? 'navigation' : 'mouillage'
        });
    }
    return days;
}

function resolveVoyageCommonDietType(assignedCrew) {
    const dietTypes = (Array.isArray(assignedCrew) ? assignedCrew : []).map(entry => sanitizeCrewDietaryProfile(entry?.dietaryProfile || {}).dietType);
    if (dietTypes.includes('vegan')) return 'vegan';
    if (dietTypes.includes('vegetarian')) return 'vegetarian';
    if (dietTypes.includes('pescatarian')) return 'pescatarian';
    if (dietTypes.includes('glutenfree')) return 'glutenfree';
    return 'omnivore';
}

function collectVoyageForbiddenFoodTerms(assignedCrew) {
    return Array.from(new Set((Array.isArray(assignedCrew) ? assignedCrew : []).flatMap(entry => {
        const profile = sanitizeCrewDietaryProfile(entry?.dietaryProfile || {});
        return splitFoodTerms(`${profile.allergiesText};${profile.dislikesText}`);
    })));
}

function templateSupportsDiet(template, dietType) {
    const safeDiet = String(template?.diet || 'omnivore').trim();
    if (dietType === 'vegan') return safeDiet === 'vegan';
    if (dietType === 'vegetarian') return ['vegan', 'vegetarian'].includes(safeDiet);
    if (dietType === 'pescatarian') return ['vegan', 'vegetarian', 'pescatarian'].includes(safeDiet);
    if (dietType === 'glutenfree') {
        const ingredientBlob = (Array.isArray(template?.ingredients) ? template.ingredients : []).map(item => String(item?.name || '').toLowerCase()).join(' ');
        return !/(wrap|pain|pates|pasta|baguette)/.test(ingredientBlob);
    }
    return true;
}

function templateMatchesRestrictions(template, forbiddenTerms) {
    const haystack = `${String(template?.title || '')} ${(Array.isArray(template?.ingredients) ? template.ingredients.map(item => item?.name || '').join(' ') : '')}`.toLowerCase();
    return !(Array.isArray(forbiddenTerms) ? forbiddenTerms : []).some(term => term && haystack.includes(term));
}

function pickVoyageMealTemplate(dayType, serviceKey, assignedCrew, usedTitles = new Set()) {
    const safeDayType = normalizeVoyageMealDayType(dayType);
    const templates = VOYAGE_MEAL_TEMPLATE_LIBRARY?.[safeDayType]?.[serviceKey] || [];
    const dominantDiet = resolveVoyageCommonDietType(assignedCrew);
    const forbiddenTerms = collectVoyageForbiddenFoodTerms(assignedCrew);
    const filtered = templates.filter(template => templateSupportsDiet(template, dominantDiet) && templateMatchesRestrictions(template, forbiddenTerms));
    const candidateList = filtered.length ? filtered : templates;
    const notUsed = candidateList.filter(template => !usedTitles.has(String(template?.title || '')));
    return (notUsed[0] || candidateList[0] || null);
}

function buildVoyageMealIngredientsFromTemplate(template, crewCount) {
    const safeCrewCount = Math.max(1, Number(crewCount || 0) || 1);
    return (Array.isArray(template?.ingredients) ? template.ingredients : []).map((ingredient, index) => sanitizeVoyageMealIngredient({
        id: `generated-${String(template?.title || 'meal').toLowerCase().replace(/[^a-z0-9]+/g, '-')}-${index}`,
        name: ingredient?.name,
        category: ingredient?.category,
        unit: ingredient?.unit,
        quantity: Math.round((Number(ingredient?.quantityPerPerson || 0) * safeCrewCount) * 100) / 100
    }, index)).filter(item => item.name);
}

function generateVoyageMealPlanEntries(plan) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    const assignedCrew = getVoyageAssignedCrewMembers(safePlan);
    const days = getVoyageMealPlanningDays(computeVoyagePlanTimeline(safePlan));
    const usedTitles = new Set();
    return days.map((day, index) => {
        const middayTemplate = pickVoyageMealTemplate(day.dayType, 'midday', assignedCrew, usedTitles);
        if (middayTemplate?.title) usedTitles.add(middayTemplate.title);
        const eveningTemplate = pickVoyageMealTemplate(day.dayType, 'evening', assignedCrew, usedTitles);
        if (eveningTemplate?.title) usedTitles.add(eveningTemplate.title);
        return sanitizeVoyageMealEntry({
            id: `voyage-meal-${safePlan.id}-${index}`,
            date: day.date,
            dayType: day.dayType,
            middayTitle: middayTemplate?.title || '',
            middayNotes: middayTemplate?.notes || '',
            middayIngredients: buildVoyageMealIngredientsFromTemplate(middayTemplate, assignedCrew.length),
            eveningTitle: eveningTemplate?.title || '',
            eveningNotes: eveningTemplate?.notes || '',
            eveningIngredients: buildVoyageMealIngredientsFromTemplate(eveningTemplate, assignedCrew.length),
            notes: ''
        }, index);
    });
}

function mergeVoyageProvisioningItems(items) {
    const merged = new Map();
    (Array.isArray(items) ? items : []).forEach((entry, index) => {
        const safeEntry = sanitizeVoyageProvisioningItem(entry, index);
        const key = `${safeEntry.scope}|${safeEntry.name.toLowerCase()}|${safeEntry.unit.toLowerCase()}|${safeEntry.stage}`;
        const existing = merged.get(key);
        if (!existing) {
            merged.set(key, safeEntry);
            return;
        }
        merged.set(key, sanitizeVoyageProvisioningItem({
            ...existing,
            quantity: Math.round((existing.quantity + safeEntry.quantity) * 100) / 100,
            checked: existing.checked && safeEntry.checked,
            source: existing.source === 'manual' || safeEntry.source === 'manual' ? 'manual' : 'auto'
        }, index));
    });
    return Array.from(merged.values()).sort((a, b) => a.scope.localeCompare(b.scope) || a.category.localeCompare(b.category) || a.name.localeCompare(b.name));
}

function buildVoyageProvisioningItemsFromPlan(plan, { includeMonthlyDefaults = false } = {}) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    const autoMealItems = safePlan.mealPlan.flatMap((meal, mealIndex) => {
        const ingredients = [];
        (meal.middayIngredients || []).forEach((entry, index) => {
            ingredients.push(sanitizeVoyageProvisioningItem({
                id: `meal-midday-${meal.id}-${index}`,
                name: entry.name,
                category: entry.category,
                quantity: entry.quantity,
                unit: entry.unit,
                scope: 'voyage_food',
                stage: 'predeparture',
                source: 'auto',
                checked: false,
                notes: meal.middayTitle || ''
            }, mealIndex + index));
        });
        (meal.eveningIngredients || []).forEach((entry, index) => {
            ingredients.push(sanitizeVoyageProvisioningItem({
                id: `meal-evening-${meal.id}-${index}`,
                name: entry.name,
                category: entry.category,
                quantity: entry.quantity,
                unit: entry.unit,
                scope: 'voyage_food',
                stage: 'predeparture',
                source: 'auto',
                checked: false,
                notes: meal.eveningTitle || ''
            }, mealIndex + index));
        });
        return ingredients;
    });

    const monthlyItems = includeMonthlyDefaults
        ? VOYAGE_MONTHLY_PROVISIONING_DEFAULTS.map((entry, index) => sanitizeVoyageProvisioningItem({
            ...entry,
            id: `monthly-default-${index}`,
            source: 'auto'
        }, index))
        : [];

    return mergeVoyageProvisioningItems(autoMealItems.concat(monthlyItems));
}

function updateVoyagePlanManagedData(planId, updater, { rerender = true, statusMessage = '', markCloudDirty = true } = {}) {
    let didUpdate = false;
    const nextPlans = voyagePlans.map((plan, index) => {
        if (plan.id !== planId) return plan;
        didUpdate = true;
        const safePlan = sanitizeVoyagePlan(plan, index);
        const nextPlan = typeof updater === 'function' ? updater(safePlan) : safePlan;
        return sanitizeVoyagePlan({
            ...nextPlan,
            updatedAt: new Date().toISOString()
        }, index);
    });
    if (!didUpdate) return false;
    setVoyagePlans(nextPlans, { markCloudDirty });
    if (rerender) renderVoyageAgendaPanel();
    if (statusMessage) setVoyagePlanStatus(statusMessage);
    return true;
}

function regenerateVoyageMealPlan(planId) {
    const plan = voyagePlans.find(entry => entry.id === planId) || null;
    if (!plan) return false;
    return updateVoyagePlanManagedData(planId, safePlan => ({
        ...safePlan,
        mealPlan: generateVoyageMealPlanEntries(safePlan)
    }), { statusMessage: t('Menus midi/soir générés pour le voyage.', 'Menús comida/cena generados para el viaje.', 'Lunch/dinner menus generated for the trip.') });
}

function regenerateVoyageProvisioning(planId, { includeMonthlyDefaults = false } = {}) {
    const plan = voyagePlans.find(entry => entry.id === planId) || null;
    if (!plan) return false;
    return updateVoyagePlanManagedData(planId, safePlan => {
        const manualItems = safePlan.provisioningItems.filter(item => item.source !== 'auto');
        return {
            ...safePlan,
            provisioningItems: mergeVoyageProvisioningItems(manualItems.concat(buildVoyageProvisioningItemsFromPlan(safePlan, { includeMonthlyDefaults })))
        };
    }, { statusMessage: t('Liste d\'avitaillement recalculée.', 'Lista de avituallamiento recalculada.', 'Provisioning list recalculated.') });
}

function roundAgendaProvisioningQuantity(quantity, unit) {
    const safeUnit = String(unit || '').toLowerCase();
    const value = Number(quantity || 0);
    if (!Number.isFinite(value) || value <= 0) return 0;
    if (['pieces', 'piece', 'rouleaux', 'rouleau', 'paquets', 'paquet', 'flacons', 'flacon', 'bouteilles', 'bouteille', 'sachets', 'sachet', 'boites', 'boite'].includes(safeUnit)) {
        return Math.ceil(value);
    }
    if (safeUnit === 'g') {
        return Math.ceil(value / 50) * 50;
    }
    if (safeUnit === 'l') {
        return Math.ceil(value * 2) / 2;
    }
    return Math.round(value * 10) / 10;
}

function mergeAgendaProvisioningItems(items) {
    const merged = new Map();
    (Array.isArray(items) ? items : []).forEach((entry, index) => {
        const safeEntry = sanitizeVoyageProvisioningItem(entry, index);
        if (!safeEntry.name || safeEntry.quantity <= 0) return;
        const key = `${safeEntry.scope}|${safeEntry.stage}|${safeEntry.category}|${safeEntry.name.toLowerCase()}|${safeEntry.unit.toLowerCase()}`;
        const existing = merged.get(key);
        if (!existing) {
            merged.set(key, safeEntry);
            return;
        }
        merged.set(key, sanitizeVoyageProvisioningItem({
            ...existing,
            quantity: existing.quantity + safeEntry.quantity,
            notes: [existing.notes, safeEntry.notes].filter(Boolean).join(' | ')
        }, index));
    });

    return Array.from(merged.values()).map((entry, index) => sanitizeVoyageProvisioningItem({
        ...entry,
        quantity: roundAgendaProvisioningQuantity(entry.quantity, entry.unit)
    }, index)).sort((a, b) => a.scope.localeCompare(b.scope) || a.stage.localeCompare(b.stage) || a.category.localeCompare(b.category) || a.name.localeCompare(b.name));
}

function buildAgendaMonthlyBoatSupplyItems({ personDays = 0, boatDays = 0 } = {}) {
    return AGENDA_MONTHLY_BOAT_SUPPLY_RULES.map((rule, index) => sanitizeVoyageProvisioningItem({
        id: `agenda-monthly-${index}`,
        name: rule.name,
        category: rule.category,
        unit: rule.unit,
        scope: rule.scope,
        stage: rule.stage,
        source: 'auto',
        checked: false,
        quantity: (Number(rule.quantityPerPersonDay || 0) * Math.max(0, personDays)) + (Number(rule.quantityPerBoatDay || 0) * Math.max(0, boatDays)),
        notes: rule.notes
    }, index)).filter(entry => entry.quantity > 0);
}

function formatProvisioningQuantityLabel(quantity, unit) {
    const safeQuantity = Number(quantity || 0);
    const safeUnit = String(unit || '').trim();
    const decimals = Number.isInteger(safeQuantity) ? 0 : 1;
    return `${safeQuantity.toFixed(decimals)} ${safeUnit}`.trim();
}

function getAgendaProvisioningScopeLabel(scope) {
    if (scope === 'monthly_boat') return t('Vie a bord', 'Vida a bordo', 'Life on board');
    return t('Cuisine equipage', 'Comida tripulacion', 'Crew meals');
}

function getAgendaProvisioningStageLabel(stage) {
    if (stage === 'escale') return t('A recharger en escale', 'A reponer en escala', 'Restock at stopover');
    if (stage === 'stock') return t('Stock permanent du bord', 'Stock permanente a bordo', 'Permanent onboard stock');
    return t('A embarquer avant depart', 'A embarcar antes de salir', 'Load before departure');
}

function getAgendaProvisioningCategoryLabel(category) {
    const labels = {
        pantry: t('Epicerie', 'Despensa', 'Pantry'),
        protein: t('Proteines', 'Proteinas', 'Protein'),
        fresh: t('Frais', 'Fresco', 'Fresh'),
        bakery: t('Boulangerie', 'Panaderia', 'Bakery'),
        household: t('Vie de bord', 'Vida a bordo', 'Household'),
        cleaning: t('Entretien', 'Limpieza', 'Cleaning'),
        water: t('Eau', 'Agua', 'Water'),
        drinks: t('Boissons', 'Bebidas', 'Drinks'),
        food: t('Snacks', 'Snacks', 'Snacks')
    };
    return labels[String(category || '').trim()] || String(category || '').trim() || t('Divers', 'Varios', 'Misc');
}

function buildAgendaProvisioningMonthLabel(dateKeys) {
    const labels = Array.from(new Set((Array.isArray(dateKeys) ? dateKeys : []).map(value => {
        const date = parseDateTimeLocalValue(`${value}T12:00`);
        if (!(date instanceof Date) || Number.isNaN(date.getTime())) return '';
        return date.toLocaleDateString(getCurrentLocale(), { month: 'long', year: 'numeric' });
    }).filter(Boolean)));
    return labels.join(' + ');
}

function buildAgendaProvisioningSnapshot() {
    const entries = getFilteredVoyagePlanEntries().filter(({ plan, timeline }) => normalizeVoyagePlanStatus(plan.status) === 'planned' && timeline.length > 0);
    const tripSummaries = [];
    const agendaItems = [];
    const dayKeys = new Set();
    let totalPersonDays = 0;
    let totalCrewSlots = 0;

    entries.forEach(({ plan, timeline }, planIndex) => {
        const safePlan = sanitizeVoyagePlan(plan, planIndex);
        const crewMembers = getVoyageAssignedCrewMembers(safePlan);
        const effectiveCrewCount = Math.max(1, crewMembers.length || 0);
        const planningDays = getVoyageMealPlanningDays(timeline);
        planningDays.forEach(day => dayKeys.add(day.date));
        const personDays = planningDays.length * effectiveCrewCount;
        totalPersonDays += personDays;
        totalCrewSlots += effectiveCrewCount;

        const mealPlan = safePlan.mealPlan.length ? safePlan.mealPlan : generateVoyageMealPlanEntries(safePlan);
        const generatedPlan = sanitizeVoyagePlan({
            ...safePlan,
            mealPlan,
            provisioningItems: safePlan.provisioningItems.filter(item => item.source === 'manual')
        }, planIndex);

        const generatedItems = buildVoyageProvisioningItemsFromPlan(generatedPlan, { includeMonthlyDefaults: false }).map((item, itemIndex) => sanitizeVoyageProvisioningItem({
            ...item,
            notes: [item.notes, safePlan.name].filter(Boolean).join(' · ')
        }, itemIndex));
        const manualItems = safePlan.provisioningItems.filter(item => item.source === 'manual').map((item, itemIndex) => sanitizeVoyageProvisioningItem({
            ...item,
            notes: [item.notes, safePlan.name].filter(Boolean).join(' · ')
        }, itemIndex));
        agendaItems.push(...generatedItems, ...manualItems);

        tripSummaries.push({
            id: safePlan.id,
            name: safePlan.name,
            crewNames: crewMembers.map(entry => getCrewMemberDisplayName(entry)),
            startDate: timeline.find(entry => entry.departure instanceof Date)?.departure || null,
            endDate: [...timeline].reverse().find(entry => entry.arrival instanceof Date)?.arrival || null,
            days: planningDays.length,
            personDays,
            mealEntries: mealPlan.length
        });
    });

    const sortedDayKeys = Array.from(dayKeys).sort();
    const boatDays = sortedDayKeys.length;
    const monthlyBoatItems = buildAgendaMonthlyBoatSupplyItems({ personDays: totalPersonDays, boatDays });
    const mergedItems = mergeAgendaProvisioningItems(agendaItems.concat(monthlyBoatItems));
    const distinctCrew = Array.from(new Set(entries.flatMap(({ plan }) => getVoyageAssignedCrewMembers(plan).map(entry => getCrewMemberDisplayName(entry))))).sort();

    return {
        tripSummaries,
        items: mergedItems,
        totalTrips: tripSummaries.length,
        totalPersonDays,
        totalCrewSlots,
        boatDays,
        distinctCrew,
        monthLabel: buildAgendaProvisioningMonthLabel(sortedDayKeys),
        generatedAt: new Date(),
        dateKeys: sortedDayKeys
    };
}

function buildAgendaProvisioningPdfFileName(snapshot) {
    const monthPart = String(snapshot?.monthLabel || 'agenda')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-z0-9\-_]+/gi, '_')
        .replace(/^_+|_+$/g, '')
        .slice(0, 40);
    const dateLabel = new Date().toISOString().slice(0, 10);
    return `ceibo_courses_mensuelles_${monthPart || 'agenda'}_${dateLabel}.pdf`;
}

