        '.print-shell > * { margin-bottom: 18px; }',
        '.print-shell > *:last-child { margin-bottom: 0; }',
        '.print-hero { padding: 24px; border-radius: 24px; background: linear-gradient(135deg, #0f395a, #1f628f 58%, #7ab6d8); color: #fff; }',
