function buildVoyageTourismPrompt(plan, timeline) {
    const safePlan = sanitizeVoyagePlan(plan || {}, 0);
    const safeTimeline = Array.isArray(timeline) ? timeline : [];
    const routeLegs = safeTimeline.filter(entry => entry?.type === 'route');
    const stopLegs = safeTimeline.filter(entry => entry?.type === 'stop');
    const orderedStops = stopLegs.map((entry, index) => {
        const start = entry?.departure instanceof Date ? formatDateTimeLocalLabel(entry.departure) : t('à préciser', 'por precisar', 'to be defined');
        const end = entry?.arrival instanceof Date ? formatDateTimeLocalLabel(entry.arrival) : t('à préciser', 'por precisar', 'to be defined');
        return `${index + 1}. ${entry.title} (${start} -> ${end})`;
    });
    const orderedRouteSummaries = routeLegs.map((entry, index) => {
        const departure = entry?.departure instanceof Date ? formatDateTimeLocalLabel(entry.departure) : t('à préciser', 'por precisar', 'to be defined');
        const arrival = entry?.arrival instanceof Date ? formatDateTimeLocalLabel(entry.arrival) : t('à préciser', 'por precisar', 'to be defined');
        const distance = Number.isFinite(entry?.distanceNm) ? `${entry.distanceNm.toFixed(1)} NM` : 'N/A';
        return `${index + 1}. ${entry.title} | ${entry.subtitle} | départ ${departure} | arrivée ${arrival} | distance ${distance}`;
    });

    const firstRoute = routeLegs[0] || null;
    const lastEntry = safeTimeline[safeTimeline.length - 1] || null;
    const tripStart = firstRoute?.title || firstRoute?.subtitle || safePlan.name;
    const tripEnd = lastEntry?.title || safePlan.name;
    const firstDeparture = firstRoute?.departure instanceof Date ? formatDateTimeLocalLabel(firstRoute.departure) : t('à préciser', 'por precisar', 'to be defined');
    const finalArrival = lastEntry?.arrival instanceof Date ? formatDateTimeLocalLabel(lastEntry.arrival) : t('à préciser', 'por precisar', 'to be defined');
    const totalDistance = routeLegs.reduce((sum, entry) => sum + (Number(entry?.distanceNm) || 0), 0);
    const crewNames = getVoyageAssignedCrewMembers(safePlan).map(entry => getCrewMemberDisplayName(entry));

    return [
        'Tu es un assistant de voyage spécialisé dans le nautisme, les itinéraires côtiers et les escales en bateau.',
        '',
        'Je prépare un voyage en bateau et je veux récupérer des informations touristiques utiles, fiables, concrètes et directement exploitables pour les escales prévues.',
        '',
        'Données du voyage :',
        `- Nom du voyage : ${safePlan.name || 'Voyage CEIBO'}`,
        `- Départ : ${tripStart}`,
        `- Arrivée : ${tripEnd}`,
        `- Fenêtre estimée : du ${firstDeparture} au ${finalArrival}`,
        `- Distance totale estimée : ${totalDistance > 0 ? `${totalDistance.toFixed(1)} NM` : 'à estimer'}`,
        `- Description du voyage : ${safePlan.description || 'Non renseignée'}`,
        `- Équipage : ${crewNames.length ? crewNames.join(', ') : 'Non précisé'}`,
        '',
        'Parcours détaillé dans l’ordre :',
        orderedRouteSummaries.length ? orderedRouteSummaries.join('\n') : '- Aucun tronçon détaillé disponible',
        '',
        'Escales / mouillages / arrêts prévus :',
        orderedStops.length ? orderedStops.join('\n') : '- Aucune escale détaillée disponible',
        '',
        'Ta mission :',
        '1. Analyser le parcours dans l’ordre réel des escales.',
        '2. Me proposer, pour chaque escale ou zone importante du trajet, les lieux touristiques à ne pas manquer.',
        '3. Suggérer des idées d’activités réalistes pour un équipage en escale courte ou moyenne.',
        '4. Donner de bonnes adresses de restaurants intéressants, locaux, typiques ou reconnus.',
        '5. Signaler les points d’intérêt emblématiques, les villages, criques, marchés, promenades, panoramas, musées ou expériences locales.',
        '6. Éviter les recommandations trop génériques ou éloignées du parcours réellement navigué.',
        '7. Si tu n’es pas certain d’une adresse précise, indique-le clairement au lieu d’inventer.',
        '',
        'Format de réponse attendu :',
        '- Commence par un résumé de 8 à 12 lignes du potentiel touristique global du voyage.',
        '- Puis fais une section par escale ou zone traversée, dans l’ordre du voyage.',
        '- Pour chaque escale, donne :',
        '  - pourquoi s’y arrêter',
        '  - 3 à 5 incontournables',
        '  - 2 à 4 idées d’activités',
        '  - 2 à 5 restaurants conseillés avec une justification courte',
        '  - une ambiance ou un conseil local',
        '- Termine par :',
        '  - top 5 absolu du parcours',
        '  - top 5 restaurants du voyage',
        '  - 3 expériences à ne pas rater',
        '  - 3 conseils pratiques pour profiter des escales',
        '',
        'Contraintes :',
        '- Réponse en français.',
        '- Style clair, concret, élégant, utile pour préparer un dossier de voyage.',
        '- Pas de blabla.',
        '- Pas d’invention.',
        '- Privilégier des recommandations réalistes pour des navigateurs en escale.'
    ].join('\n');
}

function fillVoyageLlmPromptTextarea() {
    const textarea = document.getElementById('voyageLlmPromptTextarea');
    if (!textarea) return false;

    const plan = getSelectedVoyagePlan();
    if (!plan) {
        textarea.value = '';
        setVoyageLlmPromptStatus(t('Sélectionne d\'abord un voyage.', 'Selecciona primero un viaje.', 'Select a trip first.'), true);
        return false;
    }

    const timeline = computeVoyagePlanTimeline(plan);
    if (!timeline.length) {
        textarea.value = '';
        setVoyageLlmPromptStatus(t('Ajoute au moins une étape au voyage pour générer le prompt.', 'Añade al menos una etapa al viaje para generar el prompt.', 'Add at least one leg to generate the prompt.'), true);
        return false;
    }

    textarea.value = buildVoyageTourismPrompt(plan, timeline);
    setVoyageLlmPromptStatus(t('Prompt généré pour le voyage actif.', 'Prompt generado para el viaje activo.', 'Prompt generated for the active trip.'));
    return true;
}

function closeVoyageLlmPromptModal() {
    const modal = document.getElementById('voyageLlmPromptModal');
    if (modal) modal.style.display = 'none';
}

function openVoyageLlmPromptModal() {
    const modal = document.getElementById('voyageLlmPromptModal');
    const textarea = document.getElementById('voyageLlmPromptTextarea');
    if (!modal || !textarea) return;

    modal.style.display = 'flex';
    const ok = fillVoyageLlmPromptTextarea();
    if (ok) {
        textarea.focus();
        textarea.select();
    }
}

async function copyVoyageLlmPromptToClipboard() {
    const textarea = document.getElementById('voyageLlmPromptTextarea');
    if (!textarea || !textarea.value.trim()) {
        setVoyageLlmPromptStatus(t('Aucun prompt à copier.', 'Ningún prompt para copiar.', 'No prompt to copy.'), true);
        return;
    }

    try {
        if (navigator.clipboard?.writeText) {
            await navigator.clipboard.writeText(textarea.value);
        } else {
            textarea.focus();
            textarea.select();
            document.execCommand('copy');
        }
        setVoyageLlmPromptStatus(t('Prompt copié dans le presse-papiers.', 'Prompt copiado al portapapeles.', 'Prompt copied to clipboard.'));
    } catch (_error) {
        textarea.focus();
        textarea.select();
        setVoyageLlmPromptStatus(t('Copie automatique impossible. Le prompt est sélectionné.', 'No se pudo copiar automáticamente. El prompt está seleccionado.', 'Automatic copy failed. The prompt is selected.'), true);
    }
}

function renderGooglePhotosPickerGrid(items) {
    const grid = document.getElementById('googlePhotosPickerGrid');
    if (!grid) return;

    if (!Array.isArray(items) || !items.length) {
        grid.innerHTML = `<div class="google-photos-modal__empty">${t('Aucune photo trouvée.', 'No se encontraron fotos.')}</div>`;
        return;
    }

    grid.innerHTML = items.map((item, index) => {
        const thumb = `${String(item.baseUrl || '')}=w260-h260-c`;
        const name = escapeHtml(String(item.filename || `Photo ${index + 1}`));
        const when = item.mediaMetadata?.creationTime
            ? new Date(item.mediaMetadata.creationTime).toLocaleDateString(getCurrentLocale())
            : '';
        return `<button type="button" class="google-photos-item" data-photo-index="${index}" title="${name}">
            <img src="${thumb}" alt="${name}">
            <span>${name}</span>
            <small>${escapeHtml(when)}</small>
        </button>`;
    }).join('');
}

async function requestGooglePhotosAccessToken({ forceConsent = false } = {}) {
    if (googlePhotosAccessToken && Date.now() < googlePhotosTokenExpiryMs - 5000) {
        return googlePhotosAccessToken;
    }

    const clientId = ensureGooglePhotosClientId();
    if (!clientId) throw new Error(t('Client ID Google manquant.', 'Falta Google Client ID.'));

    const oauth2 = window.google?.accounts?.oauth2;
    if (!oauth2?.initTokenClient) {
        throw new Error(t('SDK Google non chargé.', 'SDK de Google no cargado.'));
    }

    return new Promise((resolve, reject) => {
        const tokenClient = oauth2.initTokenClient({
            client_id: clientId,
            scope: 'https://www.googleapis.com/auth/photoslibrary.readonly',
            callback: (response) => {
                if (!response || response.error || !response.access_token) {
                    reject(new Error(String(response?.error || 'oauth_failed')));
                    return;
                }

                const expiresInSec = Math.max(30, Number(response.expires_in || 3600));
                googlePhotosAccessToken = String(response.access_token);
                googlePhotosTokenExpiryMs = Date.now() + (expiresInSec * 1000);
                resolve(googlePhotosAccessToken);
            },
            error_callback: (oauthError) => {
                const reason = String(oauthError?.type || oauthError?.message || 'oauth_popup_error');
                reject(new Error(reason));
            }
        });

        tokenClient.requestAccessToken({ prompt: forceConsent ? 'consent' : '' });
    });
}

async function fetchGooglePhotosMediaItems(pageToken = '') {
    const token = await requestGooglePhotosAccessToken();
    const body = {
        pageSize: 36,
        ...(pageToken ? { pageToken } : {})
    };

    const response = await fetch('https://photoslibrary.googleapis.com/v1/mediaItems:search', {
        method: 'POST',
        headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify(body)
    });

    if (!response.ok) {
        const details = await response.text();
        throw new Error(`Google Photos ${response.status}: ${details.slice(0, 180)}`);
    }

    const data = await response.json();
    const items = Array.isArray(data?.mediaItems)
        ? data.mediaItems.filter(item => item?.mimeType?.startsWith('image/') && item?.baseUrl)
        : [];

    return {
        items,
        nextPageToken: String(data?.nextPageToken || '')
    };
}

async function importGooglePhotoItemIntoWaypoint(item) {
    if (!item?.baseUrl) throw new Error('photo_invalid');

    setGooglePhotosPickerStatus(t('Import de la photo Google en cours...', 'Importando foto de Google...'));

    const imageUrl = `${String(item.baseUrl)}=w2000-h2000`;
    const response = await fetch(imageUrl);
    if (!response.ok) {
        throw new Error(`download_${response.status}`);
    }

    const blob = await response.blob();
    const mimeType = String(blob.type || 'image/jpeg');
    const fileName = String(item.filename || `google-photo-${Date.now()}.jpg`);
    const file = new File([blob], fileName, { type: mimeType });

    await handleWaypointPhotoInputChange({ target: { files: [file] } });
    closeGooglePhotosPickerModal();
    setGooglePhotosPickerStatus('');

    const status = document.getElementById('waypointPhotoStatus');
    if (status) {
        status.textContent = t('Photo Google importée: complète les infos puis sauvegarde le waypoint.', 'Foto Google importada: completa datos y guarda el waypoint.');
    }
}

async function openGooglePhotosPickerModal() {
    const modal = document.getElementById('googlePhotosPickerModal');
    const loadMoreBtn = document.getElementById('googlePhotosLoadMoreBtn');
    if (!modal) return;

    modal.style.display = 'flex';
    setGooglePhotosPickerStatus(t('Connexion Google Photos...', 'Conectando con Google Photos...'));

    try {
        const { items, nextPageToken } = await fetchGooglePhotosMediaItems('');
        googlePhotosPickerItems = items;
        googlePhotosPickerNextPageToken = nextPageToken;
        renderGooglePhotosPickerGrid(googlePhotosPickerItems);

        if (loadMoreBtn) {
            loadMoreBtn.style.display = googlePhotosPickerNextPageToken ? '' : 'none';
        }

        setGooglePhotosPickerStatus(t(`Photos disponibles: ${items.length}`, `Fotos disponibles: ${items.length}`));
    } catch (error) {
        const reason = String(error?.message || error);
        const help = buildGooglePhotosOAuthHelpMessage(error);
        setGooglePhotosPickerStatus(`${t('Connexion Google Photos impossible', 'No se puede conectar con Google Photos')}: ${reason}. ${help}`, true);
        const loadMore = document.getElementById('googlePhotosLoadMoreBtn');
        if (loadMore) loadMore.style.display = 'none';
    }
}

function estimateDataUrlSizeBytes(dataUrl) {
    const raw = String(dataUrl || '');
    const commaIndex = raw.indexOf(',');
    if (commaIndex === -1) return Math.max(0, raw.length);

    const meta = raw.slice(0, commaIndex).toLowerCase();
    const payload = raw.slice(commaIndex + 1);

    if (!meta.includes(';base64')) {
        try {
            return new TextEncoder().encode(decodeURIComponent(payload)).length;
        } catch (_error) {
            return Math.max(0, payload.length);
        }
    }

    const trimmed = payload.replace(/\s/g, '');
    const padding = trimmed.endsWith('==') ? 2 : (trimmed.endsWith('=') ? 1 : 0);
    return Math.max(0, Math.floor((trimmed.length * 3) / 4) - padding);
}

async function prepareDocumentForStorage(file, options = {}) {
    const maxSide = Number(options.maxSide) > 0 ? Number(options.maxSide) : 1280;
    const quality = Number(options.quality) > 0 ? Number(options.quality) : 0.55;
    const originalMime = String(file?.type || '').toLowerCase();
    const isImage = originalMime.startsWith('image/');

    if (!isImage) {
        const dataUrl = await imageFileToDataUrl(file);
        return {
            dataUrl,
            mimeType: originalMime,
            sizeBytes: Math.max(0, Number(file?.size || 0) || 0)
        };
    }

    const dataUrl = await imageFileToCompressedDataUrl(file, maxSide, quality);
    return {
        dataUrl,
        mimeType: 'image/jpeg',
        sizeBytes: estimateDataUrlSizeBytes(dataUrl)
    };
}

function buildWaypointPhotoPopupContent(entry, weatherHtml = '') {
    const title = entry.placeName ? escapeHtml(entry.placeName) : t('Mouillage noté', 'Fondeo valorado');
    const creator = String(entry?.creatorName || '').trim();
    const creatorLine = creator ? `<div>${t('Créateur', 'Creador')}: ${escapeHtml(creator)}</div>` : '';
    const comment = entry.comment ? `<div style="margin-top:6px;">${escapeHtml(entry.comment)}</div>` : '';
    const bottom = entry.bottomType ? `<div>${t('Fond', 'Fondo')}: ${escapeHtml(entry.bottomType)}</div>` : '';
    const image = entry.imageDataUrl
        ? `<img src="${entry.imageDataUrl}" alt="${t('Photo mouillage', 'Foto fondeo')}" style="margin-top:6px; width:100%; max-width:180px; border-radius:8px;">`
        : '';

    return `<strong>${title}</strong><br>` +
        `${entry.lat.toFixed(5)}, ${entry.lng.toFixed(5)}<br>` +
        `${t('Global', 'Global')}: ${starsLabel(entry.rating)} · ${t('Propreté', 'Limpieza')}: ${starsLabel(entry.cleanliness)} · ${t('Profondeur', 'Profundidad')}: ${entry.depthMeters} m<br>` +
        `${t('Protection', 'Protección')}: ${escapeHtml(formatProtectionList(entry.protection))}` +
        `${creatorLine}` +
        `${bottom}` +
        `${comment}` +
        `${weatherHtml}` +
        `${image}`;
}

async function enrichWaypointPhotoPopupWithCurrentWeather(marker, entry) {
    if (!marker || !entry) return;

    const loadingWeatherHtml = `<div style="margin-top:6px;"><strong>${t('Météo actuelle', 'Meteo actual')}</strong><br>${t('Chargement...', 'Cargando...')}</div>`;
    marker.setPopupContent(buildWaypointPhotoPopupContent(entry, loadingWeatherHtml));

    try {
        const weather = await getCurrentWeatherAtWaypoint(entry.lat, entry.lng);
        const nowLabel = formatWeekdayHourUtc(new Date());
        const weatherLine = formatWeatherTooltipContent(weather, nowLabel).replace('<strong>Météo</strong><br>', '');
        const weatherHtml = `<div style="margin-top:6px;"><strong>${t('Météo actuelle', 'Meteo actual')}</strong><br>${weatherLine}</div>`;
        marker.setPopupContent(buildWaypointPhotoPopupContent(entry, weatherHtml));
    } catch (error) {
        const weatherHtml = `<div style="margin-top:6px;"><strong>${t('Météo actuelle', 'Meteo actual')}</strong><br>${t('Indisponible', 'No disponible')}</div>`;
        marker.setPopupContent(buildWaypointPhotoPopupContent(entry, weatherHtml));
    }
}

function ensureWaypointPhotoMarker(entry) {
    if (!map || !entry) return null;

    let marker = waypointPhotoMarkersById.get(entry.id);
    if (!marker) {
        const icon = L.divIcon({
            className: 'waypoint-photo-map-icon',
            html: '<div class="waypoint-photo-map-icon__dot" style="width:28px;height:28px;border-radius:999px;background:#10223a;border:2px solid #7fd8ff;color:#7fd8ff;font:16px/26px Arial,sans-serif;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,0.45);">📷</div>',
            iconSize: [28, 28],
            iconAnchor: [14, 14]
        });

        marker = L.marker([entry.lat, entry.lng], {
            icon,
            keyboard: false,
            zIndexOffset: 2000
        });

        waypointPhotoMarkersById.set(entry.id, marker);
    } else {
        marker.setLatLng([entry.lat, entry.lng]);
    }

    marker._ceiboWaypointPhotoId = entry.id;

    marker.bindPopup(buildWaypointPhotoPopupContent(entry), { maxWidth: 260, autoPan: false });

    if (!marker._ceiboWeatherPopupBound) {
        marker.on('popupopen', () => {
            const entryId = marker._ceiboWaypointPhotoId;
            const liveEntry = waypointPhotoEntries.find(item => item.id === entryId) || entry;
            enrichWaypointPhotoPopupWithCurrentWeather(marker, liveEntry);
        });
        marker._ceiboWeatherPopupBound = true;
    }

    return marker;
}

function syncWaypointPhotoMarkersInView() {
    if (!map) return;

    const knownIds = new Set();

    waypointPhotoEntries.forEach(entry => {
        const marker = ensureWaypointPhotoMarker(entry);
        if (!marker) return;

        knownIds.add(entry.id);
        if (!map.hasLayer(marker)) marker.addTo(map);
    });

    waypointPhotoMarkersById.forEach((marker, id) => {
        if (!knownIds.has(id)) {
            if (map.hasLayer(marker)) map.removeLayer(marker);
            waypointPhotoMarkersById.delete(id);
        }
    });
}

function removeWaypointPhotoById(id) {
    waypointPhotoEntries = waypointPhotoEntries.filter(entry => entry.id !== id);
    persistWaypointPhotoEntries();

    if (isCloudReady()) {
        syncWaypointPhotosToCloud()
            .catch(error => setCloudStatus(t(
                `Photos locales OK, synchro cloud échouée: ${formatCloudError(error)}`,
                `Fotos locales OK, sincronización nube fallida: ${formatCloudError(error)}`,
                `Local photos OK, cloud sync failed: ${formatCloudError(error)}`
            ), true));
    }

    const marker = waypointPhotoMarkersById.get(id);
    if (marker && map?.hasLayer(marker)) {
        map.removeLayer(marker);
    }
    waypointPhotoMarkersById.delete(id);

    if (editingWaypointPhotoId === id) {
        cancelWaypointPhotoEdit();
    }

    renderWaypointPhotoList();
    syncWaypointPhotoMarkersInView();
}

function goToWaypointPhotoEntry(entry) {
    if (!entry || !Number.isFinite(entry.lat) || !Number.isFinite(entry.lng) || !map) return;

    const waypoint = L.latLng(entry.lat, entry.lng);
    addUserWaypoint(waypoint, { select: true, invalidate: true });
    map.setView([entry.lat, entry.lng], Math.max(map.getZoom(), 11));
}

function parseLatLngSearchQuery(rawQuery) {
    const query = String(rawQuery || '').trim();
    if (!query) return null;

    const match = query.match(/^(-?\d+(?:\.\d+)?)\s*[,;\/]\s*(-?\d+(?:\.\d+)?)$/);
    if (!match) return null;

    const lat = Number(match[1]);
    const lng = Number(match[2]);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return null;

    return { lat, lng };
}

function focusWaypointMapSearchResult(result) {
    const lat = Number(result?.lat);
    const lng = Number(result?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || !map) return;

    if (waypointMapSearchMarker && map.hasLayer(waypointMapSearchMarker)) {
        map.removeLayer(waypointMapSearchMarker);
    }

    waypointMapSearchMarker = L.marker([lat, lng], { zIndexOffset: 700 }).addTo(map);
    const placeName = String(result?.name || '').trim() || t('Lieu trouvé', 'Lugar encontrado', 'Found place');
    waypointMapSearchMarker.bindPopup(`<strong>${escapeHtml(placeName)}</strong><br>${lat.toFixed(5)}, ${lng.toFixed(5)}`);
    map.setView([lat, lng], Math.max(map.getZoom(), 12));
    waypointMapSearchMarker.openPopup();
}

function addWaypointFromMapSearchResult(result) {
    const lat = Number(result?.lat);
    const lng = Number(result?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || !map) return;

    addUserWaypoint(L.latLng(lat, lng), { select: true, invalidate: true });
    map.setView([lat, lng], Math.max(map.getZoom(), 12));
}

function clearWaypointMapSearchState({ keepQuery = false } = {}) {
    waypointMapSearchResults = [];
    waypointMapSearchInFlight = false;
    waypointMapSearchError = '';
    if (!keepQuery) waypointMapSearchQuery = '';

    if (waypointMapSearchAbortController) {
        waypointMapSearchAbortController.abort();
        waypointMapSearchAbortController = null;
    }
}

async function runWaypointMapSearch(rawQuery) {
    const query = String(rawQuery || '').trim();

    if (query.length < 3) {
        clearWaypointMapSearchState({ keepQuery: false });
        renderWaypointPhotoList();
        return;
    }

    const directCoords = parseLatLngSearchQuery(query);
    if (directCoords) {
        waypointMapSearchQuery = query;
        waypointMapSearchError = '';
        waypointMapSearchInFlight = false;
        waypointMapSearchResults = [
            {
                id: `coords:${directCoords.lat.toFixed(5)},${directCoords.lng.toFixed(5)}`,
                name: t('Coordonnées saisies', 'Coordenadas introducidas', 'Typed coordinates'),
                displayName: `${directCoords.lat.toFixed(5)}, ${directCoords.lng.toFixed(5)}`,
                lat: directCoords.lat,
                lng: directCoords.lng
            }
        ];
        renderWaypointPhotoList();
        return;
    }

    const normalizedQuery = query.toLowerCase();
    waypointMapSearchQuery = query;
    waypointMapSearchError = '';

    if (waypointMapSearchCache.has(normalizedQuery)) {
        waypointMapSearchInFlight = false;
        waypointMapSearchResults = waypointMapSearchCache.get(normalizedQuery);
        renderWaypointPhotoList();
        return;
    }

    waypointMapSearchInFlight = true;
    waypointMapSearchResults = [];
    renderWaypointPhotoList();

    if (waypointMapSearchAbortController) {
        waypointMapSearchAbortController.abort();
    }

    waypointMapSearchRequestId += 1;
    const requestId = waypointMapSearchRequestId;
    const controller = new AbortController();
    waypointMapSearchAbortController = controller;

    try {
        const params = new URLSearchParams({
            q: query,
            format: 'jsonv2',
            addressdetails: '1',
            limit: '6'
        });

        const response = await fetch(`https://nominatim.openstreetmap.org/search?${params.toString()}`, {
            signal: controller.signal,
            headers: {
                Accept: 'application/json',
                'Accept-Language': getCurrentLocale()
            }
        });

        if (requestId !== waypointMapSearchRequestId) return;
        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const payload = await response.json();
        const results = Array.isArray(payload)
            ? payload
                .map((item, index) => {
                    const lat = Number(item?.lat);
                    const lng = Number(item?.lon);
                    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;

                    const displayName = String(item?.display_name || '').trim();
                    const shortName = String(item?.name || displayName.split(',')[0] || '').trim();

                    return {
                        id: String(item?.place_id || `${normalizedQuery}:${index}`),
                        name: shortName || t('Lieu', 'Lugar', 'Place'),
                        displayName,
                        lat,
                        lng
                    };
                })
                .filter(Boolean)
            : [];

        waypointMapSearchCache.set(normalizedQuery, results);
        waypointMapSearchResults = results;
        waypointMapSearchError = '';
    } catch (error) {
        if (requestId !== waypointMapSearchRequestId) return;
        if (error?.name === 'AbortError') return;

        waypointMapSearchResults = [];
        waypointMapSearchError = t(
            'Recherche carte indisponible pour le moment.',
            'Búsqueda en mapa no disponible por ahora.',
            'Map search unavailable right now.'
        );
    } finally {
        if (requestId === waypointMapSearchRequestId) {
            waypointMapSearchInFlight = false;
            waypointMapSearchAbortController = null;
            renderWaypointPhotoList();
        }
    }
}

function scheduleWaypointMapSearch(rawQuery) {
    if (waypointMapSearchDebounceTimerId) {
        clearTimeout(waypointMapSearchDebounceTimerId);
    }

    const query = String(rawQuery || '').trim();
    if (query.length < 3) {
        clearWaypointMapSearchState({ keepQuery: false });
        renderWaypointPhotoList();
        return;
    }

    waypointMapSearchDebounceTimerId = window.setTimeout(() => {
        waypointMapSearchDebounceTimerId = null;
        void runWaypointMapSearch(query);
    }, 420);
}

function buildWaypointMapSearchSectionHtml(searchQuery) {
    const query = String(searchQuery || '').trim();
    if (query.length < 3) return '';

    let bodyHtml = '';
    if (waypointMapSearchInFlight) {
        bodyHtml = `<div class="arrival-list__item">${t('Recherche carte en cours...', 'Buscando en mapa...', 'Searching map...')}</div>`;
    } else if (waypointMapSearchError) {
        bodyHtml = `<div class="arrival-list__item">${escapeHtml(waypointMapSearchError)}</div>`;
    } else if (!waypointMapSearchResults.length) {
        bodyHtml = `<div class="arrival-list__item">${t('Aucun lieu carte trouvé.', 'No se encontró lugar en el mapa.', 'No map place found.')}</div>`;
    } else {
        bodyHtml = waypointMapSearchResults.map(item => {
            const name = escapeHtml(item.name || t('Lieu', 'Lugar', 'Place'));
            const displayName = escapeHtml(item.displayName || '');
            const lat = Number(item.lat);
            const lng = Number(item.lng);
            return `<div class="arrival-list__item waypoint-map-search-item">
                <div><strong>${name}</strong></div>
                <div class="arrival-list__meta">${displayName}</div>
                <div class="arrival-list__meta">${lat.toFixed(5)}, ${lng.toFixed(5)}</div>
                <div class="button-row">
                    <button type="button" class="js-waypoint-map-search-go" data-id="${escapeHtml(String(item.id))}" style="flex:1;">${t('Voir sur carte', 'Ver en mapa', 'Show on map')}</button>
                    <button type="button" class="js-waypoint-map-search-add" data-id="${escapeHtml(String(item.id))}" style="flex:1;">${t('Ajouter comme WP', 'Añadir como WP', 'Add as WP')}</button>
                </div>
            </div>`;
        }).join('');
    }

    return `<div class="waypoint-map-search-section">
        <div class="waypoint-map-search-title">${t('Résultats carte', 'Resultados mapa', 'Map results')}</div>
        ${bodyHtml}
    </div>`;
}

function renderWaypointPhotoList() {
    const container = document.getElementById('waypointPhotoListDock');
    const dockTitle = document.getElementById('waypointSavedAnchoragesDockLabel');
    if (!container) return;

    const searchTerm = waypointSearchTerm.trim().toLowerCase();
    const mapSearchSectionHtml = buildWaypointMapSearchSectionHtml(waypointSearchTerm);
    const visibleBounds = map && typeof map.getBounds === 'function'
        ? map.getBounds()
        : null;
    const entriesInCurrentMapZone = visibleBounds && typeof visibleBounds.contains === 'function'
        ? waypointPhotoEntries.filter(entry => visibleBounds.contains([entry.lat, entry.lng]))
        : waypointPhotoEntries;
    const filteredEntries = searchTerm
        ? entriesInCurrentMapZone.filter(entry => {
            const searchBlob = [
                entry.placeName,
                entry.comment,
                entry.bottomType,
                entry.creatorName,
                entry.creatorEmail,
                formatProtectionList(entry.protection),
                Number.isFinite(entry.lat) ? entry.lat.toFixed(4) : '',
                Number.isFinite(entry.lng) ? entry.lng.toFixed(4) : ''
            ].join(' ').toLowerCase();

            return searchBlob.includes(searchTerm);
        })
        : entriesInCurrentMapZone;

    if (dockTitle) {
        const countLabel = searchTerm
            ? `${filteredEntries.length}/${entriesInCurrentMapZone.length}/${waypointPhotoEntries.length}`
            : `${entriesInCurrentMapZone.length}/${waypointPhotoEntries.length}`;
        dockTitle.textContent = `${t('Mouillages enregistrés', 'Fondeos guardados')}: ${countLabel}`;
    }

    const cardsHtml = filteredEntries.map(entry => {
        const title = entry.placeName ? escapeHtml(entry.placeName) : t('Mouillage sans nom', 'Fondeo sin nombre');
        const creator = String(entry?.creatorName || '').trim();
        const canEdit = isOwnedByCurrentCloudUser(entry?.creatorEmail);
        const canDelete = isOwnedByCurrentCloudUser(entry?.creatorEmail);
        const creatorLine = creator ? `<div>${t('Créateur', 'Creador')}: ${escapeHtml(creator)}</div>` : '';
        const bottom = entry.bottomType ? `<div>${t('Fond', 'Fondo')}: ${escapeHtml(entry.bottomType)}</div>` : '';
        const comment = entry.comment ? `<div style="margin-top:4px;">${escapeHtml(entry.comment)}</div>` : '';
        const image = entry.imageDataUrl ? `<img class="waypoint-photo-card__img" src="${entry.imageDataUrl}" alt="${t('Photo mouillage', 'Foto fondeo')}">` : '';

        return `<div class="waypoint-photo-card">
            <div><strong>${title}</strong></div>
            <div><strong>${starsLabel(entry.rating)}</strong> · ${entry.lat.toFixed(4)}, ${entry.lng.toFixed(4)}</div>
            <div>${t('Propreté', 'Limpieza')} ${starsLabel(entry.cleanliness)} · ${t('Profondeur', 'Profundidad')} ${entry.depthMeters} m</div>
            <div>${t('Protection', 'Protección')} ${escapeHtml(formatProtectionList(entry.protection))}</div>
            ${creatorLine}
            ${bottom}
            ${comment}
            ${image}
            <div class="button-row">
                <button type="button" class="js-waypoint-photo-go" data-id="${escapeHtml(entry.id)}" style="flex:1;">${t('Y aller', 'Ir')}</button>
                <button type="button" class="js-waypoint-photo-center" data-id="${escapeHtml(entry.id)}" style="flex:1;">${t('Voir sur carte', 'Ver en mapa')}</button>
                <button type="button" class="js-waypoint-photo-add-to-voyage" data-id="${escapeHtml(entry.id)}" style="flex:1;">${t('Ajouter au voyage', 'Añadir al viaje', 'Add to trip')}</button>
                ${canEdit ? `<button type="button" class="js-waypoint-photo-edit" data-id="${escapeHtml(entry.id)}" style="flex:1;">${t('Modifier', 'Editar')}</button>` : ''}
                ${canDelete ? `<button type="button" class="js-waypoint-photo-delete" data-id="${escapeHtml(entry.id)}" style="flex:1;">${t('Supprimer', 'Eliminar')}</button>` : ''}
            </div>
        </div>`;
    }).join('');

    const localEmptyHtml = !waypointPhotoEntries.length
        ? `<div class="arrival-list__item">${t('Aucun mouillage enregistré.', 'No hay fondeos guardados.')}</div>`
        : (!filteredEntries.length
            ? `<div class="arrival-list__item">${searchTerm
                ? t('Aucun mouillage trouvé dans cette zone pour cette recherche.', 'No hay fondeos en esta zona para esta búsqueda.', 'No anchorages found in this area for this search.')
                : t('Aucun mouillage dans la zone visible de la carte.', 'No hay fondeos en la zona visible del mapa.', 'No anchorages in the visible map area.')}</div>`
            : cardsHtml);

    container.innerHTML = `${mapSearchSectionHtml}${localEmptyHtml}`;

    const attachWaypointMapSearchActions = () => {
        container.querySelectorAll('.js-waypoint-map-search-go').forEach(button => {
            button.addEventListener('click', () => {
                const id = String(button.getAttribute('data-id') || '');
                const entry = waypointMapSearchResults.find(item => String(item.id) === id);
                if (!entry) return;
                focusWaypointMapSearchResult(entry);
            });
        });

        container.querySelectorAll('.js-waypoint-map-search-add').forEach(button => {
            button.addEventListener('click', () => {
                const id = String(button.getAttribute('data-id') || '');
                const entry = waypointMapSearchResults.find(item => String(item.id) === id);
                if (!entry) return;
                addWaypointFromMapSearchResult(entry);
            });
        });
    };

    attachWaypointMapSearchActions();

    if (!waypointPhotoEntries.length) {
        return;
    }

    if (!filteredEntries.length) {
        return;
    }

    container.querySelectorAll('.js-waypoint-photo-go').forEach(button => {
        button.addEventListener('click', () => {
            const id = String(button.getAttribute('data-id') || '');
            const entry = waypointPhotoEntries.find(item => item.id === id);
            if (!entry) return;
            goToWaypointPhotoEntry(entry);
        });
    });

    container.querySelectorAll('.js-waypoint-photo-center').forEach(button => {
        button.addEventListener('click', () => {
            const id = String(button.getAttribute('data-id') || '');
            const entry = waypointPhotoEntries.find(item => item.id === id);
            if (!entry || !map) return;

            map.setView([entry.lat, entry.lng], Math.max(map.getZoom(), 11));
            updateWaypointGoogleMapPreview(entry.lat, entry.lng);
            syncWaypointPhotoMarkersInView();
            const marker = waypointPhotoMarkersById.get(id);
            if (marker) marker.openPopup();
        });
    });

    container.querySelectorAll('.js-waypoint-photo-add-to-voyage').forEach(button => {
        button.addEventListener('click', () => {
            const id = String(button.getAttribute('data-id') || '');
            const entry = waypointPhotoEntries.find(item => item.id === id);
            if (!entry) return;
            addWaypointEntryToSelectedVoyagePlan(entry);
        });
    });

    container.querySelectorAll('.js-waypoint-photo-edit').forEach(button => {
        button.addEventListener('click', () => {
            const id = String(button.getAttribute('data-id') || '');
            startEditWaypointPhoto(id);
        });
    });

    container.querySelectorAll('.js-waypoint-photo-delete').forEach(button => {
        button.addEventListener('click', () => {
            const id = String(button.getAttribute('data-id') || '');
            removeWaypointPhotoById(id);
        });
    });
}

async function handleWaypointPhotoInputChange(event) {
    const file = event?.target?.files?.[0];
    const status = document.getElementById('waypointPhotoStatus');
    const preview = document.getElementById('waypointPhotoPreview');

    if (!file) {
        clearWaypointPhotoDraft();
        return;
    }

    if (!file.type.startsWith('image/')) {
        if (status) status.textContent = t('Ce fichier n\'est pas une image.', 'Este archivo no es una imagen.');
        pendingWaypointPhotoDraft = null;
        return;
    }

    pendingWaypointPhotoDraft = {
        ...(pendingWaypointPhotoDraft || {}),
        file
    };

    waypointPhotoInputProcessing = true;

    try {
        if (status) status.textContent = t('Lecture des coordonnées GPS...', 'Leyendo coordenadas GPS...');

        const coords = await extractGpsCoordinatesFromPhoto(file);
        if (!coords) {
            if (editingWaypointPhotoId) {
                const entry = waypointPhotoEntries.find(item => item.id === editingWaypointPhotoId);
                if (entry) {
                    pendingWaypointPhotoDraft = { file, lat: entry.lat, lng: entry.lng };
                    if (status) status.textContent = t(
                        `Pas de GPS dans la nouvelle photo: coordonnées conservées (${entry.lat.toFixed(5)}, ${entry.lng.toFixed(5)}).`,
                        `Sin GPS en la nueva foto: coordenadas conservadas (${entry.lat.toFixed(5)}, ${entry.lng.toFixed(5)}).`
                    );
                    updateWaypointGoogleMapPreview(entry.lat, entry.lng);
                }
            } else {
                const editor = ensureWaypointEditorMap();
                const markerPos = waypointEditorMarker?.getLatLng?.();
                const editorCenter = editor?.getCenter?.();
                const fallbackLat = Number(markerPos?.lat ?? editorCenter?.lat ?? map?.getCenter?.().lat ?? 41.3851);
                const fallbackLng = Number(markerPos?.lng ?? editorCenter?.lng ?? map?.getCenter?.().lng ?? 2.1734);

                pendingWaypointPhotoDraft = { file, lat: fallbackLat, lng: fallbackLng };
                updateWaypointGoogleMapPreview(fallbackLat, fallbackLng);

                if (waypointEditorMarker) {
                    waypointEditorMarker.setLatLng([fallbackLat, fallbackLng]);
                }

                if (status) {
                    status.textContent = t(
                        'Pas de GPS EXIF: position manuelle activée sur la mini-carte (déplace le marqueur puis sauvegarde).',
                        'Sin GPS EXIF: posición manual activada en el mini-mapa (mueve el marcador y guarda).'
                    );
                }
            }
        } else {
            setWaypointDraftCoordinates(coords.lat, coords.lng);
        }

        if (waypointPhotoPreviewObjectUrl) {
            URL.revokeObjectURL(waypointPhotoPreviewObjectUrl);
        }
        waypointPhotoPreviewObjectUrl = URL.createObjectURL(file);

        if (preview) {
            preview.src = waypointPhotoPreviewObjectUrl;
            preview.style.display = 'block';
        }
    } catch (error) {
        pendingWaypointPhotoDraft = null;
        if (status) status.textContent = t('Erreur de lecture image. Essaie une autre photo (JPG/PNG).', 'Error al leer la imagen. Prueba otra foto (JPG/PNG).');
    } finally {
        waypointPhotoInputProcessing = false;
    }
}

async function handleQuickWaypointCaptureChange(event) {
    const file = event?.target?.files?.[0];
    if (!file) return;

    const status = document.getElementById('waypointPhotoStatus');

    try {
        if (!file.type.startsWith('image/')) {
            if (status) status.textContent = t('Ce fichier n\'est pas une image.', 'Este archivo no es una imagen.');
            return;
        }

        if (status) status.textContent = t('Photo rapide: lecture GPS...', 'Foto rápida: leyendo GPS...');

        const coords = await extractGpsCoordinatesFromPhoto(file);
        if (!coords) {
            if (status) status.textContent = t('Photo rapide: GPS EXIF introuvable (WP auto non créé).', 'Foto rápida: GPS EXIF no encontrado (WP auto no creado).');
            alert(t('La photo ne contient pas de coordonnées GPS. Utilise le mode manuel pour positionner le waypoint.', 'La foto no contiene coordenadas GPS. Usa el modo manual para posicionar el waypoint.'));
            return;
        }

        const imageDataUrl = await imageFileToCompressedDataUrl(file);
        const nowIso = new Date().toISOString();
        const entry = normalizeWaypointPhotoEntry({
            id: generateClientUuid(),
            lat: coords.lat,
            lng: coords.lng,
            placeName: '',
            imageDataUrl,
            comment: '',
            rating: 3,
            cleanliness: 3,
            protection: [],
            depthMeters: 10,
            bottomType: '',
            creatorEmail: getCreatorPatch().creatorEmail,
            creatorName: getCreatorPatch().creatorName,
            createdAt: nowIso,
            updatedAt: nowIso
        });

        if (!entry) {
            if (status) status.textContent = t('Photo rapide: coordonnées invalides.', 'Foto rápida: coordenadas inválidas.');
            return;
        }

        waypointPhotoEntries.unshift(entry);
        const persisted = persistWaypointPhotoEntries();
        if (!persisted) {
            waypointPhotoEntries.shift();
            alert(t('Stockage saturé: impossible d\'enregistrer cette photo.', 'Almacenamiento lleno: no se puede guardar esta foto.'));
            return;
        }

        if (isCloudReady()) {
            try {
                await syncWaypointPhotosToCloud();
            } catch (error) {
                waypointPhotoEntries.shift();
                persistWaypointPhotoEntries();
                renderWaypointPhotoList();
                syncWaypointPhotoMarkersInView();
                alert(t('Photo locale créée puis annulée: écriture cloud impossible. Vérifie la connexion cloud et réessaie.', 'Foto local creada y luego cancelada: escritura en nube imposible. Verifica la conexión cloud y vuelve a intentar.'));
                return;
            }
        }

        renderWaypointPhotoList();
        syncWaypointPhotoMarkersInView();
        if (map) {
            map.setView([entry.lat, entry.lng], Math.max(map.getZoom(), 11));
        }

        if (status) {
            status.textContent = t(
                `Photo rapide: WP créé automatiquement (${entry.lat.toFixed(5)}, ${entry.lng.toFixed(5)}).`,
                `Foto rápida: WP creado automáticamente (${entry.lat.toFixed(5)}, ${entry.lng.toFixed(5)}).`
            );
        }
    } catch (_error) {
        if (status) status.textContent = t('Photo rapide: échec de création du WP.', 'Foto rápida: fallo al crear el WP.');
    } finally {
        if (event?.target) event.target.value = '';
    }
}

async function saveWaypointPhotoEntry() {
    if (waypointPhotoInputProcessing) {
        alert(t('Photo en cours de traitement, attends 1-2 secondes puis réessaie.', 'Foto en procesamiento, espera 1-2 segundos y vuelve a intentarlo.'));
        return;
    }

    const isEdit = Number.isFinite(waypointPhotoEntries.findIndex(entry => entry.id === editingWaypointPhotoId))
        && waypointPhotoEntries.findIndex(entry => entry.id === editingWaypointPhotoId) !== -1;

    if (!Number.isFinite(pendingWaypointPhotoDraft?.lat) || !Number.isFinite(pendingWaypointPhotoDraft?.lng)) {
        alert(t('Choisis une position sur la carte ou ajoute une photo avec coordonnées GPS intégrées.', 'Elige una posición en el mapa o añade una foto con coordenadas GPS integradas.', 'Choose a position on the map or add a photo with embedded GPS coordinates.'));
        return;
    }

    const placeName = String(document.getElementById('waypointPlaceNameInput')?.value || '').trim();
    const comment = String(document.getElementById('waypointCommentInput')?.value || '').trim();
    const bottomType = String(document.getElementById('waypointBottomTypeInput')?.value || '').trim();
    const rating = clampStarRating(document.getElementById('waypointRatingInput')?.value);
    const cleanliness = clampStarRating(document.getElementById('waypointCleanlinessInput')?.value);
    const protection = getProtectionCheckboxValues();
    const depthMeters = normalizeDepthMeters(document.getElementById('waypointDepthInput')?.value);

    try {
    if (isEdit) {
        const editIndex = waypointPhotoEntries.findIndex(entry => entry.id === editingWaypointPhotoId);
        const current = waypointPhotoEntries[editIndex];
        if (!current) {
            alert(t('Waypoint à modifier introuvable.', 'No se encontró el waypoint a modificar.'));
            return;
        }

        const hasNewPhoto = !!pendingWaypointPhotoDraft?.file;
        const imageDataUrl = hasNewPhoto
            ? await imageFileToCompressedDataUrl(pendingWaypointPhotoDraft.file)
            : current.imageDataUrl;

        const previousEntry = { ...current };

        waypointPhotoEntries[editIndex] = ensureCreatorOnEditedRecord({
            ...current,
            lat: Number.isFinite(pendingWaypointPhotoDraft?.lat) ? pendingWaypointPhotoDraft.lat : current.lat,
            lng: Number.isFinite(pendingWaypointPhotoDraft?.lng) ? pendingWaypointPhotoDraft.lng : current.lng,
            placeName,
            imageDataUrl,
            comment,
            rating,
            cleanliness,
            protection,
            depthMeters,
            bottomType,
            updatedAt: new Date().toISOString()
        });

        const persisted = persistWaypointPhotoEntries();
        if (!persisted) {
            waypointPhotoEntries[editIndex] = previousEntry;
            alert(t('Enregistrement impossible: stockage local saturé. Essaie une image plus légère ou supprime des anciennes photos.', 'No se puede guardar: almacenamiento local lleno. Prueba una imagen más ligera o elimina fotos antiguas.'));
            return;
        }
        routesCloudDirty = true;

        renderWaypointPhotoList();
        syncWaypointPhotoMarkersInView();
        cancelWaypointPhotoEdit();
        const status = document.getElementById('waypointPhotoStatus');
        if (status) {
            status.textContent = t('Waypoint modifié. Synchro cloud en cours.', 'Waypoint modificado. Sincronización nube en curso.', 'Waypoint updated. Cloud sync in progress.');
        }

        if (isCloudReady()) {
            void syncWaypointPhotosToCloud()
                .then(() => setCloudStatus(t(
                    `Cloud synchronisé · ${getSavedRoutes().length} route(s) + ${waypointPhotoEntries.length} photo(s)`,
                    `Nube sincronizada · ${getSavedRoutes().length} ruta(s) + ${waypointPhotoEntries.length} foto(s)`,
                    `Cloud synced · ${getSavedRoutes().length} route(s) + ${waypointPhotoEntries.length} photo(s)`
                )))
                .catch(error => setCloudStatus(t(`Modification locale OK, synchro cloud échouée: ${formatCloudError(error)}`, `Modificación local OK, sincronización nube fallida: ${formatCloudError(error)}`), true));
        }
        return;
    }

    const imageDataUrl = pendingWaypointPhotoDraft?.file
        ? await imageFileToCompressedDataUrl(pendingWaypointPhotoDraft.file)
        : '';

    const entry = {
        id: generateClientUuid(),
        lat: pendingWaypointPhotoDraft.lat,
        lng: pendingWaypointPhotoDraft.lng,
        placeName,
        imageDataUrl,
        comment,
        rating,
        cleanliness,
        protection,
        depthMeters,
        bottomType,
        creatorEmail: getCreatorPatch().creatorEmail,
        creatorName: getCreatorPatch().creatorName,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };

    waypointPhotoEntries.unshift(entry);
    const persisted = persistWaypointPhotoEntries();
    if (!persisted) {
        waypointPhotoEntries.shift();
        alert(t('Enregistrement impossible: stockage local saturé. Essaie une image plus légère ou supprime des anciennes photos.', 'No se puede guardar: almacenamiento local lleno. Prueba una imagen más ligera o elimina fotos antiguas.'));
        return;
    }
    routesCloudDirty = true;

    renderWaypointPhotoList();
    syncWaypointPhotoMarkersInView();

    resetWaypointPhotoFormValues();
    clearWaypointPhotoDraft();
    const status = document.getElementById('waypointPhotoStatus');
    if (status) {
        status.textContent = t('Waypoint enregistré. Synchro cloud en cours.', 'Waypoint guardado. Sincronización nube en curso.', 'Waypoint saved. Cloud sync in progress.');
    }

    if (isCloudReady()) {
        void syncWaypointPhotosToCloud()
            .then(() => setCloudStatus(t(
                `Cloud synchronisé · ${getSavedRoutes().length} route(s) + ${waypointPhotoEntries.length} photo(s)`,
                `Nube sincronizada · ${getSavedRoutes().length} ruta(s) + ${waypointPhotoEntries.length} foto(s)`,
                `Cloud synced · ${getSavedRoutes().length} route(s) + ${waypointPhotoEntries.length} photo(s)`
            )))
            .catch(error => setCloudStatus(t(`Enregistrement local OK, synchro cloud échouée: ${formatCloudError(error)}`, `Guardado local OK, sincronización nube fallida: ${formatCloudError(error)}`), true));
    }
    } catch (error) {
        alert(t('Impossible d\'enregistrer la photo. Essaie une image plus légère (JPG), puis recommence.', 'No se puede guardar la foto. Prueba una imagen más ligera (JPG) y vuelve a intentarlo.'));
    }
}

function updateSelectedWaypointInfo() {
    const info = document.getElementById('selectedWpInfo');

    if (!Number.isInteger(selectedUserWaypointIndex) || selectedUserWaypointIndex < 0 || selectedUserWaypointIndex >= markers.length) {
        syncSelectedWaypointRangeRings(null);
        if (info) {
            info.textContent = t(
                'WP sélectionné: aucun · clic sur WP pour sélectionner · clic droit pour supprimer',
                'WP seleccionado: ninguno · clic en WP para seleccionar · clic derecho para eliminar'
            );
        }
        return;
    }

    const marker = markers[selectedUserWaypointIndex];
    const latlng = marker?.getLatLng?.();
    if (!latlng) {
        syncSelectedWaypointRangeRings(null);
        if (info) {
            info.textContent = t(
                'WP sélectionné: aucun · clic sur WP pour sélectionner · clic droit pour supprimer',
                'WP seleccionado: ninguno · clic en WP para seleccionar · clic derecho para eliminar'
            );
        }
        return;
    }

    syncSelectedWaypointRangeRings(latlng);
    if (info) {
        info.textContent = t(
            `WP sélectionné: ${selectedUserWaypointIndex + 1} (${latlng.lat.toFixed(4)}, ${latlng.lng.toFixed(4)})`,
            `WP seleccionado: ${selectedUserWaypointIndex + 1} (${latlng.lat.toFixed(4)}, ${latlng.lng.toFixed(4)})`
        );
    }
}

function syncSelectedWaypointRangeRings(latlng) {
    if (selectedWaypointRangeRingsLayer && map?.hasLayer(selectedWaypointRangeRingsLayer)) {
        map.removeLayer(selectedWaypointRangeRingsLayer);
    }
    selectedWaypointRangeRingsLayer = null;

    if (!map || !latlng || !Number.isFinite(latlng.lat) || !Number.isFinite(latlng.lng)) {
        return;
    }

    const ringDefinitions = [
        { radiusNm: 5, color: '#0b3d5c', weight: 2.4, opacity: 0.95 },
        { radiusNm: 10, color: '#145374', weight: 2.1, opacity: 0.9 },
        { radiusNm: 20, color: '#1c6b8c', weight: 1.9, opacity: 0.88 }
    ];
    const metersPerNm = 1852;

    selectedWaypointRangeRingsLayer = L.layerGroup(
        ringDefinitions.map(definition => L.circle(latlng, {
            radius: definition.radiusNm * metersPerNm,
            color: definition.color,
            weight: definition.weight,
            opacity: definition.opacity,
            fill: false,
            dashArray: '10 6',
            interactive: false,
            bubblingMouseEvents: false
        }))
    ).addTo(map);
}

function invalidateComputedRouteDisplay() {
    if (routeLayer && map?.hasLayer(routeLayer)) {
        map.removeLayer(routeLayer);
    }
    routeLayer = null;

    if (windLayer && map?.hasLayer(windLayer)) {
        map.removeLayer(windLayer);
    }
    windLayer = null;

    clearWaypointWindDirectionLayers();
    clearWaveDirectionSegmentLayers();
    waypointPassageSlots.clear();
    lastRouteBounds = null;
    lastRoutingDecisionSnapshot = null;

    const info = document.getElementById('info');
    if (info) info.innerHTML = '';
    const windLegend = document.getElementById('windSpeedLegend');
    if (windLegend) renderWindSpeedLegend();
    const routingDecisionSummary = document.getElementById('routingDecisionSummary');
    if (routingDecisionSummary) {
        routingDecisionSummary.innerHTML = '';
        routingDecisionSummary.style.display = 'none';
    }
}

function refreshEditableRouteOverlay() {
    if (!map) return;

    if (Array.isArray(routePoints) && routePoints.length >= 2) {
        drawRoute(routePoints);
        return;
    }

    if (routeLayer && map.hasLayer(routeLayer)) {
        map.removeLayer(routeLayer);
    }
    routeLayer = null;
}

function selectUserWaypoint(marker) {
    const index = markers.indexOf(marker);
    selectedUserWaypointIndex = index;
    updateSelectedWaypointInfo();
}

function deleteUserWaypointAtIndex(index) {
    if (!Number.isInteger(index) || index < 0 || index >= markers.length) return;

    const marker = markers[index];
    if (marker && map?.hasLayer(marker)) {
        map.removeLayer(marker);
    }

    markers.splice(index, 1);
    routePoints.splice(index, 1);

    if (selectedUserWaypointIndex === index) {
        selectedUserWaypointIndex = -1;
    } else if (selectedUserWaypointIndex > index) {
        selectedUserWaypointIndex -= 1;
    }

    invalidateComputedRouteDisplay();
    refreshEditableRouteOverlay();
    updateSelectedWaypointInfo();
}

function getLogicalInsertionIndexFromRouteClick(clickLatLng) {
    if (!Array.isArray(routePoints) || routePoints.length < 2) return routePoints.length;
    if (!clickLatLng || !map) return routePoints.length;

    const clickPoint = map.latLngToLayerPoint(clickLatLng);
    let bestIndex = routePoints.length;
    let bestDistance = Number.POSITIVE_INFINITY;

    for (let i = 0; i < routePoints.length - 1; i += 1) {
        const a = routePoints[i];
        const b = routePoints[i + 1];
        if (!a || !b) continue;

        const aPt = map.latLngToLayerPoint(a);
        const bPt = map.latLngToLayerPoint(b);
        const distancePx = L.LineUtil.pointToSegmentDistance(clickPoint, aPt, bPt);

        if (distancePx < bestDistance) {
            bestDistance = distancePx;
            bestIndex = i + 1;
        }
    }

    return bestIndex;
}

function getInsertionIndexIfNearRoute(clickLatLng, maxDistancePx = 14) {
    if (!Array.isArray(routePoints) || routePoints.length < 2) return null;
    if (!clickLatLng || !map) return null;

    const clickPoint = map.latLngToLayerPoint(clickLatLng);
    let bestIndex = null;
    let bestDistance = Number.POSITIVE_INFINITY;

    for (let i = 0; i < routePoints.length - 1; i += 1) {
        const a = routePoints[i];
        const b = routePoints[i + 1];
        if (!a || !b) continue;

        const aPt = map.latLngToLayerPoint(a);
        const bPt = map.latLngToLayerPoint(b);
        const distancePx = L.LineUtil.pointToSegmentDistance(clickPoint, aPt, bPt);

        if (distancePx < bestDistance) {
            bestDistance = distancePx;
            bestIndex = i + 1;
        }
    }

    if (!Number.isInteger(bestIndex)) return null;

    const currentZoom = typeof map.getZoom === 'function' ? Number(map.getZoom()) : Number.NaN;
    const zoomSlackPx = Number.isFinite(currentZoom)
        ? Math.max(0, Math.min(10, (12 - currentZoom) * 1.5))
        : 0;
    const effectiveMaxDistancePx = Number(maxDistancePx) + zoomSlackPx;

    return bestDistance <= effectiveMaxDistancePx ? bestIndex : null;
}

function addUserWaypoint(latlng, options = {}) {
    if (!latlng || !Number.isFinite(latlng.lat) || !Number.isFinite(latlng.lng)) return null;

    const { select = true, invalidate = true, insertIndex = null } = options;

    const hasValidInsertIndex = Number.isInteger(insertIndex) && insertIndex >= 0 && insertIndex <= routePoints.length;
    const targetIndex = hasValidInsertIndex ? insertIndex : routePoints.length;

    routePoints.splice(targetIndex, 0, latlng);
    const marker = createWaypointMarker(latlng);
    markers.splice(targetIndex, 0, marker);

    if (select) {
        selectUserWaypoint(marker);
    } else {
        updateSelectedWaypointInfo();
    }

    if (invalidate) {
        invalidateComputedRouteDisplay();
        refreshEditableRouteOverlay();
    }

    return marker;
}

function findUserWaypointIndexByCoordinates(lat, lng, tolerance = 0.000001) {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return -1;

    return routePoints.findIndex(point => {
        const pointLat = Number(point?.lat);
        const pointLng = Number(point?.lng ?? point?.lon);
        return Number.isFinite(pointLat)
            && Number.isFinite(pointLng)
            && Math.abs(pointLat - lat) <= tolerance
            && Math.abs(pointLng - lng) <= tolerance;
    });
}

function getArrivalReferenceDateTime() {
    if (lastComputedReportData?.arrivalIso) {
        const fromReport = new Date(lastComputedReportData.arrivalIso);
        if (!Number.isNaN(fromReport.getTime())) return fromReport;
    }

    return new Date(`${departureDate}T${departureTime}:00`);
}

function clearArrivalPoiMarkers() {
    arrivalPoiMarkers.forEach(marker => {
        if (map?.hasLayer(marker)) map.removeLayer(marker);
    });
    arrivalPoiMarkers = [];
}

function addArrivalPoiMarker(lat, lng, label, type = 'poi') {
    if (!map || !Number.isFinite(lat) || !Number.isFinite(lng)) return null;

    const marker = L.circleMarker([lat, lng], {
        radius: type === 'anchorage' ? 6 : 4,
        color: type === 'anchorage' ? '#7fd8ff' : '#ffcf6a',
        weight: 2,
        fillColor: type === 'anchorage' ? '#133341' : '#3a2a13',
        fillOpacity: 0.9
    }).addTo(map);

    marker.bindPopup(`<strong>${escapeHtml(label)}</strong>`, { maxWidth: 260, autoPan: false });
    arrivalPoiMarkers.push(marker);
    return marker;
}

function elementToPoint(element) {
    const lat = Number(element?.lat ?? element?.center?.lat);
    const lon = Number(element?.lon ?? element?.center?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
    return { lat, lon, tags: element?.tags || {} };
}

function getPoiLabel(point, fallback) {
    return point?.tags?.name || fallback;
}

function isOverpassTemporarilyDisabled() {
    return overpassDisabledUntil > Date.now();
}

function getOverpassDisabledError() {
    if (!isOverpassTemporarilyDisabled()) return null;
    return new Error(overpassDisabledReason || 'overpass-disabled');
}

function removeMarinePoiLayersFromMap() {
    const layers = [marineAnchoragesLayer, marinePortsLayer, marineServicesLayer];
    layers.forEach(layer => {
        if (map && layer && map.hasLayer(layer)) {
            map.removeLayer(layer);
        }
        if (typeof layer?.clearLayers === 'function') {
            layer.clearLayers();
        }
    });
}

function reportOverpassUnavailable(kind = 'generic', endpoint = '') {
    const issueKey = `${kind}:${String(endpoint || 'all')}`;
    if (overpassIssueFlags.has(issueKey)) return;
    overpassIssueFlags.add(issueKey);

    const endpointLabel = endpoint ? ` (${endpoint})` : '';
    const message = kind === 'browser-blocked'
        ? t(
            `Couches maritimes dynamiques désactivées${endpointLabel}: accès navigateur direct à Overpass refusé (CORS / réseau). Utilise un proxy serveur pour localhost.`,
            `Capas marítimas dinámicas desactivadas${endpointLabel}: acceso directo del navegador a Overpass rechazado (CORS / red). Usa un proxy del servidor en localhost.`,
            `Dynamic marine layers disabled${endpointLabel}: direct browser access to Overpass is blocked (CORS / network). Use a server proxy on localhost.`
        )
        : t(
            `Couches maritimes dynamiques indisponibles${endpointLabel}: Overpass saturé ou inaccessible.`,
            `Capas marítimas dinámicas no disponibles${endpointLabel}: Overpass saturado o inaccesible.`,
            `Dynamic marine layers unavailable${endpointLabel}: Overpass is saturated or unreachable.`
        );

    setCloudStatus(message, true, { updateBadge: false });
    console.warn(`[CEIBO] ${message}`);
}

function disableOverpassForBrowser(reason = 'browser-blocked', endpoint = '') {
    overpassDisabledReason = reason;
    overpassDisabledUntil = Date.now() + OVERPASS_BROWSER_BLOCK_COOLDOWN_MS;
    removeMarinePoiLayersFromMap();
    reportOverpassUnavailable(reason, endpoint);
}

function disableOverpassTemporarily(reason = 'generic', endpoint = '', cooldownMs = OVERPASS_429_COOLDOWN_MS) {
    overpassDisabledReason = reason;
    overpassDisabledUntil = Date.now() + Math.max(1000, Number(cooldownMs) || OVERPASS_429_COOLDOWN_MS);
    removeMarinePoiLayersFromMap();
    reportOverpassUnavailable(reason, endpoint);
}

function getMarinePoiRefreshSignature() {
    if (!map) return '';
    const visibleKeys = getMarinePoiVisibleLayerDescriptors().map(item => item.key).sort().join('|');
    const bounds = map.getBounds();
    if (!visibleKeys || !bounds) return '';
    const south = Number(bounds.getSouth()).toFixed(2);
    const west = Number(bounds.getWest()).toFixed(2);
    const north = Number(bounds.getNorth()).toFixed(2);
    const east = Number(bounds.getEast()).toFixed(2);
    return `${map.getZoom()}|${visibleKeys}|${south},${west},${north},${east}`;
}

function scheduleMarinePoiOverlayRefresh({ force = false, delayMs = MARINE_POI_REFRESH_DEBOUNCE_MS } = {}) {
    if (marinePoiOverlayRefreshTimer) {
        clearTimeout(marinePoiOverlayRefreshTimer);
        marinePoiOverlayRefreshTimer = null;
    }
    marinePoiOverlayRefreshTimer = window.setTimeout(() => {
        marinePoiOverlayRefreshTimer = null;
        void refreshMarinePoiOverlays({ force });
    }, Math.max(0, Number(delayMs) || 0));
}

async function fetchOverpassElements(query) {
    const normalizedQuery = String(query || '').trim();
    if (!normalizedQuery) return [];

    const disabledError = getOverpassDisabledError();
    if (disabledError) throw disabledError;

    const cached = overpassQueryCache.get(normalizedQuery);
    if (cached && (Date.now() - cached.ts) < OVERPASS_CACHE_TTL_MS) {
        return cached.elements;
    }

    let lastError = null;
    let lastEndpointTried = '';

    const now = Date.now();
    const orderedEndpoints = [
        overpassPreferredEndpoint,
        ...OVERPASS_URLS.filter(url => url !== overpassPreferredEndpoint)
    ];

    for (const endpoint of orderedEndpoints) {
        const blockedUntil = overpassEndpointCooldownUntil.get(endpoint) || 0;
        if (blockedUntil > now) continue;
        lastEndpointTried = endpoint;

        try {
            const requestNow = Date.now();
            const waitMs = Math.max(0, OVERPASS_MIN_INTERVAL_MS - (requestNow - overpassLastRequestAt));
            if (waitMs > 0) {
                await new Promise(resolve => setTimeout(resolve, waitMs));
            }

            const body = new URLSearchParams({ data: normalizedQuery }).toString();
            const response = await fetch(endpoint, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
                body
            });
            overpassLastRequestAt = Date.now();

            const text = await response.text();
            if (!response.ok) {
                if (response.status === 429) {
                    overpassEndpointCooldownUntil.set(endpoint, Date.now() + OVERPASS_429_COOLDOWN_MS);
                    await new Promise(resolve => setTimeout(resolve, 1200));
                }
                if (response.status === 404 || response.status >= 500) {
                    overpassEndpointCooldownUntil.set(endpoint, Date.now() + OVERPASS_BROWSER_BLOCK_COOLDOWN_MS);
                }
                lastError = new Error(`Overpass HTTP ${response.status}`);
                continue;
            }

            let data = null;
            try {
                data = JSON.parse(text);
            } catch (_parseError) {
                lastError = new Error('Overpass JSON invalide');
                continue;
            }

            const elements = Array.isArray(data?.elements) ? data.elements : [];
            overpassPreferredEndpoint = endpoint;
            overpassQueryCache.set(normalizedQuery, {
                ts: Date.now(),
                elements
            });
            overpassDisabledUntil = 0;
            overpassDisabledReason = '';
            return elements;
        } catch (error) {
            const message = String(error?.message || error || '').toLowerCase();
            const isBrowserBlocked =
                message.includes('failed to fetch')
                || message.includes('load failed')
                || message.includes('networkerror')
                || message.includes('network error')
                || message.includes('err_failed')
                || message.includes('err_http2_protocol_error')
                || message.includes('err_connection_closed')
                || message.includes('err_connection_refused')
                || message.includes('err_connection_reset');
            if (isBrowserBlocked) {
                overpassEndpointCooldownUntil.set(endpoint, Date.now() + OVERPASS_BROWSER_BLOCK_COOLDOWN_MS);
            }
            lastError = error;
        }
    }

    const finalMessage = String(lastError?.message || lastError || '').toLowerCase();
    if (
        finalMessage.includes('failed to fetch')
        || finalMessage.includes('load failed')
        || finalMessage.includes('networkerror')
        || finalMessage.includes('err_failed')
        || finalMessage.includes('err_http2_protocol_error')
        || finalMessage.includes('err_connection_closed')
        || finalMessage.includes('err_connection_refused')
        || finalMessage.includes('err_connection_reset')
    ) {
        disableOverpassForBrowser('browser-blocked', overpassPreferredEndpoint);
    } else if (
        finalMessage.includes('http 429')
        || finalMessage.includes('http 502')
        || finalMessage.includes('http 503')
        || finalMessage.includes('http 504')
        || finalMessage.includes('overpass indisponible')
    ) {
        disableOverpassTemporarily('generic', lastEndpointTried || overpassPreferredEndpoint, OVERPASS_429_COOLDOWN_MS);
    }

    throw lastError || new Error('Overpass indisponible');
}

async function fetchNearbyAnchorages(lat, lon, radiusM = 18000) {
    const query = `
        [out:json][timeout:25];
        (
          node(around:${radiusM},${lat},${lon})["seamark:type"="anchorage"];
          way(around:${radiusM},${lat},${lon})["seamark:type"="anchorage"];
          relation(around:${radiusM},${lat},${lon})["seamark:type"="anchorage"];
          node(around:${radiusM},${lat},${lon})["leisure"="marina"];
          way(around:${radiusM},${lat},${lon})["leisure"="marina"];
        );
        out center tags;
    `;

    const elements = await fetchOverpassElements(query);
    return elements
        .map(elementToPoint)
        .filter(Boolean)
        .map((point, idx) => ({
            ...point,
            name: getPoiLabel(point, `Mouillage ${idx + 1}`),
            distanceNm: distanceNm(lat, lon, point.lat, point.lon)
        }))
        .sort((a, b) => a.distanceNm - b.distanceNm)
        .slice(0, 12);
}

async function fetchNearbyAmenityList(lat, lon, kind = 'restaurant', radiusM = 6000) {
    const filter = kind === 'shop'
        ? '"shop"~"supermarket|convenience|greengrocer|bakery|butcher"'
        : '"amenity"~"restaurant|fast_food|cafe"';

    const query = `
        [out:json][timeout:25];
        (
          node(around:${radiusM},${lat},${lon})[${filter}];
          way(around:${radiusM},${lat},${lon})[${filter}];
        );
        out center tags;
    `;

    const elements = await fetchOverpassElements(query);
    return elements
        .map(elementToPoint)
        .filter(Boolean)
        .map((point, idx) => ({
            ...point,
            name: getPoiLabel(point, kind === 'shop' ? `Magasin ${idx + 1}` : `Restaurant ${idx + 1}`),
            distanceNm: distanceNm(lat, lon, point.lat, point.lon)
        }))
        .sort((a, b) => a.distanceNm - b.distanceNm)
        .slice(0, 8);
}

function getMarinePoiBoundsBbox(bounds) {
    if (!bounds || typeof bounds.getSouth !== 'function') return '';
    const south = Number(bounds.getSouth());
    const west = Number(bounds.getWest());
    const north = Number(bounds.getNorth());
    const east = Number(bounds.getEast());
    if (![south, west, north, east].every(Number.isFinite) || north <= south || east <= west) return '';
    return `${south},${west},${north},${east}`;
}

function getMarinePoiLayerDescriptors() {
    return [
        { key: 'anchorages', layer: marineAnchoragesLayer },
        { key: 'ports', layer: marinePortsLayer },
        { key: 'services', layer: marineServicesLayer }
    ];
}

function clearMarinePoiOverlayLayers() {
    getMarinePoiLayerDescriptors().forEach(item => {
        if (typeof item.layer?.clearLayers === 'function') {
            item.layer.clearLayers();
        }
    });
}

function getMarinePoiVisibleLayerDescriptors() {
    if (!map) return [];
    return getMarinePoiLayerDescriptors().filter(item => item.layer && map.hasLayer(item.layer));
}

function getMarinePoiTypeLabel(kind, tags = {}) {
    if (kind === 'anchorages') {
        if (tags['seamark:type'] === 'mooring') return t('Mouillage organisé', 'Amarre', 'Mooring');
        return t('Mouillage', 'Fondeo', 'Anchorage');
    }
    if (kind === 'ports') {
        if (tags.leisure === 'marina') return t('Marina', 'Marina', 'Marina');
        return t('Port / abri', 'Puerto / abrigo', 'Harbour / shelter');
    }
    if (tags.amenity === 'fuel') return t('Carburant', 'Combustible', 'Fuel');
    if (tags.amenity === 'drinking_water') return t('Eau', 'Agua', 'Water');
    if (tags.amenity === 'toilets') return t('Toilettes', 'Aseos', 'Toilets');
    if (tags.amenity === 'shower') return t('Douche', 'Ducha', 'Shower');
    if (tags.shop === 'boat') return t('Accastillage', 'Náutica', 'Chandlery');
    if (tags.man_made === 'slipway') return t('Cale', 'Varadero', 'Slipway');
    if (tags.craft === 'shipyard' || tags.craft === 'boatbuilder') return t('Chantier naval', 'Astillero', 'Boatyard');
    return t('Service portuaire', 'Servicio portuario', 'Port service');
}

function getMarinePoiFallbackName(kind, index) {
    if (kind === 'anchorages') return t(`Mouillage ${index + 1}`, `Fondeo ${index + 1}`, `Anchorage ${index + 1}`);
    if (kind === 'ports') return t(`Port ${index + 1}`, `Puerto ${index + 1}`, `Port ${index + 1}`);
    return t(`Service ${index + 1}`, `Servicio ${index + 1}`, `Service ${index + 1}`);
}

function getMarinePoiServiceSummary(tags = {}) {
    const summary = [];
    if (tags.amenity === 'fuel') summary.push(t('diesel / essence à confirmer', 'diesel / gasolina por confirmar', 'fuel type to confirm'));
    if (tags.amenity === 'drinking_water') summary.push(t('eau douce', 'agua dulce', 'fresh water'));
    if (tags.amenity === 'toilets') summary.push(t('sanitaires', 'aseos', 'sanitary'));
    if (tags.amenity === 'shower') summary.push(t('douches', 'duchas', 'showers'));
    if (tags.shop === 'boat') summary.push(t('matériel de bord', 'material náutico', 'boat supplies'));
    if (tags.man_made === 'slipway') summary.push(t('mise à l’eau / sortie', 'botadura / varada', 'launch / haul-out'));
    if (tags.craft === 'shipyard' || tags.craft === 'boatbuilder') summary.push(t('réparation / chantier', 'reparación / astillero', 'repair / yard'));
    return summary.join(' · ');
}

function getMarinePoiWebsite(tags = {}) {
    return String(tags.website || tags['contact:website'] || tags.url || '').trim();
}

function getMarinePoiPhone(tags = {}) {
    return String(tags.phone || tags['contact:phone'] || '').trim();
}

function getMarinePoiEmail(tags = {}) {
    return String(tags.email || tags['contact:email'] || '').trim();
}

function getMarinePoiVhf(tags = {}) {
    return String(tags['seamark:radio_station:channel'] || tags.vhf || tags['contact:vhf'] || '').trim();
}

function getMarinePoiOperator(tags = {}) {
    return String(tags.operator || tags['seamark:harbour:category'] || tags.harbour || '').trim();
}

function getMarinePoiCapacity(tags = {}) {
    return String(tags.capacity || tags['capacity:boats'] || tags['capacity:berth'] || '').trim();
}

function getMarinePoiOpeningHours(tags = {}) {
    return String(tags.opening_hours || '').trim();
}

function getMarinePoiServiceFlags(entry) {
    const tags = entry?.tags || {};
    const flags = [];
    if (entry?.kind === 'ports') {
        if (tags.leisure === 'marina') flags.push(t('marina', 'marina', 'marina'));
        if (tags.harbour === 'yes' || tags['seamark:type'] === 'harbour') flags.push(t('abri', 'abrigo', 'harbour'));
    }
    if (tags.amenity === 'fuel' || tags.fuel === 'yes' || tags.diesel === 'yes') flags.push(t('carburant', 'combustible', 'fuel'));
    if (tags.amenity === 'drinking_water' || tags.drinking_water === 'yes' || tags.water_point === 'yes') flags.push(t('eau', 'agua', 'water'));
    if (tags.amenity === 'toilets' || tags.toilets === 'yes') flags.push(t('toilettes', 'aseos', 'toilets'));
    if (tags.amenity === 'shower' || tags.shower === 'yes') flags.push(t('douches', 'duchas', 'showers'));
    if (tags.electricity === 'yes' || tags.power_supply === 'yes') flags.push(t('électricité', 'electricidad', 'electricity'));
    if (tags.wifi === 'yes' || tags.internet_access === 'wlan') flags.push(t('wifi', 'wifi', 'wifi'));
    if (tags.slipway === 'yes' || tags.man_made === 'slipway') flags.push(t('cale', 'rampa', 'slipway'));
    if (tags.shop === 'boat') flags.push(t('accastillage', 'náutica', 'chandlery'));
    if (tags.craft === 'shipyard' || tags.craft === 'boatbuilder') flags.push(t('chantier', 'astillero', 'boatyard'));
    return flags;
}

function buildMarinePoiDetailRows(entry) {
    const tags = entry?.tags || {};
    const rows = [];
    const operator = getMarinePoiOperator(tags);
    const phone = getMarinePoiPhone(tags);
    const email = getMarinePoiEmail(tags);
    const website = getMarinePoiWebsite(tags);
    const vhf = getMarinePoiVhf(tags);
    const openingHours = getMarinePoiOpeningHours(tags);
    const capacity = getMarinePoiCapacity(tags);
    const serviceFlags = getMarinePoiServiceFlags(entry);

    if (operator) rows.push({ label: t('Gestion', 'Gestión', 'Operator'), value: escapeHtml(operator) });
    if (capacity) rows.push({ label: t('Capacité', 'Capacidad', 'Capacity'), value: escapeHtml(capacity) });
    if (vhf) rows.push({ label: 'VHF', value: escapeHtml(vhf) });
    if (phone) rows.push({ label: t('Téléphone', 'Teléfono', 'Phone'), value: escapeHtml(phone) });
    if (email) rows.push({ label: 'Email', value: escapeHtml(email) });
    if (openingHours) rows.push({ label: t('Horaires', 'Horarios', 'Hours'), value: escapeHtml(openingHours) });
    if (serviceFlags.length) rows.push({ label: t('Services', 'Servicios', 'Services'), value: escapeHtml(serviceFlags.join(' · ')) });
    if (website) {
        const safeHref = escapeHtml(website);
        rows.push({
            label: 'Web',
            value: `<a href="${safeHref}" target="_blank" rel="noreferrer noopener">${safeHref}</a>`
        });
    }
    return rows;
}

function normalizeMarinePoiEntries(elements, kind) {
    const seen = new Set();
    return (Array.isArray(elements) ? elements : [])
        .map(elementToPoint)
        .filter(Boolean)
        .map((point, index) => {
            const name = getPoiLabel(point, getMarinePoiFallbackName(kind, index));
            const typeLabel = getMarinePoiTypeLabel(kind, point.tags);
            const summary = kind === 'services'
                ? getMarinePoiServiceSummary(point.tags)
                : String(point.tags?.operator || point.tags?.harbour || point.tags?.seamark?.name || '').trim();
            return {
                ...point,
                kind,
                name,
                typeLabel,
                summary
            };
        })
        .filter(entry => {
            const key = `${entry.kind}:${entry.name}:${entry.lat.toFixed(4)}:${entry.lon.toFixed(4)}`;
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
        })
        .sort((a, b) => String(a.name).localeCompare(String(b.name), 'fr', { sensitivity: 'base' }));
}

async function fetchMarinePoisInBounds(bounds, kind) {
    const bbox = getMarinePoiBoundsBbox(bounds);
    if (!bbox) return [];

    const selectorsByKind = {
        anchorages: [
            `node(${bbox})["seamark:type"="anchorage"]`,
            `way(${bbox})["seamark:type"="anchorage"]`,
            `relation(${bbox})["seamark:type"="anchorage"]`,
            `node(${bbox})["seamark:type"="mooring"]`,
            `way(${bbox})["seamark:type"="mooring"]`
        ],
        ports: [
            `node(${bbox})["leisure"="marina"]`,
            `way(${bbox})["leisure"="marina"]`,
            `relation(${bbox})["leisure"="marina"]`,
            `node(${bbox})["harbour"="yes"]`,
            `way(${bbox})["harbour"="yes"]`,
            `relation(${bbox})["harbour"="yes"]`,
            `node(${bbox})["seamark:type"="harbour"]`,
            `way(${bbox})["seamark:type"="harbour"]`,
            `relation(${bbox})["seamark:type"="harbour"]`,
            `way(${bbox})["landuse"="harbour"]`,
            `relation(${bbox})["landuse"="harbour"]`
        ],
        services: [
            `node(${bbox})["amenity"~"fuel|drinking_water|toilets|shower"]`,
            `way(${bbox})["amenity"~"fuel|drinking_water|toilets|shower"]`,
            `node(${bbox})["shop"="boat"]`,
            `way(${bbox})["shop"="boat"]`,
            `node(${bbox})["man_made"="slipway"]`,
            `way(${bbox})["man_made"="slipway"]`,
            `node(${bbox})["craft"~"shipyard|boatbuilder"]`,
            `way(${bbox})["craft"~"shipyard|boatbuilder"]`,
            `relation(${bbox})["craft"~"shipyard|boatbuilder"]`
        ]
    };

    const selectors = selectorsByKind[kind] || [];
    if (!selectors.length) return [];

    const query = `
        [out:json][timeout:25];
        (
          ${selectors.join(';\n          ')};
        );
        out center tags;
    `;

    const elements = await fetchOverpassElements(query);
    return normalizeMarinePoiEntries(elements, kind).slice(0, MARINE_POI_OVERLAY_LIMITS[kind] || 32);
}

function buildMarinePoiIcon(kind) {
    const token = kind === 'anchorages' ? 'A' : (kind === 'ports' ? 'P' : 'S');
    return L.divIcon({
        className: 'marine-poi-icon-wrapper',
        html: `<div class="marine-poi-marker marine-poi-marker--${kind}"><span>${token}</span></div>`,
        iconSize: [24, 24],
        iconAnchor: [12, 12],
        popupAnchor: [0, -10]
    });
}

function buildMarinePoiPopup(entry) {
    const coords = `${Number(entry.lat).toFixed(5)}, ${Number(entry.lon).toFixed(5)}`;
    const summaryLine = entry.summary ? `<div class="marine-poi-popup__meta">${escapeHtml(entry.summary)}</div>` : '';
    const detailRows = buildMarinePoiDetailRows(entry)
        .map(row => `<div class="marine-poi-popup__row"><span class="marine-poi-popup__label">${escapeHtml(row.label)}</span><span class="marine-poi-popup__value">${row.value}</span></div>`)
        .join('');
    const detailsBlock = detailRows ? `<div class="marine-poi-popup__details">${detailRows}</div>` : '';
    return `<div class="marine-poi-popup"><strong>${escapeHtml(entry.name)}</strong><div class="marine-poi-popup__type">${escapeHtml(entry.typeLabel)}</div>${summaryLine}${detailsBlock}<div class="marine-poi-popup__coords">${coords}</div></div>`;
}

function buildMarinePoiMarker(entry) {
    if (!map || !entry || !Number.isFinite(entry.lat) || !Number.isFinite(entry.lon)) return null;
    const marker = L.marker([entry.lat, entry.lon], {
        icon: buildMarinePoiIcon(entry.kind),
        interactive: true,
        keyboard: false,
        zIndexOffset: 780
    });
    marker.bindPopup(buildMarinePoiPopup(entry), { maxWidth: 260, autoPan: false });
    marker.bindTooltip(`${entry.typeLabel} · ${entry.name}`, {
        direction: 'top',
        opacity: 0.92
    });
    return marker;
}

async function refreshMarinePoiOverlays({ force = false } = {}) {
    if (isOverpassTemporarilyDisabled()) {
        removeMarinePoiLayersFromMap();
        return;
    }

    const visibleLayers = getMarinePoiVisibleLayerDescriptors();
    if (!map || !visibleLayers.length) return;

    const signature = getMarinePoiRefreshSignature();
    if (!signature) return;
    if (!force && marinePoiOverlayRefreshPromise) {
        return marinePoiOverlayRefreshPromise;
    }
    if (!force && signature === marinePoiOverlayLastRequestSignature && (Date.now() - marinePoiOverlayLastRequestAt) < MARINE_POI_REFRESH_COOLDOWN_MS) {
        return;
    }

    marinePoiOverlayLastRequestSignature = signature;
    marinePoiOverlayLastRequestAt = Date.now();
    marinePoiOverlayRefreshPromise = (async () => {
        const refreshToken = ++marinePoiOverlayRefreshToken;
        visibleLayers.forEach(item => {
            if (typeof item.layer?.clearLayers === 'function') {
                item.layer.clearLayers();
            }
        });

        if (map.getZoom() < MARINE_POI_OVERLAY_MIN_ZOOM) {
            return;
        }

        const paddedBounds = map.getBounds()?.pad?.(0.12) || map.getBounds();
        for (const item of visibleLayers) {
            let entries = [];
            try {
                entries = await fetchMarinePoisInBounds(paddedBounds, item.key);
            } catch (_error) {
                entries = [];
            }

            if (refreshToken !== marinePoiOverlayRefreshToken) return;
            if (!item.layer || !map.hasLayer(item.layer)) continue;

            entries.forEach(entry => {
                const marker = buildMarinePoiMarker(entry);
                if (marker) item.layer.addLayer(marker);
            });
        }
    })();

    try {
        await marinePoiOverlayRefreshPromise;
    } finally {
        marinePoiOverlayRefreshPromise = null;
    }
}

async function scoreAnchoragesForArrival(anchorages, arrivalDateTime) {
    const arrivalSlot = toDateAndHourUtc(arrivalDateTime);

    const scored = [];
    for (const anchorage of anchorages) {
        let weather = null;
        try {
            weather = await getWeatherAtDateHour(anchorage.lat, anchorage.lon, arrivalSlot.date, arrivalSlot.hour);
        } catch (_error) {
            weather = null;
        }
        const wind = Number.isFinite(weather?.windSpeed) ? weather.windSpeed : 12;
        const wave = Number.isFinite(weather?.waveHeight) ? weather.waveHeight : 0.8;

        const penalty =
            anchorage.distanceNm * 3 +
            Math.max(0, wind - RECOMMENDED_MAX_WIND_KN) * 25 +
            Math.abs(wind - 12) * 0.8 +
            Math.max(0, wave - 1.6) * 10;

        scored.push({
            ...anchorage,
            weather,
            score: penalty,
            confidence: wind <= 20 && wave <= 1.8 ? 'élevée' : (wind <= 24 ? 'moyenne' : 'prudence')
        });
    }

    return scored.sort((a, b) => a.score - b.score).slice(0, 3);
}

function buildFallbackArrivalAnchorage(destination) {
    const lat = Number(destination?.lat);
    const lon = Number(destination?.lng ?? destination?.lon);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;

    return {
        lat,
        lon,
        name: t('Point d\'arrivée à confirmer', 'Punto de llegada por confirmar', 'Arrival point to confirm'),
        distanceNm: 0,
        tags: {
            source: 'ceibo-fallback'
        }
    };
}

function renderNearbyList(containerId, items, emptyText) {
    const container = document.getElementById(containerId);
    if (!container) return;

    if (!Array.isArray(items) || items.length === 0) {
        container.innerHTML = `<div class="arrival-list__item">${escapeHtml(emptyText)}</div>`;
        return;
    }

    const isShopList = containerId === 'nearbyShops';
    const kind = isShopList ? 'shop' : 'restaurant';

    const clamp = (value, min, max) => Math.max(min, Math.min(max, value));

    const buildGoogleSearchUrl = (item) => {
        const name = String(item?.name || '').trim();
        const lat = Number(item?.lat);
        const lon = Number(item?.lon);
        const hasCoords = Number.isFinite(lat) && Number.isFinite(lon);
        const coords = hasCoords ? `${lat.toFixed(6)},${lon.toFixed(6)}` : '';
        const query = [name, coords].filter(Boolean).join(', ');
        const safeQuery = query || name || coords || '';
        return `https://maps.google.com/maps?q=${encodeURIComponent(safeQuery)}&hl=fr&z=14&output=embed`;
    };

    const buildRestaurantMenuUrl = (item) => {
        const tags = item?.tags || {};
        const websiteRaw = String(tags.website || tags['contact:website'] || '').trim();
        if (websiteRaw) {
            return /^https?:\/\//i.test(websiteRaw) ? websiteRaw : `https://${websiteRaw}`;
        }

        const name = String(item?.name || '').trim();
        const lat = Number(item?.lat);
        const lon = Number(item?.lon);
        const hasCoords = Number.isFinite(lat) && Number.isFinite(lon);
        const query = [name, 'menu', hasCoords ? `${lat.toFixed(5)},${lon.toFixed(5)}` : ''].filter(Boolean).join(' ');
        return `https://www.google.com/search?q=${encodeURIComponent(query)}`;
    };

    const formatAmenityScore = (item, amenityKind) => {
        const distance = Number(item?.distanceNm);
        const tags = item?.tags || {};
        let score = 86;

        if (Number.isFinite(distance)) {
            score -= distance * 9;
        }

        if (tags.opening_hours) score += 4;
        if (tags.phone) score += 3;
        if (tags.website) score += 4;
        if (tags['addr:street']) score += 2;
        if (tags.wheelchair === 'yes') score += 2;

        if (amenityKind === 'restaurant') {
            if (tags.cuisine) score += 6;
            if (tags.takeaway === 'yes') score += 2;
            if (tags.delivery === 'yes') score += 2;
            if (tags.outdoor_seating === 'yes') score += 1;
        } else {
            if (tags.shop) score += 4;
            if (tags.brand) score += 3;
            if (tags.organic === 'yes') score += 2;
        }

        return clamp(Math.round(score), 45, 99);
    };

    const buildAmenitySummary = (item, amenityKind) => {
        const tags = item?.tags || {};
        const summaryParts = [];

        if (amenityKind === 'restaurant') {
            const cuisine = String(tags.cuisine || '').trim();
            if (cuisine) {
                summaryParts.push(`${t('Cuisine', 'Cocina')}: ${cuisine.replaceAll(';', ', ')}`);
            }
            if (tags.takeaway === 'yes') summaryParts.push(t('À emporter', 'Para llevar'));
            if (tags.delivery === 'yes') summaryParts.push(t('Livraison', 'Entrega'));
        } else {
            const shopType = String(tags.shop || '').trim();
            if (shopType) summaryParts.push(`${t('Type', 'Tipo')}: ${shopType}`);
            const brand = String(tags.brand || '').trim();
            if (brand) summaryParts.push(`${t('Enseigne', 'Marca')}: ${brand}`);
        }

        const openingHours = String(tags.opening_hours || '').trim();
        if (openingHours) {
            summaryParts.push(`${t('Horaires', 'Horario')}: ${openingHours}`);
        }

        if (summaryParts.length === 0) {
            return t('Infos limitées (OSM)', 'Info limitada (OSM)');
        }

        return summaryParts.slice(0, 2).join(' · ');
    };

    container.innerHTML = `<div class="arrival-list">${items.map(item =>
        `<div class="arrival-list__item">
            <div class="arrival-list__head">
                <strong>${escapeHtml(item.name)}</strong>
                <span class="arrival-list__score">${t('Score', 'Puntuacion')}: ${formatAmenityScore(item, kind)}/100</span>
            </div>
            <div class="arrival-list__meta">${item.distanceNm.toFixed(2)} nm · ${escapeHtml(buildAmenitySummary(item, kind))}</div>
            <a class="arrival-list__link" href="${buildGoogleSearchUrl(item)}">${t('Voir sur Google', 'Ver en Google')}</a>
            ${kind === 'restaurant'
                ? `<a class="arrival-list__link arrival-list__link--menu" href="${buildRestaurantMenuUrl(item)}">${t('Carte / Menu', 'Carta / Menú', 'Menu')}</a>`
                : ''}
        </div>`
    ).join('')}</div>`;

    container.querySelectorAll('.arrival-list__link').forEach(link => {
        link.addEventListener('click', event => {
            event.preventDefault();
            const href = String(link.getAttribute('href') || '').trim();
            if (!href) return;
            openUrlInMapOverlay(href);
        });
    });
}

function applyAnchorageAsFinalWaypoint(anchorage) {
    if (!anchorage || !Number.isFinite(anchorage.lat) || !Number.isFinite(anchorage.lon)) return;

    const latlng = L.latLng(anchorage.lat, anchorage.lon);
    if (routePoints.length === 0) {
        routePoints.push(latlng);
        const marker = createWaypointMarker(latlng);
        markers.push(marker);
    } else {
        const lastIndex = routePoints.length - 1;
        routePoints[lastIndex] = latlng;
        const lastMarker = markers[lastIndex];
        if (lastMarker) {
            lastMarker.setLatLng(latlng);
        } else {
            const marker = createWaypointMarker(latlng);
            markers[lastIndex] = marker;
        }
    }

    map.panTo(latlng, { animate: true, duration: 0.45 });
}

function renderAnchorageRecommendations(recommendations) {
    const container = document.getElementById('anchorageRecommendations');
    if (!container) return;

    if (!Array.isArray(recommendations) || recommendations.length === 0) {
        container.innerHTML = `<div class="arrival-card">${t('Aucun mouillage recommandé trouvé.', 'No se encontró fondeo recomendado.')}</div>`;
        return;
    }

    container.innerHTML = recommendations.map((item, index) => {
        const wind = Number.isFinite(item?.weather?.windSpeed) ? `${item.weather.windSpeed.toFixed(1)} kn` : 'N/A';
        const wave = Number.isFinite(item?.weather?.waveHeight) ? `${item.weather.waveHeight.toFixed(1)} m` : 'N/A';
        return `
            <div class="arrival-card">
                <div class="arrival-card__head">
                    <span>#${index + 1} ${escapeHtml(item.name)}</span>
                    <span>${item.distanceNm.toFixed(2)} nm</span>
                </div>
                <div>${t('Vent ETA', 'Viento ETA')}: ${wind} · ${t('Houle ETA', 'Oleaje ETA')}: ${wave} · ${t('Confiance', 'Confianza')}: ${escapeHtml(item.confidence)}</div>
                <button type="button" class="apply-anchorage-btn" data-anch-index="${index}">${t('Utiliser comme WP final', 'Usar como WP final')}</button>
            </div>
        `;
    }).join('');

    const buttons = container.querySelectorAll('.apply-anchorage-btn');
    buttons.forEach(btn => {
        btn.addEventListener('click', () => {
            const idx = Number(btn.getAttribute('data-anch-index'));
            const selected = recommendations[idx];
            if (selected) applyAnchorageAsFinalWaypoint(selected);
        });
    });
}

function normalizeArrivalAnalysisHourIso(value) {
    const date = value instanceof Date ? new Date(value.getTime()) : new Date(value || '');
    if (Number.isNaN(date.getTime())) return '';
    date.setUTCMinutes(0, 0, 0);
    return date.toISOString();
}

function buildArrivalAnalysisCacheKey(destinationLat, destinationLng, arrivalDateTime) {
    const lat = Number(destinationLat);
    const lng = Number(destinationLng);
    const arrivalIso = normalizeArrivalAnalysisHourIso(arrivalDateTime);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return '';
    return `${lat.toFixed(4)}:${lng.toFixed(4)}:${arrivalIso || 'no-arrival-time'}`;
}

function sanitizeArrivalAnalysisAmenityItem(item, fallbackIndex = 0) {
    const lat = Number(item?.lat);
    const lon = Number(item?.lon ?? item?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;

    const distance = Number(item?.distanceNm);
    return {
        name: String(item?.name || `Lieu ${fallbackIndex + 1}`).trim() || `Lieu ${fallbackIndex + 1}`,
        lat,
        lon,
        distanceNm: Number.isFinite(distance) ? distance : 0,
        tags: item?.tags && typeof item.tags === 'object' && !Array.isArray(item.tags)
            ? { ...item.tags }
            : {}
    };
}

function sanitizeArrivalAnalysisRecommendationItem(item, fallbackIndex = 0) {
    const base = sanitizeArrivalAnalysisAmenityItem(item, fallbackIndex);
    if (!base) return null;

    const windSpeed = Number(item?.weather?.windSpeed ?? item?.weatherWindSpeed);
    const waveHeight = Number(item?.weather?.waveHeight ?? item?.weatherWaveHeight);
    const score = Number(item?.score);

    return {
        ...base,
        score: Number.isFinite(score) ? score : null,
        confidence: String(item?.confidence || '').trim() || 'prudence',
        weather: {
            windSpeed: Number.isFinite(windSpeed) ? windSpeed : null,
            waveHeight: Number.isFinite(waveHeight) ? waveHeight : null
        }
    };
}

function sanitizeArrivalAnalysisEntry(entry, fallbackIndex = 0) {
    const destinationLat = Number(entry?.destinationLat ?? entry?.destination?.lat);
    const destinationLng = Number(entry?.destinationLng ?? entry?.destination?.lng ?? entry?.destination?.lon);
    if (!Number.isFinite(destinationLat) || !Number.isFinite(destinationLng)) return null;

    const recommendations = (Array.isArray(entry?.recommendations) ? entry.recommendations : [])
        .map((item, index) => sanitizeArrivalAnalysisRecommendationItem(item, index))
        .filter(Boolean)
        .slice(0, 8);
    const restaurants = (Array.isArray(entry?.restaurants) ? entry.restaurants : [])
        .map((item, index) => sanitizeArrivalAnalysisAmenityItem(item, index))
        .filter(Boolean)
        .slice(0, 12);
    const shops = (Array.isArray(entry?.shops) ? entry.shops : [])
        .map((item, index) => sanitizeArrivalAnalysisAmenityItem(item, index))
        .filter(Boolean)
        .slice(0, 12);
    const arrivalIso = normalizeArrivalAnalysisHourIso(entry?.arrivalIso);
    const cacheKey = String(entry?.cacheKey || buildArrivalAnalysisCacheKey(destinationLat, destinationLng, arrivalIso)).trim();
    const nowIso = new Date().toISOString();

    return {
        id: isUuidString(entry?.id) ? String(entry.id) : generateClientUuid(),
        cacheKey,
        destinationLabel: String(entry?.destinationLabel || '').trim(),
        destinationLat,
        destinationLng,
        arrivalIso,
        routeName: String(entry?.routeName || '').trim(),
        topAnchorageName: String(entry?.topAnchorageName || recommendations[0]?.name || '').trim(),
        summaryText: String(entry?.summaryText || '').trim(),
        recommendations,
        restaurants,
        shops,
        creatorEmail: normalizeEmailForCompare(entry?.creatorEmail || ''),
        creatorName: String(entry?.creatorName || '').trim(),
        createdAt: String(entry?.createdAt || nowIso),
        updatedAt: String(entry?.updatedAt || entry?.createdAt || nowIso)
    };
}

function getArrivalAnalysisStorageList() {
    try {
        return loadArrayFromStorage(ARRIVAL_ANALYSIS_STORAGE_KEY);
    } catch (_error) {
        return [];
    }
}

function setArrivalAnalysisStorageList(list) {
    try {
        saveArrayToStorage(ARRIVAL_ANALYSIS_STORAGE_KEY, list);
        return true;
    } catch (_error) {
        return false;
    }
}

function loadArrivalAnalysisEntries() {
    arrivalAnalysisEntries = getArrivalAnalysisStorageList()
        .map((entry, index) => sanitizeArrivalAnalysisEntry(entry, index))
        .filter(Boolean)
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
}

function setArrivalAnalysisEntries(list, { persistLocal = true, refreshUi = true } = {}) {
    arrivalAnalysisEntries = (Array.isArray(list) ? list : [])
        .map((entry, index) => sanitizeArrivalAnalysisEntry(entry, index))
        .filter(Boolean)
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))
        .slice(0, MAX_ARRIVAL_ANALYSIS_CACHE_ENTRIES);

    if (persistLocal) {
        setArrivalAnalysisStorageList(arrivalAnalysisEntries);
    }

    if (refreshUi) {
        renderArrivalSavedSearches();
    }
}

function persistArrivalAnalysisEntries() {
    return setArrivalAnalysisStorageList(arrivalAnalysisEntries);
}

function setArrivalCacheStatus(message, isError = false) {
    const status = document.getElementById('arrivalCacheStatus');
    if (!status) return;
    status.textContent = String(message || '');
    status.style.color = isError ? '#ff8f8f' : '';
}

function buildArrivalSummaryText(recommendations) {
    if (Array.isArray(recommendations) && recommendations.length > 0) {
        return t(
            `Top mouillage: ${recommendations[0].name} · ${recommendations[0].distanceNm.toFixed(2)} nm de l'arrivée`,
            `Mejor fondeo: ${recommendations[0].name} · ${recommendations[0].distanceNm.toFixed(2)} mn de la llegada`,
            `Top anchorage: ${recommendations[0].name} · ${recommendations[0].distanceNm.toFixed(2)} nm from arrival`
        );
    }

    return t(
        'Analyse mouillage: aucun mouillage adapté trouvé à proximité.',
        'Análisis fondeo: no se encontró un fondeo adecuado cerca.',
        'Anchorage analysis: no suitable anchorage found nearby.'
    );
}

function renderArrivalSummary(recommendations) {
    const summary = document.getElementById('arrivalSummary');
    if (!summary) return;

    if (Array.isArray(recommendations) && recommendations.length > 0) {
        summary.innerHTML = `<strong>${t('Top mouillage:', 'Mejor fondeo:', 'Top anchorage:')}</strong> ${escapeHtml(recommendations[0].name)} · ${recommendations[0].distanceNm.toFixed(2)} nm ${t('de l\'arrivée', 'de la llegada', 'from arrival')}`;
        return;
    }

    summary.textContent = buildArrivalSummaryText(recommendations);
}

function buildArrivalAnalysisLabel(entry) {
    const routeName = String(entry?.routeName || '').trim();
    const destinationLabel = String(entry?.destinationLabel || '').trim();
    const topAnchorageName = String(entry?.topAnchorageName || '').trim();

    if (routeName && destinationLabel) return `${routeName} · ${destinationLabel}`;
    if (routeName && topAnchorageName) return `${routeName} · ${topAnchorageName}`;
    if (destinationLabel) return destinationLabel;
    if (topAnchorageName) return topAnchorageName;

    return `${entry.destinationLat.toFixed(4)}, ${entry.destinationLng.toFixed(4)}`;
}

function renderArrivalAnalysisEntry(entry, { fromCache = false } = {}) {
    if (!entry) return false;

    clearArrivalPoiMarkers();
    entry.recommendations.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'anchorage'));
    entry.restaurants.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'restaurant'));
    entry.shops.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'shop'));

    renderArrivalSummary(entry.recommendations);
    renderAnchorageRecommendations(entry.recommendations);
    renderNearbyList('nearbyRestaurants', entry.restaurants, t('Aucun restaurant proche trouvé', 'No se encontraron restaurantes cercanos', 'No nearby restaurant found'));
    renderNearbyList('nearbyShops', entry.shops, t('Aucun magasin proche trouvé', 'No se encontraron tiendas cercanas', 'No nearby shop found'));

    setArrivalCacheStatus(
        fromCache
            ? t(
                `Analyse mémorisée rechargée · ${buildArrivalAnalysisLabel(entry)}`,
                `Análisis guardado recargado · ${buildArrivalAnalysisLabel(entry)}`,
                `Saved analysis reloaded · ${buildArrivalAnalysisLabel(entry)}`
            )
            : t(
                `Analyse mémorisée en local · ${buildArrivalAnalysisLabel(entry)}`,
                `Análisis guardado en local · ${buildArrivalAnalysisLabel(entry)}`,
                `Analysis cached locally · ${buildArrivalAnalysisLabel(entry)}`
            )
    );
    return true;
}

function findBestArrivalAnalysisMatch(destination, arrivalDateTime = null) {
    if (!destination || !Number.isFinite(destination.lat) || !Number.isFinite(destination.lng)) {
        return arrivalAnalysisEntries[0] || null;
    }

    const exactKey = buildArrivalAnalysisCacheKey(destination.lat, destination.lng, arrivalDateTime);
    if (exactKey) {
        const exactMatch = arrivalAnalysisEntries.find(entry => entry.cacheKey === exactKey);
        if (exactMatch) return exactMatch;
    }

    const nearbyMatches = arrivalAnalysisEntries
        .map(entry => ({
            entry,
            distance: distanceNm(destination.lat, destination.lng, entry.destinationLat, entry.destinationLng),
            timeDeltaMs: arrivalDateTime
                ? Math.abs(new Date(entry.arrivalIso || 0).getTime() - new Date(arrivalDateTime).getTime())
                : Number.POSITIVE_INFINITY
        }))
        .filter(item => Number.isFinite(item.distance) && item.distance <= ARRIVAL_ANALYSIS_MATCH_RADIUS_NM)
        .sort((a, b) => {
            if (a.distance !== b.distance) return a.distance - b.distance;
            return a.timeDeltaMs - b.timeDeltaMs;
        });

    return nearbyMatches[0]?.entry || arrivalAnalysisEntries[0] || null;
}

function renderArrivalSavedSearches() {
    const container = document.getElementById('arrivalSavedSearches');
    const loadLatestBtn = document.getElementById('loadLatestArrivalCacheBtn');
    if (loadLatestBtn) loadLatestBtn.disabled = arrivalAnalysisEntries.length === 0;
    if (!container) return;

    if (!arrivalAnalysisEntries.length) {
        container.innerHTML = `<div class="arrival-list__item">${t('Aucune analyse mémorisée.', 'Ningún análisis guardado.', 'No saved analysis.')}</div>`;
        return;
    }

    container.innerHTML = arrivalAnalysisEntries.map(entry => {
        const label = escapeHtml(buildArrivalAnalysisLabel(entry));
        const updatedAt = escapeHtml(formatUtcDateTime(entry.updatedAt || entry.createdAt));
        const recCount = Array.isArray(entry.recommendations) ? entry.recommendations.length : 0;
        const restCount = Array.isArray(entry.restaurants) ? entry.restaurants.length : 0;
        const shopCount = Array.isArray(entry.shops) ? entry.shops.length : 0;
        const canDelete = isOwnedByCurrentCloudUser(entry?.creatorEmail);
        return `<div class="arrival-saved-item">
            <div class="arrival-saved-item__title">
                <span>${label}</span>
                <span>${updatedAt}</span>
            </div>
            <div class="arrival-saved-item__meta">${escapeHtml(String(entry.summaryText || buildArrivalSummaryText(entry.recommendations)))}</div>
            <div class="arrival-saved-item__meta">${t('Mouillages', 'Fondeos', 'Anchorages')}: ${recCount} · ${t('Restaurants', 'Restaurantes', 'Restaurants')}: ${restCount} · ${t('Magasins', 'Tiendas', 'Shops')}: ${shopCount}</div>
            <div class="button-row">
                <button type="button" class="js-arrival-analysis-load" data-id="${escapeHtml(entry.id)}">${t('Charger', 'Cargar', 'Load')}</button>
                ${canDelete ? `<button type="button" class="js-arrival-analysis-delete" data-id="${escapeHtml(entry.id)}">${t('Supprimer', 'Eliminar', 'Delete')}</button>` : ''}
            </div>
        </div>`;
    }).join('');

    container.querySelectorAll('.js-arrival-analysis-load').forEach(button => {
        button.addEventListener('click', () => {
            const entry = arrivalAnalysisEntries.find(item => item.id === String(button.getAttribute('data-id') || ''));
            if (!entry) return;
            renderArrivalAnalysisEntry(entry, { fromCache: true });
        });
    });

    container.querySelectorAll('.js-arrival-analysis-delete').forEach(button => {
        button.addEventListener('click', () => {
            deleteArrivalAnalysisEntry(String(button.getAttribute('data-id') || ''));
        });
    });
}

function deleteArrivalAnalysisEntry(entryId) {
    const existingIndex = arrivalAnalysisEntries.findIndex(entry => entry.id === entryId);
    if (existingIndex < 0) return false;

    const target = arrivalAnalysisEntries[existingIndex];
    const confirmed = window.confirm(t(
        `Supprimer l'analyse mémorisée “${buildArrivalAnalysisLabel(target)}” ?`,
        `¿Eliminar el análisis guardado “${buildArrivalAnalysisLabel(target)}”?`,
        `Delete the saved analysis “${buildArrivalAnalysisLabel(target)}”?`
    ));
    if (!confirmed) return false;

    const previousEntries = [...arrivalAnalysisEntries];
    arrivalAnalysisEntries.splice(existingIndex, 1);
    if (!persistArrivalAnalysisEntries()) {
        arrivalAnalysisEntries = previousEntries;
        setArrivalCacheStatus(t('Suppression impossible: stockage local saturé ou indisponible.', 'Eliminación imposible: almacenamiento local saturado o no disponible.', 'Delete failed: local storage unavailable or full.'), true);
        return false;
    }

    arrivalAnalysesCloudDirty = true;
    renderArrivalSavedSearches();
    setArrivalCacheStatus(t('Analyse mémorisée supprimée.', 'Análisis guardado eliminado.', 'Saved analysis deleted.'));
    tryFlushPendingCloudDataPush();
    return true;
}

function storeArrivalAnalysisSnapshot({ destination, arrivalTime, recommendations, restaurants, shops }) {
    if (!destination || !Number.isFinite(destination.lat) || !Number.isFinite(destination.lng)) {
        return null;
    }

    const creator = getCreatorPatch();
    const nowIso = new Date().toISOString();
    const currentRoute = Number.isInteger(currentLoadedRouteIndex) ? getSavedRoutes()[currentLoadedRouteIndex] : null;
    const destinationLabel = String(lastComputedReportData?.segments?.slice(-1)?.[0]?.arrivalLabel || '').trim();
    const safeEntry = sanitizeArrivalAnalysisEntry({
        id: generateClientUuid(),
        cacheKey: buildArrivalAnalysisCacheKey(destination.lat, destination.lng, arrivalTime),
        destinationLat: destination.lat,
        destinationLng: destination.lng,
        destinationLabel,
        arrivalIso: arrivalTime,
        routeName: String(currentRoute?.name || '').trim(),
        topAnchorageName: recommendations?.[0]?.name || '',
        summaryText: buildArrivalSummaryText(recommendations),
        recommendations,
        restaurants,
        shops,
        creatorEmail: creator.creatorEmail,
        creatorName: creator.creatorName,
        createdAt: nowIso,
        updatedAt: nowIso
    });

    if (!safeEntry) return null;

    const previousEntries = [...arrivalAnalysisEntries];
    const existingIndex = arrivalAnalysisEntries.findIndex(entry => entry.cacheKey === safeEntry.cacheKey);
    if (existingIndex >= 0) {
        safeEntry.id = arrivalAnalysisEntries[existingIndex].id;
        safeEntry.createdAt = arrivalAnalysisEntries[existingIndex].createdAt || nowIso;
        arrivalAnalysisEntries.splice(existingIndex, 1);
    }
    arrivalAnalysisEntries.unshift(safeEntry);
    arrivalAnalysisEntries = arrivalAnalysisEntries.slice(0, MAX_ARRIVAL_ANALYSIS_CACHE_ENTRIES);

    if (!persistArrivalAnalysisEntries()) {
        arrivalAnalysisEntries = previousEntries;
        setArrivalCacheStatus(t('Analyse calculée mais non mémorisée: stockage local saturé.', 'Análisis calculado pero no guardado: almacenamiento local lleno.', 'Analysis computed but not cached: local storage full.'), true);
        return null;
    }

    arrivalAnalysesCloudDirty = true;
    renderArrivalSavedSearches();
    setArrivalCacheStatus(
        isCloudReady()
            ? t('Analyse mémorisée en local. Sauvegarde cloud en cours.', 'Análisis guardado en local. Copia nube en curso.', 'Analysis cached locally. Cloud backup in progress.')
            : t('Analyse mémorisée en local. Sauvegarde cloud en attente.', 'Análisis guardado en local. Copia nube en espera.', 'Analysis cached locally. Cloud backup pending.')
    );
    tryFlushPendingCloudDataPush();
    return safeEntry;
}

function loadLatestArrivalAnalysisForCurrentRoute() {
    if (!arrivalAnalysisEntries.length) {
        setArrivalCacheStatus(t('Aucune analyse mémorisée disponible.', 'Ningún análisis guardado disponible.', 'No saved analysis available.'), true);
        return false;
    }

    const destination = routePoints[routePoints.length - 1];
    const arrivalTime = routePoints.length >= 2 ? getArrivalReferenceDateTime() : null;
    const entry = findBestArrivalAnalysisMatch(destination, arrivalTime);
    if (!entry) {
        setArrivalCacheStatus(t('Aucune analyse mémorisée compatible avec cette arrivée.', 'Ningún análisis guardado compatible con esta llegada.', 'No saved analysis matches this arrival.'), true);
        return false;
    }

    return renderArrivalAnalysisEntry(entry, { fromCache: true });
}

async function analyzeArrivalZone() {
    if (routePoints.length < 2) {
        alert(t('Ajoute au moins 2 waypoints pour analyser la zone d\'arrivée.', 'Añade al menos 2 waypoints para analizar la zona de llegada.'));
        return;
    }

    beginAiTrafficSession(t('Analyse zone arrivée', 'Análisis zona llegada'));

    const button = document.getElementById('analyzeArrivalBtn');
    const summary = document.getElementById('arrivalSummary');
    if (button) {
        button.disabled = true;
        button.textContent = t('Analyse en cours...', 'Análisis en curso...');
    }
    if (summary) summary.textContent = t('Analyse mouillage: récupération des données...', 'Análisis fondeo: recuperando datos...');

    clearArrivalPoiMarkers();
    pushAiTrafficLog(t('Nettoyage des marqueurs d\'arrivée précédents', 'Limpieza de marcadores de llegada anteriores'));

    try {
        const destination = routePoints[routePoints.length - 1];
        const arrivalTime = getArrivalReferenceDateTime();
        const arrivalWarnings = [];
        pushAiTrafficLog(t(
            `Destination ciblée: ${Number(destination.lat).toFixed(4)}, ${Number(destination.lng).toFixed(4)}`,
            `Destino objetivo: ${Number(destination.lat).toFixed(4)}, ${Number(destination.lng).toFixed(4)}`
        ));

        pushAiTrafficLog(t('Recherche mouillages à proximité (Overpass)...', 'Busqueda de fondeos cercanos (Overpass)...'));
        let anchorages = [];
        try {
            anchorages = await fetchNearbyAnchorages(destination.lat, destination.lng);
        } catch (error) {
            const message = String(error?.message || error || 'Overpass indisponible');
            arrivalWarnings.push(t('Mouillages live indisponibles', 'Fondeos live no disponibles', 'Live anchorages unavailable'));
            pushAiTrafficLog(t(
                `Recherche mouillages indisponible: ${message}`,
                `Busqueda de fondeos no disponible: ${message}`,
                `Anchorage lookup unavailable: ${message}`
            ));
        }
        if (!anchorages.length) {
            const fallbackAnchorage = buildFallbackArrivalAnchorage(destination);
            if (fallbackAnchorage) {
                anchorages = [fallbackAnchorage];
                arrivalWarnings.push(t('Conseil réduit au point d\'arrivée final', 'Consejo reducido al punto final de llegada', 'Fallback limited to final arrival point'));
                pushAiTrafficLog(t(
                    'Aucun mouillage OSM disponible: utilisation du point d\'arrivée comme fallback.',
                    'Sin fondeos OSM disponibles: uso del punto de llegada como fallback.',
                    'No OSM anchorages available: using arrival point as fallback.'
                ));
            }
        }
        pushAiTrafficLog(t(`Mouillages trouvés: ${anchorages.length}`, `Fondeos encontrados: ${anchorages.length}`));

        pushAiTrafficLog(t('Recherche restaurants proches...', 'Busqueda de restaurantes cercanos...'));
        let restaurants = [];
        try {
            restaurants = await fetchNearbyAmenityList(destination.lat, destination.lng, 'restaurant');
        } catch (error) {
            const message = String(error?.message || error || 'Overpass indisponible');
            arrivalWarnings.push(t('Restaurants indisponibles', 'Restaurantes no disponibles', 'Restaurants unavailable'));
            pushAiTrafficLog(t(
                `Recherche restaurants indisponible: ${message}`,
                `Busqueda de restaurantes no disponible: ${message}`,
                `Restaurant lookup unavailable: ${message}`
            ));
        }
        pushAiTrafficLog(t(`Restaurants trouvés: ${restaurants.length}`, `Restaurantes encontrados: ${restaurants.length}`));

        pushAiTrafficLog(t('Recherche magasins proches...', 'Busqueda de tiendas cercanas...'));
        let shops = [];
        try {
            shops = await fetchNearbyAmenityList(destination.lat, destination.lng, 'shop');
        } catch (error) {
            const message = String(error?.message || error || 'Overpass indisponible');
            arrivalWarnings.push(t('Magasins indisponibles', 'Tiendas no disponibles', 'Shops unavailable'));
            pushAiTrafficLog(t(
                `Recherche magasins indisponible: ${message}`,
                `Busqueda de tiendas no disponible: ${message}`,
                `Shop lookup unavailable: ${message}`
            ));
        }
        pushAiTrafficLog(t(`Magasins trouvés: ${shops.length}`, `Tiendas encontradas: ${shops.length}`));

        pushAiTrafficLog(t('Scoring météo des mouillages...', 'Puntuacion meteo de los fondeos...'));
        const recommendations = await scoreAnchoragesForArrival(anchorages, arrivalTime);
        pushAiTrafficLog(t(
            `Top recommandations calculées: ${recommendations.length}`,
            `Top recomendaciones calculadas: ${recommendations.length}`
        ));

        recommendations.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'anchorage'));
        restaurants.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'restaurant'));
        shops.forEach(item => addArrivalPoiMarker(item.lat, item.lon, item.name, 'shop'));
        pushAiTrafficLog(t('Marqueurs arrivée affichés sur la carte', 'Marcadores de llegada mostrados en el mapa'));

        renderAnchorageRecommendations(recommendations);
        renderNearbyList('nearbyRestaurants', restaurants, t('Aucun restaurant proche trouvé', 'No se encontraron restaurantes cercanos'));
        renderNearbyList('nearbyShops', shops, t('Aucun magasin proche trouvé', 'No se encontraron tiendas cercanas'));
        pushAiTrafficLog(t('Listes arrivée mises à jour', 'Listas de llegada actualizadas'));

        renderArrivalSummary(recommendations);
        if (arrivalWarnings.length) {
            setArrivalCacheStatus(arrivalWarnings.join(' · '), true);
        }
        if (recommendations.length) {
            pushAiTrafficLog(t(
                `Top mouillage: ${recommendations[0].name} (${recommendations[0].distanceNm.toFixed(2)} nm)`,
                `Mejor fondeo: ${recommendations[0].name} (${recommendations[0].distanceNm.toFixed(2)} nm)`
            ));
        } else {
            pushAiTrafficLog(t('Aucun mouillage adapté trouvé', 'No se encontró fondeo adecuado'));
        }

        storeArrivalAnalysisSnapshot({
            destination,
            arrivalTime,
            recommendations,
            restaurants,
            shops
        });
        endAiTrafficSession(t('Analyse arrivée terminée', 'Análisis llegada terminado'));
    } catch (_error) {
        pushAiTrafficLog(t('Erreur pendant l\'analyse arrivée', 'Error durante el análisis de llegada'));
        const destination = routePoints[routePoints.length - 1];
        const arrivalTime = getArrivalReferenceDateTime();
        const cachedEntry = findBestArrivalAnalysisMatch(destination, arrivalTime);
        if (cachedEntry) {
            renderArrivalAnalysisEntry(cachedEntry, { fromCache: true });
            pushAiTrafficLog(t('Analyse live indisponible: cache ARRIVEE rechargé', 'Análisis live no disponible: caché LLEGADA recargado'));
            endAiTrafficSession(t('Analyse arrivée rechargée depuis le cache', 'Análisis llegada recargado desde caché'));
            return;
        }
        if (summary) summary.textContent = t('Analyse mouillage: erreur de récupération des données.', 'Análisis fondeo: error al recuperar datos.');
        setArrivalCacheStatus(t('Échec de l\'analyse et aucun cache compatible disponible.', 'Falló el análisis y no hay caché compatible disponible.', 'Analysis failed and no compatible cache is available.'), true);
        endAiTrafficSession(t('Analyse arrivée terminée en erreur', 'Análisis llegada terminado con error'));
    } finally {
        if (button) {
            button.disabled = false;
            button.textContent = t('Conseiller mouillage à l\'arrivée', 'Sugerir fondeo a la llegada');
        }
    }
}

function formatDurationHours(totalHours) {
    if (!Number.isFinite(totalHours)) return 'N/A';
    const hours = Math.floor(totalHours);
    const minutes = Math.round((totalHours - hours) * 60);
    if (hours <= 0) return `${minutes} min`;
    return `${hours} h ${String(minutes).padStart(2, '0')}`;
}

function getWeatherFavorabilityPenalty(weather) {
    const wind = Number(weather?.windSpeed);
    const wave = Number(weather?.waveHeight);
    const precip = Number(weather?.precipitation);
    const current = Number(weather?.currentSpeedKnots);

    let penalty = 0;
    if (Number.isFinite(wind)) {
        if (wind > RECOMMENDED_MAX_WIND_KN) penalty += (wind - RECOMMENDED_MAX_WIND_KN) * 20;
        penalty += Math.abs(wind - 12) * 0.9;
    } else {
        penalty += 8;
    }

    if (Number.isFinite(wave)) {
        if (wave > 2.5) penalty += (wave - 2.5) * 12;
        else penalty += wave * 2;
    }

    if (Number.isFinite(precip)) penalty += precip * 2.5;
    if (Number.isFinite(current)) {
        if (current > 1.6) penalty += (current - 1.6) * 14;
        else penalty += current * 1.5;
    }
    return penalty;
}

function isPreferredAiDepartureHour(dateTime) {
    if (!(dateTime instanceof Date) || Number.isNaN(dateTime.getTime())) return true;
    const hour = dateTime.getHours();
    return hour >= AI_ROUTE_DAYTIME_START_HOUR && hour < AI_ROUTE_DAYTIME_END_HOUR;
}

function getAiDepartureHourPenalty(dateTime) {
    return isPreferredAiDepartureHour(dateTime) ? 0 : 28;
}

function formatAiDurationCell(hours) {
    return Number.isFinite(hours) ? formatDurationHours(hours) : 'N/A';
}

function buildAiRouteComment(item) {
    const comments = [];

    if (Number(item?.strongWindHours) >= 2) {
        comments.push(t('vent fort présent', 'viento fuerte presente'));
    } else if (Number(item?.maxWind) <= RECOMMENDED_MAX_WIND_KN) {
        comments.push(t('vent contenu', 'viento contenido'));
    }

    if (Number(item?.calmHours) >= 2) {
        comments.push(t('risque de pétole', 'riesgo de calma'));
    } else if (Number(item?.lightWindHours) <= 1.5) {
        comments.push(t('peu de molles', 'pocas encalmadas'));
    }

    if (Number(item?.motorSharePercent) >= 25) {
        comments.push(t('moteur notable', 'motor notable'));
    }

    if (!isPreferredAiDepartureHour(item?.departureDateTime)) {
        comments.push(t('départ nocturne', 'salida nocturna'));
    }

    if (Number(item?.totalTimeHours) > AI_ROUTE_MAX_DURATION_HOURS) {
        comments.push(t('traversée trop longue', 'travesia demasiado larga'));
    }

    return comments.length ? comments.join(' · ') : t('équilibre météo favorable', 'equilibrio meteo favorable');
}

function buildAiRouteReason(item, index) {
    const reasons = [];

    if (index === 0) {
        reasons.push(t('meilleure fenêtre globale', 'mejor ventana global'));
    }

    if (Number(item?.strongWindHours) <= 0.5 && Number(item?.maxWind) <= RECOMMENDED_MAX_WIND_KN) {
        reasons.push(t('évite les coups de vent', 'evita los golpes de viento'));
    } else if (Number(item?.strongWindHours) >= 2 || Number(item?.maxWind) > RECOMMENDED_MAX_WIND_KN) {
        reasons.push(t('reste exposée au vent fort', 'sigue expuesta al viento fuerte'));
    }

    if (Number(item?.calmHours) <= 0.5 && Number(item?.motorSharePercent) <= 10) {
        reasons.push(t('évite la pétole', 'evita la calma'));
    } else if (Number(item?.calmHours) >= 2 || Number(item?.motorSharePercent) >= 25) {
        reasons.push(t('risque de molles / moteur', 'riesgo de calmas / motor'));
    }

    if (isPreferredAiDepartureHour(item?.departureDateTime)) {
        reasons.push(t('départ en horaire favorable', 'salida en horario favorable'));
    } else {
        reasons.push(t('départ de nuit moins favorable', 'salida nocturna menos favorable'));
    }

    if (Number(item?.totalTimeHours) <= 72) {
        reasons.push(t('durée contenue', 'duracion contenida'));
    } else if (Number(item?.totalTimeHours) > AI_ROUTE_MAX_DURATION_HOURS) {
        reasons.push(t('durée limite dépassée', 'duracion limite superada'));
    }

    return reasons.slice(0, 3).join(' · ');
}

function getAiRouteStatusMeta(item, index) {
    const strongWindHours = Number(item?.strongWindHours) || 0;
    const calmHours = Number(item?.calmHours) || 0;
    const motorSharePercent = Number(item?.motorSharePercent) || 0;
    const maxWind = Number(item?.maxWind) || 0;
    const totalTimeHours = Number(item?.totalTimeHours) || 0;
    const preferredDeparture = isPreferredAiDepartureHour(item?.departureDateTime);
    const isOverallBest = index === 0 || Number(item?.globalRank) === 0;

    const isGood =
        isOverallBest
        || (
            strongWindHours <= 0.5
            && maxWind <= RECOMMENDED_MAX_WIND_KN
            && calmHours <= 0.75
            && motorSharePercent <= 15
            && totalTimeHours <= 72
            && preferredDeparture
        );

    if (isGood) {
        return {
            key: 'good',
            label: t('Bon compromis', 'Buen compromiso')
        };
    }

    const shouldAvoid =
        strongWindHours >= 2
        || maxWind > RECOMMENDED_MAX_WIND_KN + 4
        || calmHours >= 2
        || motorSharePercent >= 25
        || totalTimeHours > AI_ROUTE_MAX_DURATION_HOURS;

    if (shouldAvoid) {
        return {
            key: 'avoid',
            label: t('A éviter', 'Evitar')
        };
    }

    return {
        key: 'acceptable',
        label: t('Acceptable', 'Aceptable')
    };
}

function updateAiRouteRefreshButtonState() {
    const button = document.getElementById('refreshAiRoutesBtn');
    if (!button) return;
    button.disabled = !lastAiRouteMatrixCache;
}

function updateMapWorkspaceLayoutState() {
    const mapContainer = document.getElementById('mapWorkspace');
    const aiRouteDockPanel = document.getElementById('aiRouteDockPanel');
    if (!mapContainer) return;

    const shouldShowDocumentOnly = activeTabName === 'document';
    const shouldShowAiMatrixOnly = activeTabName === 'routing' && isAiRouteMatrixVisible && !!lastAiRouteMatrixCache?.candidates?.length;
    const shouldShowVoyagesOnly = activeTabName === 'voyages';

    if (aiRouteDockPanel) {
        aiRouteDockPanel.classList.toggle('is-visible', shouldShowAiMatrixOnly);
    }
    syncAiDockSections();

    mapContainer.classList.toggle('map-workspace--document-only', shouldShowDocumentOnly);
    mapContainer.classList.toggle('map-workspace--ai-matrix-only', shouldShowAiMatrixOnly && !shouldShowDocumentOnly);
    mapContainer.classList.toggle('map-workspace--voyages-only', shouldShowVoyagesOnly);

    if (!shouldShowAiMatrixOnly && lastAiRouteTooltipIndex >= 0) {
        hideAiRouteTooltip();
    }

    if (map && activeTabName !== 'maintenance') {
        window.setTimeout(() => {
            map.invalidateSize();
        }, 80);
    }
}

function invalidateAiRouteAnalysisState(message = null) {
    lastAiRouteCandidates = [];
    lastAiRouteMatrixCache = null;
    isAiRouteMatrixVisible = false;
    updateAiRouteRefreshButtonState();

    const info = document.getElementById('aiRouteSuggestionInfo');
    const container = document.getElementById('aiRouteSuggestions');
    if (info) {
        info.textContent = message || t('Analyse route + météo: en attente', 'Análisis ruta + meteo: en espera');
    }
    if (container) {
        container.innerHTML = '';
    }
    updateMapWorkspaceLayoutState();
}

function restoreAiRouteMatrixViewFromCache() {
    if (!lastAiRouteMatrixCache?.candidates?.length) return false;
    renderAiRouteCandidates(lastAiRouteMatrixCache, { fromCache: true });
    return true;
}

function buildAiRouteCacheSignature() {
    const pointsSignature = normalizeRouteScenarioPoints(routePoints)
        .map(point => `${point.lat.toFixed(5)},${point.lng.toFixed(5)}`)
        .join('|');

    return JSON.stringify({
        departureDate,
        tackingTimeHours: Number.isFinite(tackingTimeHours) ? Number(tackingTimeHours.toFixed(2)) : 0,
        route: pointsSignature
    });
}

function getAiRouteMatrixBaseDate() {
    const dateOnly = new Date(`${departureDate}T00:00:00`);
    if (!Number.isNaN(dateOnly.getTime())) return dateOnly;
    const fallback = new Date();
    fallback.setHours(0, 0, 0, 0);
    return fallback;
}

function formatAiRouteMatrixDayLabel(dateTime) {
    if (!(dateTime instanceof Date) || Number.isNaN(dateTime.getTime())) return 'N/A';
    const locale = currentLanguage === 'es' ? 'es-ES' : 'fr-FR';
    return new Intl.DateTimeFormat(locale, {
        weekday: 'short',
        day: '2-digit',
        month: '2-digit'
    }).format(dateTime);
}

function formatAiRouteMatrixHourLabel(hour) {
    return `${String(hour).padStart(2, '0')}:00`;
}

function clampAiRouteScore(value) {
    return Math.max(0, Math.min(100, Math.round(value)));
}

function buildAiRouteDecisionScoreContext(candidates) {
    if (!Array.isArray(candidates) || candidates.length === 0) {
        return null;
    }

    const aiScores = candidates
        .map(item => Number(item?.aiScore))
        .filter(Number.isFinite);

    if (!aiScores.length) {
        return null;
    }

    return {
        minAiScore: Math.min(...aiScores),
        maxAiScore: Math.max(...aiScores)
    };
}

function getAiRouteDecisionScore(item, context = null) {
    let score = 100;
    const aiScore = Number(item?.aiScore);
    const strongWindHours = Number(item?.strongWindHours) || 0;
    const calmHours = Number(item?.calmHours) || 0;
    const motorSharePercent = Number(item?.motorSharePercent) || 0;
    const totalTimeHours = Number(item?.totalTimeHours) || 0;
    const departureTwa = Number(item?.departureTwa);

    score -= strongWindHours * 7;
    score -= calmHours * 6;
    score -= Math.max(0, motorSharePercent - 10) * 0.6;
    score -= Math.max(0, totalTimeHours - 60) * 0.25;

    if (Number.isFinite(departureTwa)) {
        if (departureTwa >= 55 && departureTwa <= 140) score += 6;
        else if (departureTwa < 35 || departureTwa > 165) score -= 8;
        else if (departureTwa < 55 || departureTwa > 150) score -= 2;
    }

    if (Number.isFinite(aiScore) && context && Number.isFinite(context.minAiScore) && Number.isFinite(context.maxAiScore)) {
        const spread = context.maxAiScore - context.minAiScore;
        const relativeAiScore = spread > 0
            ? ((context.maxAiScore - aiScore) / spread) * 100
            : 100;
        score = score * 0.7 + relativeAiScore * 0.3;
    }

    return clampAiRouteScore(score);
}

function applyAiRouteDecisionScores(candidates) {
    if (!Array.isArray(candidates) || candidates.length === 0) return;
    const context = buildAiRouteDecisionScoreContext(candidates);
    candidates.forEach(item => {
        item.decisionScore = getAiRouteDecisionScore(item, context);
    });
}

function describeAiRouteWindAngle(twa) {
    if (!Number.isFinite(twa)) return t('angle inconnu', 'angulo desconocido');
    if (twa < 35) return t('vent debout', 'viento de proa');
    if (twa < 60) return t('près', 'ceñida');
    if (twa <= 120) return t('travers', 'través');
    if (twa <= 155) return t('portant', 'portante');
    return t('vent arrière', 'popa');
}

function getAiRouteWindSummary(item) {
    const windSpeed = Number(item?.departureWeather?.windSpeed);
    const windDirection = Number(item?.departureWindDirection);
    const twa = Number(item?.departureTwa);
    const angleLabel = describeAiRouteWindAngle(twa);
    const directionLabel = Number.isFinite(windDirection)
        ? `${Math.round(windDirection)}° ${degreesToCardinalFr(windDirection)}`
        : t('dir. N/A', 'dir. N/A');
    const speedLabel = Number.isFinite(windSpeed) ? `${windSpeed.toFixed(0)} kn` : 'N/A';
    return `${angleLabel} · ${speedLabel} · ${directionLabel}`;
}

function shortenAiRouteVariantLabel(label) {
    const source = String(label || '').trim();
    if (!source) return t('Route', 'Ruta');
    if (source === t('Route actuelle', 'Ruta actual')) return t('Actuelle', 'Actual');
    if (source === t('Contournement nord', 'Rodeo norte')) return t('Nord', 'Norte');
    if (source === t('Contournement sud', 'Rodeo sur')) return t('Sud', 'Sur');
    if (source === t('Directe départ-arrivée', 'Directa salida-llegada')) return t('Directe', 'Directa');
    return source;
}

function isAiNightHour(dateTime) {
    if (!(dateTime instanceof Date) || Number.isNaN(dateTime.getTime())) return false;
    const hour = dateTime.getHours();
    return hour < AI_ROUTE_DAYTIME_START_HOUR || hour >= AI_ROUTE_DAYTIME_END_HOUR;
}

function getAiTimelineSegmentStatusMeta(segment) {
    const windSpeed = Number(segment?.windSpeed) || 0;
    const waveHeight = Number(segment?.waveHeight) || 0;
    const motorSharePercent = Number(segment?.motorSharePercent) || 0;
    const twa = Number(segment?.twa);

    if (
        windSpeed > RECOMMENDED_MAX_WIND_KN + 3
        || windSpeed < MOTOR_WIND_THRESHOLD_KN
        || waveHeight >= 2.4
        || motorSharePercent >= 50
        || (Number.isFinite(twa) && (twa < 35 || twa > 165))
    ) {
        return { key: 'avoid', label: t('A éviter', 'Evitar') };
    }

    if (
        windSpeed >= 9
        && windSpeed <= RECOMMENDED_MAX_WIND_KN
        && waveHeight <= 1.6
        && motorSharePercent <= 20
        && (!Number.isFinite(twa) || (twa >= 55 && twa <= 145))
    ) {
        return { key: 'good', label: t('Bon compromis', 'Buen compromiso') };
    }

    return { key: 'acceptable', label: t('Acceptable', 'Aceptable') };
}

function getAiTimelineSegmentScore(segment) {
    let score = 100;
    const windSpeed = Number(segment?.windSpeed) || 0;
    const waveHeight = Number(segment?.waveHeight) || 0;
    const motorSharePercent = Number(segment?.motorSharePercent) || 0;
    const twa = Number(segment?.twa);

    if (windSpeed < MOTOR_WIND_THRESHOLD_KN) score -= 28;
    else score -= Math.abs(windSpeed - 14) * 2.4;
    if (windSpeed > RECOMMENDED_MAX_WIND_KN) score -= (windSpeed - RECOMMENDED_MAX_WIND_KN) * 4.5;
    score -= waveHeight * 10;
    score -= motorSharePercent * 0.45;

    if (Number.isFinite(twa)) {
        if (twa >= 55 && twa <= 140) score += 6;
        else if (twa < 35 || twa > 165) score -= 10;
        else if (twa < 50 || twa > 150) score -= 3;
    }

    if (segment?.isNight) score -= 3;
    return Math.max(0, Math.min(100, Math.round(score)));
}

function buildAiTimelineSegment(dateTime, partial) {
    const segment = {
        dateTime,
        durationHours: Number(partial?.durationHours) || 0,
        windSpeed: Number(partial?.windHours) > 0 ? partial.windWeighted / partial.windHours : null,
        windGust: Number(partial?.gustHours) > 0 ? partial.gustWeighted / partial.gustHours : null,
        waveHeight: Number(partial?.waveHours) > 0 ? partial.waveWeighted / partial.waveHours : null,
        currentSpeed: Number(partial?.currentHours) > 0 ? partial.currentWeighted / partial.currentHours : null,
        windDirection: Number(partial?.windDirectionHours) > 0 ? partial.windDirectionWeighted / partial.windDirectionHours : null,
        bearing: Number(partial?.bearingHours) > 0 ? partial.bearingWeighted / partial.bearingHours : null,
        twa: Number(partial?.twaHours) > 0 ? partial.twaWeighted / partial.twaHours : null,
        motorSharePercent: Number(partial?.durationHours) > 0 ? Math.round((partial.motorHours / partial.durationHours) * 100) : 0,
        isNight: isAiNightHour(dateTime)
    };
    segment.segmentScore = getAiTimelineSegmentScore(segment);
    segment.status = getAiTimelineSegmentStatusMeta(segment);
    return segment;
}

function buildAiRouteTimelineSegmentsFromBuckets(timelineBuckets, departureDateTime) {
    const indexes = Array.from(timelineBuckets.keys()).sort((a, b) => a - b);
    return indexes.map(index => {
        const bucket = timelineBuckets.get(index);
        const dateTime = new Date(departureDateTime.getTime() + index * AI_ROUTE_DEPARTURE_STEP_HOURS * 3600 * 1000);
        return buildAiTimelineSegment(dateTime, bucket);
    });
}

function formatAiTimelineHeader(offsetIndex) {
    const totalHours = offsetIndex * AI_ROUTE_DEPARTURE_STEP_HOURS;
    const dayOffset = Math.floor(totalHours / 24);
    const hourOffset = totalHours % 24;
    return dayOffset > 0
        ? `J+${dayOffset} ${String(hourOffset).padStart(2, '0')}h`
        : `H+${String(hourOffset).padStart(2, '0')}h`;
}

function selectTopAiRouteDeparturesPerDay(candidates, maxPerDay = 3) {
    if (!Array.isArray(candidates) || candidates.length === 0) return [];

    const grouped = new Map();
    candidates.forEach(candidate => {
        const dayIndex = Number(candidate?.matrixDayIndex);
        if (!Number.isFinite(dayIndex)) return;
        const list = grouped.get(dayIndex) || [];
        list.push(candidate);
        grouped.set(dayIndex, list);
    });

    const selected = [];
    Array.from(grouped.keys()).sort((a, b) => a - b).forEach(dayIndex => {
        const dayCandidates = grouped.get(dayIndex) || [];
        dayCandidates.sort((a, b) => {
            const scoreA = Number(a?.decisionScore) || 0;
            const scoreB = Number(b?.decisionScore) || 0;
            if (scoreA !== scoreB) return scoreB - scoreA;
            return (Number(a?.aiScore) || 0) - (Number(b?.aiScore) || 0);
        });
        selected.push(...dayCandidates.slice(0, maxPerDay));
    });

    return selected;
}

function randomInRange(min, max) {
    return min + Math.random() * (max - min);
}

function buildMockDepartureWeather(statusKey) {
    const windDirection = Math.round(randomInRange(0, 359));
    const waveHeight = statusKey === 'good'
        ? randomInRange(0.4, 1.2)
        : statusKey === 'acceptable'
            ? randomInRange(0.9, 2.1)
            : randomInRange(1.8, 3.3);
    const windSpeed = statusKey === 'good'
        ? randomInRange(9, 16)
        : statusKey === 'acceptable'
            ? randomInRange(6, 20)
            : randomInRange(3, 28);

    return {
        windSpeed,
        windGust: windSpeed + randomInRange(1, statusKey === 'avoid' ? 10 : 5),
        windDirection,
        waveHeight,
        precipitation: statusKey === 'avoid' ? randomInRange(0.8, 4.2) : randomInRange(0, 1.4),
        currentSpeedKnots: randomInRange(0.1, statusKey === 'avoid' ? 1.9 : 1.1)
    };
}

function buildMockAiRouteCandidate(routeVariant, candidateDate, dayIndex, hour) {
    const qualityRoll = Math.random();
    const statusKey = qualityRoll < 0.36 ? 'good' : qualityRoll < 0.76 ? 'acceptable' : 'avoid';
    const departureWeather = buildMockDepartureWeather(statusKey);
    const baseBearing = Array.isArray(routeVariant?.points) && routeVariant.points.length >= 2
        ? getBearing(
            { lat: routeVariant.points[0].lat, lon: routeVariant.points[0].lng },
            { lat: routeVariant.points[1].lat, lon: routeVariant.points[1].lng }
        )
        : 90;
    const departureTwa = Math.max(20, Math.min(175,
        statusKey === 'good'
            ? randomInRange(55, 125)
            : statusKey === 'acceptable'
                ? randomInRange(38, 150)
                : (Math.random() < 0.5 ? randomInRange(20, 38) : randomInRange(150, 175))
    ));
    const departureWindDirection = Number.isFinite(baseBearing)
        ? (baseBearing + departureTwa + 360) % 360
        : departureWeather.windDirection;
    departureWeather.windDirection = departureWindDirection;

    const totalTimeHours = statusKey === 'good'
        ? randomInRange(42, 66)
        : statusKey === 'acceptable'
            ? randomInRange(54, 82)
            : randomInRange(72, 104);
    const calmHours = statusKey === 'good'
        ? randomInRange(0, 0.8)
        : statusKey === 'acceptable'
            ? randomInRange(0.4, 2)
            : randomInRange(1.8, 5.2);
    const strongWindHours = statusKey === 'good'
        ? randomInRange(0, 0.5)
        : statusKey === 'acceptable'
            ? randomInRange(0.2, 1.5)
            : randomInRange(1.8, 6.5);
    const motorSharePercent = statusKey === 'good'
        ? Math.round(randomInRange(0, 12))
        : statusKey === 'acceptable'
            ? Math.round(randomInRange(8, 22))
            : Math.round(randomInRange(18, 46));
    const averageWind = statusKey === 'good'
        ? randomInRange(11, 16)
        : statusKey === 'acceptable'
            ? randomInRange(9, 18)
            : randomInRange(7, 20);
    const maxWind = statusKey === 'good'
        ? randomInRange(14, 19.5)
        : statusKey === 'acceptable'
            ? randomInRange(18, 24)
            : randomInRange(23, 31);
    const aiScore = statusKey === 'good'
        ? randomInRange(18, 45)
        : statusKey === 'acceptable'
            ? randomInRange(44, 76)
            : randomInRange(74, 126);
    const arrivalDateTime = new Date(candidateDate.getTime() + totalTimeHours * 3600 * 1000);
    const routePointCount = Array.isArray(routeVariant?.points) ? routeVariant.points.length : 2;
    const timelineSegments = [];
    const segmentCount = Math.max(1, Math.ceil(totalTimeHours / AI_ROUTE_DEPARTURE_STEP_HOURS));

    for (let segmentIndex = 0; segmentIndex < segmentCount; segmentIndex += 1) {
        const segmentDateTime = new Date(candidateDate.getTime() + segmentIndex * AI_ROUTE_DEPARTURE_STEP_HOURS * 3600 * 1000);
        const segmentStatusKey = statusKey === 'good'
            ? (Math.random() < 0.72 ? 'good' : 'acceptable')
            : statusKey === 'acceptable'
                ? (Math.random() < 0.2 ? 'good' : Math.random() < 0.82 ? 'acceptable' : 'avoid')
                : (Math.random() < 0.7 ? 'avoid' : 'acceptable');
        const segmentWeather = buildMockDepartureWeather(segmentStatusKey);
        const segmentTwa = Math.max(20, Math.min(175,
            segmentStatusKey === 'good'
                ? randomInRange(55, 130)
                : segmentStatusKey === 'acceptable'
                    ? randomInRange(38, 152)
                    : (Math.random() < 0.5 ? randomInRange(20, 38) : randomInRange(152, 175))
        ));
        const segmentWindDirection = Number.isFinite(baseBearing)
            ? (baseBearing + segmentTwa + 360) % 360
            : segmentWeather.windDirection;
        timelineSegments.push(buildAiTimelineSegment(segmentDateTime, {
            durationHours: Math.min(AI_ROUTE_DEPARTURE_STEP_HOURS, Math.max(0.5, totalTimeHours - segmentIndex * AI_ROUTE_DEPARTURE_STEP_HOURS)),
            windWeighted: segmentWeather.windSpeed,
            windHours: 1,
            gustWeighted: segmentWeather.windGust,
            gustHours: 1,
            waveWeighted: segmentWeather.waveHeight,
            waveHours: 1,
            currentWeighted: segmentWeather.currentSpeedKnots,
            currentHours: 1,
            windDirectionWeighted: segmentWindDirection,
            windDirectionHours: 1,
            bearingWeighted: baseBearing,
            bearingHours: 1,
            twaWeighted: segmentTwa,
            twaHours: 1,
            motorHours: segmentStatusKey === 'avoid' ? randomInRange(0.8, 2.4) : randomInRange(0, 0.8)
        }));
    }

    return {
        departureDateTime: candidateDate,
        arrivalDateTime,
        totalTimeHours,
        maxWind,
        maxGust: maxWind + randomInRange(1, statusKey === 'avoid' ? 8 : 4),
        minWind: Math.max(1, averageWind - randomInRange(3, 7)),
        hasMotorSegment: motorSharePercent > 0,
        motorTimeHours: totalTimeHours * (motorSharePercent / 100),
        motorSharePercent,
        departureWeather,
        arrivalWeather: buildMockDepartureWeather(statusKey === 'good' ? 'acceptable' : statusKey),
        departureBearing: baseBearing,
        departureWindDirection,
        departureTwa,
        score: aiScore,
        aiScore,
        averageWind,
        averageCurrent: randomInRange(0.2, 1.3),
        calmHours,
        lightWindHours: calmHours + randomInRange(0.2, 1.6),
        idealWindHours: Math.max(0, totalTimeHours - calmHours - strongWindHours - randomInRange(4, 12)),
        strongWindHours,
        strongGustHours: Math.max(0, strongWindHours - randomInRange(0, 0.8)),
        maxWave: departureWeather.waveHeight,
        isSafe: maxWind <= RECOMMENDED_MAX_WIND_KN,
        isNoMotor: motorSharePercent <= 5,
        routePointCount,
        label: t('Simulation', 'Simulacion'),
        sailMode: 'auto',
        routeVariantLabel: routeVariant?.routeVariantLabel || t('Route actuelle', 'Ruta actual'),
        routeScenarioPoints: Array.isArray(routeVariant?.points) ? routeVariant.points : [],
        timelineSegments,
        matrixDayIndex: dayIndex,
        matrixHour: hour
    };
}

function buildMockAiRouteMatrixCandidates(baseDateTime, routeVariants) {
    const slotWinners = [];

    for (let dayIndex = 0; dayIndex < AI_ROUTE_ANALYSIS_WINDOW_DAYS; dayIndex += 1) {
        const dayDate = new Date(baseDateTime.getTime());
        dayDate.setDate(baseDateTime.getDate() + dayIndex);
        dayDate.setHours(0, 0, 0, 0);

        for (const hour of AI_ROUTE_MATRIX_HOURS) {
            const candidateDate = new Date(dayDate.getTime());
            candidateDate.setHours(hour, 0, 0, 0);

            const variantIndex = Math.floor(randomInRange(0, Math.max(1, routeVariants.length)));
            const routeVariant = routeVariants[Math.min(routeVariants.length - 1, variantIndex)] || routeVariants[0];
            const candidate = buildMockAiRouteCandidate(routeVariant, candidateDate, dayIndex, hour);
            slotWinners.push(candidate);
        }
    }

    const ranking = [...slotWinners].sort((a, b) => a.aiScore - b.aiScore);
    applyAiRouteDecisionScores(slotWinners);
    ranking.forEach((item, index) => {
        item.globalRank = index;
    });

    return slotWinners;
}

function buildAiRouteTooltipHtml(item, segmentIndex = -1) {
    if (!item) return '';

    const routeName = shortenAiRouteVariantLabel(item?.routeVariantLabel);
    const timelineSegments = Array.isArray(item?.timelineSegments) ? item.timelineSegments : [];
    const segment = Number.isInteger(segmentIndex) && segmentIndex >= 0 ? timelineSegments[segmentIndex] || null : null;

    if (segment) {
        const status = segment.status || getAiTimelineSegmentStatusMeta(segment);
        const score = Number(segment?.segmentScore) || 0;
        const departureWind = Number.isFinite(segment?.windSpeed) ? `${segment.windSpeed.toFixed(1)} kn` : 'N/A';
        const departureDir = Number.isFinite(segment?.windDirection)
            ? `${Math.round(segment.windDirection)}° ${degreesToCardinalFr(segment.windDirection)}`
            : 'N/A';

        return `<div class="ai-route-tooltip__title">${escapeHtml(formatWeekdayHourUtc(segment.dateTime))} · ${escapeHtml(formatAiTimelineHeader(segmentIndex))}</div>` +
            `<div class="ai-route-tooltip__pill"><span class="ai-route-status ai-route-status--${status.key}">${escapeHtml(status.label)}</span><strong>${score}/100</strong></div>` +
            `<div class="ai-route-tooltip__line"><strong>${t('Route', 'Ruta')}:</strong> ${escapeHtml(routeName)}</div>` +
            `<div class="ai-route-tooltip__line"><strong>${t('Vent segment', 'Viento segmento')}:</strong> ${escapeHtml(departureWind)} · ${escapeHtml(departureDir)}</div>` +
            `<div class="ai-route-tooltip__line"><strong>${t('Angle', 'Angulo')}:</strong> ${escapeHtml(describeAiRouteWindAngle(segment?.twa))} (${Number.isFinite(segment?.twa) ? `${Math.round(segment.twa)}°` : 'N/A'})</div>` +
            `<div class="ai-route-tooltip__line"><strong>${t('Houle', 'Oleaje')}:</strong> ${escapeHtml(Number.isFinite(segment?.waveHeight) ? `${segment.waveHeight.toFixed(1)} m` : 'N/A')}</div>` +
            `<div class="ai-route-tooltip__line"><strong>${t('Moteur', 'Motor')}:</strong> ${escapeHtml(String(Number.isFinite(segment?.motorSharePercent) ? `${segment.motorSharePercent}%` : 'N/A'))} · <strong>${t('Durée', 'Duracion')}:</strong> ${escapeHtml(formatAiDurationCell(segment.durationHours))}</div>` +
            `<div class="ai-route-tooltip__line ai-route-table__muted">${segment.isNight ? escapeHtml(t('Segment de nuit', 'Segmento nocturno')) : escapeHtml(t('Segment de jour', 'Segmento diurno'))}</div>`;
    }

    const status = getAiRouteStatusMeta(item, item?.globalRank);
    const departureWind = Number.isFinite(item?.departureWeather?.windSpeed) ? `${item.departureWeather.windSpeed.toFixed(1)} kn` : 'N/A';
    const departureDir = Number.isFinite(item?.departureWindDirection)
        ? `${Math.round(item.departureWindDirection)}° ${degreesToCardinalFr(item.departureWindDirection)}`
        : 'N/A';
    const score = Number(item?.decisionScore) || 0;

    return `<div class="ai-route-tooltip__title">${escapeHtml(formatWeekdayHourUtc(item.departureDateTime))}</div>` +
        `<div class="ai-route-tooltip__pill"><span class="ai-route-status ai-route-status--${status.key}">${escapeHtml(status.label)}</span><strong>${score}/100</strong></div>` +
        `<div class="ai-route-tooltip__line"><strong>${t('Route', 'Ruta')}:</strong> ${escapeHtml(routeName)}</div>` +
        `<div class="ai-route-tooltip__line"><strong>${t('Vent départ', 'Viento salida')}:</strong> ${escapeHtml(departureWind)} · ${escapeHtml(departureDir)}</div>` +
        `<div class="ai-route-tooltip__line"><strong>${t('Durée', 'Duracion')}:</strong> ${escapeHtml(formatAiDurationCell(item?.totalTimeHours))}</div>` +
        `<div class="ai-route-tooltip__line ai-route-table__muted">${escapeHtml(buildAiRouteComment(item))}</div>`;
}

function positionAiRouteTooltip(clientX, clientY) {
    const tooltip = document.getElementById('aiRouteMatrixTooltip');
    if (!tooltip || tooltip.hidden) return;

    const margin = 16;
    const rect = tooltip.getBoundingClientRect();
    const left = Math.min(window.innerWidth - rect.width - margin, clientX + 16);
    const top = Math.min(window.innerHeight - rect.height - margin, clientY + 16);
    tooltip.style.left = `${Math.max(margin, left)}px`;
    tooltip.style.top = `${Math.max(margin, top)}px`;
}

function showAiRouteTooltip(index, segmentIndex = -1, clientX = 0, clientY = 0) {
    const tooltip = document.getElementById('aiRouteMatrixTooltip');
    const item = lastAiRouteCandidates[index];
    if (!tooltip || !item) return;

    lastAiRouteTooltipIndex = index;
    tooltip.innerHTML = buildAiRouteTooltipHtml(item, segmentIndex);
    tooltip.hidden = false;
    positionAiRouteTooltip(clientX, clientY);
}

function hideAiRouteTooltip() {
    const tooltip = document.getElementById('aiRouteMatrixTooltip');
    if (!tooltip) return;
    lastAiRouteTooltipIndex = -1;
    tooltip.hidden = true;
}

function normalizeRouteScenarioPoints(source) {
    if (!Array.isArray(source)) return [];

    return source
        .map(point => {
            const lat = Number(point?.lat);
            const lng = Number(point?.lng ?? point?.lon);
            if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
            return { lat, lng };
        })
        .filter(Boolean);
}

async function estimateRouteForDepartureOnPoints(routeScenarioPoints, departureDateTime) {
    const points = normalizeRouteScenarioPoints(routeScenarioPoints);
    if (points.length < 2) return null;

    let totalTimeHours = 0;
    let maxWind = 0;
    let maxGust = 0;
    let minWind = Number.POSITIVE_INFINITY;
    let hasMotorSegment = false;
    let motorTimeHours = 0;
    let weightedWindHours = 0;
    let weightedCurrentHours = 0;
    let routeWeatherPenalty = 0;
    let calmHours = 0;
    let lightWindHours = 0;
    let idealWindHours = 0;
    let strongWindHours = 0;
    let strongGustHours = 0;
    let maxWave = 0;
    const timelineBuckets = new Map();

    for (let i = 0; i < points.length - 1; i++) {
        const start = { lat: points[i].lat, lon: points[i].lng };
        const end = { lat: points[i + 1].lat, lon: points[i + 1].lng };
        const legStartDateTime = new Date(departureDateTime.getTime() + totalTimeHours * 3600 * 1000);
        const legStartSlot = toDateAndHourUtc(legStartDateTime);
        const legStartWeather = await getWeatherAtDateHour(start.lat, start.lon, legStartSlot.date, legStartSlot.hour);
        const effectiveSpeed = estimateEffectiveSpeedForLegSplit(start, end, legStartWeather);
        const directDistanceNm = distanceNm(start.lat, start.lon, end.lat, end.lon);
        const maxDistanceForWeatherNm = getMaxDistanceForWeatherSplit(start, end, legStartWeather, effectiveSpeed, directDistanceNm);
        const legPoints = densifyPolylineForWeather([start, end], maxDistanceForWeatherNm);

        for (let legIndex = 0; legIndex < legPoints.length - 1; legIndex++) {
            const legStart = legPoints[legIndex];
            const legEnd = legPoints[legIndex + 1];

            const passageDateTime = new Date(departureDateTime.getTime() + totalTimeHours * 3600 * 1000);
            const passageSlot = toDateAndHourUtc(passageDateTime);
            const weather = await getWeatherAtDateHour(legStart.lat, legStart.lon, passageSlot.date, passageSlot.hour);

            const windSpeed = Number.isFinite(weather?.windSpeed) ? weather.windSpeed : 10;
            const windGust = Number.isFinite(weather?.windGust) ? weather.windGust : windSpeed;
            const windDirection = Number.isFinite(weather?.windDirection) ? weather.windDirection : 0;
            maxWind = Math.max(maxWind, windSpeed);
            maxGust = Math.max(maxGust, windGust);
            minWind = Math.min(minWind, windSpeed);

            const isMotorSegment = windSpeed < MOTOR_WIND_THRESHOLD_KN;
            if (isMotorSegment) hasMotorSegment = true;
            const resolvedTackTimeHours = getAutoTackingTimeHours(
                legStart,
                legEnd,
                windDirection,
                windSpeed,
                tackingTimeHours
            );

            const rawSegment = isMotorSegment
                ? {
                    distance: distanceNm(legStart.lat, legStart.lon, legEnd.lat, legEnd.lon),
                    speed: MOTOR_SPEED_KN,
                    bearing: getBearing(legStart, legEnd),
                    timeHours: distanceNm(legStart.lat, legStart.lon, legEnd.lat, legEnd.lon) / MOTOR_SPEED_KN,
                    type: 'motor'
                }
                : routeSegment(legStart, legEnd, windDirection, windSpeed, resolvedTackTimeHours, resolveSegmentPolar(legStart, legEnd, windDirection, windSpeed).polarData);

            const twa = isMotorSegment ? null : computeTWA(rawSegment.bearing, windDirection);
            const sailSetup = getSailRecommendation({
                isMotorSegment,
                tws: windSpeed,
                twa,
                sailModeValue: sailMode
            });

            const sailFactor = getSailPerformanceFactor({
                isMotorSegment,
                sailModeValue: sailMode,
                tws: windSpeed,
                twa,
                sailSetup
            });

            const correctedSpeed = isMotorSegment
                ? rawSegment.speed
                : rawSegment.speed * sailFactor;
            const sog = getSpeedOverGround(correctedSpeed, rawSegment.bearing, weather);
            const safeSog = Number.isFinite(sog.speedKnots) ? Math.max(0.8, sog.speedKnots) : correctedSpeed;
            const timeHours = rawSegment.distance / safeSog;
            const weightedTimeHours = Number.isFinite(timeHours) ? Math.max(0.25, timeHours) : 0.25;
            const waveHeight = Number(weather?.waveHeight);
            const currentSpeed = Number(weather?.currentSpeedKnots);
            let remainingHours = timeHours;
            let elapsedBeforeSegment = totalTimeHours;

            while (remainingHours > 1e-6) {
                const bucketIndex = Math.floor(elapsedBeforeSegment / AI_ROUTE_DEPARTURE_STEP_HOURS);
                const bucketStartHours = bucketIndex * AI_ROUTE_DEPARTURE_STEP_HOURS;
                const bucketRemainingHours = Math.max(0.01, (bucketStartHours + AI_ROUTE_DEPARTURE_STEP_HOURS) - elapsedBeforeSegment);
                const chunkHours = Math.min(remainingHours, bucketRemainingHours);
                const bucket = timelineBuckets.get(bucketIndex) || {
                    durationHours: 0,
                    windWeighted: 0,
                    windHours: 0,
                    gustWeighted: 0,
                    gustHours: 0,
                    waveWeighted: 0,
                    waveHours: 0,
                    currentWeighted: 0,
                    currentHours: 0,
                    windDirectionWeighted: 0,
                    windDirectionHours: 0,
                    bearingWeighted: 0,
                    bearingHours: 0,
                    twaWeighted: 0,
                    twaHours: 0,
                    motorHours: 0
                };

                bucket.durationHours += chunkHours;
                bucket.windWeighted += windSpeed * chunkHours;
                bucket.windHours += chunkHours;
                bucket.gustWeighted += windGust * chunkHours;
                bucket.gustHours += chunkHours;
                if (Number.isFinite(waveHeight)) {
                    bucket.waveWeighted += waveHeight * chunkHours;
                    bucket.waveHours += chunkHours;
                }
                if (Number.isFinite(currentSpeed)) {
                    bucket.currentWeighted += currentSpeed * chunkHours;
                    bucket.currentHours += chunkHours;
                }
                if (Number.isFinite(windDirection)) {
                    bucket.windDirectionWeighted += windDirection * chunkHours;
                    bucket.windDirectionHours += chunkHours;
                }
                if (Number.isFinite(rawSegment?.bearing)) {
                    bucket.bearingWeighted += rawSegment.bearing * chunkHours;
                    bucket.bearingHours += chunkHours;
                }
                if (Number.isFinite(twa)) {
                    bucket.twaWeighted += twa * chunkHours;
                    bucket.twaHours += chunkHours;
                }
                if (isMotorSegment) {
                    bucket.motorHours += chunkHours;
                }

                timelineBuckets.set(bucketIndex, bucket);
                elapsedBeforeSegment += chunkHours;
                remainingHours -= chunkHours;
            }

            routeWeatherPenalty += getWeatherFavorabilityPenalty(weather) * weightedTimeHours;
            weightedWindHours += windSpeed * weightedTimeHours;
            weightedCurrentHours += (Number.isFinite(currentSpeed) ? currentSpeed : 0) * weightedTimeHours;
            if (windSpeed < MOTOR_WIND_THRESHOLD_KN) calmHours += weightedTimeHours;
            if (windSpeed < 8) lightWindHours += weightedTimeHours;
            if (windSpeed >= 8 && windSpeed <= 18) idealWindHours += weightedTimeHours;
            if (windSpeed > RECOMMENDED_MAX_WIND_KN) strongWindHours += weightedTimeHours;
            if (windGust > RECOMMENDED_MAX_WIND_KN + 5) strongGustHours += weightedTimeHours;
            if (Number.isFinite(waveHeight)) maxWave = Math.max(maxWave, waveHeight);
            if (isMotorSegment) motorTimeHours += timeHours;
            totalTimeHours += timeHours;
        }
    }

    const departureSlot = toDateAndHourUtc(departureDateTime);
    const arrivalDateTime = new Date(departureDateTime.getTime() + totalTimeHours * 3600 * 1000);
    const arrivalSlot = toDateAndHourUtc(arrivalDateTime);

    const departureWeather = await getWeatherAtDateHour(
        points[0].lat,
        points[0].lng,
        departureSlot.date,
        departureSlot.hour
    );

    const arrivalWeather = await getWeatherAtDateHour(
        points[points.length - 1].lat,
        points[points.length - 1].lng,
        arrivalSlot.date,
        arrivalSlot.hour
    );
    const departureBearing = points.length >= 2
        ? getBearing(
            { lat: points[0].lat, lon: points[0].lng },
            { lat: points[1].lat, lon: points[1].lng }
        )
        : null;
    const departureWindDirection = Number(departureWeather?.windDirection);
    const departureTwa = Number.isFinite(departureBearing) && Number.isFinite(departureWindDirection)
        ? computeTWA(departureBearing, departureWindDirection)
        : null;

    const weightedDurationHours = Math.max(0.5, totalTimeHours);
    const averageWind = weightedWindHours > 0 ? weightedWindHours / weightedDurationHours : null;
    const averageCurrent = weightedCurrentHours > 0 ? weightedCurrentHours / weightedDurationHours : null;
    const baseScore =
        routeWeatherPenalty +
        getWeatherFavorabilityPenalty(departureWeather) * 0.5 +
        getWeatherFavorabilityPenalty(arrivalWeather) * 0.5 +
        calmHours * 18 +
        Math.max(0, lightWindHours - calmHours) * 7 +
        strongWindHours * 20 +
        strongGustHours * 12 +
        (maxWind > RECOMMENDED_MAX_WIND_KN ? (maxWind - RECOMMENDED_MAX_WIND_KN) * 45 : 0) +
        (maxGust > RECOMMENDED_MAX_WIND_KN + 8 ? (maxGust - (RECOMMENDED_MAX_WIND_KN + 8)) * 18 : 0) +
        motorTimeHours * 10 +
        totalTimeHours * 0.25 -
        idealWindHours * 2;
    const score = Math.max(0, baseScore);

    const windFloorOk = Number.isFinite(minWind) && minWind > MOTOR_WIND_THRESHOLD_KN;
    const motorSharePercent = Number.isFinite(totalTimeHours) && totalTimeHours > 0
        ? Math.round((motorTimeHours / totalTimeHours) * 100)
        : 0;
    const timelineSegments = buildAiRouteTimelineSegmentsFromBuckets(timelineBuckets, departureDateTime);

    return {
        departureDateTime,
        arrivalDateTime,
        totalTimeHours,
        maxWind,
        maxGust,
        minWind,
        hasMotorSegment,
        motorTimeHours,
        motorSharePercent,
        departureWeather,
        arrivalWeather,
        departureBearing,
        departureWindDirection,
        departureTwa,
        score,
        averageWind,
        averageCurrent,
        calmHours,
        lightWindHours,
        idealWindHours,
        strongWindHours,
        strongGustHours,
        maxWave,
        timelineSegments,
        isSafe: maxWind <= RECOMMENDED_MAX_WIND_KN,
        isNoMotor: windFloorOk && !hasMotorSegment,
        routePointCount: points.length
    };
}

function updateRoutingControlsUiFromState() {
    const saveRouteFromRoutingBtn = document.getElementById('saveRouteFromRoutingBtn');
    if (saveRouteFromRoutingBtn) {
        const saved = getSavedRoutes();
        const hasLoaded = Number.isInteger(currentLoadedRouteIndex)
            && currentLoadedRouteIndex >= 0
            && currentLoadedRouteIndex < saved.length;
        if (!hasLoaded) {
            saveRouteFromRoutingBtn.style.display = '';
        } else {
            const loadedRoute = saved[currentLoadedRouteIndex] || null;
            saveRouteFromRoutingBtn.style.display = isOwnedByCurrentCloudUser(loadedRoute?.creatorEmail) ? '' : 'none';
        }
    }
    updateRoutingPolarProfileUi();
}

function hasLoadedRouteSelection() {
    const saved = getSavedRoutes();
    return Number.isInteger(currentLoadedRouteIndex)
        && currentLoadedRouteIndex >= 0
        && currentLoadedRouteIndex < saved.length;
}

function canAccessRoutingTab() {
    return hasLoadedRouteSelection() || (Array.isArray(routePoints) && routePoints.length >= 2);
}

function updateRoutingTabAvailability() {
    const routingTabBtn = document.getElementById('routingTabBtn');
    if (!routingTabBtn) return;

    const shouldEnable = !isAuthGateLocked() && canAccessRoutingTab();
    routingTabBtn.disabled = !shouldEnable;
    routingTabBtn.classList.toggle('tab-btn--locked', !shouldEnable);

    if (!shouldEnable && activeTabName === 'routing') {
        const routesTabBtn = document.getElementById('routesTabBtn');
        if (routesTabBtn && !routesTabBtn.disabled) {
            routesTabBtn.click();
        }
    }
}

function buildAiRouteMatrixData(candidates, baseDateTime, signature) {
    if (!Array.isArray(candidates) || candidates.length === 0) return null;

    const orderedCandidates = [...candidates].sort((a, b) => {
        const timeA = a?.departureDateTime instanceof Date ? a.departureDateTime.getTime() : 0;
        const timeB = b?.departureDateTime instanceof Date ? b.departureDateTime.getTime() : 0;
        return timeA - timeB;
    });

    const segmentCount = orderedCandidates.reduce((maxCount, item) => {
        const count = Array.isArray(item?.timelineSegments) ? item.timelineSegments.length : 0;
        return Math.max(maxCount, count);
    }, 0);

    const bestCandidateIndex = orderedCandidates.reduce((bestIndex, item, index) => {
        if (!Number.isInteger(bestIndex) || bestIndex < 0) return index;
        const best = orderedCandidates[bestIndex];
        const currentDecisionScore = Number(item?.decisionScore) || 0;
        const bestDecisionScore = Number(best?.decisionScore) || 0;
        if (currentDecisionScore !== bestDecisionScore) return currentDecisionScore > bestDecisionScore ? index : bestIndex;
        return Number(item?.aiScore) < Number(best?.aiScore) ? index : bestIndex;
    }, -1);

    return {
        signature,
        generatedAt: new Date(),
        baseDateTime,
        segmentCount,
        candidates: orderedCandidates,
        bestCandidateIndex
    };
}

function renderAiRouteCandidates(matrixData, options = {}) {
    const info = document.getElementById('aiRouteSuggestionInfo');
    const container = document.getElementById('aiRouteSuggestions');
    if (!info || !container) return;

    if (!matrixData || !Array.isArray(matrixData?.candidates) || matrixData.candidates.length === 0) {
        lastAiRouteCandidates = [];
        lastAiRouteMatrixCache = null;
        isAiRouteMatrixVisible = false;
        info.textContent = t('Analyse route + météo: aucune option exploitable sur 5 jours.', 'Análisis ruta + meteo: ninguna opción utilizable en 5 días.');
        container.innerHTML = '';
        updateAiRouteRefreshButtonState();
        updateMapWorkspaceLayoutState();
        return;
    }

    const fromCache = options?.fromCache === true;
    lastAiRouteCandidates = matrixData.candidates;
    lastAiRouteMatrixCache = matrixData;
    isAiRouteMatrixVisible = true;
    updateAiRouteRefreshButtonState();

    const generatedAtLabel = matrixData.generatedAt instanceof Date && !Number.isNaN(matrixData.generatedAt.getTime())
        ? matrixData.generatedAt.toLocaleTimeString(currentLanguage === 'es' ? 'es-ES' : 'fr-FR', { hour: '2-digit', minute: '2-digit' })
        : '--:--';
    const bestCandidate = Number.isInteger(matrixData.bestCandidateIndex) && matrixData.bestCandidateIndex >= 0
        ? matrixData.candidates[matrixData.bestCandidateIndex]
        : null;

    const infoPrefix = AI_ROUTE_MATRIX_USE_MOCK
        ? t('Mode test', 'Modo prueba')
        : t('Analyse réelle', 'Analisis real');
    info.textContent = fromCache
        ? t(
            `${infoPrefix}: matrice 5 jours chargée depuis la mémoire (${generatedAtLabel}), avec 3 départs fixes par jour: 08:00, 12:00, 18:00. Clique une case pour charger le départ, ou utilise Rafraîchir pour recalculer.`,
            `${infoPrefix}: matriz de 5 dias cargada desde memoria (${generatedAtLabel}), con 3 salidas fijas por día: 08:00, 12:00, 18:00. Pulsa una celda para cargar la salida, o usa Actualizar para recalcular.`
        )
        : t(
            `${infoPrefix}: matrice 5 jours calculée (${generatedAtLabel}), avec 3 départs fixes par jour: 08:00, 12:00, 18:00. Clique une case pour charger le départ.`,
            `${infoPrefix}: matriz de 5 dias calculada (${generatedAtLabel}), con 3 salidas fijas por día: 08:00, 12:00, 18:00. Pulsa una celda para cargar la salida.`
        );

    const summaryHtml = bestCandidate
        ? (() => {
            const bestStatus = getAiRouteStatusMeta(bestCandidate, bestCandidate?.globalRank);
            return `<div class="ai-route-matrix-summary">` +
                `<div class="ai-route-matrix-summary__headline">${t('Meilleur créneau global', 'Mejor franja global')}</div>` +
                `<div><span class="ai-route-status ai-route-status--${bestStatus.key}">${escapeHtml(bestStatus.label)}</span>` +
                `<strong>${Number(bestCandidate?.decisionScore) || 0}/100</strong> · ${escapeHtml(formatWeekdayHourUtc(bestCandidate.departureDateTime))}</div>` +
                `<div class="ai-route-table__muted">${escapeHtml(shortenAiRouteVariantLabel(bestCandidate?.routeVariantLabel))} · ${escapeHtml(getAiRouteWindSummary(bestCandidate))}</div>` +
                `</div>`;
        })()
        : '';

    const legendHtml = `<div class="ai-route-matrix-legend">` +
        `<span class="ai-route-status ai-route-status--good">${t('Bon compromis', 'Buen compromiso')}</span>` +
        `<span class="ai-route-status ai-route-status--acceptable">${t('Acceptable', 'Aceptable')}</span>` +
        `<span class="ai-route-status ai-route-status--avoid">${t('A éviter', 'Evitar')}</span>` +
        `</div>`;

    const rows = matrixData.candidates.map((item, candidateIndex) => {
        const rowStatus = getAiRouteStatusMeta(item, item?.globalRank);
        const departureLabel = formatWeekdayHourUtc(item.departureDateTime);
        const routeLabel = shortenAiRouteVariantLabel(item?.routeVariantLabel);
        const timelineSegments = Array.isArray(item?.timelineSegments) ? item.timelineSegments : [];

        const cells = Array.from({ length: matrixData.segmentCount }, (_unused, segmentIndex) => {
            const segment = timelineSegments[segmentIndex] || null;
            if (!segment) {
                return `<td><div class="ai-route-matrix-cell ai-route-matrix-cell--empty">${t('Arrivé', 'Llegado')}</div></td>`;
            }

            const segmentStatus = segment.status || getAiTimelineSegmentStatusMeta(segment);
            const segmentScore = Number(segment?.segmentScore) || 0;
            const title = `${departureLabel} · ${formatAiTimelineHeader(segmentIndex)} · ${segmentScore}/100`;
            const nightBadge = segment.isNight
                ? `<span class="ai-route-matrix-cell__badge">${t('nuit', 'noche')}</span>`
                : '';

            return `<td>` +
                `<button type="button" class="ai-route-matrix-cell ai-route-matrix-cell--${segmentStatus.key}" data-ai-route-index="${candidateIndex}" data-ai-route-segment-index="${segmentIndex}" data-ai-route-action="apply" title="${escapeHtml(title)}">` +
                `<span class="ai-route-matrix-cell__score">${segmentScore}</span>` +
                `<span class="ai-route-matrix-cell__meta">${escapeHtml(getAiRouteWindSummary({ departureWeather: { windSpeed: segment.windSpeed }, departureWindDirection: segment.windDirection, departureTwa: segment.twa }))}</span>` +
                `<span class="ai-route-matrix-cell__route">${escapeHtml(formatAiDurationCell(segment.durationHours))} · ${escapeHtml(routeLabel)}</span>` +
                `${nightBadge}` +
                `</button>` +
                `</td>`;
        }).join('');

        return `<tr>` +
            `<th scope="row" class="ai-route-matrix__departure">` +
            `<div><strong>${escapeHtml(departureLabel)}</strong></div>` +
            `<div class="ai-route-table__muted">${escapeHtml(routeLabel)} · ${formatAiDurationCell(item.totalTimeHours)}</div>` +
            `</th>` +
            `${cells}` +
            `<td class="ai-route-matrix__final">` +
            `<span class="ai-route-status ai-route-status--${rowStatus.key}">${escapeHtml(rowStatus.label)}</span>` +
            `<strong>${Number(item?.decisionScore) || 0}/100</strong><br>` +
            `<span class="ai-route-table__muted">${escapeHtml(buildAiRouteReason(item, item?.globalRank))}</span>` +
            `</td>` +
            `</tr>`;
    }).join('');

    const headerHours = Array.from({ length: matrixData.segmentCount }, (_unused, segmentIndex) => formatAiTimelineHeader(segmentIndex))
        .map(label => `<th>${escapeHtml(label)}</th>`)
        .join('');

    container.innerHTML =
        summaryHtml +
        legendHtml +
        `<div class="ai-route-table-wrap ai-route-matrix-wrap"><table class="ai-route-matrix">` +
        `<thead><tr>` +
        `<th>${t('Départ', 'Salida')}</th>` +
        `${headerHours}` +
        `<th>${t('Score global', 'Puntuacion global')}</th>` +
        `</tr></thead><tbody>${rows}</tbody></table></div>`;

    updateMapWorkspaceLayoutState();
}

function replaceRouteWithScenarioPoints(points) {
    const normalized = normalizeRouteScenarioPoints(points);
    if (normalized.length < 2 || !map) return;

    markers.forEach(marker => {
        if (map.hasLayer(marker)) map.removeLayer(marker);
    });
    markers = [];
    routePoints = [];
    selectedUserWaypointIndex = -1;
    currentLoadedRouteIndex = -1;

    if (routeLayer && map.hasLayer(routeLayer)) {
        map.removeLayer(routeLayer);
    }
    routeLayer = null;

    if (windLayer && map.hasLayer(windLayer)) {
        map.removeLayer(windLayer);
    }
    windLayer = null;

    clearWaypointWindDirectionLayers();
    clearWaveDirectionSegmentLayers();
    clearGeneratedWaypointMarkers();
    clearArrivalPoiMarkers();
    waypointPassageSlots.clear();
    lastRouteBounds = null;
    lastComputedReportData = null;

    normalized.forEach(point => {
        const marker = createWaypointMarker([point.lat, point.lng]);
        markers.push(marker);
        routePoints.push(marker.getLatLng());
    });

    drawRoute(routePoints);
    updateSelectedWaypointInfo();
    updateRoutingTabAvailability();
}

function applyAiRouteCandidate(index) {
    const candidate = lastAiRouteCandidates[index];
    if (!candidate) return;

    if (Array.isArray(candidate.routeScenarioPoints) && candidate.routeScenarioPoints.length >= 2) {
        replaceRouteWithScenarioPoints(candidate.routeScenarioPoints);
    }

    sailMode = 'auto';
    setActivePolarProfile(POLAR_AUTO_PROFILE_ID, { persist: false, syncEditor: false });
    updateRoutingControlsUiFromState();

    if (candidate?.departureDateTime instanceof Date && !Number.isNaN(candidate.departureDateTime.getTime())) {
        const inputValue = toLocalDateTimeInputValue(candidate.departureDateTime);
        setDepartureFromDateTimeInput(inputValue, { suppressAiInvalidation: true });
    }

    const info = document.getElementById('aiRouteSuggestionInfo');
    if (info) {
        const routeVariant = candidate.routeVariantLabel || t('Trajectoire standard', 'Trayectoria estándar');
        info.textContent = t(
            `Option appliquée: ${routeVariant} · départ ${formatWeekdayHourUtc(candidate.departureDateTime)} · profil optimum auto actif. Tu peux maintenant cliquer Calculer.`,
            `Opcion aplicada: ${routeVariant} · salida ${formatWeekdayHourUtc(candidate.departureDateTime)} · perfil optimo auto activo. Ahora puedes hacer clic en Calcular.`
        );
    }
}

async function applyAndComputeAiRouteCandidate(index) {
    const candidate = lastAiRouteCandidates[index];
    if (!candidate) return;

    applyAiRouteCandidate(index);

    const info = document.getElementById('aiRouteSuggestionInfo');
    if (info) {
        const routeVariant = candidate.routeVariantLabel || t('Trajectoire standard', 'Trayectoria estándar');
        info.textContent = t(
            `Option appliquée: ${routeVariant}. Calcul du routing en cours...`,
            `Opcion aplicada: ${routeVariant}. Calculo del routing en curso...`
        );
    }

    await computeRoute();

    if (info) {
        const routeVariant = candidate.routeVariantLabel || t('Trajectoire standard', 'Trayectoria estándar');
        info.textContent = t(
            `Routing calculé pour ${routeVariant} · départ ${formatWeekdayHourUtc(candidate.departureDateTime)}.`,
            `Routing calculado para ${routeVariant} · salida ${formatWeekdayHourUtc(candidate.departureDateTime)}.`
        );
    }
}

function scoreAiCandidate(estimate, options = {}) {
    const departureHourPenalty = Number(options?.departureHourPenalty) || 0;
    const durationPenalty = Number(options?.durationPenalty) || 0;
    const excessDurationPenalty = Number.isFinite(estimate?.totalTimeHours) && estimate.totalTimeHours > AI_ROUTE_MAX_DURATION_HOURS
        ? 240 + (estimate.totalTimeHours - AI_ROUTE_MAX_DURATION_HOURS) * 18
        : 0;
    const motorPenalty = Number.isFinite(estimate?.motorSharePercent) ? estimate.motorSharePercent * 0.55 : 0;
    return (estimate?.score || 0) + departureHourPenalty + durationPenalty + excessDurationPenalty + motorPenalty;
}

function buildAiRouteVariants() {
    const currentPath = normalizeRouteScenarioPoints(routePoints);
    if (currentPath.length < 2) return [];

    const variants = [
        {
            routeVariantLabel: t('Route actuelle', 'Ruta actual'),
            points: currentPath
        }
    ];

    const start = currentPath[0];
    const end = currentPath[currentPath.length - 1];
    const bearing = getBearing({ lat: start.lat, lon: start.lng }, { lat: end.lat, lon: end.lng });
    const totalNm = distanceNm(start.lat, start.lng, end.lat, end.lng);
    const detourNm = Math.max(12, Math.min(40, totalNm * 0.18));
    const mid = movePoint(start.lat, start.lng, bearing, totalNm / 2);

    const northDetour = movePoint(mid.lat, mid.lon, bearing + 90, detourNm);
    const southDetour = movePoint(mid.lat, mid.lon, bearing - 90, detourNm);

    variants.push({
        routeVariantLabel: t('Contournement nord', 'Rodeo norte'),
        points: [start, { lat: northDetour.lat, lng: northDetour.lon }, end]
    });
    variants.push({
        routeVariantLabel: t('Contournement sud', 'Rodeo sur'),
        points: [start, { lat: southDetour.lat, lng: southDetour.lon }, end]
    });

    if (currentPath.length > 2) {
        variants.push({
            routeVariantLabel: t('Directe départ-arrivée', 'Directa salida-llegada'),
            points: [start, end]
        });
    }

    return variants;
}

async function suggestAiRouteOptions(options = {}) {
    if (routePoints.length < 2) {
        alert(t('Ajoute au moins 2 waypoints pour analyser des routes IA.', 'Añade al menos 2 waypoints para analizar rutas IA.'));
        return;
    }

    const forceRefresh = options?.forceRefresh === true;
    if (forceRefresh) {
        clearWeatherForecastCache();
    }
    const signature = buildAiRouteCacheSignature();
    if (!forceRefresh && lastAiRouteMatrixCache?.signature === signature) {
        renderAiRouteCandidates(lastAiRouteMatrixCache, { fromCache: true });
        return;
    }

    forecastWindowDays = AI_ROUTE_ANALYSIS_WINDOW_DAYS;
    const forecastWindowDaysSelect = document.getElementById('forecastWindowDaysSelect');
    if (forecastWindowDaysSelect) {
        forecastWindowDaysSelect.value = String(AI_ROUTE_ANALYSIS_WINDOW_DAYS);
    }

    const button = document.getElementById('suggestAiRoutesBtn');
    const refreshButton = document.getElementById('refreshAiRoutesBtn');
    const info = document.getElementById('aiRouteSuggestionInfo');

    if (button) {
        button.disabled = true;
        button.textContent = t('Analyse matrice...', 'Analisis matriz...');
    }
    if (refreshButton) refreshButton.disabled = true;
    if (info) {
        info.textContent = forceRefresh
            ? t('Recalcul route + météo en cours: cache météo vidé...', 'Recalculo ruta + meteo en curso: cache meteo vaciada...')
            : t('Analyse route + météo sur 5 jours en cours...', 'Análisis ruta + meteo de 5 días en curso...');
    }
    beginAiTrafficSession('Assistant route + fenêtre météo 5 jours');

    const originalSailMode = sailMode;
    const originalTackingTimeHours = tackingTimeHours;
    const originalPolarProfileId = activePolarProfileId;

    try {
        const baseDateTime = getAiRouteMatrixBaseDate();
        if (Number.isNaN(baseDateTime.getTime())) throw new Error('invalid-departure');

        const routeVariants = buildAiRouteVariants();
        if (!routeVariants.length) throw new Error('no-route-variant');
        pushAiTrafficLog(`Variantes trajectoires détectées: ${routeVariants.length}`);

        if (AI_ROUTE_MATRIX_USE_MOCK) {
            const slotWinners = buildMockAiRouteMatrixCandidates(baseDateTime, routeVariants);
            const matrixData = buildAiRouteMatrixData(slotWinners, baseDateTime, signature);
            renderAiRouteCandidates(matrixData, { fromCache: false });
            pushAiTrafficLog(`Mode test: ${slotWinners.length} départ(s) simulé(s)`);
            endAiTrafficSession('Analyse route + météo simulée');
            return;
        }

        sailMode = 'auto';
        activePolarProfileId = POLAR_AUTO_PROFILE_ID;
        pushAiTrafficLog('Profil optimum forcé: voile auto + meilleure polaire par segment');

        const slotWinners = [];
        const totalSlots = AI_ROUTE_ANALYSIS_WINDOW_DAYS * AI_ROUTE_MATRIX_HOURS.length;
        let processedSlots = 0;

        for (let dayIndex = 0; dayIndex < AI_ROUTE_ANALYSIS_WINDOW_DAYS; dayIndex += 1) {
            const dayDate = new Date(baseDateTime.getTime());
            dayDate.setDate(baseDateTime.getDate() + dayIndex);
            dayDate.setHours(0, 0, 0, 0);

            for (const hour of AI_ROUTE_MATRIX_HOURS) {
                const candidateDate = new Date(dayDate.getTime());
                candidateDate.setHours(hour, 0, 0, 0);
                pushAiTrafficLog(`Créneau ${processedSlots + 1}/${totalSlots}: ${formatWeekdayHourUtc(candidateDate)}`);

                let bestCandidate = null;
                for (const variant of routeVariants) {
                    const estimate = await estimateRouteForDepartureOnPoints(variant.points, candidateDate);
                    if (!estimate) continue;

                    const departureHourPenalty = getAiDepartureHourPenalty(candidateDate);
                    const aiScore = scoreAiCandidate(estimate, { departureHourPenalty });
                    const candidate = {
                        ...estimate,
                        aiScore,
                        departureHourPenalty,
                        label: t('Optimum', 'Optimo'),
                        sailMode: 'auto',
                        routeVariantLabel: variant.routeVariantLabel,
                        routeScenarioPoints: variant.points,
                        matrixDayIndex: dayIndex,
                        matrixHour: hour
                    };

                    if (!bestCandidate || candidate.aiScore < bestCandidate.aiScore) {
                        bestCandidate = candidate;
                    }
                }

                if (bestCandidate) {
                    slotWinners.push(bestCandidate);
                }

                processedSlots += 1;
                if (button) {
                    button.textContent = t(
                        `Analyse ${processedSlots}/${totalSlots}`,
                        `Analisis ${processedSlots}/${totalSlots}`
                    );
                }
                if (info) {
                    info.textContent = t(
                        `Analyse en cours: ${processedSlots}/${totalSlots} créneaux calculés.`,
                        `Analisis en curso: ${processedSlots}/${totalSlots} franjas calculadas.`
                    );
                }
            }
        }

        if (slotWinners.length === 0) {
            renderAiRouteCandidates(null);
            pushAiTrafficLog('Aucun créneau exploitable');
            endAiTrafficSession('Aucune case exploitable dans la matrice');
            return;
        }

        const ranking = [...slotWinners].sort((a, b) => a.aiScore - b.aiScore);
        applyAiRouteDecisionScores(slotWinners);
        ranking.forEach((item, index) => {
            item.globalRank = index;
        });

        const matrixData = buildAiRouteMatrixData(slotWinners, baseDateTime, signature);
        renderAiRouteCandidates(matrixData, { fromCache: false });
        pushAiTrafficLog(`Matrice finale: ${slotWinners.length} départ(s) calculé(s) sur 3 créneaux fixes par jour`);
        endAiTrafficSession('Analyse route + météo terminée');
    } catch (_error) {
        renderAiRouteCandidates(null);
        if (info) info.textContent = t('Analyse route + météo: impossible de calculer des options pour le moment.', 'Análisis ruta + meteo: no se pueden calcular opciones por ahora.');
        endAiTrafficSession('Erreur pendant l\'analyse route + météo');
    } finally {
        sailMode = originalSailMode;
        tackingTimeHours = originalTackingTimeHours;
        activePolarProfileId = originalPolarProfileId;
        updateRoutingControlsUiFromState();
        if (button) {
            button.disabled = false;
            button.textContent = t('Calculer matrice départ (5 j)', 'Calcular matriz de salida (5 d)');
        }
        updateAiRouteRefreshButtonState();
    }
}

function buildRouteVectorDataUrl(reportData) {
    const polyline = reportData?.routeVector?.polyline;
    const waypoints = Array.isArray(reportData?.routeVector?.waypoints)
        ? reportData.routeVector.waypoints
        : [];
    if (!Array.isArray(polyline) || polyline.length < 2) return null;

    const lats = polyline.map(p => Number(p?.lat)).filter(Number.isFinite);
    const lngs = polyline.map(p => Number(p?.lng)).filter(Number.isFinite);
    if (lats.length < 2 || lngs.length < 2) return null;

    const minLat = Math.min(...lats);
    const maxLat = Math.max(...lats);
    const minLng = Math.min(...lngs);
    const maxLng = Math.max(...lngs);

    const width = 1100;
    const height = 460;
    const pad = 34;
    const innerW = width - pad * 2;
    const innerH = height - pad * 2;
    const latSpan = Math.max(1e-9, maxLat - minLat);
    const lngSpan = Math.max(1e-9, maxLng - minLng);

    const toXY = (point) => {
        const x = pad + ((point.lng - minLng) / lngSpan) * innerW;
        const y = pad + ((maxLat - point.lat) / latSpan) * innerH;
        return { x, y };
    };

    const projected = polyline.map(toXY);
    const pathD = projected
        .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`)
        .join(' ');

    const start = projected[0];
    const end = projected[projected.length - 1];

    const projectedWaypoints = waypoints
        .map(wp => {
            const lat = Number(wp?.lat);
            const lng = Number(wp?.lng);
            if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
            const p = toXY({ lat, lng });
            return {
                ...p,
                label: String(wp?.label || ''),
                icon: String(wp?.icon || '•')
            };
        })
        .filter(Boolean);

    const gridLines = [];
    const steps = 5;
    for (let i = 1; i < steps; i++) {
        const gx = pad + (innerW * i) / steps;
        const gy = pad + (innerH * i) / steps;
        gridLines.push(`<line x1="${gx.toFixed(1)}" y1="${pad}" x2="${gx.toFixed(1)}" y2="${height - pad}" stroke="#1f3a51" stroke-opacity="0.35" stroke-width="1" />`);
        gridLines.push(`<line x1="${pad}" y1="${gy.toFixed(1)}" x2="${width - pad}" y2="${gy.toFixed(1)}" stroke="#1f3a51" stroke-opacity="0.35" stroke-width="1" />`);
    }

    const waypointNodes = projectedWaypoints.map((wp, idx) => {
        const textX = Math.min(width - 100, wp.x + 8).toFixed(1);
        const textY = Math.max(14, wp.y - 8).toFixed(1);
        return `
            <circle cx="${wp.x.toFixed(1)}" cy="${wp.y.toFixed(1)}" r="4.5" fill="#7fd8ff" stroke="#ffffff" stroke-width="1.5" />
            <text x="${textX}" y="${textY}" fill="#d8f4ff" font-size="11" font-family="Arial">${escapeHtml(wp.icon || '')}${escapeHtml(wp.label || `WP ${idx + 1}`)}</text>
        `;
    }).join('');

    const northX = width - 52;
    const northY = 30;

    const svg = `
        <svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
            <rect x="0" y="0" width="${width}" height="${height}" rx="16" ry="16" fill="#0e1620"/>
            <rect x="${pad}" y="${pad}" width="${innerW}" height="${innerH}" rx="10" ry="10" fill="#102434" stroke="#2a4d67" stroke-width="1.2"/>
            ${gridLines.join('')}
            <path d="${pathD}" fill="none" stroke="#ff9a3a" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>
            ${waypointNodes}
            <circle cx="${start.x.toFixed(1)}" cy="${start.y.toFixed(1)}" r="6" fill="#37d67a" stroke="#ffffff" stroke-width="2"/>
            <circle cx="${end.x.toFixed(1)}" cy="${end.y.toFixed(1)}" r="6" fill="#ff5f6d" stroke="#ffffff" stroke-width="2"/>
            <text x="${Math.min(width - 90, start.x + 10).toFixed(1)}" y="${Math.max(18, start.y - 10).toFixed(1)}" fill="#bde9ff" font-size="13" font-family="Arial">${t('Départ', 'Salida')}</text>
            <text x="${Math.min(width - 90, end.x + 10).toFixed(1)}" y="${Math.max(18, end.y - 10).toFixed(1)}" fill="#ffc8ce" font-size="13" font-family="Arial">${t('Arrivée', 'Llegada')}</text>
            <circle cx="${northX}" cy="${northY}" r="16" fill="#102434" stroke="#7fd8ff" stroke-width="1.2"/>
            <path d="M ${northX} ${northY - 10} L ${northX - 5} ${northY + 4} L ${northX} ${northY + 1} L ${northX + 5} ${northY + 4} Z" fill="#7fd8ff"/>
            <text x="${northX}" y="${northY + 13}" text-anchor="middle" fill="#d8f4ff" font-size="10" font-family="Arial" font-weight="700">N</text>
        </svg>`;

    return `data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(svg)))}`;
}

async function captureMapImageDataUrl() {
    if (!map || typeof window.html2canvas !== 'function') return null;

    let previousCenter = null;
    let previousZoom = null;
    let previousBaseLayer = null;

    try {
        previousCenter = map.getCenter();
        previousZoom = map.getZoom();
        previousBaseLayer = activeBaseLayer;

        if (activeBaseLayer !== standardTileLayer) {
            if (activeBaseLayer && map.hasLayer(activeBaseLayer)) map.removeLayer(activeBaseLayer);
            if (!map.hasLayer(standardTileLayer)) map.addLayer(standardTileLayer);
            activeBaseLayer = standardTileLayer;
        }

        if (lastRouteBounds?.isValid?.()) {
            map.fitBounds(lastRouteBounds, { padding: [40, 40], animate: false });
        }

        map.invalidateSize(false);
        await new Promise(resolve => setTimeout(resolve, 380));

        const canvas = await window.html2canvas(map.getContainer(), {
            useCORS: true,
            allowTaint: false,
            backgroundColor: '#0e1620',
            scale: 2,
            logging: false,
            width: map.getSize().x,
            height: map.getSize().y
        });

        return canvas.toDataURL('image/jpeg', 0.92);
    } catch (error) {
        return null;
    } finally {
        if (previousBaseLayer && activeBaseLayer !== previousBaseLayer) {
            if (activeBaseLayer && map.hasLayer(activeBaseLayer)) map.removeLayer(activeBaseLayer);
            if (!map.hasLayer(previousBaseLayer)) map.addLayer(previousBaseLayer);
            activeBaseLayer = previousBaseLayer;
        }

        if (previousCenter && Number.isFinite(previousZoom)) {
            map.setView(previousCenter, previousZoom, { animate: false });
            map.invalidateSize(false);
        }
    }
}

