function sanitizeNavChecklistItem(item, fallbackIndex = 0, mode = 'departure') {
    return {
        id: String(item?.id || `${mode}-${Date.now()}-${fallbackIndex}`),
        label: String(item?.label || '').trim(),
        done: !!item?.done,
        custom: !!item?.custom
    };
}

function sanitizeNavChecklistState(value) {
    const base = getDefaultNavChecklistState();
    const source = value && typeof value === 'object' ? value : {};
    const sanitizeList = (list, defaults, mode) => {
        const raw = Array.isArray(list) ? list : defaults;
        const cleaned = raw
            .map((item, index) => sanitizeNavChecklistItem(item, index, mode))
            .filter(item => item.label);
        return cleaned.length ? cleaned : defaults;
    };

    return {
        departure: sanitizeList(source.departure, base.departure, 'departure'),
        arrival: sanitizeList(source.arrival, base.arrival, 'arrival'),
        templates: {
            departure: String(source?.templates?.departure || 'standard'),
            arrival: String(source?.templates?.arrival || 'standard')
        }
    };
}

function saveNavChecklistState() {
    localStorage.setItem(NAV_CHECKLIST_STORAGE_KEY, JSON.stringify(navChecklistState));
}

function loadNavChecklistState() {
    const raw = localStorage.getItem(NAV_CHECKLIST_STORAGE_KEY);
    if (!raw) {
        navChecklistState = getDefaultNavChecklistState();
        saveNavChecklistState();
        return;
    }
    try {
        navChecklistState = sanitizeNavChecklistState(JSON.parse(raw));
    } catch (_error) {
        navChecklistState = getDefaultNavChecklistState();
        saveNavChecklistState();
    }
}

function getActiveNavChecklistItems() {
    const mode = activeNavChecklistMode === 'arrival' ? 'arrival' : 'departure';
    const list = navChecklistState?.[mode];
    return Array.isArray(list) ? list : [];
}

function setActiveNavChecklistMode(mode) {
    activeNavChecklistMode = mode === 'arrival' ? 'arrival' : 'departure';

    const departureBtn = document.getElementById('navChecklistDepartureBtn');
    const arrivalBtn = document.getElementById('navChecklistArrivalBtn');
    const templateSelect = document.getElementById('navChecklistTemplateSelect');
    if (departureBtn) departureBtn.classList.toggle('active', activeNavChecklistMode === 'departure');
    if (arrivalBtn) arrivalBtn.classList.toggle('active', activeNavChecklistMode === 'arrival');
    if (templateSelect) {
        const selectedTemplate = String(navChecklistState?.templates?.[activeNavChecklistMode] || 'standard');
        templateSelect.value = ['standard', 'night', 'bad_weather', 'harbor'].includes(selectedTemplate)
            ? selectedTemplate
            : 'standard';
    }

    renderNavChecklist();
}

function renderNavChecklist() {
    const listNode = document.getElementById('navChecklistList');
    const progressNode = document.getElementById('navChecklistProgress');
    if (!listNode || !progressNode) return;

    const items = getActiveNavChecklistItems();
    const doneCount = items.filter(item => item.done).length;
    progressNode.textContent = `${doneCount}/${items.length} ${t('elements coches', 'elementos marcados')}`;

    listNode.innerHTML = '';
    if (!items.length) {
        listNode.innerHTML = `<div class="cloud-status">${t('Checklist vide.', 'Checklist vacia.')}</div>`;
        return;
    }

    items.forEach(item => {
        const row = document.createElement('div');
        row.className = `log-checklist-item ${item.done ? 'log-checklist-item--done' : ''}`;

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = !!item.done;
        checkbox.addEventListener('change', () => {
            const target = getActiveNavChecklistItems().find(entry => entry.id === item.id);
            if (!target) return;
            target.done = checkbox.checked;
            saveNavChecklistState();
            renderNavChecklist();
        });

        const label = document.createElement('label');
        label.textContent = item.label;

        row.appendChild(checkbox);
        row.appendChild(label);

        if (item.custom) {
            const removeBtn = document.createElement('button');
            removeBtn.type = 'button';
            removeBtn.className = 'log-checklist-remove';
            removeBtn.textContent = t('Suppr.', 'Borrar');
            removeBtn.addEventListener('click', () => {
                navChecklistState[activeNavChecklistMode] = getActiveNavChecklistItems().filter(entry => entry.id !== item.id);
                saveNavChecklistState();
                renderNavChecklist();
            });
            row.appendChild(removeBtn);
        }

        listNode.appendChild(row);
    });
}

function addNavChecklistItemFromInput() {
    const input = document.getElementById('navChecklistNewItemInput');
    const label = String(input?.value || '').trim();
    if (!label) return;

    getActiveNavChecklistItems().push({
        id: `${activeNavChecklistMode}-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        label,
        done: false,
        custom: true
    });
    saveNavChecklistState();
    if (input) input.value = '';
    renderNavChecklist();
}

function resetNavChecklistToDefault() {
    navChecklistState = getDefaultNavChecklistState();
    saveNavChecklistState();
    setActiveNavChecklistMode(activeNavChecklistMode);
    renderNavChecklist();
}

function applyNavChecklistTemplateToActiveMode() {
    const select = document.getElementById('navChecklistTemplateSelect');
    const selectedTemplate = String(select?.value || 'standard');
    const safeTemplate = ['standard', 'night', 'bad_weather', 'harbor'].includes(selectedTemplate)
        ? selectedTemplate
        : 'standard';

    navChecklistState[activeNavChecklistMode] = getNavChecklistTemplateItems(activeNavChecklistMode, safeTemplate);
    navChecklistState.templates = navChecklistState.templates || {};
    navChecklistState.templates[activeNavChecklistMode] = safeTemplate;
    saveNavChecklistState();
    renderNavChecklist();
}

function normalizeNavSwellProfile(value) {
    return ['conservative', 'balanced', 'sport'].includes(String(value || '').toLowerCase())
        ? String(value).toLowerCase()
        : 'balanced';
}

function loadNavSwellProfile() {
    const raw = localStorage.getItem(NAV_SWELL_PROFILE_STORAGE_KEY);
    navSwellProfile = normalizeNavSwellProfile(raw);
    const select = document.getElementById('navSwellProfileSelect');
    if (select) {
        select.value = navSwellProfile;
    }
}

function setNavSwellProfile(value, { persist = true } = {}) {
    navSwellProfile = normalizeNavSwellProfile(value);
    if (persist) {
        localStorage.setItem(NAV_SWELL_PROFILE_STORAGE_KEY, navSwellProfile);
    }
    updateNavLiveDashboard();
}

function cloneDashboardThresholdDefaults() {
    return Object.fromEntries(
        Object.entries(DASHBOARD_THRESHOLD_DEFAULTS).map(([metricKey, defaults]) => [metricKey, { ...defaults }])
    );
}

function parseDashboardThresholdValue(value, fallback = null) {
    if (value === null || value === undefined || value === '') return fallback;
    const parsed = Number.parseFloat(String(value));
    return Number.isFinite(parsed) ? parsed : fallback;
}

function sanitizeDashboardThresholdMetric(metricKey, rawMetric) {
    const defaults = DASHBOARD_THRESHOLD_DEFAULTS[metricKey] || {};
    const source = rawMetric && typeof rawMetric === 'object' ? rawMetric : {};
    const nextMetric = {
        warnLow: parseDashboardThresholdValue(source.warnLow, defaults.warnLow ?? null),
        alertLow: parseDashboardThresholdValue(source.alertLow, defaults.alertLow ?? null),
        warnHigh: parseDashboardThresholdValue(source.warnHigh, defaults.warnHigh ?? null),
        alertHigh: parseDashboardThresholdValue(source.alertHigh, defaults.alertHigh ?? null)
    };

    if (Number.isFinite(nextMetric.warnLow) && Number.isFinite(nextMetric.alertLow)) {
        const orderedLow = [nextMetric.warnLow, nextMetric.alertLow].sort((left, right) => left - right);
        [nextMetric.alertLow, nextMetric.warnLow] = orderedLow;
    }
    if (Number.isFinite(nextMetric.warnHigh) && Number.isFinite(nextMetric.alertHigh)) {
        const orderedHigh = [nextMetric.warnHigh, nextMetric.alertHigh].sort((left, right) => left - right);
        [nextMetric.warnHigh, nextMetric.alertHigh] = orderedHigh;
    }

    return nextMetric;
}

function sanitizeDashboardThresholdConfig(rawConfig) {
    const defaults = cloneDashboardThresholdDefaults();
    if (!rawConfig || typeof rawConfig !== 'object') {
        return defaults;
    }

    for (const metricKey of Object.keys(defaults)) {
        defaults[metricKey] = sanitizeDashboardThresholdMetric(metricKey, rawConfig[metricKey]);
    }
    return defaults;
}

function loadDashboardThresholdConfig() {
    try {
        const raw = localStorage.getItem(DASHBOARD_THRESHOLD_CONFIG_STORAGE_KEY);
        dashboardThresholdConfig = raw
            ? sanitizeDashboardThresholdConfig(JSON.parse(raw))
            : cloneDashboardThresholdDefaults();
    } catch (_) {
        dashboardThresholdConfig = cloneDashboardThresholdDefaults();
    }
}

function saveDashboardThresholdConfig() {
    if (!dashboardThresholdConfig) return;
    try {
        localStorage.setItem(DASHBOARD_THRESHOLD_CONFIG_STORAGE_KEY, JSON.stringify(dashboardThresholdConfig));
    } catch (_) { /* ignore */ }
}

function getDashboardThreshold(metricKey) {
    if (!dashboardThresholdConfig) {
        dashboardThresholdConfig = cloneDashboardThresholdDefaults();
    }
    return dashboardThresholdConfig[metricKey] || DASHBOARD_THRESHOLD_DEFAULTS[metricKey] || null;
}

function computeDashboardGaugeState(value, thresholdKey) {
    const thresholds = getDashboardThreshold(thresholdKey);
    if (!Number.isFinite(value) || !thresholds) return 'normal';

    if (Number.isFinite(thresholds.alertLow) && value <= thresholds.alertLow) return 'alert';
    if (Number.isFinite(thresholds.alertHigh) && value >= thresholds.alertHigh) return 'alert';
    if (Number.isFinite(thresholds.warnLow) && value <= thresholds.warnLow) return 'warn';
    if (Number.isFinite(thresholds.warnHigh) && value >= thresholds.warnHigh) return 'warn';
    return 'normal';
}

function formatDashboardThresholdInputValue(value) {
    return Number.isFinite(value) ? String(value) : '';
}

function setDashboardThresholdStatus(message, isError = false) {
    const node = document.getElementById('dashboardThresholdStatus');
    if (!node) return;
    node.textContent = String(message || '');
    node.classList.toggle('dashboard-threshold-status--error', Boolean(isError));
}

function renderDashboardThresholdConfigUi() {
    if (!dashboardThresholdConfig) return;

    document.querySelectorAll('[data-threshold-metric][data-threshold-field]').forEach(input => {
        const metricKey = input.dataset.thresholdMetric;
        const field = input.dataset.thresholdField;
        if (!metricKey || !field) return;
        const metricConfig = getDashboardThreshold(metricKey);
        input.value = formatDashboardThresholdInputValue(metricConfig?.[field]);
    });
}

function refreshDashboardThresholdConsumers() {
    renderMaintenanceSignalKDashboard();
    updateNavLiveDashboard();
}

function initDashboardThresholdUi() {
    loadDashboardThresholdConfig();
    renderDashboardThresholdConfigUi();
    setDashboardThresholdStatus(t(
        'Seuils dashboard sauvegardés localement sur cet appareil.',
        'Umbrales del dashboard guardados localmente en este dispositivo.'
    ));

    document.querySelectorAll('[data-threshold-metric][data-threshold-field]').forEach(input => {
        if (input.dataset.thresholdBound === '1') return;
        input.dataset.thresholdBound = '1';
        input.addEventListener('input', () => {
            const metricKey = input.dataset.thresholdMetric;
            const field = input.dataset.thresholdField;
            if (!metricKey || !field) return;

            const nextMetric = {
                ...getDashboardThreshold(metricKey),
                [field]: input.value === '' ? null : Number.parseFloat(input.value)
            };
            dashboardThresholdConfig = sanitizeDashboardThresholdConfig({
                ...dashboardThresholdConfig,
                [metricKey]: nextMetric
            });
            saveDashboardThresholdConfig();
            renderDashboardThresholdConfigUi();
            refreshDashboardThresholdConsumers();
            setDashboardThresholdStatus(t(
                'Seuils mis à jour.',
                'Umbrales actualizados.'
            ));
        });
    });

    const resetButton = document.getElementById('dashboardThresholdResetBtn');
    if (resetButton && resetButton.dataset.thresholdBound !== '1') {
        resetButton.dataset.thresholdBound = '1';
        resetButton.addEventListener('click', () => {
            dashboardThresholdConfig = cloneDashboardThresholdDefaults();
            saveDashboardThresholdConfig();
            renderDashboardThresholdConfigUi();
            refreshDashboardThresholdConsumers();
            setDashboardThresholdStatus(t(
                'Seuils réinitialisés aux valeurs par défaut.',
                'Umbrales restablecidos a los valores por defecto.'
            ));
        });
    }
}

function updateNavPolarCaptureHint() {
    const hintEl = document.getElementById('navCapturePolarHint');
    if (!hintEl) return;

    const activeProfile = getSelectedPolarProfileForNavLog();
    const profileName = String(activeProfile?.name || '').trim();
    hintEl.textContent = profileName
        ? t(
            `Voilure active: ${profileName} — capturer quand l'allure est stable.`,
            `Velamen activo: ${profileName} — capturar cuando la ceñida sea estable.`
        )
        : t(
            'Utiliser le champ Voilure puis capturer quand l\'allure est stable.',
            'Usar el campo Velamen y capturar cuando la ceñida sea estable.'
        );
}

function captureNavPolarPoint() {
    const profile = getSelectedPolarProfileForNavLog();
    if (!profile) {
        setNavLogStatus(t('Aucun profil polaire actif.', 'Ningún perfil polar activo.'), true);
        updateNavPolarCaptureHint();
        return;
    }

    const sailConfig = String(document.getElementById('watchSailConfigInput')?.value || '').trim();
    const tws = Number.isFinite(signalkLatestWindSpeedKn) ? signalkLatestWindSpeedKn : null;
    const twa = Number.isFinite(signalkLatestTwaDeg) ? normalizeTwaDegrees(signalkLatestTwaDeg) : null;
    const speed = Number.isFinite(navLatestSpeedKn) ? navLatestSpeedKn : null;

    if (!Number.isFinite(tws) || tws <= 0) {
        setNavLogStatus(t('TWS manquant — connecter SignalK.', 'TWS faltante — conectar SignalK.'), true);
        updateNavPolarCaptureHint();
        return;
    }
    if (!Number.isFinite(twa) || twa <= 0) {
        setNavLogStatus(t('TWA manquant — connecter SignalK.', 'TWA faltante — conectar SignalK.'), true);
        updateNavPolarCaptureHint();
        return;
    }
    if (!Number.isFinite(speed) || speed <= 0) {
        setNavLogStatus(t('Vitesse manquante — GPS ou SignalK requis.', 'Velocidad faltante — GPS o SignalK requerido.'), true);
        updateNavPolarCaptureHint();
        return;
    }

    // Round TWS to nearest even kn (standard polar slices), TWA to nearest 5°
    const twsKey = String(Math.round(tws / 2) * 2 || 2);
    const twaKey = String(Math.max(5, Math.round(twa / 5) * 5));
    const speedRounded = Math.round(speed * 100) / 100;

    if (!profile.polarData || typeof profile.polarData !== 'object') {
        profile.polarData = {};
    }
    if (!profile.polarData[twsKey] || typeof profile.polarData[twsKey] !== 'object') {
        profile.polarData[twsKey] = {};
    }
    profile.polarData[twsKey][twaKey] = speedRounded;
    profile.updatedAt = new Date().toISOString();

    savePolarProfiles();

    const sailInfo = sailConfig ? ` · ${sailConfig}` : '';
    setNavLogStatus(t(
        `✓ Capturé: ${profile.name}${sailInfo} · TWS ${twsKey} kn / TWA ${twaKey}° → ${speedRounded.toFixed(1)} kn`,
        `✓ Capturado: ${profile.name}${sailInfo} · TWS ${twsKey} kn / TWA ${twaKey}° → ${speedRounded.toFixed(1)} kn`
    ));
    updateNavPolarCaptureHint();
}

function getSwellProfileConfig() {
    if (navSwellProfile === 'conservative') {
        return {
            windThresholds: [8, 14, 19, 24],
            windValues: [0.5, 1.0, 1.6, 2.3, 3.0],
            heelBoost: 0.55,
            heavyStartsAt: 2.2,
            veryHeavyStartsAt: 3.2
        };
    }
    if (navSwellProfile === 'sport') {
        return {
            windThresholds: [12, 18, 24, 30],
            windValues: [0.3, 0.7, 1.1, 1.7, 2.4],
            heelBoost: 0.3,
            heavyStartsAt: 2.8,
            veryHeavyStartsAt: 3.8
        };
    }
    return {
        windThresholds: [10, 16, 22, 28],
        windValues: [0.4, 0.8, 1.3, 1.9, 2.7],
        heelBoost: 0.4,
        heavyStartsAt: 2.5,
        veryHeavyStartsAt: 3.6
    };
}

function estimateSwellFromNavContext({ windSpeedKn, heelDeg, seaState }) {
    const profileConfig = getSwellProfileConfig();
    let swellM = 0.4;
    const wind = Number(windSpeedKn);
    const heel = Math.abs(Number(heelDeg) || 0);
    const sea = String(seaState || '').trim().toLowerCase();

    if (Number.isFinite(wind)) {
        if (wind < profileConfig.windThresholds[0]) swellM = profileConfig.windValues[0];
        else if (wind < profileConfig.windThresholds[1]) swellM = profileConfig.windValues[1];
        else if (wind < profileConfig.windThresholds[2]) swellM = profileConfig.windValues[2];
        else if (wind < profileConfig.windThresholds[3]) swellM = profileConfig.windValues[3];
        else swellM = profileConfig.windValues[4];
    }

    if (heel >= 20) swellM += profileConfig.heelBoost;
    if (heel >= 30) swellM += profileConfig.heelBoost;

    if (sea.includes('calm') || sea.includes('calme')) swellM -= 0.2;
    else if (sea.includes('agit')) swellM += 0.4;
    if (sea.includes('fort')) swellM += 0.5;

    const value = Math.max(0.2, Math.min(5.5, swellM));
    let level = t('calme', 'calma');
    if (value >= 0.8) level = t('moderee', 'moderada');
    if (value >= 1.6) level = t('formee', 'formada');
    if (value >= profileConfig.heavyStartsAt) level = t('forte', 'fuerte');
    if (value >= profileConfig.veryHeavyStartsAt) level = t('tres forte', 'muy fuerte');
    return { value, level };
}

function estimateRelativeHumidityPctFromAbsolute(absHumidityGm3, airTempC) {
    const abs = Number(absHumidityGm3);
    const temp = Number(airTempC);
    if (!Number.isFinite(abs) || !Number.isFinite(temp)) return null;

    // Saturation absolute humidity approximation (g/m3) from temperature (C).
    const saturation = (6.112 * Math.exp((17.67 * temp) / (temp + 243.5)) * 2.1674) / (273.15 + temp);
    if (!Number.isFinite(saturation) || saturation <= 0) return null;

    return Math.max(0, Math.min(100, (abs / saturation) * 100));
}

function estimateDewPointC(airTempC, relativeHumidityPct, absHumidityGm3 = null) {
    const temp = Number(airTempC);
    let humidity = Number(relativeHumidityPct);

    if (!Number.isFinite(humidity)) {
        humidity = estimateRelativeHumidityPctFromAbsolute(absHumidityGm3, temp);
    }
    if (!Number.isFinite(temp) || !Number.isFinite(humidity)) return null;

    const rh = Math.max(0.1, Math.min(100, humidity));
    const a = 17.62;
    const b = 243.12;
    const gamma = Math.log(rh / 100) + ((a * temp) / (b + temp));
    const dewPoint = (b * gamma) / (a - gamma);
    return Number.isFinite(dewPoint) ? dewPoint : null;
}

function setNavLiveDashboardGauge(widgetKey, value, min, max, thresholdKey = null) {
    const widget = document.querySelector(`[data-nav-widget="${widgetKey}"]`);
    if (!widget) return;

    let fillPct = 0;
    if (Number.isFinite(value) && Number.isFinite(min) && Number.isFinite(max) && max > min) {
        fillPct = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
    }
    widget.style.setProperty('--sk-fill', `${fillPct}%`);

    widget.dataset.state = computeDashboardGaugeState(value, thresholdKey);
}

function setNavLiveDashboardBalance(balanceKey, value, min, max) {
    const balance = document.querySelector(`[data-nav-balance="${balanceKey}"]`);
    if (!balance) return;
    let positionPct = 50;
    if (Number.isFinite(value) && Number.isFinite(min) && Number.isFinite(max) && max > min) {
        positionPct = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
    }
    balance.style.setProperty('--sk-balance', `${positionPct}%`);
}

function setNavLiveDashboardNeedle(needleKey, degrees) {
    const needle = document.querySelector(`[data-nav-needle="${needleKey}"]`);
    if (!needle) return;
    const safeDegrees = Number.isFinite(degrees) ? degrees : 0;
    needle.style.transform = `translateX(-50%) rotate(${safeDegrees}deg)`;
}

function updateNavLiveDashboard() {
    const speedNode = document.getElementById('navLiveSpeedValue');
    const heelNode = document.getElementById('navLiveHeelValue');
    const heelBalanceNode = document.getElementById('navLiveHeelBalanceValue');
    const batteryTempNode = document.getElementById('navLiveBatteryTempValue');
    const headingNode = document.getElementById('navLiveHeadingValue');
    const courseNode = document.getElementById('navLiveCourseValue');
    const logNode = document.getElementById('navLiveLogValue');
    const twaNode = document.getElementById('navLiveTwaValue');
    const twsNode = document.getElementById('navLiveTwsValue');
    const twdNode = document.getElementById('navLiveTwdValue');
    const baroNode = document.getElementById('navLiveBaroValue');
    const airTempNode = document.getElementById('navLiveAirTempValue');
    const probeTempNode = document.getElementById('navLiveProbeTempValue');
    const humidityNode = document.getElementById('navLiveHumidityValue');
    const dewPointNode = document.getElementById('navLiveDewPointValue');
    const cloudNode = document.getElementById('navLiveCloudValue');
    const rainNode = document.getElementById('navLiveRainValue');
    const engineNode = document.getElementById('navLiveEngineValue');
    const engineFramesNode = document.getElementById('navLiveEngineFramesValue');
    const rpmNode = document.getElementById('navLiveRpmValue');
    const pointOfSailNode = document.getElementById('navLivePointOfSailValue');
    const swellNode = document.getElementById('navLiveSwellValue');
    const liveCardNode = document.getElementById('navLiveTableCard');
    if (!speedNode || !heelNode || !headingNode || !swellNode) return;

    const latestEntry = Array.isArray(navLogEntries) && navLogEntries.length
        ? navLogEntries[navLogEntries.length - 1]
        : null;
    const selectedEntry = getSelectedNavTraceEntry();
    const contextEntry = selectedEntry || latestEntry;
    const contextTraceEntries = selectedEntry ? getNavTraceEntriesForEntry(selectedEntry) : getNavGpsTraceEntries();
    const latestTraceEntry = contextTraceEntries.length
        ? contextTraceEntries[contextTraceEntries.length - 1]
        : null;
    const previousTraceEntry = contextTraceEntries.length > 1
        ? contextTraceEntries[contextTraceEntries.length - 2]
        : null;
    const derivedTraceMetrics = computeDerivedNavMetricsFromPoints(previousTraceEntry, latestTraceEntry);

    const headingInput = document.getElementById('watchHeadingInput');
    const windSpeedInput = document.getElementById('watchWindSpeedInput');
    const seaStateInput = document.getElementById('watchSeaStateInput');

    const speed = selectedEntry
        ? (Number.isFinite(latestTraceEntry?.speedKn)
            ? latestTraceEntry.speedKn
            : (Number.isFinite(derivedTraceMetrics.speedKn)
                ? derivedTraceMetrics.speedKn
                : (Number.isFinite(contextEntry?.speedKn) ? contextEntry.speedKn : null)))
        : (Number.isFinite(navLatestSpeedKn)
            ? navLatestSpeedKn
            : (Number.isFinite(latestTraceEntry?.speedKn)
                ? latestTraceEntry.speedKn
                : (Number.isFinite(derivedTraceMetrics.speedKn)
                    ? derivedTraceMetrics.speedKn
                    : (Number.isFinite(contextEntry?.speedKn) ? contextEntry.speedKn : null))));
    const heel = selectedEntry
        ? (Number.isFinite(latestTraceEntry?.heelDeg)
            ? latestTraceEntry.heelDeg
            : (Number.isFinite(contextEntry?.heelDeg) ? contextEntry.heelDeg : null))
        : (Number.isFinite(navLatestHeelDeg)
            ? navLatestHeelDeg
            : (Number.isFinite(latestTraceEntry?.heelDeg)
                ? latestTraceEntry.heelDeg
                : (Number.isFinite(contextEntry?.heelDeg) ? contextEntry.heelDeg : null)));

    const liveHeadingInput = Number.parseFloat(String(headingInput?.value || ''));
    const heading = selectedEntry
        ? (Number.isFinite(derivedTraceMetrics.courseDeg)
            ? derivedTraceMetrics.courseDeg
            : (Number.isFinite(contextEntry?.headingDeg) ? contextEntry.headingDeg : null))
        : (Number.isFinite(navLatestCourseDeg)
            ? navLatestCourseDeg
            : (Number.isFinite(derivedTraceMetrics.courseDeg)
                ? derivedTraceMetrics.courseDeg
                : (Number.isFinite(liveHeadingInput)
                    ? liveHeadingInput
                    : (Number.isFinite(contextEntry?.headingDeg) ? contextEntry.headingDeg : null))));

    const liveWindInput = Number.parseFloat(String(windSpeedInput?.value || ''));
    const wind = Number.isFinite(liveWindInput)
        ? liveWindInput
        : (Number.isFinite(signalkLatestWindSpeedKn)
            ? signalkLatestWindSpeedKn
            : (Number.isFinite(latestTraceEntry?.windSpeedKn)
                ? latestTraceEntry.windSpeedKn
                : (Number.isFinite(contextEntry?.windSpeedKn) ? contextEntry.windSpeedKn : null)));

    const twd = Number.isFinite(signalkLatestWindDir)
        ? normalizeCourseDegrees(signalkLatestWindDir)
        : (Number.isFinite(latestTraceEntry?.windDirectionDeg)
            ? normalizeCourseDegrees(latestTraceEntry.windDirectionDeg)
            : (Number.isFinite(contextEntry?.windDirectionDeg)
                ? normalizeCourseDegrees(contextEntry.windDirectionDeg)
                : null));

    const twaFromHeading = Number.isFinite(heading) && Number.isFinite(twd)
        ? Math.abs(computeTWA(heading, twd))
        : null;
    const signedTwaFromHeading = Number.isFinite(heading) && Number.isFinite(twd)
        ? computeTWA(heading, twd)
        : null;
    const twa = Number.isFinite(signalkLatestTwaDeg)
        ? normalizeTwaDegrees(signalkLatestTwaDeg)
        : (Number.isFinite(latestTraceEntry?.twaDeg)
            ? normalizeTwaDegrees(latestTraceEntry.twaDeg)
            : (Number.isFinite(twaFromHeading) ? normalizeTwaDegrees(twaFromHeading) : null));
    const signedTwa = Number.isFinite(signalkLatestTwaDeg)
        ? normalizeSignedRelativeDegrees(signalkLatestTwaDeg)
        : (Number.isFinite(latestTraceEntry?.twaDeg)
            ? normalizeSignedRelativeDegrees(latestTraceEntry.twaDeg)
            : (Number.isFinite(signedTwaFromHeading) ? signedTwaFromHeading : null));

    const liveBaroInput = Number.parseFloat(String(document.getElementById('watchBarometerInput')?.value || ''));
    const liveLogInput = Number.parseFloat(String(document.getElementById('watchLogNmInput')?.value || ''));
    const baro = Number.isFinite(liveBaroInput)
        ? liveBaroInput
        : (Number.isFinite(signalkLatestBaroHpa)
            ? signalkLatestBaroHpa
            : (Number.isFinite(latestTraceEntry?.barometerHpa)
                ? latestTraceEntry.barometerHpa
                : (Number.isFinite(contextEntry?.barometerHpa)
                    ? contextEntry.barometerHpa
                    : (Number.isFinite(navLatestWeatherPressureHpa) ? navLatestWeatherPressureHpa : null))));

    const logNm = Number.isFinite(liveLogInput)
        ? liveLogInput
        : (Number.isFinite(signalkLatestLogNm)
            ? signalkLatestLogNm
            : (Number.isFinite(maintenanceSignalKLatestFrame?.logNm)
                ? Number(maintenanceSignalKLatestFrame.logNm)
                : (Number.isFinite(contextEntry?.logDistanceNm) ? contextEntry.logDistanceNm : null)));

    const airTemp = Number.isFinite(signalkLatestAirTempC)
        ? signalkLatestAirTempC
        : (Number.isFinite(latestTraceEntry?.temperatureC)
            ? latestTraceEntry.temperatureC
            : (Number.isFinite(contextEntry?.temperatureC)
                ? contextEntry.temperatureC
                : (Number.isFinite(navLatestAirTempC) ? navLatestAirTempC : null)));

    const probeTemp = Number.isFinite(signalkLatestProbeTempC)
        ? signalkLatestProbeTempC
        : null;

    const batteryTemp = Number.isFinite(signalkLatestBatteryTempC)
        ? signalkLatestBatteryTempC
        : (Number.isFinite(maintenanceSignalKLatestFrame?.batteryTempC)
            ? Number(maintenanceSignalKLatestFrame.batteryTempC)
            : null);

    const computedHumidity = estimateRelativeHumidityPctFromAbsolute(signalkLatestAbsHumidityGm3, airTemp);

    const humidity = Number.isFinite(signalkLatestHumidityPct)
        ? signalkLatestHumidityPct
        : (Number.isFinite(latestTraceEntry?.humidityPct)
            ? latestTraceEntry.humidityPct
            : (Number.isFinite(contextEntry?.humidityPct)
                ? contextEntry.humidityPct
                : (Number.isFinite(computedHumidity) ? computedHumidity : null)));

    const dewPoint = estimateDewPointC(airTemp, humidity, signalkLatestAbsHumidityGm3);

    const cloudCover = Number.isFinite(signalkLatestCloudCoverPct)
        ? signalkLatestCloudCoverPct
        : (Number.isFinite(latestTraceEntry?.cloudCoverPct)
            ? latestTraceEntry.cloudCoverPct
            : (Number.isFinite(contextEntry?.cloudCoverPct) ? contextEntry.cloudCoverPct : null));

    const rainRate = Number.isFinite(signalkLatestRainRateMmH)
        ? signalkLatestRainRateMmH
        : (Number.isFinite(latestTraceEntry?.rainRateMmH)
            ? latestTraceEntry.rainRateMmH
            : (Number.isFinite(contextEntry?.rainRateMmH) ? contextEntry.rainRateMmH : null));

    const engineRunning = typeof signalkLatestEngineRunning === 'boolean'
        ? signalkLatestEngineRunning
        : (typeof maintenanceSignalKLatestFrame?.engineRunning === 'boolean'
            ? maintenanceSignalKLatestFrame.engineRunning
            : null);

    const engineRpm = Number.isFinite(signalkLatestEngineRpm)
        ? signalkLatestEngineRpm
        : (Number.isFinite(maintenanceSignalKLatestFrame?.engineRpm)
            ? Number(maintenanceSignalKLatestFrame.engineRpm)
            : null);

    const lat = Number.isFinite(navGpsLatestFix?.lat)
        ? navGpsLatestFix.lat
        : (Number.isFinite(latestTraceEntry?.lat)
            ? latestTraceEntry.lat
            : (Number.isFinite(contextEntry?.lat) ? contextEntry.lat : null));

    const lng = Number.isFinite(navGpsLatestFix?.lng)
        ? navGpsLatestFix.lng
        : (Number.isFinite(latestTraceEntry?.lng)
            ? latestTraceEntry.lng
            : (Number.isFinite(contextEntry?.lng) ? contextEntry.lng : null));

    const seaState = String(seaStateInput?.value || contextEntry?.seaState || '');
    const swell = estimateSwellFromNavContext({ windSpeedKn: wind, heelDeg: heel, seaState });

    const pointOfSailLabel = (() => {
        const absTwa = Math.abs(Number(twa));
        if (!Number.isFinite(absTwa)) return '--';
        if (absTwa < 35) return t('Près serré', 'Ceñida cerrada');
        if (absTwa < 60) return t('Près', 'Ceñida');
        if (absTwa < 85) return t('Bon plein', 'A un descuartelar');
        if (absTwa < 115) return t('Travers', 'Través');
        if (absTwa < 145) return t('Largue', 'Largo');
        if (absTwa < 170) return t('Grand largue', 'Aleta');
        return t('Vent arrière', 'Popa');
    })();

    speedNode.textContent = Number.isFinite(speed) ? `${speed.toFixed(1)} kn` : '-- kn';
    heelNode.textContent = Number.isFinite(heel) ? `${heel.toFixed(1)}°` : '--';
    if (heelBalanceNode) heelBalanceNode.textContent = Number.isFinite(heel) ? `${heel.toFixed(1)}°` : '--';
    if (batteryTempNode) batteryTempNode.textContent = Number.isFinite(batteryTemp) ? `${batteryTemp.toFixed(1)}°C` : '--';
    headingNode.textContent = Number.isFinite(heading) ? `${Math.round(normalizeCourseDegrees(heading))}°` : '--';
    if (courseNode) courseNode.textContent = Number.isFinite(heading) ? `${Math.round(normalizeCourseDegrees(heading))}°` : '--';
    if (logNode) logNode.textContent = Number.isFinite(logNm) ? `${logNm.toFixed(2)} nm` : '--';
    if (twaNode) twaNode.textContent = Number.isFinite(twa) ? `${Math.round(twa)}°` : '--';
    if (twsNode) twsNode.textContent = Number.isFinite(wind) ? `${wind.toFixed(1)} kn` : '--';
    if (twdNode) twdNode.textContent = Number.isFinite(twd)
        ? `${Math.round(twd)}° ${degreesToCardinalFr(twd)}`
        : '--';
    if (baroNode) baroNode.textContent = Number.isFinite(baro) ? `${baro.toFixed(1)} hPa` : '--';
    if (airTempNode) airTempNode.textContent = Number.isFinite(airTemp) ? `${airTemp.toFixed(1)}°C` : '--';
    if (probeTempNode) probeTempNode.textContent = Number.isFinite(probeTemp) ? `${probeTemp.toFixed(1)}°C` : '--';
    if (humidityNode) humidityNode.textContent = Number.isFinite(humidity) ? `${humidity.toFixed(0)}%` : '--';
    if (dewPointNode) dewPointNode.textContent = Number.isFinite(dewPoint) ? `${dewPoint.toFixed(1)}°C` : '--';
    if (cloudNode) cloudNode.textContent = Number.isFinite(cloudCover) ? `${cloudCover.toFixed(0)}%` : '--';
    if (rainNode) rainNode.textContent = Number.isFinite(rainRate) ? `${rainRate.toFixed(2)} mm/h` : '--';
    if (engineNode) engineNode.textContent = typeof engineRunning === 'boolean' ? (engineRunning ? 'ON' : 'OFF') : '--';
    if (engineFramesNode) engineFramesNode.textContent = String(Number(maintenanceSignalKStats?.engine || 0));
    if (rpmNode) rpmNode.textContent = Number.isFinite(engineRpm) ? `${Math.round(engineRpm)} rpm` : '--';
    if (pointOfSailNode) {
        pointOfSailNode.textContent = pointOfSailLabel;
        pointOfSailNode.dataset.empty = pointOfSailLabel === '--' ? '1' : '0';
    }
    swellNode.textContent = `${swell.value.toFixed(1)} m`;

    const swellThresholds = getDashboardThreshold('navSwell');
    const swellWarnHigh = Number.isFinite(swellThresholds?.warnHigh) ? swellThresholds.warnHigh : 2.2;
    const swellAlertHigh = Number.isFinite(swellThresholds?.alertHigh) ? swellThresholds.alertHigh : 3.4;

    const swellClass = swell.value >= swellAlertHigh
        ? 'log-live-swell--heavy'
        : (swell.value >= swellWarnHigh ? 'log-live-swell--rough' : (swell.value >= 1 ? 'log-live-swell--moderate' : 'log-live-swell--calm'));
    swellNode.classList.remove('log-live-swell--calm', 'log-live-swell--moderate', 'log-live-swell--rough', 'log-live-swell--heavy');
    swellNode.classList.add(swellClass);
    if (liveCardNode) {
        liveCardNode.classList.toggle('log-live-table-card--heavy', swell.value >= swellWarnHigh);
        liveCardNode.classList.toggle('log-live-table-card--weather-alert',
            (Number.isFinite(rainRate) && rainRate >= 0.4)
            || (Number.isFinite(wind) && wind >= 25)
            || swell.value >= swellAlertHigh);
    }

    setNavLiveDashboardGauge('speed', speed, 0, 12, 'navSpeed');
    setNavLiveDashboardGauge('twa', Number.isFinite(twa) ? Math.abs(twa) : null, 0, 180);
    setNavLiveDashboardGauge('tws', wind, 0, 40);
    setNavLiveDashboardGauge('cog', Number.isFinite(heading) ? normalizeCourseDegrees(heading) : null, 0, 360);
    setNavLiveDashboardGauge('heel', Number.isFinite(heel) ? Math.abs(heel) : null, 0, 45, 'navHeel');
    setNavLiveDashboardGauge('airTemp', airTemp, -10, 45);
    setNavLiveDashboardGauge('dewPoint', dewPoint, -10, 30);
    setNavLiveDashboardGauge('swell', swell.value, 0, 5.5, 'navSwell');
    setNavLiveDashboardGauge('probeTemp', probeTemp, 0, 120, 'signalkProbeTemp');
    setNavLiveDashboardGauge('batteryTemp', batteryTemp, 0, 60, 'signalkBatteryTemp');
    setNavLiveDashboardGauge('humidity', humidity, 0, 100, 'signalkHumidity');
    setNavLiveDashboardGauge('baro', baro, 960, 1040, 'signalkBaro');
    setNavLiveDashboardGauge('rpm', engineRpm, 0, 3500, 'signalkRpm');
    setNavLiveDashboardBalance('twa', signedTwa, -180, 180);
    setNavLiveDashboardBalance('heel', Number.isFinite(heel) ? heel : null, -45, 45);
    setNavLiveDashboardNeedle('heading', Number.isFinite(heading) ? normalizeCourseDegrees(heading) : 0);
    setNavLiveDashboardNeedle('wind', Number.isFinite(twd) ? normalizeCourseDegrees(twd) : 0);

    updateNavPolarCaptureHint();
    renderEngineLogTemperatureFields();
}

function readFiniteOrientationValue(value) {
    return typeof value === 'number' && Number.isFinite(value) ? value : null;
}

function getScreenOrientationAngle() {
    const orientationAngle = readFiniteOrientationValue(window?.screen?.orientation?.angle);
    if (Number.isFinite(orientationAngle)) return orientationAngle;

    const legacyAngle = readFiniteOrientationValue(window?.orientation);
    if (Number.isFinite(legacyAngle)) return legacyAngle;

    return 0;
}

function deriveHeelDegreesFromOrientationEvent(event) {
    const gamma = readFiniteOrientationValue(event?.gamma);
    const beta = readFiniteOrientationValue(event?.beta);
    if (!Number.isFinite(gamma) && !Number.isFinite(beta)) return null;

    const normalizedAngle = ((getScreenOrientationAngle() % 360) + 360) % 360;
    let heelDeg = gamma;

    if (normalizedAngle === 90) {
        heelDeg = Number.isFinite(beta) ? -beta : gamma;
    } else if (normalizedAngle === 270) {
        heelDeg = Number.isFinite(beta) ? beta : gamma;
    } else if (normalizedAngle === 180) {
        heelDeg = Number.isFinite(gamma) ? -gamma : beta;
    } else if (!Number.isFinite(heelDeg)) {
        heelDeg = beta;
    }

    return Number.isFinite(heelDeg)
        ? Math.max(-89.9, Math.min(89.9, heelDeg))
        : null;
}

function drawHeelSpeedChart() {
    const canvas = document.getElementById('heelSpeedChart');
    if (!canvas) return;
    const context = canvas.getContext('2d');
    if (!context) return;

    const width = canvas.width;
    const height = canvas.height;

    context.clearRect(0, 0, width, height);
    context.fillStyle = '#0f1d2b';
    context.fillRect(0, 0, width, height);

    context.strokeStyle = 'rgba(255,255,255,0.15)';
    context.lineWidth = 1;
    context.beginPath();
    context.moveTo(36, 10);
    context.lineTo(36, height - 28);
    context.lineTo(width - 12, height - 28);
    context.stroke();

    const points = [
        ...navLogEntries,
        ...getNavGpsTraceEntries()
    ]
        .filter(item => Number.isFinite(item?.heelDeg) && Number.isFinite(item?.speedKn))
        .slice(-140);

    if (!points.length) {
        context.fillStyle = '#9cb5c9';
        context.font = '12px Arial';
        context.fillText(t('Aucune donnée inclinaison/vitesse', 'Sin datos inclinación/velocidad'), 50, 26);
        return;
    }

    const maxHeel = Math.max(20, ...points.map(item => Math.abs(item.heelDeg)));
    const maxSpeed = Math.max(8, ...points.map(item => item.speedKn));

    points.forEach(item => {
        const x = 36 + (Math.abs(item.heelDeg) / maxHeel) * (width - 52);
        const y = (height - 28) - (item.speedKn / maxSpeed) * (height - 42);
        context.fillStyle = '#8fe7ff';
        context.beginPath();
        context.arc(x, y, 2.4, 0, Math.PI * 2);
        context.fill();
    });

    context.fillStyle = '#9cb5c9';
    context.font = '11px Arial';
    context.fillText(t(`Inclinaison max: ${maxHeel.toFixed(1)}°`, `Inclinación máx: ${maxHeel.toFixed(1)}°`), 40, height - 10);
    context.fillText(t(`Vitesse max: ${maxSpeed.toFixed(1)} kn`, `Velocidad máx: ${maxSpeed.toFixed(1)} kn`), width - 160, 20);
}

function renderNavLogList() {
    const container = document.getElementById('navLogList');
    if (!container) return;

    if (!Array.isArray(navLogEntries) || navLogEntries.length === 0) {
        container.innerHTML = `<div class="log-card">${t('Aucune entrée navigation pour le moment.', 'No hay entradas de navegación por ahora.')}</div>`;
        drawHeelSpeedChart();
        updateNavLiveDashboard();
        renderNavGpsTraceOnMap();
        return;
    }

    container.innerHTML = '';

    const headerRow = document.createElement('div');
    headerRow.className = 'log-list-header';
    headerRow.innerHTML =
        `<span>${t('Date', 'Fecha')}</span>` +
        `<span>${t('Créateur', 'Creador')}</span>` +
        `<span>${t('Quart', 'Guardia')}</span>` +
        `<span>${t('Loch', 'Corredera')}</span>`;
    container.appendChild(headerRow);

    navLogEntries
        .slice()
        .reverse()
        .forEach(item => {
            const watchTime = item?.watchTimeIso ? formatDateTimeFr(item.watchTimeIso) : formatDateTimeFr(item?.timestamp);
            const watchEndTime = item?.watchEndTimeIso ? formatDateTimeFr(item.watchEndTimeIso) : '';
            const creatorName = String(item?.creatorName || '').trim();
            const creatorLabel = creatorName || '[creatorName manquant]';
            const watchCrewLabel = String(item?.watchCrew || '').trim() || '[quart manquant]';
            const loch = Number.isFinite(item?.logDistanceNm) ? `${item.logDistanceNm.toFixed(1)} NM` : '[loch manquant]';
            const watchRangeLabel = watchEndTime ? `${watchTime} -> ${watchEndTime}` : watchTime;
            const row = document.createElement('div');
            row.className = 'log-list-row';
            if ((editingNavLogEntryId && String(item?.id || '') === editingNavLogEntryId)
                || (navSelectedTraceEntryId && String(item?.id || '') === navSelectedTraceEntryId)) {
                row.classList.add('log-list-row--active');
            }

            const summaryRow = document.createElement('div');
            summaryRow.className = 'log-list-summary';
            summaryRow.innerHTML =
                `<span class="log-list-col">${escapeHtml(watchRangeLabel)}</span>` +
                `<span class="log-list-col">${escapeHtml(creatorLabel)}</span>` +
                `<span class="log-list-col">${escapeHtml(watchCrewLabel)}</span>` +
                `<span class="log-list-col">${escapeHtml(loch)}</span>`;
            summaryRow.addEventListener('click', () => {
                startEditNavLogEntry(String(item?.id || ''));
            });

            row.appendChild(summaryRow);

            const eventLabel = String(item?.events || '').trim();
            if (eventLabel) {
                const eventsRow = document.createElement('div');
                eventsRow.style.margin = '4px 0 0';
                eventsRow.style.fontSize = '11px';
                eventsRow.style.opacity = '0.88';
                eventsRow.style.color = eventLabel.includes('ALERTE') || eventLabel.includes('⚠️') ? '#ffb3b3' : '#cbe9ff';
                eventsRow.textContent = eventLabel.length > 170 ? `${eventLabel.slice(0, 170)}…` : eventLabel;
                eventsRow.addEventListener('click', () => {
                    startEditNavLogEntry(String(item?.id || ''));
                });
                row.appendChild(eventsRow);
            }

            const traceHintRow = document.createElement('div');
            traceHintRow.style.margin = '6px 0 0';
            traceHintRow.style.fontSize = '11px';
            traceHintRow.style.opacity = '0.82';
            traceHintRow.style.color = '#8fe7ff';
            traceHintRow.textContent = t(
                'Cliquer pour rouvrir la trace sur la carte',
                'Tocar para reabrir la traza en el mapa'
            );
            traceHintRow.addEventListener('click', () => {
                startEditNavLogEntry(String(item?.id || ''));
            });
            row.appendChild(traceHintRow);

            const actionRow = document.createElement('div');
            actionRow.className = 'button-row';
            actionRow.style.marginTop = '6px';

            const exportBtn = document.createElement('button');
            exportBtn.type = 'button';
            exportBtn.style.flex = '1';
            exportBtn.textContent = t('PDF log', 'PDF log', 'Log PDF');
            exportBtn.addEventListener('click', event => {
                event.stopPropagation();
                void exportNavLogEntryPdf(String(item?.id || ''));
            });
            actionRow.appendChild(exportBtn);

            row.appendChild(actionRow);

            container.appendChild(row);
        });

    drawHeelSpeedChart();
    updateNavLiveDashboard();
    renderNavGpsTraceOnMap();
}

function getNavGpsTraceEntries() {
    return (Array.isArray(navGpsSessionSamples) ? navGpsSessionSamples : [])
        .filter(item => Number.isFinite(item?.lat) && Number.isFinite(item?.lng));
}

function normalizeCourseDegrees(value) {
    const degrees = Number(value);
    if (!Number.isFinite(degrees)) return null;
    return ((degrees % 360) + 360) % 360;
}

function normalizeTwaDegrees(value) {
    const degrees = normalizeCourseDegrees(value);
    if (!Number.isFinite(degrees)) return null;
    return degrees > 180 ? 360 - degrees : degrees;
}

function normalizeSignedRelativeDegrees(value) {
    const degrees = normalizeCourseDegrees(value);
    if (!Number.isFinite(degrees)) return null;
    return degrees > 180 ? degrees - 360 : degrees;
}

function getNavTraceEntryTimestampMs(entry) {
    if (!entry) return NaN;
    const rawValue = entry?.timestamp ?? entry?.watchTimeIso ?? entry?.fixTimeMs ?? null;
    return toTimestampMs(rawValue);
}

function shouldRefreshNavPointWeather(lat, lng, { force = false } = {}) {
    if (force) return true;
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;

    const nowMs = Date.now();
    if ((nowMs - navLastWeatherRefreshAtMs) >= NAV_POINT_WEATHER_REFRESH_INTERVAL_MS) {
        return true;
    }

    if (!Number.isFinite(navLastWeatherRefreshLat) || !Number.isFinite(navLastWeatherRefreshLng)) {
        return true;
    }

    const movedNm = distanceNm(navLastWeatherRefreshLat, navLastWeatherRefreshLng, lat, lng);
    return Number.isFinite(movedNm) && movedNm >= NAV_POINT_WEATHER_REFRESH_DISTANCE_NM;
}

async function refreshNavPointWeather(lat, lng, { force = false } = {}) {
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return false;
    if (navWeatherRefreshInFlight) return false;
    if (!shouldRefreshNavPointWeather(lat, lng, { force })) return false;

    navWeatherRefreshInFlight = true;
    navLastWeatherRefreshAtMs = Date.now();
    navLastWeatherRefreshLat = lat;
    navLastWeatherRefreshLng = lng;

    try {
        const weather = await getCurrentWeatherAtWaypoint(lat, lng);
        const airTemp = Number(weather?.temperature);
        const seaTemp = Number(weather?.seaSurfaceTemperature);
        const pressure = Number(weather?.pressure);

        navLatestAirTempC = Number.isFinite(airTemp) ? airTemp : navLatestAirTempC;
        navLatestSeaTempC = Number.isFinite(seaTemp) ? seaTemp : navLatestSeaTempC;
        navLatestWeatherPressureHpa = Number.isFinite(pressure) ? pressure : navLatestWeatherPressureHpa;
        navLatestWeatherUpdatedAt = String(weather?.updatedAt || new Date().toISOString());
        return true;
    } catch (_error) {
        return false;
    } finally {
        navWeatherRefreshInFlight = false;
    }
}

function buildNavTracePointPopupHtml(entry, isLoadingWeather = false) {
    const lat = Number(entry?.lat);
    const lng = Number(entry?.lng);
    const speedKn = Number(entry?.speedKn);
    const heelDeg = Number(entry?.heelDeg);
    const headingDeg = Number(entry?.headingDeg);
    const windDirectionDeg = Number(entry?.windDirectionDeg);
    const windSpeedKn = Number(entry?.windSpeedKn);
    const windGustKn = Number(entry?.windGustKn);
    const barometerHpa = Number(entry?.barometerHpa);
    const airTempC = Number(entry?.temperatureC);
    const seaTempC = Number(entry?.seaSurfaceTemperatureC);
    const waveHeightM = Number(entry?.waveHeightM);
    const wavePeriodS = Number(entry?.wavePeriodS);
    const precipitationMm = Number(entry?.precipitationMm);
    const oceanCurrentKn = Number(entry?.oceanCurrentKn);
    const oceanCurrentDeg = Number(entry?.oceanCurrentDeg);

    const na = '—';
    const headingLabel = Number.isFinite(headingDeg) ? `${Math.round(normalizeCourseDegrees(headingDeg))}°` : na;
    const windDirLabel = Number.isFinite(windDirectionDeg)
        ? `${Math.round(normalizeCourseDegrees(windDirectionDeg))}° ${degreesToCardinalFr(windDirectionDeg)}`
        : na;
    const currentDirLabel = Number.isFinite(oceanCurrentDeg)
        ? `${Math.round(normalizeCourseDegrees(oceanCurrentDeg))}° ${degreesToCardinalFr(oceanCurrentDeg)}`
        : na;

    const row = (label, value) =>
        `<tr><td style="color:#5a7070;padding:2px 8px 2px 0;white-space:nowrap;font-size:11px">${label}</td>` +
        `<td style="font-weight:600;font-size:12px">${value}</td></tr>`;

    const sectionHd = (icon, label) =>
        `<tr><td colspan="2" style="padding:5px 0 2px;border-bottom:1px solid #dde8e8;color:#0a5c5a;` +
        `font-size:10px;letter-spacing:.07em;text-transform:uppercase;font-weight:700">${icon} ${label}</td></tr>`;

    const waveLabel = Number.isFinite(waveHeightM)
        ? `${waveHeightM.toFixed(1)} m${Number.isFinite(wavePeriodS) ? ` · ${wavePeriodS.toFixed(0)}s` : ''}`
        : na;
    const currentLabel = Number.isFinite(oceanCurrentKn)
        ? `${oceanCurrentKn.toFixed(1)} kn · ${currentDirLabel}`
        : na;

    const tableStyle = 'border-collapse:collapse;width:100%;margin-bottom:4px';
    const loadingRow = isLoadingWeather
        ? `<tr><td colspan="2" style="color:#888;font-size:11px;padding:3px 0 1px">` +
          `⏳ ${t('Chargement météo...', 'Cargando meteo...')}</td></tr>`
        : '';

    const rows =
        sectionHd('🧭', t('Navigation', 'Navegación')) +
        row(t('Heure', 'Hora'), escapeHtml(formatDateTimeFr(entry?.timestamp))) +
        row(t('Position', 'Posición'), Number.isFinite(lat) && Number.isFinite(lng) ? `${lat.toFixed(5)}, ${lng.toFixed(5)}` : na) +
        row(t('Vitesse', 'Velocidad'), Number.isFinite(speedKn) ? `${speedKn.toFixed(1)} kn` : na) +
        row(t('Cap', 'Rumbo'), headingLabel) +
        row(t('Inclinaison', 'Inclinación'), Number.isFinite(heelDeg) ? `${heelDeg.toFixed(1)}°` : na) +
        sectionHd('🌦', t('Météo', 'Meteo')) +
        row(t('Vent', 'Viento'), Number.isFinite(windSpeedKn) ? `${windSpeedKn.toFixed(1)} kn · ${windDirLabel}` : na) +
        row(t('Rafales', 'Ráfagas'), Number.isFinite(windGustKn) ? `${windGustKn.toFixed(1)} kn` : na) +
        row(t('Temp air', 'Temp aire'), Number.isFinite(airTempC) ? `${airTempC.toFixed(1)}°C` : na) +
        row(t('Temp mer', 'Temp mar'), Number.isFinite(seaTempC) ? `${seaTempC.toFixed(1)}°C` : na) +
        row(t('Pression', 'Presión'), Number.isFinite(barometerHpa) ? `${barometerHpa.toFixed(0)} hPa` : na) +
        row(t('Pluie', 'Lluvia'), Number.isFinite(precipitationMm) ? `${precipitationMm.toFixed(1)} mm` : na) +
        row(t('Houle', 'Oleaje'), waveLabel) +
        row(t('Courant', 'Corriente'), currentLabel) +
        loadingRow +
        sectionHd('⛵', t('État de mer', 'Estado de mar')) +
        row(t('État de mer', 'Estado de mar'), escapeHtml(String(entry?.seaState || na))) +
        row(t('Voilure', 'Velamen'), escapeHtml(String(entry?.sailConfig || na))) +
        row(t('Source', 'Origen'), escapeHtml(String(entry?.source || na)));

    return `<div style="min-width:240px;max-width:290px;font-family:inherit">` +
        `<div style="font-weight:700;font-size:13px;color:#0a5c5a;margin-bottom:5px;` +
        `border-bottom:2px solid #0a5c5a;padding-bottom:4px">` +
        `📍 ${t('Point de trace GPS', 'Punto de traza GPS')}</div>` +
        `<table style="${tableStyle}">${rows}</table>` +
        `</div>`;
}

function computeDerivedNavMetricsFromPoints(previousPoint, currentPoint) {
    const previousLat = Number(previousPoint?.lat);
    const previousLng = Number(previousPoint?.lng ?? previousPoint?.lon);
    const currentLat = Number(currentPoint?.lat);
    const currentLng = Number(currentPoint?.lng ?? currentPoint?.lon);
    const previousMs = getNavTraceEntryTimestampMs(previousPoint);
    const currentMs = getNavTraceEntryTimestampMs(currentPoint);

    if (!Number.isFinite(previousLat) || !Number.isFinite(previousLng) || !Number.isFinite(currentLat) || !Number.isFinite(currentLng)) {
        return { speedKn: null, courseDeg: null };
    }

    if (!Number.isFinite(previousMs) || !Number.isFinite(currentMs) || currentMs <= previousMs) {
        return { speedKn: null, courseDeg: null };
    }

    const elapsedHours = (currentMs - previousMs) / (60 * 60 * 1000);
    if (!Number.isFinite(elapsedHours) || elapsedHours <= 0) {
        return { speedKn: null, courseDeg: null };
    }

    const distanceValueNm = distanceNm(previousLat, previousLng, currentLat, currentLng);
    if (!Number.isFinite(distanceValueNm)) {
        return { speedKn: null, courseDeg: null };
    }

    const hasMeaningfulMove = distanceValueNm >= 0.003;
    const speedKn = hasMeaningfulMove ? (distanceValueNm / elapsedHours) : 0;
    const courseDeg = hasMeaningfulMove
        ? normalizeCourseDegrees(getBearing(
            { lat: previousLat, lon: previousLng },
            { lat: currentLat, lon: currentLng }
        ))
        : null;

    return {
        speedKn: Number.isFinite(speedKn) ? speedKn : null,
        courseDeg
    };
}

function getNavLogEntryById(entryId) {
    const targetId = String(entryId || '').trim();
    if (!targetId) return null;
    return Array.isArray(navLogEntries)
        ? (navLogEntries.find(item => String(item?.id || '') === targetId) || null)
        : null;
}

function getNavLogEntryTimeRange(entry) {
    if (!entry || typeof entry !== 'object') return null;

    const startMs = toTimestampMs(entry?.watchTimeIso || entry?.timestamp || null);
    if (!Number.isFinite(startMs)) return null;

    let endMs = toTimestampMs(entry?.watchEndTimeIso || null);
    if (!Number.isFinite(endMs) || endMs < startMs) {
        const safeEntries = sanitizeNavLogEntriesList(navLogEntries);
        const entryIndex = safeEntries.findIndex(item => String(item?.id || '') === String(entry?.id || ''));
        if (entryIndex >= 0) {
            const nextEntry = safeEntries[entryIndex + 1] || null;
            const nextStartMs = toTimestampMs(nextEntry?.watchTimeIso || nextEntry?.timestamp || null);
            if (Number.isFinite(nextStartMs) && nextStartMs > startMs) {
                endMs = nextStartMs - 1000;
            }
        }
    }

    if (!Number.isFinite(endMs) || endMs < startMs) {
        endMs = startMs + NAV_GPS_SAMPLE_INTERVAL_MS + 120000;
    }

    return { startMs, endMs };
}

function getNavTraceEntriesForEntry(entry) {
    const embeddedTrace = sanitizeNavGpsTraceSamplesList(entry?.traceSamples);
    if (embeddedTrace.length) {
        return embeddedTrace;
    }

    const timeRange = getNavLogEntryTimeRange(entry);
    if (!timeRange) return [];

    const startBoundaryMs = timeRange.startMs - 30000;
    const endBoundaryMs = timeRange.endMs + 90000;

    return getNavGpsTraceEntries().filter(item => {
        const itemMs = getNavTraceEntryTimestampMs(item);
        return Number.isFinite(itemMs) && itemMs >= startBoundaryMs && itemMs <= endBoundaryMs;
    });
}

function getSelectedNavTraceEntry() {
    return getNavLogEntryById(navSelectedTraceEntryId || editingNavLogEntryId || '');
}

function focusNavTraceEntriesOnMap(traceEntries) {
    if (!map || !Array.isArray(traceEntries) || traceEntries.length === 0) return;

    const latlngs = traceEntries
        .map(item => [Number(item?.lat), Number(item?.lng)])
        .filter(([lat, lng]) => Number.isFinite(lat) && Number.isFinite(lng));

    if (!latlngs.length) return;

    if (latlngs.length === 1) {
        map.setView(latlngs[0], Math.max(map.getZoom(), 14));
        return;
    }

    const bounds = L.latLngBounds(latlngs);
    if (bounds.isValid()) {
        map.fitBounds(bounds, { padding: [28, 28] });
    }
}

function ensureNavGpsTraceLayerGroup() {
    if (!map) return null;
    if (!navGpsTraceLayerGroup) {
        navGpsTraceLayerGroup = L.layerGroup();
    }
    if (!map.hasLayer(navGpsTraceLayerGroup)) {
        navGpsTraceLayerGroup.addTo(map);
    }
    return navGpsTraceLayerGroup;
}

function updateNavCurrentPositionMarker(fix) {
    if (!map) return;
    const lat = Number(fix?.lat);
    const lng = Number(fix?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;

    const speedKn = Number(fix?.speedKn);
    const headingDeg = Number(navLatestCourseDeg);
    const fixTimeLabel = formatDateTimeFr(fix?.fixTimeMs || Date.now());

    if (!navCurrentPositionMarker) {
        navCurrentPositionMarker = L.circleMarker([lat, lng], {
            radius: 8,
            color: '#05324d',
            weight: 2,
            fillColor: '#37d2ff',
            fillOpacity: 0.92
        }).addTo(map);
    } else {
        navCurrentPositionMarker.setLatLng([lat, lng]);
        if (!map.hasLayer(navCurrentPositionMarker)) {
            navCurrentPositionMarker.addTo(map);
        }
    }

    const speedLabel = Number.isFinite(speedKn) ? `${speedKn.toFixed(1)} kn` : 'N/A';
    const headingLabel = Number.isFinite(headingDeg)
        ? `${Math.round(((headingDeg % 360) + 360) % 360)} deg`
        : 'N/A';
    navCurrentPositionMarker.bindPopup(
        `${t('Position GPS actuelle', 'Posicion GPS actual')}<br>` +
        `${t('Heure', 'Hora')}: ${fixTimeLabel}<br>` +
        `${t('Vitesse', 'Velocidad')}: ${speedLabel}<br>` +
        `${t('Cap', 'Rumbo')}: ${headingLabel}<br>` +
        `${t('Temp air', 'Temp aire')}: ${Number.isFinite(navLatestAirTempC) ? `${navLatestAirTempC.toFixed(1)}°C` : 'N/A'}`
    );
    navCurrentPositionMarker.bindTooltip(t('Position actuelle', 'Posicion actual'), {
        direction: 'top',
        offset: [0, -8],
        opacity: 0.9
    });
}

function getNavHeelTraceColor(heelDeg) {
    const heel = Math.abs(Number(heelDeg) || 0);
    if (heel >= 25) return '#ff4d4d';
    if (heel >= 15) return '#ffb648';
    return '#34c759';
}

function renderNavGpsTraceOnMap() {
    if (!map) return;

    const selectedEntry = getSelectedNavTraceEntry();
    const selectedTraceEntries = selectedEntry ? getNavTraceEntriesForEntry(selectedEntry) : [];
    const traceEntries = selectedTraceEntries.length ? selectedTraceEntries : getNavGpsTraceEntries();
    const isFocusedTrace = selectedTraceEntries.length > 0;
    const layerGroup = ensureNavGpsTraceLayerGroup();
    if (!layerGroup) return;

    layerGroup.clearLayers();
    if (!traceEntries.length) return;

    const latlngs = traceEntries.map(item => [item.lat, item.lng]);
    const polyline = L.polyline(latlngs, {
        color: isFocusedTrace ? '#ffd166' : '#5ac8fa',
        weight: 3,
        opacity: 0.9
    });
    if (selectedEntry) {
        const label = String(selectedEntry?.watchCrew || '').trim() || t('Session GPS', 'Sesion GPS');
        polyline.bindPopup(`${t('Trace sélectionnée', 'Traza seleccionada')}<br>${escapeHtml(label)}`);
    }
    layerGroup.addLayer(polyline);

    // Keep markers lightweight: show heel points only on recent samples.
    const heelMarkers = traceEntries.slice(-300);
    heelMarkers.forEach(entry => {
        const heel = Number.isFinite(entry?.heelDeg) ? entry.heelDeg : null;
        const marker = L.circleMarker([entry.lat, entry.lng], {
            radius: 4,
            color: '#0b1f2e',
            weight: 1,
            fillColor: isFocusedTrace ? '#ffd166' : getNavHeelTraceColor(heel),
            fillOpacity: 0.9
        });

        const needsWeatherFetch = !Number.isFinite(entry.waveHeightM) || !Number.isFinite(entry.precipitationMm);
        marker.bindPopup(buildNavTracePointPopupHtml(entry, needsWeatherFetch), { maxWidth: 310, autoPan: false });

        if (needsWeatherFetch) {
            marker.on('popupopen', async () => {
                try {
                    const ts = new Date(entry.timestamp);
                    const dateStr = ts.toISOString().split('T')[0];
                    const hourStr = `${String(ts.getUTCHours()).padStart(2, '0')}:00`;
                    const weather = await getWeatherAtDateHour(entry.lat, entry.lng, dateStr, hourStr);
                    if (!marker.isPopupOpen()) return;
                    const enriched = {
                        ...entry,
                        windSpeedKn: Number.isFinite(entry.windSpeedKn) ? entry.windSpeedKn : weather?.windSpeed,
                        windDirectionDeg: Number.isFinite(entry.windDirectionDeg) ? entry.windDirectionDeg : weather?.windDirection,
                        windGustKn: Number.isFinite(entry.windGustKn) ? entry.windGustKn : weather?.windGust,
                        temperatureC: Number.isFinite(entry.temperatureC) ? entry.temperatureC : weather?.temperature,
                        seaSurfaceTemperatureC: Number.isFinite(entry.seaSurfaceTemperatureC) ? entry.seaSurfaceTemperatureC : weather?.seaSurfaceTemperature,
                        barometerHpa: Number.isFinite(entry.barometerHpa) ? entry.barometerHpa : weather?.pressure,
                        waveHeightM: Number.isFinite(entry.waveHeightM) ? entry.waveHeightM : weather?.waveHeight,
                        wavePeriodS: Number.isFinite(entry.wavePeriodS) ? entry.wavePeriodS : weather?.wavePeriod,
                        precipitationMm: Number.isFinite(entry.precipitationMm) ? entry.precipitationMm : weather?.precipitation,
                        windGustKn: Number.isFinite(entry.windGustKn) ? entry.windGustKn : weather?.windGust,
                        oceanCurrentKn: Number.isFinite(entry.oceanCurrentKn) ? entry.oceanCurrentKn : weather?.currentSpeedKnots,
                        oceanCurrentDeg: Number.isFinite(entry.oceanCurrentDeg) ? entry.oceanCurrentDeg : weather?.oceanCurrentDirection,
                    };
                    marker.setPopupContent(buildNavTracePointPopupHtml(enriched, false));
                } catch (_e) {
                    if (marker.isPopupOpen()) marker.setPopupContent(buildNavTracePointPopupHtml(entry, false));
                }
            });
        }

        layerGroup.addLayer(marker);
    });
}

function resetNavLogEditorForm() {
    const watchTimeInput = document.getElementById('watchTimeInput');
    const watchEndTimeInput = document.getElementById('watchEndTimeInput');
    const watchCrewInput = document.getElementById('watchCrewInput');
    const watchHeadingInput = document.getElementById('watchHeadingInput');
    const watchWindDirInput = document.getElementById('watchWindDirInput');
    const watchWindSpeedInput = document.getElementById('watchWindSpeedInput');
    const watchSeaStateInput = document.getElementById('watchSeaStateInput');
    const watchSailConfigInput = document.getElementById('watchSailConfigInput');
    const watchBarometerInput = document.getElementById('watchBarometerInput');
    const watchLogNmInput = document.getElementById('watchLogNmInput');
    const watchEventsInput = document.getElementById('watchEventsInput');

    if (watchTimeInput) watchTimeInput.value = toLocalDateTimeInputValue(new Date());
    if (watchEndTimeInput) watchEndTimeInput.value = '';
    if (watchCrewInput) watchCrewInput.value = '';
    if (watchHeadingInput) watchHeadingInput.value = '';
    if (watchWindDirInput) watchWindDirInput.value = '';
    if (watchWindSpeedInput) watchWindSpeedInput.value = '';
    if (watchSeaStateInput) watchSeaStateInput.value = 'calme';
    if (watchSailConfigInput) {
        const activeProfile = getSelectedPolarProfileForNavLog();
        const activeProfileName = String(activeProfile?.name || '');
        refreshNavSailConfigSelect(activeProfileName);
        watchSailConfigInput.dataset.polarProfileName = activeProfileName;
    }
    if (watchBarometerInput) watchBarometerInput.value = '';
    if (watchLogNmInput) watchLogNmInput.value = '';
    if (watchEventsInput) watchEventsInput.value = '';
}

function updateNavLogFormMode() {
    const saveBtn = document.getElementById('addManualNavLogBtn');
    const deleteBtn = document.getElementById('deleteNavLogBtn');

    if (saveBtn) {
        saveBtn.textContent = editingNavLogEntryId
            ? t('Mettre à jour entrée', 'Actualizar entrada', 'Update entry')
            : t('Enregistrer entrée', 'Guardar entrada', 'Save entry');
    }

    if (deleteBtn) {
        const editingEntry = editingNavLogEntryId
            ? navLogEntries.find(item => String(item?.id || '') === String(editingNavLogEntryId))
            : null;
        const canDelete = !!editingEntry && isOwnedByCurrentCloudUser(editingEntry?.creatorEmail);
        deleteBtn.style.display = canDelete ? '' : 'none';
    }
}

function cancelNavLogEdit() {
    editingNavLogEntryId = null;
    navSelectedTraceEntryId = '';
    resetNavLogEditorForm();
    updateNavLogFormMode();
    logWorkspaceMode = 'nav';
    renderNavLogList();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
}

function closeLogWorkspacePanel() {
    editingNavLogEntryId = null;
    editingEngineLogEntryId = null;
    engineLogDraftStartProbeTempC = null;
    navSelectedTraceEntryId = '';
    logWorkspaceMode = 'none';
    resetNavLogEditorForm();

    const hoursInput = document.getElementById('engineHoursInput');
    const fuelInput = document.getElementById('fuelAddedInput');
    const noteInput = document.getElementById('engineLogNoteInput');
    if (hoursInput) hoursInput.value = '';
    if (fuelInput) fuelInput.value = '';
    if (noteInput) noteInput.value = '';

    updateNavLogFormMode();
    updateEngineLogFormMode();
    refreshEngineHoursInputGuard();
    renderNavLogList();
    renderEngineLogList();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
}

function startEditNavLogEntry(entryId) {
    const targetId = String(entryId || '');
    const entry = navLogEntries.find(item => String(item?.id || '') === targetId);
    if (!entry) return;

    if (activeTabName === 'navlog' && !navLogLayoutState.showLog) {
        navLogLayoutState = {
            ...navLogLayoutState,
            showLog: true
        };
        saveNavLogLayoutState();
    }

    const watchTimeInput = document.getElementById('watchTimeInput');
    const watchEndTimeInput = document.getElementById('watchEndTimeInput');
    const watchCrewInput = document.getElementById('watchCrewInput');
    const watchHeadingInput = document.getElementById('watchHeadingInput');
    const watchWindDirInput = document.getElementById('watchWindDirInput');
    const watchWindSpeedInput = document.getElementById('watchWindSpeedInput');
    const watchSeaStateInput = document.getElementById('watchSeaStateInput');
    const watchSailConfigInput = document.getElementById('watchSailConfigInput');
    const watchBarometerInput = document.getElementById('watchBarometerInput');
    const watchLogNmInput = document.getElementById('watchLogNmInput');
    const watchEventsInput = document.getElementById('watchEventsInput');

    if (!watchTimeInput || !watchCrewInput || !watchHeadingInput || !watchWindDirInput || !watchWindSpeedInput || !watchSeaStateInput || !watchSailConfigInput || !watchBarometerInput || !watchLogNmInput || !watchEventsInput) {
        return;
    }

    editingNavLogEntryId = targetId;
    navSelectedTraceEntryId = targetId;
    const entryDate = parseDateInputFlexible(entry?.watchTimeIso || entry?.timestamp || Date.now());
    watchTimeInput.value = toLocalDateTimeInputValue(entryDate || new Date());
    const entryEndDate = parseDateInputFlexible(entry?.watchEndTimeIso || null);
    if (watchEndTimeInput) {
        watchEndTimeInput.value = entryEndDate ? toLocalDateTimeInputValue(entryEndDate) : '';
    }
    watchCrewInput.value = String(entry?.watchCrew || '');
    watchHeadingInput.value = Number.isFinite(entry?.headingDeg) ? String(Math.round(entry.headingDeg)) : '';
    watchWindDirInput.value = Number.isFinite(entry?.windDirectionDeg) ? String(Math.round(entry.windDirectionDeg)) : '';
    watchWindSpeedInput.value = Number.isFinite(entry?.windSpeedKn) ? entry.windSpeedKn.toFixed(1) : '';
    watchSeaStateInput.value = String(entry?.seaState || 'calme');
    refreshNavSailConfigSelect(String(entry?.sailConfig || ''));
    delete watchSailConfigInput.dataset.polarProfileName;
    watchBarometerInput.value = Number.isFinite(entry?.barometerHpa) ? entry.barometerHpa.toFixed(1) : '';
    watchLogNmInput.value = Number.isFinite(entry?.logDistanceNm) ? entry.logDistanceNm.toFixed(1) : '';
    watchEventsInput.value = String(entry?.events || '');

    logWorkspaceMode = 'nav';
    updateNavLogFormMode();
    renderNavLogList();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
    focusNavTraceEntriesOnMap(getNavTraceEntriesForEntry(entry));
}

function deleteEditingNavLogEntry() {
    const targetId = String(editingNavLogEntryId || '').trim();
    if (!targetId) return;

    const entry = navLogEntries.find(item => String(item?.id || '') === targetId);
    if (!entry) {
        editingNavLogEntryId = null;
        updateNavLogFormMode();
        setNavLogStatus(t('Entrée introuvable.', 'Entrada no encontrada.', 'Entry not found.'), true);
        renderNavLogList();
        renderLogWorkspacePanel();
        updateNavLiveDashboard();
        return;
    }

    const watchTimeLabel = entry?.watchTimeIso
        ? formatDateTimeFr(entry.watchTimeIso)
        : formatDateTimeFr(entry?.timestamp || new Date().toISOString());
    const confirmed = window.confirm(
        t(
            `Supprimer définitivement le log du ${watchTimeLabel} ?`,
            `¿Eliminar definitivamente el log del ${watchTimeLabel}?`,
            `Permanently delete the log from ${watchTimeLabel}?`
        )
    );
    if (!confirmed) return;

    navLogEntries = navLogEntries.filter(item => String(item?.id || '') !== targetId);
    editingNavLogEntryId = null;
    if (navSelectedTraceEntryId === targetId) {
        navSelectedTraceEntryId = '';
    }
    logWorkspaceMode = 'none';
    resetNavLogEditorForm();
    updateNavLogFormMode();
    saveNavLogEntries();
    renderNavLogList();
    renderLogWorkspacePanel();
    setNavLogStatus(t('Log de navigation supprimé.', 'Log de navegación eliminado.', 'Navigation log deleted.'));
    updateNavLiveDashboard();
}

function appendNavLogEntry({ lat, lng, speedKn, heelDeg, source = 'gps', watchTimeIso = null, watchEndTimeIso = null, watchCrew = '', headingDeg = null, windDirectionDeg = null, windSpeedKn = null, seaState = '', sailConfig = '', barometerHpa = null, logDistanceNm = null, events = '', traceSamples = [] }) {
    const hasPosition = Number.isFinite(lat) && Number.isFinite(lng);

    if (!hasPosition && source !== 'manual') return;

    const createdEntry = {
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        timestamp: new Date().toISOString(),
        watchTimeIso,
        watchEndTimeIso,
        traceSamples: sanitizeNavGpsTraceSamplesList(traceSamples),
        lat: hasPosition ? lat : null,
        lng: hasPosition ? lng : null,
        speedKn: Number.isFinite(speedKn) ? speedKn : null,
        heelDeg: Number.isFinite(heelDeg) ? heelDeg : null,
        source,
        watchCrew,
        headingDeg: Number.isFinite(headingDeg) ? headingDeg : null,
        windDirectionDeg: Number.isFinite(windDirectionDeg) ? windDirectionDeg : null,
        windSpeedKn: Number.isFinite(windSpeedKn) ? windSpeedKn : null,
        seaState,
        sailConfig,
        barometerHpa: Number.isFinite(barometerHpa) ? barometerHpa : null,
        logDistanceNm: Number.isFinite(logDistanceNm) ? logDistanceNm : null,
        events,
        creatorEmail: getCreatorPatch().creatorEmail,
        creatorName: getCreatorPatch().creatorName
    };

    navLogEntries.push(createdEntry);

    if (navLogEntries.length > 1200) {
        navLogEntries = navLogEntries.slice(navLogEntries.length - 1200);
    }

    saveNavLogEntries();
    renderNavLogList();
    updateNavLiveDashboard();
    return createdEntry;
}

function captureNavGpsSample(sampleSource = 'gps-watch') {
    if (!navGpsLatestFix || !Number.isFinite(navGpsLatestFix.lat) || !Number.isFinite(navGpsLatestFix.lng)) {
        return false;
    }

    const watchHeadingInput = document.getElementById('watchHeadingInput');
    const watchWindDirInput = document.getElementById('watchWindDirInput');
    const watchWindSpeedInput = document.getElementById('watchWindSpeedInput');
    const watchSeaStateInput = document.getElementById('watchSeaStateInput');
    const watchSailConfigInput = document.getElementById('watchSailConfigInput');
    const watchBarometerInput = document.getElementById('watchBarometerInput');

    const headingFromInput = Number.parseFloat(String(watchHeadingInput?.value || ''));
    const windDirFromInput = Number.parseFloat(String(watchWindDirInput?.value || ''));
    const windSpeedFromInput = Number.parseFloat(String(watchWindSpeedInput?.value || ''));
    const barometerFromInput = Number.parseFloat(String(watchBarometerInput?.value || ''));

    const sampleHeadingDeg = Number.isFinite(navLatestCourseDeg)
        ? normalizeCourseDegrees(navLatestCourseDeg)
        : (Number.isFinite(headingFromInput) ? normalizeCourseDegrees(headingFromInput) : null);
    const sampleWindDirectionDeg = Number.isFinite(signalkLatestWindDir)
        ? normalizeCourseDegrees(signalkLatestWindDir)
        : (Number.isFinite(windDirFromInput) ? normalizeCourseDegrees(windDirFromInput) : null);
    const sampleWindSpeedKn = Number.isFinite(signalkLatestWindSpeedKn)
        ? signalkLatestWindSpeedKn
        : (Number.isFinite(windSpeedFromInput) ? windSpeedFromInput : null);
    const sampleSeaState = String(watchSeaStateInput?.value || '').trim();
    const sampleSailConfig = String(watchSailConfigInput?.value || '').trim();

    const nowSlot = toDateAndHourUtc(new Date());
    const cachedWeather = weatherCache.get(
        getWeatherCacheKeyAtDateHour(navGpsLatestFix.lat, navGpsLatestFix.lng, nowSlot.date, nowSlot.hour)
    );
    const cachedAirTemp = Number(cachedWeather?.temperature);
    const cachedSeaTemp = Number(cachedWeather?.seaSurfaceTemperature);
    const cachedPressure = Number(cachedWeather?.pressure);
    const cachedWaveHeight = Number(cachedWeather?.waveHeight);
    const cachedWavePeriod = Number(cachedWeather?.wavePeriod);
    const cachedPrecip = Number(cachedWeather?.precipitation);
    const cachedWindGust = Number(cachedWeather?.windGust);
    const cachedCurrentKn = Number(cachedWeather?.currentSpeedKnots);
    const cachedCurrentDeg = Number(cachedWeather?.oceanCurrentDirection);

    if (!Number.isFinite(navLatestAirTempC) && Number.isFinite(cachedAirTemp)) {
        navLatestAirTempC = cachedAirTemp;
    }
    if (!Number.isFinite(navLatestSeaTempC) && Number.isFinite(cachedSeaTemp)) {
        navLatestSeaTempC = cachedSeaTemp;
    }
    if (!Number.isFinite(navLatestWeatherPressureHpa) && Number.isFinite(cachedPressure)) {
        navLatestWeatherPressureHpa = cachedPressure;
    }

    const sampleBarometerHpa = Number.isFinite(barometerFromInput)
        ? barometerFromInput
        : (Number.isFinite(navLatestWeatherPressureHpa) ? navLatestWeatherPressureHpa : null);

    void refreshNavPointWeather(navGpsLatestFix.lat, navGpsLatestFix.lng);

    navGpsSessionSamples.push({
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        timestamp: new Date().toISOString(),
        lat: navGpsLatestFix.lat,
        lng: navGpsLatestFix.lng,
        speedKn: navGpsLatestFix.speedKn,
        heelDeg: Number.isFinite(navLatestHeelDeg) ? navLatestHeelDeg : null,
        headingDeg: sampleHeadingDeg,
        windDirectionDeg: sampleWindDirectionDeg,
        windSpeedKn: sampleWindSpeedKn,
        seaState: sampleSeaState,
        sailConfig: sampleSailConfig,
        barometerHpa: sampleBarometerHpa,
        temperatureC: Number.isFinite(navLatestAirTempC) ? navLatestAirTempC : null,
        seaSurfaceTemperatureC: Number.isFinite(navLatestSeaTempC) ? navLatestSeaTempC : null,
        waveHeightM: Number.isFinite(cachedWaveHeight) ? cachedWaveHeight : null,
        wavePeriodS: Number.isFinite(cachedWavePeriod) ? cachedWavePeriod : null,
        precipitationMm: Number.isFinite(cachedPrecip) ? cachedPrecip : null,
        windGustKn: Number.isFinite(cachedWindGust) ? cachedWindGust : null,
        oceanCurrentKn: Number.isFinite(cachedCurrentKn) ? cachedCurrentKn : null,
        oceanCurrentDeg: Number.isFinite(cachedCurrentDeg) ? cachedCurrentDeg : null,
        weatherUpdatedAt: navLatestWeatherUpdatedAt,
        source: sampleSource
    });

    if (navGpsSessionSamples.length > 50000) {
        const overflow = navGpsSessionSamples.length - 50000;
        navGpsSessionSamples = navGpsSessionSamples.slice(overflow);
        navGpsSessionStartSampleIndex = Math.max(0, navGpsSessionStartSampleIndex - overflow);
    }

    navGpsSessionHasSample = true;
    saveNavGpsTraceSamples();
    renderNavGpsTraceOnMap();
    drawHeelSpeedChart();
    return true;
}

function appendAutoNavSessionSummaryEntry() {
    const sessionEntries = getCurrentNavGpsSessionSamples();

    if (!sessionEntries.length) return null;

    let distance = 0;
    for (let index = 1; index < sessionEntries.length; index++) {
        const previous = sessionEntries[index - 1];
        const current = sessionEntries[index];
        distance += distanceNm(previous.lat, previous.lng, current.lat, current.lng);
    }

    const speedValues = sessionEntries.map(item => item?.speedKn).filter(value => Number.isFinite(value));
    const heelValues = sessionEntries.map(item => item?.heelDeg).filter(value => Number.isFinite(value));
    const averageSpeed = speedValues.length ? speedValues.reduce((sum, value) => sum + value, 0) / speedValues.length : null;
    const averageHeel = heelValues.length ? heelValues.reduce((sum, value) => sum + Math.abs(value), 0) / heelValues.length : null;
    const durationMinutes = navGpsSessionStartMs > 0 ? Math.max(0, (Date.now() - navGpsSessionStartMs) / 60000) : null;

    const watchHeadingInput = document.getElementById('watchHeadingInput');
    const watchWindDirInput = document.getElementById('watchWindDirInput');
    const watchWindSpeedInput = document.getElementById('watchWindSpeedInput');
    const watchSeaStateInput = document.getElementById('watchSeaStateInput');
    const watchSailConfigInput = document.getElementById('watchSailConfigInput');
    const watchBarometerInput = document.getElementById('watchBarometerInput');

    const headingFromInput = Number.parseFloat(String(watchHeadingInput?.value || ''));
    const windDirFromInput = Number.parseFloat(String(watchWindDirInput?.value || ''));
    const windSpeedFromInput = Number.parseFloat(String(watchWindSpeedInput?.value || ''));
    const barometerFromInput = Number.parseFloat(String(watchBarometerInput?.value || ''));

    const latestHeadingDeg = Number.isFinite(navLatestCourseDeg)
        ? normalizeCourseDegrees(navLatestCourseDeg)
        : (Number.isFinite(headingFromInput) ? normalizeCourseDegrees(headingFromInput) : null);
    const latestWindDirectionDeg = Number.isFinite(signalkLatestWindDir)
        ? normalizeCourseDegrees(signalkLatestWindDir)
        : (Number.isFinite(windDirFromInput) ? normalizeCourseDegrees(windDirFromInput) : null);
    const latestWindSpeedKn = Number.isFinite(signalkLatestWindSpeedKn)
        ? signalkLatestWindSpeedKn
        : (Number.isFinite(windSpeedFromInput) ? windSpeedFromInput : null);
    const latestBarometerHpa = Number.isFinite(barometerFromInput) ? barometerFromInput : null;
    const latestSeaState = String(watchSeaStateInput?.value || '').trim();
    const latestSailConfig = String(watchSailConfigInput?.value || '').trim();

    const summaryText = t(
        `Session GPS auto: ${sessionEntries.length} points · durée ${durationMinutes ? durationMinutes.toFixed(1) : '0.0'} min · distance ${distance.toFixed(2)} NM · vitesse moy ${Number.isFinite(averageSpeed) ? averageSpeed.toFixed(1) : 'N/A'} kn · inclinaison moy ${Number.isFinite(averageHeel) ? averageHeel.toFixed(1) : 'N/A'}°`,
        `Sesión GPS auto: ${sessionEntries.length} puntos · duración ${durationMinutes ? durationMinutes.toFixed(1) : '0.0'} min · distancia ${distance.toFixed(2)} NM · velocidad media ${Number.isFinite(averageSpeed) ? averageSpeed.toFixed(1) : 'N/A'} kn · inclinación media ${Number.isFinite(averageHeel) ? averageHeel.toFixed(1) : 'N/A'}°`
    );

    const summaryEntry = appendNavLogEntry({
        lat: null,
        lng: null,
        speedKn: averageSpeed,
        heelDeg: averageHeel,
        source: 'manual',
        watchTimeIso: navGpsSessionStartMs > 0 ? new Date(navGpsSessionStartMs).toISOString() : new Date().toISOString(),
        watchEndTimeIso: new Date().toISOString(),
        watchCrew: t('AUTO GPS', 'AUTO GPS'),
        headingDeg: latestHeadingDeg,
        windDirectionDeg: latestWindDirectionDeg,
        windSpeedKn: latestWindSpeedKn,
        seaState: latestSeaState,
        sailConfig: latestSailConfig,
        barometerHpa: latestBarometerHpa,
        logDistanceNm: distance,
        events: summaryText,
        traceSamples: sessionEntries
    });

    return {
        entryId: String(summaryEntry?.id || ''),
        points: sessionEntries.length,
        distance,
        durationMinutes
    };
}

function addManualNavigationLogEntry(event) {
    const now = Date.now();
    // Ignore accidental double-fire (e.g. direct + delegated listeners firing together).
    if (now - navLogLastSubmitMs < 250) return;
    navLogLastSubmitMs = now;

    if (event?.preventDefault) event.preventDefault();
    if (event?.stopPropagation) event.stopPropagation();

    let manualData;
    try {
        manualData = getManualNavFormData();
    } catch (error) {
        const details = String(error?.message || error || 'erreur inconnue');
        setNavLogStatus(t(
            `Lecture du formulaire journal impossible: ${details}`,
            `Lectura del formulario diario imposible: ${details}`
        ), true);
        return;
    }

    if (editingNavLogEntryId) {
        let updated = false;
        navLogEntries = navLogEntries.map(entry => {
            if (String(entry?.id || '') !== editingNavLogEntryId) return entry;
            updated = true;
            const normalizedEntry = sanitizeNavLogEntry({
                ...entry,
                ...manualData,
                source: 'manual',
                speedKn: Number.isFinite(navLatestSpeedKn) ? navLatestSpeedKn : entry?.speedKn ?? null,
                heelDeg: Number.isFinite(navLatestHeelDeg) ? navLatestHeelDeg : entry?.heelDeg ?? null,
                creatorEmail: entry?.creatorEmail || getCreatorPatch().creatorEmail,
                creatorName: entry?.creatorName || getCreatorPatch().creatorName
            });
            return normalizedEntry || entry;
        });

        if (updated) {
            saveNavLogEntries();
            updateNavLogFormMode();
            renderNavLogList();
            setNavLogStatus(t('Entrée journal mise à jour.', 'Entrada de diario actualizada.'));
            alert(t('Mise à jour du log de navigation confirmée.', 'Actualización del log de navegación confirmada.'));
            // Keep nav editor visible after an update to avoid closing the workspace unexpectedly.
            logWorkspaceMode = 'nav';
            renderLogWorkspacePanel();
            updateNavLiveDashboard();
            return;
        }

        // If edit mode points to a stale/missing entry, fallback to create mode instead of a silent no-op.
        editingNavLogEntryId = null;
        setNavLogStatus(t('Mode édition invalide détecté, création d\'une nouvelle entrée.', 'Modo edición inválido detectado, creación de una nueva entrada.'));
    }

    try {
        appendNavLogEntry({
            lat: null,
            lng: null,
            speedKn: navLatestSpeedKn,
            heelDeg: navLatestHeelDeg,
            source: 'manual',
            ...manualData
        });
    } catch (error) {
        const details = String(error?.message || error || 'erreur inconnue');
        setNavLogStatus(t(
            `Enregistrement du journal impossible: ${details}`,
            `Registro del diario imposible: ${details}`
        ), true);
        return;
    }

    setNavLogStatus(t(`Entrée jour de bord ajoutée · ${navLogEntries.length} entrée(s)`, `Entrada de bitácora añadida · ${navLogEntries.length} entrada(s)`));

    editingNavLogEntryId = null;
    logWorkspaceMode = 'none';
    resetNavLogEditorForm();
    updateNavLogFormMode();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
}

function handleNavOrientation(event) {
    const heelDeg = deriveHeelDegreesFromOrientationEvent(event);
    if (!Number.isFinite(heelDeg)) return;
    navLatestHeelDeg = heelDeg;
    updateNavLiveDashboard();
}

function ensureMotionListenerBound() {
    if (navMotionListenerBound) return;
    window.addEventListener('deviceorientation', handleNavOrientation, true);
    navMotionListenerBound = true;
}

async function requestMotionPermissionIfNeeded() {
    try {
        if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
            const permission = await DeviceOrientationEvent.requestPermission();
            if (permission !== 'granted') {
                setNavLogStatus(t('Inclinaison refusée par iOS.', 'Inclinación rechazada por iOS.'), true);
                return false;
            }
        }

        ensureMotionListenerBound();
        setNavLogStatus(t('Capteur inclinaison activé.', 'Sensor de inclinación activado.'));
        return true;
    } catch (_error) {
        setNavLogStatus(t('Impossible d’activer le capteur inclinaison.', 'No se puede activar el sensor de inclinación.'), true);
        return false;
    }
}

function getLatestEngineLogEntry() {
    const safeEntries = sanitizeEngineLogEntriesList(engineLogEntries);
    if (!safeEntries.length) return null;
    return safeEntries[safeEntries.length - 1] || null;
}

function clamp01(value) {
    const n = Number(value);
    if (!Number.isFinite(n)) return 0;
    return Math.max(0, Math.min(1, n));
}

function setEngineSensorStatus(message, isError = false) {
    const status = document.getElementById('engineSensorStatus');
    if (!status) return;
    status.textContent = message;
    status.style.color = isError ? '#ff8f8f' : '';
}

function resolveEngineSensorHoursBaseline() {
    const latest = getLatestEngineLogEntry();
    const latestHours = Number(latest?.hours);
    const hoursInput = document.getElementById('engineHoursInput');
    const typedHours = Number.parseFloat(String(hoursInput?.value || ''));

    if (Number.isFinite(typedHours) && Number.isFinite(latestHours) && typedHours > latestHours) {
        return typedHours;
    }
    if (Number.isFinite(typedHours) && !Number.isFinite(latestHours)) {
        return typedHours;
    }
    if (Number.isFinite(latestHours)) {
        return latestHours;
    }
    return null;
}

function renderEngineSensorUi() {
    const stateValue = document.getElementById('engineSensorStateValue');
    const scoreValue = document.getElementById('engineSensorScoreValue');
    const vibrationValue = document.getElementById('engineSensorVibrationValue');
    const speedValue = document.getElementById('engineSensorSpeedValue');
    const rpmValue = document.getElementById('engineSensorRpmValue');
    const startBtn = document.getElementById('engineSensorStartBtn');
    const stopBtn = document.getElementById('engineSensorStopBtn');

    if (scoreValue) scoreValue.textContent = `${Math.round(engineSensorScore * 100)}`;
    if (vibrationValue) vibrationValue.textContent = engineSensorSmoothedVibration.toFixed(3);
    if (speedValue) {
        if (Number.isFinite(engineSensorLastSpeedKn)) {
            speedValue.textContent = `${engineSensorLastSpeedKn.toFixed(1)} kn`;
        } else if (Number.isFinite(navLatestSpeedKn)) {
            speedValue.textContent = `${navLatestSpeedKn.toFixed(1)} kn`;
        } else {
            speedValue.textContent = '-- kn';
        }
    }
    if (rpmValue) {
        const rpm = resolveCurrentEngineRpm();
        rpmValue.textContent = Number.isFinite(rpm) ? `${Math.round(rpm)} rpm` : '-- rpm';
    }

    if (stateValue) {
        stateValue.textContent = engineSensorDetectedRunning ? 'ON' : 'OFF';
        stateValue.classList.toggle('engine-sensor-state--on', engineSensorDetectedRunning);
        stateValue.classList.toggle('engine-sensor-state--off', !engineSensorDetectedRunning);
    }

    if (startBtn) startBtn.disabled = engineSensorDetectionActive;
    if (stopBtn) stopBtn.disabled = !engineSensorDetectionActive;
}

function startEngineSensorSpeedWatch() {
    if (!engineSensorDetectionActive || !navigator.geolocation || engineSensorGeoWatchId !== null) return;

    engineSensorGeoWatchId = navigator.geolocation.watchPosition(
        position => {
            const speedMs = Number(position?.coords?.speed);
            engineSensorLastSpeedKn = Number.isFinite(speedMs) ? speedMs * 1.943844 : null;
            renderEngineSensorUi();
        },
        () => {
            engineSensorLastSpeedKn = null;
            renderEngineSensorUi();
        },
        {
            enableHighAccuracy: true,
            maximumAge: 10000,
            timeout: 12000
        }
    );
}

function stopEngineSensorSpeedWatch() {
    if (engineSensorGeoWatchId === null || !navigator.geolocation) return;
    navigator.geolocation.clearWatch(engineSensorGeoWatchId);
    engineSensorGeoWatchId = null;
}

function finalizeEngineSensorSession() {
    if (!engineSensorRunningStartMs || !engineSensorDetectedRunning) return;

    const nowMs = Date.now();
    const durationMs = Math.max(0, nowMs - engineSensorRunningStartMs);
    const durationHours = durationMs / (60 * 60 * 1000);
    engineSensorDetectedRunning = false;

    if (durationMs < 45000) {
        engineSensorRunningStartProbeTempC = null;
        setEngineSensorStatus(t('Détection moteur: session ignorée (<45s).', 'Detección motor: sesión ignorada (<45s).', 'Engine detection: session ignored (<45s).'));
        renderEngineSensorUi();
        return;
    }

    const latest = getLatestEngineLogEntry();
    const previousHours = Number(latest?.hours);
    let baselineHours = Number(engineSensorRunningHoursBaseline);
    if (!Number.isFinite(baselineHours) && Number.isFinite(previousHours)) {
        baselineHours = previousHours;
    }

    if (!Number.isFinite(baselineHours)) {
        engineSensorRunningStartProbeTempC = null;
        setEngineSensorStatus(t(
            'Détection moteur: définis d\'abord un compteur moteur manuel pour activer l\'auto-log.',
            'Detección motor: define primero un contador motor manual para activar el auto-log.',
            'Engine detection: set a manual engine-hour counter first to enable auto-log.'
        ), true);
        renderEngineSensorUi();
        return;
    }

    let estimatedHours = baselineHours + durationHours;
    if (Number.isFinite(previousHours)) {
        estimatedHours = Math.max(estimatedHours, previousHours + 0.1);
    }
    estimatedHours = Number(estimatedHours.toFixed(1));

    const durationMinutes = Math.max(1, Math.round(durationMs / 60000));
    const note = t(
        `Auto capteurs iPad: moteur detecte ~${durationMinutes} min (score max ${Math.round(engineSensorScore * 100)}).`,
        `Auto sensores iPad: motor detectado ~${durationMinutes} min (score max ${Math.round(engineSensorScore * 100)}).`,
        `Auto iPad sensors: engine detected ~${durationMinutes} min (peak score ${Math.round(engineSensorScore * 100)}).`
    );
    const probeTempStartC = Number.isFinite(engineSensorRunningStartProbeTempC) ? engineSensorRunningStartProbeTempC : null;
    const probeTempEndC = Number.isFinite(signalkLatestProbeTempC) ? signalkLatestProbeTempC : null;

    engineLogEntries.push({
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
        timestamp: new Date().toISOString(),
        creatorEmail: getCreatorPatch().creatorEmail,
        creatorName: getCreatorPatch().creatorName,
        hours: estimatedHours,
        fuelAddedL: 0,
        probeTempStartC,
        probeTempEndC,
        note
    });

    if (engineLogEntries.length > 800) {
        engineLogEntries = engineLogEntries.slice(engineLogEntries.length - 800);
    }

    saveEngineLogEntries();
    renderEngineLogList();
    refreshEngineHoursInputGuard();
    setEngineSensorStatus(t(
        `Détection moteur: session enregistrée (${durationMinutes} min).`,
        `Detección motor: sesión guardada (${durationMinutes} min).`,
        `Engine detection: session saved (${durationMinutes} min).`
    ));
    engineSensorRunningStartProbeTempC = null;
    renderEngineSensorUi();
}

function evaluateEngineSensorState(nowMs = Date.now()) {
    const speedKn = Number.isFinite(engineSensorLastSpeedKn)
        ? engineSensorLastSpeedKn
        : (Number.isFinite(navLatestSpeedKn) ? navLatestSpeedKn : 0);

    const vibrationNorm = clamp01(engineSensorSmoothedVibration / 0.22);
    const speedNorm = clamp01((speedKn - 1.2) / 3.3);
    let rawScore = clamp01((vibrationNorm * 0.74) + (speedNorm * 0.26));

    const staleMs = nowMs - engineSensorLastSampleMs;
    if (staleMs > 3500) rawScore *= 0.75;
    if (staleMs > 8000) rawScore *= 0.4;

    engineSensorScore = clamp01((engineSensorScore * 0.8) + (rawScore * 0.2));

    if (!engineSensorDetectedRunning) {
        if (engineSensorScore >= ENGINE_SENSOR_ON_THRESHOLD) {
            if (!engineSensorOnCandidateSinceMs) {
                engineSensorOnCandidateSinceMs = nowMs;
            }
            if (nowMs - engineSensorOnCandidateSinceMs >= ENGINE_SENSOR_ON_HOLD_MS) {
                engineSensorDetectedRunning = true;
                engineSensorRunningStartMs = nowMs;
                engineSensorRunningHoursBaseline = resolveEngineSensorHoursBaseline();
                engineSensorRunningStartProbeTempC = Number.isFinite(signalkLatestProbeTempC) ? signalkLatestProbeTempC : null;
                engineSensorOffCandidateSinceMs = 0;
                setEngineSensorStatus(t('Détection moteur: ON confirmé.', 'Detección motor: ON confirmado.', 'Engine detection: ON confirmed.'));
            }
        } else {
            engineSensorOnCandidateSinceMs = 0;
        }
    } else if (engineSensorScore <= ENGINE_SENSOR_OFF_THRESHOLD) {
        if (!engineSensorOffCandidateSinceMs) {
            engineSensorOffCandidateSinceMs = nowMs;
        }
        if (nowMs - engineSensorOffCandidateSinceMs >= ENGINE_SENSOR_OFF_HOLD_MS) {
            finalizeEngineSensorSession();
            engineSensorOnCandidateSinceMs = 0;
            engineSensorOffCandidateSinceMs = 0;
            engineSensorRunningStartMs = 0;
            engineSensorRunningHoursBaseline = null;
        }
    } else {
        engineSensorOffCandidateSinceMs = 0;
    }

    renderEngineSensorUi();
}

function handleEngineMotion(event) {
    if (!engineSensorDetectionActive) return;

    const acceleration = event?.accelerationIncludingGravity || event?.acceleration;
    const ax = Number(acceleration?.x);
    const ay = Number(acceleration?.y);
    const az = Number(acceleration?.z);
    if (!Number.isFinite(ax) || !Number.isFinite(ay) || !Number.isFinite(az)) {
        return;
    }

    const magnitude = Math.sqrt((ax * ax) + (ay * ay) + (az * az));
    const vibration = Math.abs(magnitude - 9.81);
    engineSensorSmoothedVibration = (engineSensorSmoothedVibration * 0.86) + (vibration * 0.14);
    engineSensorLastSampleMs = Date.now();
    evaluateEngineSensorState(engineSensorLastSampleMs);
}

function ensureEngineMotionListenerBound() {
    if (engineSensorMotionListenerBound) return;
    window.addEventListener('devicemotion', handleEngineMotion, true);
    engineSensorMotionListenerBound = true;
}

function unbindEngineMotionListener() {
    if (!engineSensorMotionListenerBound) return;
    window.removeEventListener('devicemotion', handleEngineMotion, true);
    engineSensorMotionListenerBound = false;
}

async function requestEngineMotionPermissionIfNeeded() {
    try {
        if (typeof DeviceMotionEvent !== 'undefined' && typeof DeviceMotionEvent.requestPermission === 'function') {
            const permission = await DeviceMotionEvent.requestPermission();
            if (permission !== 'granted') {
                setEngineSensorStatus(t('Détection moteur: permission capteur refusée.', 'Detección motor: permiso sensor rechazado.', 'Engine detection: motion permission denied.'), true);
                return false;
            }
        }
        return true;
    } catch (_error) {
        setEngineSensorStatus(t('Détection moteur: impossible d\'activer le capteur.', 'Detección motor: no se puede activar el sensor.', 'Engine detection: unable to enable motion sensor.'), true);
        return false;
    }
}

function startEngineSensorDetection() {
    if (engineSensorDetectionActive) return;

    engineSensorDetectionActive = true;
    engineSensorScore = 0;
    engineSensorSmoothedVibration = 0;
    engineSensorLastSampleMs = 0;
    engineSensorOnCandidateSinceMs = 0;
    engineSensorOffCandidateSinceMs = 0;
    engineSensorDetectedRunning = false;
    engineSensorRunningStartMs = 0;
    engineSensorRunningHoursBaseline = null;
    engineSensorRunningStartProbeTempC = null;
    engineSensorLastSpeedKn = null;

    ensureEngineMotionListenerBound();
    startEngineSensorSpeedWatch();

    if (engineSensorTickTimerId !== null) {
        window.clearInterval(engineSensorTickTimerId);
    }
    engineSensorTickTimerId = window.setInterval(() => {
        evaluateEngineSensorState(Date.now());
    }, ENGINE_SENSOR_TICK_INTERVAL_MS);

    setEngineSensorStatus(t('Détection moteur active: en écoute des capteurs.', 'Detección motor activa: escuchando sensores.', 'Engine detection active: listening to sensors.'));
    renderEngineSensorUi();
}

function stopEngineSensorDetection() {
    if (!engineSensorDetectionActive) {
        renderEngineSensorUi();
        return;
    }

    const wasRunning = engineSensorDetectedRunning;
    engineSensorDetectionActive = false;

    if (engineSensorTickTimerId !== null) {
        window.clearInterval(engineSensorTickTimerId);
        engineSensorTickTimerId = null;
    }

    unbindEngineMotionListener();
    stopEngineSensorSpeedWatch();

    if (wasRunning) {
        finalizeEngineSensorSession();
    }

    engineSensorDetectedRunning = false;
    engineSensorOnCandidateSinceMs = 0;
    engineSensorOffCandidateSinceMs = 0;
    engineSensorRunningStartMs = 0;
    engineSensorRunningHoursBaseline = null;
    engineSensorRunningStartProbeTempC = null;
    engineSensorScore = 0;
    engineSensorSmoothedVibration = 0;
    engineSensorLastSampleMs = 0;
    engineSensorLastSpeedKn = null;

    setEngineSensorStatus(t('Détection moteur: arrêtée.', 'Detección motor: detenida.', 'Engine detection: stopped.'));
    renderEngineSensorUi();
}

function resolveCurrentEngineRpm() {
    if (Number.isFinite(signalkLatestEngineRpm)) {
        return signalkLatestEngineRpm;
    }
    return null;
}

async function startEngineSensorDetectionWithPermission() {
    const ok = await requestEngineMotionPermissionIfNeeded();
    if (!ok) return;
    startEngineSensorDetection();
}

function isGeolocationSecureContext() {
    if (window.isSecureContext) return true;
    const host = String(window.location.hostname || '').trim().toLowerCase();
    return host === 'localhost' || host === '127.0.0.1';
}

function getGeolocationErrorMessage(error) {
    const code = Number(error?.code);
    const details = error?.message ? `: ${error.message}` : '';

    if (code === 1) {
        return t(
            `Acces GPS refuse. Autorise la localisation dans Safari pour ce site${details}`,
            `Acceso GPS denegado. Autoriza la ubicacion en Safari para este sitio${details}`
        );
    }

    if (code === 2) {
        return t(
            `Position indisponible (signal GPS/Wi-Fi insuffisant)${details}`,
            `Posicion no disponible (senal GPS/Wi-Fi insuficiente)${details}`
        );
    }

    if (code === 3) {
        return t(
            `GPS trop lent: delai depasse${details}`,
            `GPS demasiado lento: tiempo agotado${details}`
        );
    }

    return t(`Erreur GPS${details}`, `Error GPS${details}`);
}

function applyCurrentPositionFix(position) {
    const latitude = Number(position?.coords?.latitude);
    const longitude = Number(position?.coords?.longitude);
    const speedMs = Number(position?.coords?.speed);
    const speedKn = Number.isFinite(speedMs) ? speedMs * 1.943844 : null;

    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
        setNavLogStatus(t('Fix GPS invalide recu.', 'Fix GPS invalido recibido.'), true);
        return false;
    }

    navGpsLatestFix = {
        lat: latitude,
        lng: longitude,
        speedKn,
        fixTimeMs: Date.now()
    };

    updateNavCurrentPositionMarker(navGpsLatestFix);
    evaluateAnchorDragAlarmWithFix(navGpsLatestFix);
    if (map) {
        map.setView([latitude, longitude], Math.max(map.getZoom(), 13));
    }
    updateNavLiveDashboard();
    return true;
}

function requestCurrentPositionWithFallback(onSuccess, onError) {
    if (!navigator.geolocation) {
        onError({ code: 2, message: 'geolocation-unavailable' });
        return;
    }

    navigator.geolocation.getCurrentPosition(
        onSuccess,
        primaryError => {
            const code = Number(primaryError?.code);
            const canRetryWithLowAccuracy = code === 2 || code === 3;
            if (!canRetryWithLowAccuracy) {
                onError(primaryError);
                return;
            }

            setNavLogStatus(
                t(
                    'GPS haute precision indisponible, nouvelle tentative standard...',
                    'GPS de alta precision no disponible, nuevo intento estandar...'
                )
            );

            navigator.geolocation.getCurrentPosition(
                onSuccess,
                onError,
                {
                    enableHighAccuracy: false,
                    maximumAge: 60000,
                    timeout: 20000
                }
            );
        },
        {
            enableHighAccuracy: true,
            maximumAge: 0,
            timeout: 12000
        }
    );
}

function locateNowOnMap() {
    if (!navigator.geolocation) {
        setNavLogStatus(t('GPS non disponible sur cet appareil.', 'GPS no disponible en este dispositivo.'), true);
        return;
    }

    if (!isGeolocationSecureContext()) {
        setNavLogStatus(
            t(
                'GPS bloque: ouvre l\'app en HTTPS (ou localhost). Sur iPad, la geolocalisation est refusee en HTTP.',
                'GPS bloqueado: abre la app en HTTPS (o localhost). En iPad, la geolocalizacion se rechaza en HTTP.'
            ),
            true
        );
        return;
    }

    setNavLogStatus(t('Recherche de la position en cours...', 'Buscando posición actual...'));

    requestCurrentPositionWithFallback(
        position => {
            if (!applyCurrentPositionFix(position)) return;
            setNavLogStatus(t('Position actuelle affichee sur la carte.', 'Posición actual mostrada en el mapa.'));
        },
        error => {
            setNavLogStatus(getGeolocationErrorMessage(error), true);
        }
    );
}

function locatePreciselyOnMap() {
    if (!navigator.geolocation) {
        setNavLogStatus(t('GPS non disponible sur cet appareil.', 'GPS no disponible en este dispositivo.'), true);
        return;
    }

    if (!isGeolocationSecureContext()) {
        setNavLogStatus(
            t(
                'GPS bloque: ouvre l\'app en HTTPS (ou localhost). Sur iPad, la geolocalisation est refusee en HTTP.',
                'GPS bloqueado: abre la app en HTTPS (o localhost). En iPad, la geolocalizacion se rechaza en HTTP.'
            ),
            true
        );
        return;
    }

    setNavLogStatus(t('Forcage geolocalisation precise en cours...', 'Forzando geolocalización precisa...'));

    navigator.geolocation.getCurrentPosition(
        position => {
            if (!applyCurrentPositionFix(position)) return;
            setNavLogStatus(t('Position precise affichee sur la carte.', 'Posición precisa mostrada en el mapa.'));
        },
        error => {
            setNavLogStatus(getGeolocationErrorMessage(error), true);
        },
        {
            enableHighAccuracy: true,
            maximumAge: 0,
            timeout: 25000
        }
    );
}

function startNavigationLogging() {
    // ---- Route vers SignalK si le mode est activé ----
    if (signalkConfig.mode === 'signalk') {
        startSignalKNavigationLogging();
        return;
    }

    if (!navigator.geolocation) {
        setNavLogStatus(t('GPS non disponible sur cet appareil.', 'GPS no disponible en este dispositivo.'), true);
        return;
    }

    if (!isGeolocationSecureContext()) {
        setNavLogStatus(
            t(
                'GPS bloque: ouvre l\'app en HTTPS (ou localhost). Sur iPad, la geolocalisation est refusee en HTTP.',
                'GPS bloqueado: abre la app en HTTPS (o localhost). En iPad, la geolocalización se rechaza en HTTP.'
            ),
            true
        );
        return;
    }

    if (navWatchId !== null) {
        setNavLogStatus(t('Log GPS déjà actif.', 'Log GPS ya activo.'));
        return;
    }

    stopPassiveNavigationWatch();
    resetNavAutoLogArming(null);
    navGpsLatestFix = null;
    navSelectedTraceEntryId = '';
    navGpsSessionStartMs = Date.now();
    navGpsSessionStartEntryIndex = navLogEntries.length;
    navGpsSessionStartSampleIndex = Array.isArray(navGpsSessionSamples) ? navGpsSessionSamples.length : 0;
    navGpsSessionHasSample = false;
    navHasCenteredOnFirstFix = false;

    if (navGpsSampleTimerId !== null) {
        window.clearInterval(navGpsSampleTimerId);
        navGpsSampleTimerId = null;
    }

    navGpsSampleTimerId = window.setInterval(() => {
        const captured = captureNavGpsSample('gps-watch');
        if (captured) {
            const sessionPoints = getCurrentNavGpsSessionSamples().length;
            setNavLogStatus(t(`Log GPS actif · point capturé (${NAV_GPS_SAMPLE_INTERVAL_MS / 1000}s) · ${sessionPoints} point(s)`, `Log GPS activo · punto capturado (${NAV_GPS_SAMPLE_INTERVAL_MS / 1000}s) · ${sessionPoints} punto(s)`));
        }
    }, NAV_GPS_SAMPLE_INTERVAL_MS);

    navWatchId = navigator.geolocation.watchPosition(
        position => {
            const latitude = Number(position?.coords?.latitude);
            const longitude = Number(position?.coords?.longitude);
            const rawSpeedMs = position?.coords?.speed;
            const speedMs = typeof rawSpeedMs === 'number' && Number.isFinite(rawSpeedMs)
                ? rawSpeedMs
                : null;
            const rawHeadingDeg = position?.coords?.heading;
            const headingDeg = typeof rawHeadingDeg === 'number' && Number.isFinite(rawHeadingDeg)
                ? rawHeadingDeg
                : null;
            const nativeSpeedKn = Number.isFinite(speedMs) ? speedMs * 1.943844 : null;
            const fixTimeMs = Number.isFinite(Number(position?.timestamp))
                ? Number(position.timestamp)
                : Date.now();

            if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return;

            const nextFix = {
                lat: latitude,
                lng: longitude,
                speedKn: nativeSpeedKn,
                fixTimeMs
            };
            const derivedMetrics = computeDerivedNavMetricsFromPoints(navGpsLatestFix, nextFix);
            const resolvedSpeedKn = Number.isFinite(nativeSpeedKn) ? nativeSpeedKn : derivedMetrics.speedKn;
            const resolvedCourseDeg = Number.isFinite(headingDeg)
                ? normalizeCourseDegrees(headingDeg)
                : (Number.isFinite(derivedMetrics.courseDeg) ? derivedMetrics.courseDeg : navLatestCourseDeg);

            navLatestSpeedKn = Number.isFinite(resolvedSpeedKn) ? resolvedSpeedKn : null;
            navLatestCourseDeg = Number.isFinite(resolvedCourseDeg) ? resolvedCourseDeg : navLatestCourseDeg;

            navGpsLatestFix = {
                lat: latitude,
                lng: longitude,
                speedKn: Number.isFinite(resolvedSpeedKn) ? resolvedSpeedKn : null,
                fixTimeMs
            };

            updateNavCurrentPositionMarker(navGpsLatestFix);
            evaluateAnchorDragAlarmWithFix(navGpsLatestFix);
            if (!navHasCenteredOnFirstFix && map) {
                map.setView([latitude, longitude], Math.max(map.getZoom(), 13));
                navHasCenteredOnFirstFix = true;
            }

            if (!navGpsSessionHasSample) {
                captureNavGpsSample('gps-watch');
            }

            const sessionPoints = getCurrentNavGpsSessionSamples().length;
            setNavLogStatus(t(`Log GPS actif · fix reçu · capture chaque minute · ${sessionPoints} point(s)`, `Log GPS activo · fix recibido · captura cada minuto · ${sessionPoints} punto(s)`));
            updateNavLiveDashboard();
        },
        error => {
            setNavLogStatus(getGeolocationErrorMessage(error), true);
        },
        {
            enableHighAccuracy: true,
            maximumAge: 0,
            timeout: 10000
        }
    );

    syncNavLogGpsCompactUi();
}

    // ============================================================
    // SIGNALK INTEGRATION


    function loadSignalKConfig() {
        try {
            const raw = localStorage.getItem(SIGNALK_CONFIG_STORAGE_KEY);
            if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed && typeof parsed === 'object') {
                    signalkConfig = {
                        mode: parsed.mode === 'signalk' ? 'signalk' : 'auto',
                        host: typeof parsed.host === 'string' ? parsed.host : '',
                        autoLogEnabled: parsed.autoLogEnabled !== false
                    };
                }
            }
        } catch (_) { /* ignore */ }
    }

    function saveSignalKConfig() {
        try {
            localStorage.setItem(SIGNALK_CONFIG_STORAGE_KEY, JSON.stringify(signalkConfig));
        } catch (_) { /* ignore */ }
    }

    function recordMaintenanceSignalKStats(data = null) {
        if (!data || typeof data !== 'object') return;

        maintenanceSignalKStats.updates += 1;

        if (Number.isFinite(data.lat) && Number.isFinite(data.lng)) {
            maintenanceSignalKStats.positions += 1;
        }
        if (Number.isFinite(data.twsKn) || Number.isFinite(data.twaDeg) || Number.isFinite(data.twdDeg)) {
            maintenanceSignalKStats.wind += 1;
        }
        if (typeof data.engineRunning === 'boolean' || Number.isFinite(data.engineRpm)) {
            maintenanceSignalKStats.engine += 1;
        }

        const weatherTick = Number(data.weatherFrameTick);
        if (Number.isFinite(weatherTick) && weatherTick > maintenanceSignalKStats.lastWeatherTick) {
            maintenanceSignalKStats.lastWeatherTick = weatherTick;
            maintenanceSignalKStats.weather += 1;
        }
    }

    function flushScheduledSignalKUiRefresh() {
        signalKUiRefreshTimerId = null;
        lastSignalKUiRefreshAtMs = Date.now();

        const data = pendingSignalKUiData;
        pendingSignalKUiData = null;

        updateMaintenanceSignalKMonitor(data);
        updateNavLiveDashboard();
    }

    function scheduleSignalKUiRefresh(data = null) {
        if (data && typeof data === 'object') {
            pendingSignalKUiData = { ...(pendingSignalKUiData || {}), ...data };
        }

        if (signalKUiRefreshTimerId !== null) return;

        const elapsedMs = Date.now() - lastSignalKUiRefreshAtMs;
        const delayMs = elapsedMs >= SIGNALK_UI_REFRESH_INTERVAL_MS
            ? 0
            : (SIGNALK_UI_REFRESH_INTERVAL_MS - elapsedMs);

        signalKUiRefreshTimerId = window.setTimeout(flushScheduledSignalKUiRefresh, delayMs);
    }

    function setSignalKMonitorValue(id, value) {
        const node = document.getElementById(id);
        if (!node) return;
        node.textContent = String(value ?? '--');
    }

    function setSignalKDashboardGauge(widgetKey, value, min, max, thresholdKey = null) {
        const widget = document.querySelector(`[data-sk-widget="${widgetKey}"]`);
        if (!widget) return;

        let fillPct = 0;
        if (Number.isFinite(value) && Number.isFinite(min) && Number.isFinite(max) && max > min) {
            fillPct = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
        }
        widget.style.setProperty('--sk-fill', `${fillPct}%`);

        widget.dataset.state = computeDashboardGaugeState(value, thresholdKey);
    }

    function setSignalKDashboardBalance(balanceKey, value, min, max) {
        const balance = document.querySelector(`[data-sk-balance="${balanceKey}"]`);
        if (!balance) return;
        let positionPct = 50;
        if (Number.isFinite(value) && Number.isFinite(min) && Number.isFinite(max) && max > min) {
            positionPct = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
        }
        balance.style.setProperty('--sk-balance', `${positionPct}%`);
    }

    function setSignalKDashboardNeedle(needleKey, degrees) {
        const needle = document.querySelector(`[data-sk-needle="${needleKey}"]`);
        if (!needle) return;
        const safeDegrees = Number.isFinite(degrees) ? degrees : 0;
        needle.style.transform = `translateX(-50%) rotate(${safeDegrees}deg)`;
    }

    function resetMaintenanceSignalKMonitor() {
        [
            'maintenanceSignalKProbeTempValue',
            'maintenanceSignalKBatteryTempValue',
            'maintenanceSignalKHumidityValue',
            'maintenanceSignalKDewPointValue',
            'maintenanceSignalKCloudCoverValue',
            'maintenanceSignalKRainRateValue',
            'maintenanceSignalKLatValue',
            'maintenanceSignalKLngValue',
            'maintenanceSignalKSpeedValue',
            'maintenanceSignalKCourseValue',
            'maintenanceSignalKHeadingValue',
            'maintenanceSignalKHeelValue',
            'maintenanceSignalKTwsValue',
            'maintenanceSignalKTwaValue',
            'maintenanceSignalKTwdValue',
            'maintenanceSignalKBaroValue',
            'maintenanceSignalKLogValue',
            'maintenanceSignalKEngineValue',
            'maintenanceSignalKRpmValue',
            'maintenanceSignalKWeatherDetailMirror'
        ].forEach(id => setSignalKMonitorValue(id, '--'));

        setSignalKMonitorValue('maintenanceSignalKEngineCountValue', '0');
        setSignalKMonitorValue('maintenanceSignalKLastUpdateValue', '--');

        setSignalKDashboardGauge('probeTemp', null, 0, 120, 'signalkProbeTemp');
        setSignalKDashboardGauge('batteryTemp', null, 0, 60, 'signalkBatteryTemp');
        setSignalKDashboardGauge('humidity', null, 0, 100, 'signalkHumidity');
        setSignalKDashboardGauge('baro', null, 960, 1040, 'signalkBaro');
        setSignalKDashboardGauge('rpm', null, 0, 3500, 'signalkRpm');
        setSignalKDashboardBalance('heel', null, -45, 45);
        setSignalKDashboardBalance('twa', null, -180, 180);
        setSignalKDashboardNeedle('heading', 0);
        setSignalKDashboardNeedle('course', 0);
        maintenanceSignalKLatestFrame = null;
    }

    function renderMaintenanceSignalKDashboard(data = null, dewPointC = null) {
        const dashboard = document.getElementById('maintenanceSignalKDashboard');
        if (!dashboard) return;

        if (data && typeof data === 'object') {
            const previousFrame = maintenanceSignalKLatestFrame || {};
            maintenanceSignalKLatestFrame = {
                ...previousFrame,
                ...data,
                dewPointC: Number.isFinite(dewPointC) ? dewPointC : previousFrame.dewPointC
            };
        }

        const frame = maintenanceSignalKLatestFrame;
        if (!frame) return;

        const headingDisplayDeg = Number.isFinite(frame.headingDeg) ? frame.headingDeg : frame.courseDeg;
        const heelDeg = Number.isFinite(frame.heelDeg) ? frame.heelDeg : null;
        const twaDeg = Number.isFinite(frame.twaDeg) ? normalizeSignedRelativeDegrees(frame.twaDeg) : null;

        setSignalKDashboardGauge('probeTemp', frame.probeTempC, 0, 120, 'signalkProbeTemp');
        setSignalKDashboardGauge('batteryTemp', frame.batteryTempC, 0, 60, 'signalkBatteryTemp');
        setSignalKDashboardGauge('humidity', frame.humidityPct, 0, 100, 'signalkHumidity');
        setSignalKDashboardGauge('baro', frame.baroHpa, 960, 1040, 'signalkBaro');
        setSignalKDashboardGauge('rpm', frame.engineRpm, 0, 3500, 'signalkRpm');
        setSignalKDashboardBalance('heel', heelDeg, -45, 45);
        setSignalKDashboardBalance('twa', twaDeg, -180, 180);
        setSignalKDashboardNeedle('heading', Number.isFinite(headingDisplayDeg) ? normalizeCourseDegrees(headingDisplayDeg) : 0);
        setSignalKDashboardNeedle('course', Number.isFinite(frame.courseDeg) ? normalizeCourseDegrees(frame.courseDeg) : 0);

        const weatherDetailMirror = document.getElementById('maintenanceSignalKWeatherDetailMirror');
        if (weatherDetailMirror) {
            weatherDetailMirror.textContent = frame.weatherPathLast ? String(frame.weatherPathLast) : '--';
            weatherDetailMirror.title = frame.weatherPathLast ? String(frame.weatherPathLast) : '';
        }
    }

    function appendMaintenanceSignalKEvent(message, className = '') {
        const container = document.getElementById('maintenanceSignalKEvents');
        if (!container) return;

        const firstChild = container.firstElementChild;
        if (firstChild && firstChild.classList.contains('signalk-monitor-event--muted')) {
            container.innerHTML = '';
        }

        const item = document.createElement('div');
        item.className = `signalk-monitor-event${className ? ` ${className}` : ''}`;
        item.textContent = `${formatDateTimeFr(new Date().toISOString())} · ${message}`;
        container.prepend(item);

        while (container.children.length > 20) {
            container.removeChild(container.lastElementChild);
        }
    }

    function updateMaintenanceSignalKMonitor(data = null) {
        if (!data || typeof data !== 'object') return;

        setSignalKMonitorValue('maintenanceSignalKEngineCountValue', maintenanceSignalKStats.engine);

        const dewPointC = estimateDewPointC(data.airTempC, data.humidityPct, data.absHumidityGm3);

        setSignalKMonitorValue('maintenanceSignalKProbeTempValue', Number.isFinite(data.probeTempC) ? `${data.probeTempC.toFixed(1)}°C` : '--');
        setSignalKMonitorValue('maintenanceSignalKBatteryTempValue', Number.isFinite(data.batteryTempC) ? `${data.batteryTempC.toFixed(1)}°C` : '--');
        setSignalKMonitorValue('maintenanceSignalKHumidityValue', Number.isFinite(data.humidityPct) ? `${data.humidityPct.toFixed(0)}%` : '--');
        setSignalKMonitorValue('maintenanceSignalKDewPointValue', Number.isFinite(dewPointC) ? `${dewPointC.toFixed(1)}°C` : '--');
        setSignalKMonitorValue('maintenanceSignalKCloudCoverValue', Number.isFinite(data.cloudCoverPct) ? `${data.cloudCoverPct.toFixed(0)}%` : '--');
        setSignalKMonitorValue('maintenanceSignalKRainRateValue', Number.isFinite(data.rainRateMmH) ? `${data.rainRateMmH.toFixed(2)} mm/h` : '--');

        setSignalKMonitorValue('maintenanceSignalKLatValue', Number.isFinite(data.lat) ? data.lat.toFixed(5) : '--');
        setSignalKMonitorValue('maintenanceSignalKLngValue', Number.isFinite(data.lng) ? data.lng.toFixed(5) : '--');
        setSignalKMonitorValue('maintenanceSignalKSpeedValue', Number.isFinite(data.speedKn) ? `${data.speedKn.toFixed(1)} kn` : '--');
        setSignalKMonitorValue('maintenanceSignalKCourseValue', Number.isFinite(data.courseDeg) ? `${Math.round(normalizeCourseDegrees(data.courseDeg))}°` : '--');
        const headingDisplayDeg = Number.isFinite(data.headingDeg) ? data.headingDeg : data.courseDeg;
        setSignalKMonitorValue('maintenanceSignalKHeadingValue', Number.isFinite(headingDisplayDeg) ? `${Math.round(normalizeCourseDegrees(headingDisplayDeg))}°` : '--');
        setSignalKMonitorValue('maintenanceSignalKHeelValue', Number.isFinite(data.heelDeg) ? `${data.heelDeg.toFixed(1)}°` : '--');
        setSignalKMonitorValue('maintenanceSignalKTwsValue', Number.isFinite(data.twsKn) ? `${data.twsKn.toFixed(1)} kn` : '--');
        setSignalKMonitorValue('maintenanceSignalKTwaValue', Number.isFinite(data.twaDeg) ? `${Math.round(data.twaDeg)}°` : '--');
        setSignalKMonitorValue('maintenanceSignalKTwdValue', Number.isFinite(data.twdDeg) ? `${Math.round(normalizeCourseDegrees(data.twdDeg))}°` : '--');
        setSignalKMonitorValue('maintenanceSignalKBaroValue', Number.isFinite(data.baroHpa) ? `${data.baroHpa.toFixed(1)} hPa` : '--');
        setSignalKMonitorValue('maintenanceSignalKLogValue', Number.isFinite(data.logNm) ? `${data.logNm.toFixed(2)} nm` : '--');
        setSignalKMonitorValue('maintenanceSignalKEngineValue', typeof data.engineRunning === 'boolean' ? (data.engineRunning ? 'ON' : 'OFF') : '--');
        setSignalKMonitorValue('maintenanceSignalKRpmValue', Number.isFinite(data.engineRpm) ? `${Math.round(data.engineRpm)} rpm` : '--');

        const pathLabel = data.weatherPathLast ? `${data.weatherPathLast}` : null;
        if (pathLabel) {
            setSignalKMonitorValue('maintenanceSignalKStatusDetailValue', pathLabel);
        }
        setSignalKMonitorValue('maintenanceSignalKLastUpdateValue', formatDateTimeFr(new Date().toISOString()));
        renderMaintenanceSignalKDashboard(data, dewPointC);
    }

    function updateSignalKStatusBadge(status) {
        const badgeCandidates = [
            document.getElementById('signalkStatusBadge'),
            document.getElementById('maintenanceSignalKStatusBadge')
        ].filter(Boolean);
        const textCandidates = [
            document.getElementById('signalkStatusText'),
            document.getElementById('maintenanceSignalKStatusText')
        ].filter(Boolean);

        if (!badgeCandidates.length && !textCandidates.length) return;

        const labels = {
            disconnected: '⚫ Déconnecté',
            connecting:   '🟡 Connexion…',
            connected:    '🟢 Connecté',
            error:        '🔴 Erreur'
        };

        badgeCandidates.forEach(badge => {
            badge.className = 'signalk-badge signalk-badge--' + status;
        });
        textCandidates.forEach(text => {
            text.textContent = labels[status] || status;
        });

        const detail = document.getElementById('maintenanceSignalKStatusDetailValue');
        const lastStatus = document.getElementById('maintenanceSignalKLastStatusValue');
        if (detail) detail.textContent = labels[status] || status;
        if (lastStatus) lastStatus.textContent = formatDateTimeFr(new Date().toISOString());

        const dashboard = document.getElementById('maintenanceSignalKDashboard');
        if (dashboard) dashboard.dataset.status = status;
    }

    function setSignalKManagedInputValue(inputId, value, formatter = null) {
        const input = document.getElementById(inputId);
        if (!input || input.dataset.userEdited) return;
        if (!Number.isFinite(value)) return;

        const nextValue = typeof formatter === 'function'
            ? formatter(value)
            : String(value);

        input.value = String(nextValue);
    }

    function resetSignalKManagedInputUserEdits() {
        ['watchHeadingInput', 'watchWindDirInput', 'watchWindSpeedInput', 'watchBarometerInput', 'watchLogNmInput'].forEach(id => {
            const input = document.getElementById(id);
            if (!input) return;
            delete input.dataset.userEdited;
        });
    }

    function sanitizeSignalKJoystickDirection(direction) {
        const normalized = String(direction || '').trim().toLowerCase();
        return ['left', 'right', 'up', 'down', 'center'].includes(normalized) ? normalized : 'center';
    }

    function resetSignalKJoystickState() {
        signalkLatestJoystickX = null;
        signalkLatestJoystickY = null;
        signalkLatestJoystickPressed = false;
        signalkLatestJoystickDirection = 'center';
        signalkLastJoystickDirection = 'center';
        signalkLastJoystickPressed = false;
        signalkLastJoystickActionAtMs = 0;
        signalkLastJoystickButtonEventAt = 0;
        if (signalKJoystickOpenTimerId !== null) {
            window.clearTimeout(signalKJoystickOpenTimerId);
            signalKJoystickOpenTimerId = null;
        }
    }

    function restoreNavLogLayoutFromJoystick() {
        navLogLayoutState = { showMap: true, showLog: true, showChecklist: true };
        saveNavLogLayoutState();
        setSidebarCollapsed(false);
        renderLogWorkspacePanel();
        applyNavLogLayoutState();
    }

    function openNavLogFromJoystick() {
        const navLogTabTrigger = document.getElementById('navLogTabBtn');

        try {
            activateTab('navlog');
            if (activeTabName !== 'navlog' && navLogTabTrigger instanceof HTMLElement) {
                navLogTabTrigger.click();
            }

            window.setTimeout(() => {
                if (activeTabName === 'navlog') {
                    setNavLogStatus(t('Joystick · Journal nav ouvert.', 'Joystick · Diario nav abierto.'));
                    return;
                }
            }, 80);
        } catch (error) {
            if (navLogTabTrigger instanceof HTMLElement) {
                try {
                    navLogTabTrigger.click();
                } catch (_fallbackError) {
                    return;
                }
            }
        }
    }

    function scheduleNavLogOpenFromJoystick() {
        if (signalKJoystickOpenTimerId !== null) {
            return;
        }

        signalKJoystickOpenTimerId = window.setTimeout(() => {
            signalKJoystickOpenTimerId = null;
            openNavLogFromJoystick();
        }, 0);
    }

    function runSignalKJoystickNavLogAction(direction) {
        switch (direction) {
            case 'left':
                setSidebarCollapsed(!isSidebarCollapsed);
                setNavLogStatus(t('Joystick · menu Journal nav basculé.', 'Joystick · menú Diario nav alternado.'));
                return;
            case 'up':
                setNavLogLayoutSection('showMap', !navLogLayoutState.showMap);
                setNavLogStatus(t('Joystick · panneau carte basculé.', 'Joystick · panel mapa alternado.'));
                return;
            case 'right':
                setNavLogLayoutSection('showLog', !navLogLayoutState.showLog);
                setNavLogStatus(t('Joystick · panneau log basculé.', 'Joystick · panel diario alternado.'));
                return;
            case 'down':
                setNavLogLayoutSection('showChecklist', !navLogLayoutState.showChecklist);
                setNavLogStatus(t('Joystick · panneau checklist basculé.', 'Joystick · panel checklist alternado.'));
                return;
            default:
                return;
        }
    }

    function handleSignalKJoystickInput(data) {
        if (!data || typeof data !== 'object') return;

        if (Number.isFinite(data.joystickX)) signalkLatestJoystickX = Number(data.joystickX);
        if (Number.isFinite(data.joystickY)) signalkLatestJoystickY = Number(data.joystickY);
        if (typeof data.joystickPressed === 'boolean') signalkLatestJoystickPressed = data.joystickPressed;

        const direction = sanitizeSignalKJoystickDirection(data.joystickDirection);
        signalkLatestJoystickDirection = direction;
        const pressedEdge = signalkLatestJoystickPressed && !signalkLastJoystickPressed;
        signalkLastJoystickPressed = signalkLatestJoystickPressed;

        if (activeTabName !== 'navlog' && signalkLatestJoystickPressed) {
            scheduleNavLogOpenFromJoystick();
            return;
        }

        const buttonEventAt = Number(data.joystickButtonEventAt);
        if (Number.isFinite(buttonEventAt) && buttonEventAt > signalkLastJoystickButtonEventAt) {
            signalkLastJoystickButtonEventAt = buttonEventAt;
            if (activeTabName !== 'navlog') {
                scheduleNavLogOpenFromJoystick();
            } else {
                restoreNavLogLayoutFromJoystick();
                setNavLogStatus(t('Joystick · affichage Journal nav réinitialisé.', 'Joystick · vista Diario nav reiniciada.'));
            }
            return;
        }

        if (pressedEdge) {
            if (activeTabName !== 'navlog') {
                scheduleNavLogOpenFromJoystick();
            } else {
                restoreNavLogLayoutFromJoystick();
                setNavLogStatus(t('Joystick · affichage Journal nav réinitialisé.', 'Joystick · vista Diario nav reiniciada.'));
            }
            return;
        }

        if (direction === 'center') {
            signalkLastJoystickDirection = 'center';
            return;
        }

        if (activeTabName !== 'navlog') {
            signalkLastJoystickDirection = direction;
            return;
        }

        const now = Date.now();
        const directionChanged = direction !== signalkLastJoystickDirection;
        const repeatAllowed = (now - signalkLastJoystickActionAtMs) >= SIGNALK_JOYSTICK_REPEAT_MS;
        if (!directionChanged && !repeatAllowed) {
            return;
        }

        signalkLastJoystickDirection = direction;
        signalkLastJoystickActionAtMs = now;
        runSignalKJoystickNavLogAction(direction);
    }

    function applySignalKUpdate(data) {
        const fix = navGpsLatestFix;
        const now = Date.now();
        const headingValue = Number.isFinite(data.headingDeg)
            ? data.headingDeg
            : (Number.isFinite(data.courseDeg) ? data.courseDeg : null);
        const relativeTwaDeg = Number.isFinite(data.twaDeg)
            ? normalizeSignedRelativeDegrees(data.twaDeg)
            : null;
        const windDirectionValue = Number.isFinite(data.twdDeg)
            ? data.twdDeg
            : (Number.isFinite(relativeTwaDeg) && Number.isFinite(headingValue)
                ? normalizeCourseDegrees(headingValue + relativeTwaDeg)
                : null);

        // ---- GPS position ----
        if (Number.isFinite(data.lat) && Number.isFinite(data.lng)) {
            const speedKn = Number.isFinite(data.speedKn) ? data.speedKn : null;
            const nextFix = { lat: data.lat, lng: data.lng, speedKn, fixTimeMs: now };
            const derived = computeDerivedNavMetricsFromPoints(fix, nextFix);
            navLatestSpeedKn = Number.isFinite(speedKn) ? speedKn
                : (Number.isFinite(derived.speedKn) ? derived.speedKn : navLatestSpeedKn);
            navLatestCourseDeg = Number.isFinite(data.courseDeg) ? data.courseDeg
                : (Number.isFinite(derived.courseDeg) ? derived.courseDeg : navLatestCourseDeg);
            navGpsLatestFix = nextFix;
            updateNavCurrentPositionMarker(navGpsLatestFix);
            evaluateAnchorDragAlarmWithFix(navGpsLatestFix);
            if (!navHasCenteredOnFirstFix && map) {
                map.setView([data.lat, data.lng], Math.max(map.getZoom(), 13));
                navHasCenteredOnFirstFix = true;
            }
            if (signalkLoggingActive) {
                if (!navGpsSessionHasSample) captureNavGpsSample('signalk');
                const pts = getCurrentNavGpsSessionSamples().length;
                setNavLogStatus(t(
                    `SignalK · fix reçu · ${pts} point(s)`,
                    `SignalK · fix recibido · ${pts} punto(s)`
                ));
            } else {
                maybeAutoStartNavigationLogging(nextFix, 'SignalK');
            }
        }

        if (Number.isFinite(headingValue)) {
            setSignalKManagedInputValue('watchHeadingInput', normalizeCourseDegrees(headingValue), value => Math.round(value));
        }

        // ---- Gîte (heel) ----
        if (Number.isFinite(data.heelDeg)) {
            navLatestHeelDeg = data.heelDeg;
        }

        // ---- Vent ----
        if (Number.isFinite(data.twsKn)) {
            signalkLatestWindSpeedKn = data.twsKn;
            setSignalKManagedInputValue('watchWindSpeedInput', data.twsKn, value => value.toFixed(1));
        }
        if (Number.isFinite(data.twaDeg)) {
            signalkLatestTwaDeg = normalizeTwaDegrees(data.twaDeg);
        }
        if (Number.isFinite(windDirectionValue)) {
            signalkLatestWindDir = windDirectionValue;
            setSignalKManagedInputValue('watchWindDirInput', windDirectionValue, value => Math.round(normalizeCourseDegrees(value)));
        }

        // ---- Baromètre / loch ----
        if (Number.isFinite(data.baroHpa)) {
            signalkLatestBaroHpa = data.baroHpa;
            navLatestWeatherPressureHpa = data.baroHpa;
            setSignalKManagedInputValue('watchBarometerInput', data.baroHpa, value => value.toFixed(1));
        }
        if (Number.isFinite(data.airTempC)) {
            signalkLatestAirTempC = data.airTempC;
            navLatestAirTempC = data.airTempC;
        }
        if (Number.isFinite(data.probeTempC)) {
            signalkLatestProbeTempC = data.probeTempC;
        }
        if (Number.isFinite(data.batteryTempC)) {
            signalkLatestBatteryTempC = data.batteryTempC;
        }
        if (Number.isFinite(data.humidityPct)) {
            signalkLatestHumidityPct = data.humidityPct;
        }
        if (Number.isFinite(data.absHumidityGm3)) {
            signalkLatestAbsHumidityGm3 = data.absHumidityGm3;
            if (!Number.isFinite(signalkLatestHumidityPct) && Number.isFinite(signalkLatestAirTempC)) {
                const computedHumidity = estimateRelativeHumidityPctFromAbsolute(signalkLatestAbsHumidityGm3, signalkLatestAirTempC);
                if (Number.isFinite(computedHumidity)) {
                    signalkLatestHumidityPct = computedHumidity;
                }
            }
        }
        if (Number.isFinite(data.cloudCoverPct)) {
            signalkLatestCloudCoverPct = data.cloudCoverPct;
        }
        if (Number.isFinite(data.rainRateMmH)) {
            signalkLatestRainRateMmH = data.rainRateMmH;
        }
        if (Number.isFinite(data.logNm)) {
            signalkLatestLogNm = data.logNm;
            setSignalKManagedInputValue('watchLogNmInput', data.logNm, value => value.toFixed(1));
        }

        handleSignalKJoystickInput(data);

        // ---- Moteur ----
        if (typeof data.engineRunning === 'boolean') {
            signalkLatestEngineRunning = data.engineRunning;
            engineSensorDetectedRunning = data.engineRunning;
            if (!data.engineRunning && !Number.isFinite(data.engineRpm)) {
                signalkLatestEngineRpm = null;
                updateEngineAudioRegimeUi();
            }
            renderEngineSensorUi();
        }
        if (Number.isFinite(data.engineRpm)) {
            signalkLatestEngineRpm = data.engineRpm;
            renderEngineSensorUi();
            updateEngineAudioRegimeUi();
        }

        recordMaintenanceSignalKStats(data);
        scheduleSignalKUiRefresh(data);
    }

    function bindSignalKClientCallbacks() {
        if (!signalkClient) return;

        signalkClient.onStatusChange = (status) => {
            updateSignalKStatusBadge(status);
            appendMaintenanceSignalKEvent(`SignalK status: ${status}`,
                status === 'error' ? 'signalk-monitor-event--error' :
                status === 'connected' ? 'signalk-monitor-event--ok' : '');
            if (status === 'error') {
                setNavLogStatus(t(
                    'SignalK: connexion perdue — vérifiez le serveur RPi.',
                    'SignalK: conexión perdida — verifique el servidor RPi.'
                ), true);
            } else if (status === 'connected' && signalkConfig.mode === 'signalk' && !signalkLoggingActive) {
                setNavLogStatus(getAutoLogArmedStatusMessage('signalk'));
            }
        };
        signalkClient.onUpdate = applySignalKUpdate;
    }

    function ensureSignalKStreamingConnection({ announce = true } = {}) {
        const host = signalkConfig.host.trim();
        if (!host) {
            if (announce) {
                setNavLogStatus(t(
                    'SignalK: adresse du serveur manquante (paramètre SignalK).',
                    'SignalK: dirección de servidor faltante (parámetro SignalK).'
                ), true);
            }
            return false;
        }

        if (!signalkClient) {
            signalkClient = new SignalKClient();
        }

        bindSignalKClientCallbacks();

        const status = signalkClient.getStatus();
        const shouldReconnect = signalkStreamingHost !== host || status === 'disconnected' || status === 'error';
        signalkStreamingHost = host;

        if (shouldReconnect) {
            signalkClient.connect(host);
            appendMaintenanceSignalKEvent(`Connexion demandée vers ${host}`);
            if (announce) {
                setNavLogStatus(t(`SignalK · connexion vers ${host}…`, `SignalK · conectando a ${host}…`));
            }
        } else if (announce && status === 'connected') {
            setNavLogStatus(getAutoLogArmedStatusMessage('signalk'));
        }

        return true;
    }

    function stopSignalKStreamingConnection({ resetMonitor = true } = {}) {
        signalkStreamingHost = '';
        if (signalKUiRefreshTimerId !== null) {
            window.clearTimeout(signalKUiRefreshTimerId);
            signalKUiRefreshTimerId = null;
        }
        pendingSignalKUiData = null;
        if (signalkClient) {
            signalkClient.disconnect();
        }
        updateSignalKStatusBadge('disconnected');
        appendMaintenanceSignalKEvent('SignalK déconnecté');
        if (resetMonitor) {
            signalkLatestTwaDeg = null;
            signalkLatestBaroHpa = null;
            signalkLatestAirTempC = null;
            signalkLatestProbeTempC = null;
            signalkLatestBatteryTempC = null;
            signalkLatestHumidityPct = null;
            signalkLatestAbsHumidityGm3 = null;
            signalkLatestCloudCoverPct = null;
            signalkLatestRainRateMmH = null;
            signalkLatestEngineRpm = null;
            signalkLatestEngineRunning = null;
            signalkLatestLogNm = null;
            resetSignalKJoystickState();
            resetMaintenanceSignalKMonitor();
            renderEngineSensorUi();
            updateEngineAudioRegimeUi();
            updateNavLiveDashboard();
        }
    }

    function startSignalKNavigationLogging() {
        if (signalkLoggingActive) {
            setNavLogStatus(t('Log SignalK déjà actif.', 'Log SignalK ya activo.'));
            return;
        }

        stopPassiveNavigationWatch();
        resetNavAutoLogArming(null);
        navHasCenteredOnFirstFix = false;
        navGpsSessionStartMs = Date.now();
        navGpsSessionStartEntryIndex = navLogEntries.length;
        navGpsSessionStartSampleIndex = Array.isArray(navGpsSessionSamples) ? navGpsSessionSamples.length : 0;
        navGpsSessionHasSample = false;
        signalkLoggingActive = true;
        resetSignalKManagedInputUserEdits();

        if (navGpsSampleTimerId !== null) {
            window.clearInterval(navGpsSampleTimerId);
            navGpsSampleTimerId = null;
        }
        navGpsSampleTimerId = window.setInterval(() => {
            const captured = captureNavGpsSample('signalk');
            if (captured) {
                const pts = getCurrentNavGpsSessionSamples().length;
                setNavLogStatus(t(
                    `SignalK · point capturé · ${pts} point(s)`,
                    `SignalK · punto capturado · ${pts} punto(s)`
                ));
            }
        }, NAV_GPS_SAMPLE_INTERVAL_MS);

        if (!ensureSignalKStreamingConnection({ announce: true })) {
            signalkLoggingActive = false;
            if (navGpsSampleTimerId !== null) {
                window.clearInterval(navGpsSampleTimerId);
                navGpsSampleTimerId = null;
            }
            return;
        }

        if (navGpsLatestFix && !navGpsSessionHasSample) {
            captureNavGpsSample('signalk');
        }

        syncNavLogGpsCompactUi();
        setNavLogStatus(t('SignalK · log actif.', 'SignalK · log activo.'));
    }

    function stopSignalKNavigationLogging(options = {}) {
        const { disconnectStream = false } = options;
        signalkLoggingActive = false;
        if (navGpsSampleTimerId !== null) {
            window.clearInterval(navGpsSampleTimerId);
            navGpsSampleTimerId = null;
        }
        if (disconnectStream) {
            stopSignalKStreamingConnection({ resetMonitor: true });
        }
    }

    function initSignalKUi() {
        const modeAutoButtons = [
            document.getElementById('signalkModeAutoBtn'),
            document.getElementById('maintenanceSignalKModeAutoBtn')
        ].filter(Boolean);
        const modeSkButtons = [
            document.getElementById('signalkModeSkBtn'),
            document.getElementById('maintenanceSignalKModeSkBtn')
        ].filter(Boolean);
        const hostInputs = [
            document.getElementById('signalkHostInput'),
            document.getElementById('maintenanceSignalKHostInput')
        ].filter(Boolean);
        const autoLogToggles = [
            document.getElementById('signalkAutoLogToggle'),
            document.getElementById('maintenanceSignalKAutoLogToggle')
        ].filter(Boolean);
        const connectButtons = [
            document.getElementById('signalkConnectBtn'),
            document.getElementById('maintenanceSignalKConnectBtn')
        ].filter(Boolean);
        const disconnectButtons = [
            document.getElementById('maintenanceSignalKDisconnectBtn')
        ].filter(Boolean);

        if (!modeAutoButtons.length || !modeSkButtons.length || !hostInputs.length || !connectButtons.length) return;

        // Restore saved config
        loadSignalKConfig();
        hostInputs.forEach(input => {
            input.value = signalkConfig.host;
        });
        syncSignalKAutoLogControls();
        _applySignalKModeButtons();

        maintenanceSignalKStats = {
            updates: 0,
            weather: 0,
            positions: 0,
            wind: 0,
            engine: 0,
            lastWeatherTick: 0
        };
        initDashboardThresholdUi();
        resetMaintenanceSignalKMonitor();

        const eventsContainer = document.getElementById('maintenanceSignalKEvents');
        if (eventsContainer && !eventsContainer.children.length) {
            eventsContainer.innerHTML = '<div class="signalk-monitor-event signalk-monitor-event--muted">Aucun événement SignalK pour le moment.</div>';
        }

        modeAutoButtons.forEach(button => {
            if (button.dataset.skBound === '1') return;
            button.dataset.skBound = '1';
            button.addEventListener('click', () => {
                signalkConfig.mode = 'auto';
                saveSignalKConfig();
                _applySignalKModeButtons();
                stopSignalKNavigationLogging({ disconnectStream: true });
                resetNavAutoLogArming(navGpsLatestFix);
                startPassiveNavigationWatch();
                updateSignalKStatusBadge('disconnected');
                setNavLogStatus(
                    isSignalKAutoLogEnabled()
                        ? t(
                            `Mode autonome activé · auto-log armé (> ${NAV_AUTO_LOG_START_DISTANCE_M} m).`,
                            `Modo autónomo activado · auto-log armado (> ${NAV_AUTO_LOG_START_DISTANCE_M} m).`
                        )
                        : t(
                            'Mode autonome activé · auto-log désactivé.',
                            'Modo autónomo activado · auto-log desactivado.'
                        )
                );
            });
        });

        modeSkButtons.forEach(button => {
            if (button.dataset.skBound === '1') return;
            button.dataset.skBound = '1';
            button.addEventListener('click', () => {
                stopPassiveNavigationWatch();
                signalkConfig.mode = 'signalk';
                saveSignalKConfig();
                _applySignalKModeButtons();
                resetSignalKManagedInputUserEdits();
                if (signalkConfig.host.trim()) {
                    ensureSignalKStreamingConnection({ announce: true });
                } else {
                    setNavLogStatus(
                        isSignalKAutoLogEnabled()
                            ? t(
                                'Mode SignalK activé. Renseigne l\'adresse du serveur pour armer l\'auto-log.',
                                'Modo SignalK activado. Indica la dirección del servidor para armar el auto-log.'
                            )
                            : t(
                                'Mode SignalK activé. Renseigne l\'adresse du serveur pour afficher le live.',
                                'Modo SignalK activado. Indica la dirección del servidor para mostrar el live.'
                            )
                    );
                }
            });
        });

        autoLogToggles.forEach(toggle => {
            if (toggle.dataset.skBound === '1') return;
            toggle.dataset.skBound = '1';
            toggle.addEventListener('change', () => {
                signalkConfig.autoLogEnabled = toggle.checked;
                saveSignalKConfig();
                resetNavAutoLogArming(navGpsLatestFix);
                syncSignalKAutoLogControls();

                if (activeTabName === 'navlog' && !isNavigationLoggingActive()) {
                    setNavLogStatus(getAutoLogArmedStatusMessage(signalkConfig.mode));
                }
            });
        });

        hostInputs.forEach(input => {
            if (input.dataset.skBound === '1') return;
            input.dataset.skBound = '1';
            input.addEventListener('input', () => {
                signalkConfig.host = input.value.trim();
                hostInputs.forEach(other => {
                    if (other !== input) other.value = signalkConfig.host;
                });
                saveSignalKConfig();
            });
        });

        connectButtons.forEach(button => {
            if (button.dataset.skBound === '1') return;
            button.dataset.skBound = '1';
            button.addEventListener('click', () => {
                signalkConfig.host = (hostInputs[0]?.value || '').trim();
                hostInputs.forEach(input => {
                    input.value = signalkConfig.host;
                });
                saveSignalKConfig();
                if (!signalkConfig.host) {
                    setNavLogStatus(t('SignalK: entrez l\'adresse du serveur.', 'SignalK: ingrese la dirección del servidor.'), true);
                    return;
                }
                resetSignalKManagedInputUserEdits();
                ensureSignalKStreamingConnection({ announce: true });
            });
        });

        disconnectButtons.forEach(button => {
            if (button.dataset.skBound === '1') return;
            button.dataset.skBound = '1';
            button.addEventListener('click', () => {
                stopSignalKNavigationLogging({ disconnectStream: true });
                updateSignalKStatusBadge('disconnected');
                setNavLogStatus(t('SignalK: déconnecté.', 'SignalK: desconectado.'));
            });
        });

        // Manual edits pause SignalK autofill for the targeted field until the next SignalK session/connect.
        ['watchHeadingInput', 'watchWindSpeedInput', 'watchWindDirInput', 'watchBarometerInput', 'watchLogNmInput'].forEach(id => {
            const el = document.getElementById(id);
            if (!el) return;
            el.addEventListener('input', () => { el.dataset.userEdited = '1'; });
        });

        updateSignalKStatusBadge('disconnected');

        if (signalkConfig.mode === 'signalk' && signalkConfig.host.trim() && !signalkLoggingActive) {
            window.setTimeout(() => {
                if (signalkConfig.mode !== 'signalk' || !signalkConfig.host.trim() || signalkLoggingActive) return;
                ensureSignalKStreamingConnection({ announce: true });
            }, 120);
        } else if (signalkConfig.mode === 'auto' && activeTabName === 'navlog') {
            startPassiveNavigationWatch();
        }
    }

    function _applySignalKModeButtons() {
        const modeAutoButtons = [
            document.getElementById('signalkModeAutoBtn'),
            document.getElementById('maintenanceSignalKModeAutoBtn')
        ].filter(Boolean);
        const modeSkButtons = [
            document.getElementById('signalkModeSkBtn'),
            document.getElementById('maintenanceSignalKModeSkBtn')
        ].filter(Boolean);
        const skPanel      = document.getElementById('signalkSkPanel');
        const motionBtn    = document.getElementById('requestMotionPermissionBtn');
        if (!modeAutoButtons.length || !modeSkButtons.length) return;
        const isAuto = signalkConfig.mode === 'auto';
        modeAutoButtons.forEach(btn => btn.classList.toggle('signalk-mode-btn--active', isAuto));
        modeSkButtons.forEach(btn => btn.classList.toggle('signalk-mode-btn--active', !isAuto));
        if (skPanel) skPanel.style.display = isAuto ? 'none' : '';
        // Capteur inclinaison iPad inutile en mode SignalK (le gîte vient du serveur)
        if (motionBtn) motionBtn.style.display = isAuto ? '' : 'none';

        const modeValue = document.getElementById('maintenanceSignalKModeValue');
        if (modeValue) modeValue.textContent = isAuto ? t('Auto iPad', 'Auto iPad') : 'SignalK';
    }

    // ============================================================
    // END SIGNALK INTEGRATION
    // ============================================================


function stopNavigationLogging(options = {}) {
    const { createAutoSessionSummary = true } = options;
    const lastKnownFix = cloneNavFixForAutoLog(navGpsLatestFix);

    // Stop active logging session while keeping passive monitoring alive.
    if (signalkConfig.mode === 'signalk') {
        stopSignalKNavigationLogging({ disconnectStream: false });
    }

    if (navWatchId !== null && navigator.geolocation) {
        navigator.geolocation.clearWatch(navWatchId);
        navWatchId = null;
    }

    syncNavLogGpsCompactUi();

    if (navGpsSampleTimerId !== null) {
        window.clearInterval(navGpsSampleTimerId);
        navGpsSampleTimerId = null;
    }

    if (createAutoSessionSummary) {
        captureNavGpsSample('gps-watch');
    }

    let summary = null;
    if (createAutoSessionSummary) {
        summary = appendAutoNavSessionSummaryEntry();
    }

    if (summary) {
        navSelectedTraceEntryId = String(summary.entryId || '');
        renderNavLogList();
        renderNavGpsTraceOnMap();
        const selectedEntry = getNavLogEntryById(navSelectedTraceEntryId);
        if (selectedEntry) {
            focusNavTraceEntriesOnMap(getNavTraceEntriesForEntry(selectedEntry));
        }
        setNavLogStatus(t(
            `Log GPS arrêté · session enregistrée (${summary.points} points, ${summary.distance.toFixed(2)} NM). Clique la ligne du journal pour revoir la trace.`,
            `Log GPS detenido · sesión guardada (${summary.points} puntos, ${summary.distance.toFixed(2)} NM). Toca la línea del diario para reabrir la traza.`
        ));
    } else {
        setNavLogStatus(t(`Log GPS arrêté · ${navLogEntries.length} point(s) enregistrés.`, `Log GPS detenido · ${navLogEntries.length} punto(s) guardado(s).`));
    }

    signalkLoggingActive = false;
    navGpsLatestFix = lastKnownFix;
    navGpsSessionStartMs = 0;
    navGpsSessionStartEntryIndex = navLogEntries.length;
    navGpsSessionStartSampleIndex = Array.isArray(navGpsSessionSamples) ? navGpsSessionSamples.length : 0;
    navGpsSessionHasSample = false;
    navHasCenteredOnFirstFix = false;
    resetNavAutoLogArming(lastKnownFix);

    if (signalkConfig.mode === 'auto') {
        startPassiveNavigationWatch();
    } else if (signalkConfig.mode === 'signalk' && signalkConfig.host.trim()) {
        ensureSignalKStreamingConnection({ announce: false });
    }

    syncNavLogGpsCompactUi();
}

function clearNavigationLogbook() {
    stopNavigationLogging({ createAutoSessionSummary: false });
    navLogEntries = [];
    navGpsSessionSamples = [];
    navGpsSessionStartSampleIndex = 0;
    navLatestSpeedKn = null;
    navLatestHeelDeg = null;
    navLatestCourseDeg = null;
    editingNavLogEntryId = null;
    navSelectedTraceEntryId = '';
    logWorkspaceMode = 'none';
    resetNavLogEditorForm();
    updateNavLogFormMode();
    saveNavLogEntries();
    saveNavGpsTraceSamples();
    renderNavLogList();
    renderLogWorkspacePanel();
    setNavLogStatus(t('Journal navigation effacé.', 'Diario de navegación borrado.'));
    updateNavLiveDashboard();
}

function loadNavigationLogbook() {
    navLogEntries = sanitizeNavLogEntriesList(loadArrayFromStorage(NAV_LOG_STORAGE_KEY));
    loadNavGpsTraceSamples();
    loadAnchorDragAlarmState();
    navGpsSessionStartSampleIndex = Array.isArray(navGpsSessionSamples) ? navGpsSessionSamples.length : 0;
    editingNavLogEntryId = null;
    navSelectedTraceEntryId = '';
    logWorkspaceMode = 'none';
    updateNavLogFormMode();
    const watchTimeInput = document.getElementById('watchTimeInput');
    if (watchTimeInput) {
        watchTimeInput.value = toLocalDateTimeInputValue(new Date());
    }
    loadNavChecklistState();
    loadNavSwellProfile();
    if (navGpsLatestFix) {
        updateNavCurrentPositionMarker(navGpsLatestFix);
    }
    setActiveNavChecklistMode(activeNavChecklistMode);
    renderNavLogList();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
    syncNavLogGpsCompactUi();
}

function openNavLogCreateForm() {
    editingNavLogEntryId = null;
    navSelectedTraceEntryId = '';
    resetNavLogEditorForm();
    logWorkspaceMode = 'nav';
    updateNavLogFormMode();
    renderNavLogList();
    renderLogWorkspacePanel();
    updateNavLiveDashboard();
}

function openEngineLogCreateForm() {
    editingEngineLogEntryId = null;
    engineLogDraftStartProbeTempC = Number.isFinite(signalkLatestProbeTempC) ? signalkLatestProbeTempC : null;
    const hoursInput = document.getElementById('engineHoursInput');
    const fuelInput = document.getElementById('fuelAddedInput');
    const noteInput = document.getElementById('engineLogNoteInput');
    if (hoursInput) hoursInput.value = '';
    if (fuelInput) fuelInput.value = '';
    if (noteInput) noteInput.value = '';
    refreshEngineHoursInputGuard();
    logWorkspaceMode = 'engine';
    updateEngineLogFormMode();
    renderEngineLogList();
    renderLogWorkspacePanel();
}

function renderEngineLogTemperatureFields() {
    const startInput = document.getElementById('engineTempStartInput');
    const endInput = document.getElementById('engineTempEndInput');
    if (!startInput && !endInput) return;

    const editedEntry = editingEngineLogEntryId
        ? engineLogEntries.find(entry => String(entry?.id || '') === String(editingEngineLogEntryId))
        : null;
    const startTemp = editedEntry
        ? Number(editedEntry?.probeTempStartC)
        : Number(engineLogDraftStartProbeTempC);
    const endTemp = editedEntry
        ? Number(editedEntry?.probeTempEndC)
        : Number(signalkLatestProbeTempC);

    if (startInput) startInput.value = formatTemperatureC(startTemp, '');
    if (endInput) endInput.value = formatTemperatureC(endTemp, '');
}

function getEngineLogPreviousEntry(entryId) {
    const safeEntries = sanitizeEngineLogEntriesList(engineLogEntries);
    if (!safeEntries.length) return null;

    const targetId = String(entryId || '').trim();
    if (!targetId) {
        return safeEntries[safeEntries.length - 1] || null;
    }

    const currentIndex = safeEntries.findIndex(entry => String(entry?.id || '') === targetId);
    if (currentIndex <= 0) return null;
    return safeEntries[currentIndex - 1] || null;
}

function refreshEngineHoursInputGuard() {
    const hoursInput = document.getElementById('engineHoursInput');
    if (!hoursInput) return;

    const previousEntry = getEngineLogPreviousEntry(editingEngineLogEntryId);
    if (!previousEntry || !Number.isFinite(previousEntry.hours)) {
        hoursInput.removeAttribute('min');
        hoursInput.title = '';
        return;
    }

    // HTML min cannot express strict ">"; strict check is enforced in JS on save.
    hoursInput.min = String(previousEntry.hours);
    hoursInput.title = t(
        `Doit être supérieur à ${previousEntry.hours.toFixed(1)} h`,
        `Debe ser superior a ${previousEntry.hours.toFixed(1)} h`
    );
}

function saveEngineLogEntries() {
    saveArrayToStorage(ENGINE_LOG_STORAGE_KEY, engineLogEntries);
    scheduleCloudLogbookPush({ includeNav: false, includeEngine: true });
}

function renderLogWorkspacePanel() {
    const panel = document.getElementById('logWorkspacePanel');
    const title = document.getElementById('logWorkspaceTitle');
    const placeholder = document.getElementById('logWorkspacePlaceholder');
    const navPanel = document.getElementById('navLogEditorPanel');
    const enginePanel = document.getElementById('engineLogEditorPanel');
    if (!panel || !title || !placeholder || !navPanel || !enginePanel) return;

    const navVisible = logWorkspaceMode === 'nav';
    const engineVisible = logWorkspaceMode === 'engine';
    const shouldShowPanel = (activeTabName === 'navlog')
        || (activeTabName === 'maintenance' && activeMaintenanceSubtab === 'engine');

    panel.style.display = shouldShowPanel ? 'block' : 'none';
    panel.classList.toggle('log-workspace-panel--nav-compact', activeTabName === 'navlog');

    navPanel.style.display = navVisible ? 'block' : 'none';
    enginePanel.style.display = engineVisible ? 'block' : 'none';
    placeholder.style.display = navVisible || engineVisible ? 'none' : 'flex';

    if (navVisible) {
        updateNavLogFormMode();
        title.textContent = editingNavLogEntryId
            ? t('Modifier entrée de navigation', 'Editar entrada de navegación')
            : t('Créer entrée de navigation', 'Crear entrada de navegación');
    } else if (engineVisible) {
        title.textContent = editingEngineLogEntryId
            ? t('Modifier entrée moteur', 'Editar entrada de motor')
            : t('Créer entrée moteur', 'Crear entrada de motor');
        renderEngineLogTemperatureFields();
    } else {
        title.textContent = t('Saisie journal', 'Edición diario');
    }

        applyNavLogLayoutState();
    renderNavChecklist();
    updateNavLiveDashboard();
}

function updateEngineLogFormMode() {
    const saveBtn = document.getElementById('saveEngineLogBtn');
    const cancelBtn = document.getElementById('cancelEngineLogEditBtn');

    if (saveBtn) {
        saveBtn.textContent = editingEngineLogEntryId
            ? t('Mettre à jour entrée moteur', 'Actualizar entrada motor')
            : t('Ajouter entrée moteur', 'Añadir entrada motor');
    }

    if (cancelBtn) {
        cancelBtn.style.display = editingEngineLogEntryId ? '' : 'none';
    }
}

function cancelEngineLogEdit() {
    editingEngineLogEntryId = null;
    engineLogDraftStartProbeTempC = null;

    const hoursInput = document.getElementById('engineHoursInput');
    const fuelInput = document.getElementById('fuelAddedInput');
    const noteInput = document.getElementById('engineLogNoteInput');
    if (hoursInput) hoursInput.value = '';
    if (fuelInput) fuelInput.value = '';
    if (noteInput) noteInput.value = '';
    refreshEngineHoursInputGuard();

    if (logWorkspaceMode === 'engine') {
        logWorkspaceMode = 'none';
    }

    updateEngineLogFormMode();
    renderEngineLogList();
    renderLogWorkspacePanel();
}

function startEditEngineLogEntry(entryId) {
    const targetId = String(entryId || '');
    const entry = engineLogEntries.find(item => String(item?.id || '') === targetId);
    if (!entry) return;

    const hoursInput = document.getElementById('engineHoursInput');
    const fuelInput = document.getElementById('fuelAddedInput');
    const noteInput = document.getElementById('engineLogNoteInput');
    if (!hoursInput || !fuelInput || !noteInput) return;

    editingEngineLogEntryId = targetId;
    engineLogDraftStartProbeTempC = null;
    hoursInput.value = Number.isFinite(entry?.hours) ? String(entry.hours) : '';
    fuelInput.value = Number.isFinite(entry?.fuelAddedL) ? String(entry.fuelAddedL) : '';
    noteInput.value = String(entry?.note || '');
    refreshEngineHoursInputGuard();
    logWorkspaceMode = 'engine';

    updateEngineLogFormMode();
    renderEngineLogList();
    renderLogWorkspacePanel();
}

function renderEngineLogList() {
    const container = document.getElementById('engineLogList');
    if (!container) return;

    if (!Array.isArray(engineLogEntries) || engineLogEntries.length === 0) {
        container.innerHTML = `<div class="log-card">${t('Aucune entrée moteur pour le moment.', 'No hay entradas de motor por ahora.')}</div>`;
        return;
    }

    container.innerHTML = '';

    const headerRow = document.createElement('div');
    headerRow.className = 'log-list-header';
    headerRow.innerHTML =
        `<span>${t('Date', 'Fecha')}</span>` +
        `<span>${t('Auteur', 'Autor')}</span>` +
        `<span>${t('Compteur', 'Contador')}</span>` +
        `<span>${t('Temp moteur', 'Temp motor', 'Engine temp')}</span>`;
    container.appendChild(headerRow);

    engineLogEntries
        .slice()
        .reverse()
        .forEach(entry => {
            const creator = String(entry?.creatorName || '').trim() || String(entry?.creatorEmail || '').trim() || 'N/A';
            const hours = Number.isFinite(entry?.hours) ? `${entry.hours.toFixed(1)} h` : 'N/A';
            const tempStart = Number(entry?.probeTempStartC);
            const tempEnd = Number(entry?.probeTempEndC);
            const tempRange = `${formatTemperatureC(tempStart)} -> ${formatTemperatureC(tempEnd)}`;

            const row = document.createElement('div');
            row.className = 'log-list-row';
            if (editingEngineLogEntryId && String(entry?.id || '') === editingEngineLogEntryId) {
                row.classList.add('log-list-row--active');
            }

            const summaryRow = document.createElement('div');
            summaryRow.className = 'log-list-summary';
            summaryRow.innerHTML =
                `<span class="log-list-col">${escapeHtml(formatDateTimeFr(entry?.timestamp))}</span>` +
                `<span class="log-list-col">${escapeHtml(creator)}</span>` +
                `<span class="log-list-col">${escapeHtml(hours)}</span>` +
                `<span class="log-list-col">${escapeHtml(tempRange)}</span>`;
            summaryRow.addEventListener('click', () => {
                startEditEngineLogEntry(String(entry?.id || ''));
            });

            row.appendChild(summaryRow);
            container.appendChild(row);
        });
}

function addEngineLogEntryFromForm() {
    const hoursInput = document.getElementById('engineHoursInput');
    const fuelInput = document.getElementById('fuelAddedInput');
    const noteInput = document.getElementById('engineLogNoteInput');

    const hours = parseFloat(String(hoursInput?.value || ''));
    const fuelAddedL = parseFloat(String(fuelInput?.value || ''));
    const note = String(noteInput?.value || '').trim();

    if (!Number.isFinite(hours)) {
        alert(t('Renseigne le compteur moteur (heures).', 'Introduce el contador motor (horas).'));
        return;
    }

    const previousEntry = getEngineLogPreviousEntry(editingEngineLogEntryId);
    if (previousEntry && Number.isFinite(previousEntry.hours) && !(hours > previousEntry.hours)) {
        alert(t(
            `Le compteur moteur doit être strictement supérieur à l'entrée précédente (${previousEntry.hours.toFixed(1)} h).`,
            `El contador motor debe ser estrictamente superior a la entrada anterior (${previousEntry.hours.toFixed(1)} h).`
        ));
        return;
    }

    const nextValues = {
        hours,
        fuelAddedL: Number.isFinite(fuelAddedL) ? Math.max(0, fuelAddedL) : 0,
        note
    };

    if (editingEngineLogEntryId) {
        let updated = false;
        engineLogEntries = engineLogEntries.map(entry => {
            if (String(entry?.id || '') !== editingEngineLogEntryId) return entry;
            updated = true;
            return ensureCreatorOnEditedRecord({
                ...entry,
                ...nextValues
            });
        });

        if (!updated) {
            editingEngineLogEntryId = null;
        }
    } else {
        const probeTempStartC = Number.isFinite(engineLogDraftStartProbeTempC) ? engineLogDraftStartProbeTempC : null;
        const probeTempEndC = Number.isFinite(signalkLatestProbeTempC) ? signalkLatestProbeTempC : null;
        engineLogEntries.push({
            id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            timestamp: new Date().toISOString(),
            creatorEmail: getCreatorPatch().creatorEmail,
            creatorName: getCreatorPatch().creatorName,
            probeTempStartC,
            probeTempEndC,
            ...nextValues
        });

        if (engineLogEntries.length > 800) {
            engineLogEntries = engineLogEntries.slice(engineLogEntries.length - 800);
        }
    }

    saveEngineLogEntries();
    renderEngineLogList();
    cancelEngineLogEdit();
}

function loadEngineLogbook() {
    engineLogEntries = [];
    loadEngineSoundSnapshots();
    renderEngineLogList();
    cancelEngineLogEdit();
    renderEngineSensorUi();
}

function ensureWeatherFocusMarker() {
    if (!map || weatherFocusMarker) return;

    const icon = L.divIcon({
        className: 'weather-focus-icon',
        html: '<div class="weather-focus-icon__dot"></div>',
        iconSize: [18, 18],
        iconAnchor: [9, 9]
    });

    weatherFocusMarker = L.marker([0, 0], {
        icon,
        keyboard: false,
        interactive: false,
        zIndexOffset: 1400
    });
}

function setWeatherPointerPlacementMode(enabled) {
    weatherPointerPlacementMode = Boolean(enabled);
    if (!map) return;

    const shouldUseCrosshair = weatherPointerPlacementMode && activeTabName === 'weather' && !measureModeEnabled;
    map.getContainer().style.cursor = shouldUseCrosshair ? 'crosshair' : '';

    const status = document.getElementById('weatherOutlookStatus');
    if (status && weatherPointerPlacementMode) {
        status.textContent = t('Météo: clique sur la carte pour placer le pointeur.', 'Meteo: haz clic en el mapa para colocar el puntero.');
    }
}

function setWeatherFocusPoint(latlng, { refresh = true, sourceLabel = t('pointeur carte', 'puntero mapa') } = {}) {
    if (!Number.isFinite(latlng?.lat) || !Number.isFinite(latlng?.lng)) return;

    weatherFocusPoint = { lat: latlng.lat, lng: latlng.lng };
    invalidateWeatherDiagnostic(t('Analyse synoptique: point changé, relance l\'analyse.', 'Análisis sinóptico: punto cambiado, vuelve a lanzar el análisis.', 'Synoptic analysis: point changed, run it again.'));
    ensureWeatherFocusMarker();
    if (weatherFocusMarker) {
        weatherFocusMarker.setLatLng([weatherFocusPoint.lat, weatherFocusPoint.lng]);
        if (!map.hasLayer(weatherFocusMarker)) {
            weatherFocusMarker.addTo(map);
        }
    }

    const status = document.getElementById('weatherOutlookStatus');
    if (status) {
        status.textContent = `${t('Météo', 'Meteo')}: ${sourceLabel} (${weatherFocusPoint.lat.toFixed(4)}, ${weatherFocusPoint.lng.toFixed(4)})`;
    }

    if (refresh) {
        refreshWeatherOutlook();
    }
}

function computeWeatherImpactLabel(weather) {
    const wind = Number(weather?.windSpeed);
    const wave = Number(weather?.waveHeight);
    const current = Number(weather?.currentSpeedKnots);

    if ((Number.isFinite(wind) && wind > 24) || (Number.isFinite(wave) && wave > 2.3) || (Number.isFinite(current) && current > 1.8)) {
        return { text: t('À risque', 'Con riesgo'), className: 'weather-card weather-card--risk' };
    }
    if ((Number.isFinite(wind) && wind > 18) || (Number.isFinite(wave) && wave > 1.6) || (Number.isFinite(current) && current > 1.0)) {
        return { text: t('Modéré', 'Moderado'), className: 'weather-card' };
    }
    return { text: t('Favorable', 'Favorable'), className: 'weather-card weather-card--ok' };
}

function getWeatherReferenceCoordinates(forceMapCenter = false) {
    if (map && forceMapCenter) {
        const center = map.getCenter();
        return { lat: center.lat, lng: center.lng, source: t('centre carte', 'centro mapa') };
    }

    if (weatherFocusPoint && Number.isFinite(weatherFocusPoint.lat) && Number.isFinite(weatherFocusPoint.lng)) {
        return { lat: weatherFocusPoint.lat, lng: weatherFocusPoint.lng, source: t('pointeur météo', 'puntero meteo') };
    }

    if (routePoints.length > 0) {
        const last = routePoints[routePoints.length - 1];
        return { lat: last.lat, lng: last.lng, source: t('dernier waypoint', 'último waypoint') };
    }

    if (map) {
        const center = map.getCenter();
        return { lat: center.lat, lng: center.lng, source: t('centre carte', 'centro mapa') };
    }

    return null;
}

function buildWeatherAnalysisListHtml(items) {
    if (!Array.isArray(items) || !items.length) return '';
    return `<ul class="weather-analysis-list">${items.map(item => `<li>${escapeHtml(String(item || ''))}</li>`).join('')}</ul>`;
}

function buildWeatherIndicatorListHtml(items) {
    if (!Array.isArray(items) || !items.length) return '';
    return `<ul class="weather-stage-indicators">${items.map(item => `<li>${escapeHtml(String(item || ''))}</li>`).join('')}</ul>`;
}

function normalizeWeatherStageBadgeClass(status) {
    const value = String(status || '').toLowerCase();
    if (value === 'active') return 'weather-regime-badge weather-regime-badge--active';
    if (value === 'watch') return 'weather-regime-badge weather-regime-badge--watch';
    return 'weather-regime-badge weather-regime-badge--quiet';
}

function normalizeCorsicaStageBadgeClass(status) {
    const value = String(status || '').toLowerCase();
    if (value === 'active') return 'weather-corsica-badge weather-corsica-badge--active';
    if (value === 'watch') return 'weather-corsica-badge weather-corsica-badge--watch';
    return 'weather-corsica-badge weather-corsica-badge--quiet';
}

function formatWeatherStageBadgeLabel(status) {
    const value = String(status || '').toLowerCase();
    if (value === 'active') return t('Actif', 'Activo', 'Active');
    if (value === 'watch') return t('À surveiller', 'Vigilar', 'Watch');
    return t('Calme', 'Calma', 'Quiet');
}

function renderWeatherCenterStage(payload) {
    const stage = document.getElementById('weatherCenterStage');
    if (!stage) return;

    const isWeather = activeTabName === 'weather';
    if (!isWeather || !payload || typeof payload !== 'object' || weatherCenterStageDismissed) {
        stage.innerHTML = '';
        stage.style.display = 'none';
        return;
    }

    const regimeMatrix = Array.isArray(payload.regime_matrix) ? payload.regime_matrix : [];
    const corsicaSubregions = Array.isArray(payload.corsica_subregions) ? payload.corsica_subregions : [];
    const corsicaRelays = Array.isArray(payload.corsica_regional_relays) ? payload.corsica_regional_relays : [];

    const regimeHtml = regimeMatrix.length
        ? `<div class="weather-center-stage__section">
                <strong class="weather-center-stage__section-title">${t('Tableau des régimes', 'Tabla de regímenes', 'Regime matrix')}</strong>
                <div class="weather-regime-grid">${regimeMatrix.map(item => `
                    <article class="weather-regime-card">
                        <div class="weather-regime-card__head">
                            <strong>${escapeHtml(String(item?.label || ''))}</strong>
                            <span class="${normalizeWeatherStageBadgeClass(item?.status)}">${escapeHtml(formatWeatherStageBadgeLabel(item?.status))}</span>
                        </div>
                        <div class="weather-regime-card__summary">${escapeHtml(String(item?.summary || ''))}</div>
                        <div class="weather-stage-confidence">${t('Confiance', 'Confianza', 'Confidence')}: ${escapeHtml(String(item?.confidence || 'n/a'))}</div>
                        ${buildWeatherIndicatorListHtml(item?.indicators)}
                    </article>`).join('')}</div>
            </div>`
        : '';

    const corsicaHtml = corsicaSubregions.length
        ? `<div class="weather-center-stage__section">
                <strong class="weather-center-stage__section-title">${t('Zoom Corse', 'Zoom Córcega', 'Corsica focus')}</strong>
                <div class="weather-corsica-grid">${corsicaSubregions.map(item => `
                    <article class="weather-corsica-card">
                        <div class="weather-corsica-card__head">
                            <strong>${escapeHtml(String(item?.label || ''))}</strong>
                            <span class="${normalizeCorsicaStageBadgeClass(item?.status)}">${escapeHtml(formatWeatherStageBadgeLabel(item?.status))}</span>
                        </div>
                        <div class="weather-corsica-card__summary">${escapeHtml(String(item?.summary || ''))}</div>
                        <div class="weather-stage-confidence">${t('Confiance', 'Confianza', 'Confidence')}: ${escapeHtml(String(item?.confidence || 'n/a'))}</div>
                        ${buildWeatherIndicatorListHtml(item?.indicators)}
                    </article>`).join('')}</div>
            </div>`
        : '';

    const corsicaRelaysHtml = corsicaRelays.length
        ? `<div class="weather-center-stage__section">
                <strong class="weather-center-stage__section-title">${t('Relais Ligurie / Sardaigne / Tyrrhénienne', 'Relés Liguria / Cerdeña / Tirreno', 'Ligurian / Sardinian / Tyrrhenian relays')}</strong>
                ${buildWeatherAnalysisListHtml(corsicaRelays)}
            </div>`
        : '';

    stage.innerHTML = `
        <button type="button" class="weather-center-stage__close" id="weatherCenterStageCloseBtn" aria-label="${escapeHtml(t('Fermer', 'Cerrar', 'Close'))}">${escapeHtml(t('Fermer', 'Cerrar', 'Close'))}</button>
        <div class="weather-center-stage__title">
            <div>
                <strong>${escapeHtml(String(payload.focus_region || t('Zone analysée', 'Zona analizada', 'Analyzed area')))}</strong>
                <div class="weather-center-stage__subtitle">${escapeHtml(String(payload.headline || ''))}</div>
            </div>
            <div class="weather-center-stage__title-actions">
                <div class="weather-center-stage__subtitle">${escapeHtml(String(payload.generated_at_label || ''))}</div>
            </div>
        </div>
        ${regimeHtml}
        ${corsicaHtml}
        ${corsicaRelaysHtml}`;
    const closeBtn = document.getElementById('weatherCenterStageCloseBtn');
    if (closeBtn) {
        closeBtn.addEventListener('click', closeWeatherCenterStage, { once: true });
    }
    stage.style.display = regimeHtml || corsicaHtml || corsicaRelaysHtml ? 'block' : 'none';
}

function renderWeatherDiagnostic(payload) {
    const panel = document.getElementById('weatherDiagnosticPanel');
    if (!panel) return;

    if (!payload || typeof payload !== 'object') {
        panel.innerHTML = '';
        return;
    }

    const metrics = payload.metrics || {};
    const sections = [
        {
            title: t('Faits générateurs', 'Hechos generadores', 'Generating factors'),
            items: payload.generating_factors
        },
        {
            title: t('Pourquoi maintenant', 'Por qué ahora', 'Why now'),
            items: payload.mechanisms
        },
        {
            title: t('Régimes Méditerranée ouest', 'Regímenes Mediterráneo oeste', 'Western Mediterranean regimes'),
            items: payload.regional_regimes
        },
        {
            title: t('Relais Corse bassin proche', 'Relés Córcega cuenca cercana', 'Corsica nearby-basin relays'),
            items: payload.corsica_regional_relays
        },
        {
            title: t('Évolution 2–7 jours', 'Evolución 2–7 días', 'Evolution 2–7 days'),
            items: payload.day_outlook
        },
        {
            title: t('Contexte climatologique', 'Contexto climatológico', 'Climatology context'),
            items: payload.climate_context
        },
        {
            title: t('Relais régionaux / atlantiques', 'Relés regionales / atlánticos', 'Regional / Atlantic relays'),
            items: payload.remote_signals
        },
        {
            title: t('Limites', 'Límites', 'Limits'),
            items: payload.limitations
        }
    ].filter(section => Array.isArray(section.items) && section.items.length);

    const metaHtml = `
        <div class="weather-analysis-meta">
            <div class="weather-analysis-chip"><strong>${t('Confiance', 'Confianza', 'Confidence')}</strong>${escapeHtml(String(payload.confidence || 'n/a'))}</div>
            <div class="weather-analysis-chip"><strong>${t('Généré', 'Generado', 'Generated')}</strong>${escapeHtml(String(payload.generated_at_label || payload.generated_at || 'n/a'))}</div>
            <div class="weather-analysis-chip"><strong>${t('Vent actuel', 'Viento actual', 'Current wind')}</strong>${escapeHtml(String(metrics.current_wind || 'n/a'))}</div>
            <div class="weather-analysis-chip"><strong>${t('Pression', 'Presión', 'Pressure')}</strong>${escapeHtml(String(metrics.current_pressure || 'n/a'))}</div>
        </div>`;

    const sectionsHtml = sections.map(section => `
        <div class="weather-card">
            <strong class="weather-analysis-section-title">${escapeHtml(section.title)}</strong>
            ${buildWeatherAnalysisListHtml(section.items)}
        </div>`).join('');

    const commandHtml = payload.command_hint
        ? `<div class="weather-analysis-command">${escapeHtml(String(payload.command_hint))}</div>`
        : '';

    panel.innerHTML = `
        <div class="weather-card weather-card--ok">
            <strong>${escapeHtml(String(payload.headline || t('Analyse synoptique', 'Análisis sinóptico', 'Synoptic analysis')))}</strong><br>
            ${escapeHtml(String(payload.summary || ''))}
            ${metaHtml}
        </div>
        ${sectionsHtml}
        ${commandHtml}`;

    lastWeatherDiagnosticPayload = payload;
    weatherCenterStageDismissed = false;
    renderWeatherCenterStage(payload);
}

async function requestWeatherDiagnostic(lat, lon, horizonDays) {
    const response = await fetch(`${LOCAL_WEATHER_ANALYSIS_API_URL}/weather/analyze`, {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            lat,
            lon,
            horizon_days: Math.max(2, Math.min(7, Number(horizonDays) || 3)),
            language: currentLanguage
        })
    });

    if (!response.ok) {
        const raw = await response.text();
        throw new Error(raw || `HTTP ${response.status}`);
    }

    return response.json();
}

async function refreshWeatherDiagnostic() {
    const status = document.getElementById('weatherDiagnosticStatus');
    const panel = document.getElementById('weatherDiagnosticPanel');
    const focus = getWeatherReferenceCoordinates(false);

    if (!status || !panel) return;
    if (!focus) {
        status.textContent = t('Analyse synoptique: coordonnées indisponibles.', 'Análisis sinóptico: coordenadas no disponibles.', 'Synoptic analysis: coordinates unavailable.');
        panel.innerHTML = '';
        renderWeatherCenterStage(null);
        return;
    }

    status.textContent = `${t('Analyse synoptique', 'Análisis sinóptico', 'Synoptic analysis')}: ${t('chargement', 'cargando', 'loading')} (${focus.lat.toFixed(4)}, ${focus.lng.toFixed(4)})...`;
    lastWeatherDiagnosticPayload = null;
    weatherCenterStageDismissed = false;
    panel.innerHTML = '';
    renderWeatherCenterStage(null);

    try {
        const payload = await requestWeatherDiagnostic(focus.lat, focus.lng, forecastWindowDays);
        renderWeatherDiagnostic(payload);
        status.textContent = `${t('Analyse synoptique', 'Análisis sinóptico', 'Synoptic analysis')}: ${focus.source} (${focus.lat.toFixed(4)}, ${focus.lng.toFixed(4)})`;
    } catch (error) {
        const commandHint = 'cd /Users/maxpatissier/Downloads/ceibo && /Users/maxpatissier/Downloads/ceibo/.venv/bin/python weather/server.py --host 127.0.0.1 --port 8777';
        lastWeatherDiagnosticPayload = null;
        renderWeatherCenterStage(null);
        status.textContent = t(
            'Analyse synoptique indisponible: démarre le serveur météo local.',
            'Análisis sinóptico no disponible: inicia el servidor meteo local.',
            'Synoptic analysis unavailable: start the local weather server.'
        );
        panel.innerHTML = `
            <div class="weather-card weather-card--risk">
                <strong>${t('Serveur météo local requis', 'Servidor meteo local requerido', 'Local weather server required')}</strong><br>
                ${escapeHtml(String(error?.message || error || 'Erreur inconnue'))}
                <div class="weather-analysis-command">${escapeHtml(commandHint)}</div>
            </div>`;
    }
}

async function refreshWeatherOutlook({ forceMapCenter = false } = {}) {
    const status = document.getElementById('weatherOutlookStatus');
    const list = document.getElementById('weatherOutlookList');
    if (!status || !list) return;

    const focus = getWeatherReferenceCoordinates(forceMapCenter);
    if (!focus) {
        status.textContent = t('Météo: coordonnées indisponibles.', 'Meteo: coordenadas no disponibles.');
        return;
    }

    status.textContent = `${t('Météo', 'Meteo')}: ${t('chargement', 'cargando')} (${focus.source})...`;

    try {
        if (forceMapCenter && map) {
            const center = map.getCenter();
            setWeatherFocusPoint(center, { refresh: false, sourceLabel: t('centre carte', 'centro mapa') });
        }

        const current = await getCurrentWeatherAtWaypoint(focus.lat, focus.lng);

        const dayOffsets = [1, 2, 3];
        const forecastEntries = [];

        for (const offset of dayOffsets) {
            const target = new Date();
            target.setUTCDate(target.getUTCDate() + offset);
            target.setUTCHours(12, 0, 0, 0);
            const slot = toDateAndHourUtc(target);
            const weather = await getWeatherAtDateHour(focus.lat, focus.lng, slot.date, slot.hour);
            forecastEntries.push({ slot, weather });
        }

        const nowImpact = computeWeatherImpactLabel(current);
        const nowWind = formatWindKnotsWithBeaufort(current?.windSpeed);
        const nowWave = Number.isFinite(current?.waveHeight) ? `${current.waveHeight.toFixed(1)} m` : 'N/A';
        const nowCurrent = Number.isFinite(current?.currentSpeedKnots) ? `${current.currentSpeedKnots.toFixed(1)} kn` : 'N/A';
        const nowCurrentDirection = Number.isFinite(current?.oceanCurrentDirection) ? `${Math.round(current.oceanCurrentDirection)}° ${degreesToCardinalFr(current.oceanCurrentDirection)}` : 'N/A';
        const nowSeaTemp = Number.isFinite(current?.seaSurfaceTemperature) ? `${current.seaSurfaceTemperature.toFixed(1)}°C` : 'N/A';
        const nowTemp = Number.isFinite(current?.temperature) ? `${current.temperature.toFixed(1)}°C` : 'N/A';
        const nowPressure = Number.isFinite(current?.pressure) ? `${current.pressure.toFixed(0)} hPa` : 'N/A';
        const nowGust = formatWindKnotsWithBeaufort(current?.windGust);

        const weatherSeries = [current, ...forecastEntries.map(entry => entry.weather)];
        const tempEvolution = buildWeatherMetricEvolutionSummary(weatherSeries.map(entry => entry?.temperature), {
            unit: '°C',
            decimals: 1,
            riseThreshold: 0.8,
            fallThreshold: -0.8
        });
        const seaTempEvolution = buildWeatherMetricEvolutionSummary(weatherSeries.map(entry => entry?.seaSurfaceTemperature), {
            unit: '°C',
            decimals: 1,
            riseThreshold: 0.6,
            fallThreshold: -0.6
        });
        const pressureEvolution = buildWeatherMetricEvolutionSummary(weatherSeries.map(entry => entry?.pressure), {
            unit: ' hPa',
            decimals: 0,
            riseThreshold: 1.2,
            fallThreshold: -1.2
        });

        const forecastHtml = forecastEntries.map(entry => {
            const impact = computeWeatherImpactLabel(entry.weather);
            const wind = formatWindKnotsWithBeaufort(entry.weather?.windSpeed);
            const wave = Number.isFinite(entry.weather?.waveHeight) ? `${entry.weather.waveHeight.toFixed(1)} m` : 'N/A';
            const dir = Number.isFinite(entry.weather?.windDirection) ? `${Math.round(entry.weather.windDirection)}° ${degreesToCardinalFr(entry.weather.windDirection)}` : 'N/A';
            const rain = Number.isFinite(entry.weather?.precipitation) ? `${entry.weather.precipitation.toFixed(1)} mm` : 'N/A';
            const temp = Number.isFinite(entry.weather?.temperature) ? `${entry.weather.temperature.toFixed(1)}°C` : 'N/A';
            const seaTemp = Number.isFinite(entry.weather?.seaSurfaceTemperature) ? `${entry.weather.seaSurfaceTemperature.toFixed(1)}°C` : 'N/A';
            const pressure = Number.isFinite(entry.weather?.pressure) ? `${entry.weather.pressure.toFixed(0)} hPa` : 'N/A';
            const currentSpeed = Number.isFinite(entry.weather?.currentSpeedKnots) ? `${entry.weather.currentSpeedKnots.toFixed(1)} kn` : 'N/A';
            const currentDir = Number.isFinite(entry.weather?.oceanCurrentDirection) ? `${Math.round(entry.weather.oceanCurrentDirection)}° ${degreesToCardinalFr(entry.weather.oceanCurrentDirection)}` : 'N/A';
            return `<div class="${impact.className}"><strong>${entry.slot.date} · 12:00 UTC</strong><br>${t('Impact nav', 'Impacto nav')}: ${impact.text}<br>${t('Temp', 'Temp')}: ${temp} · ${t('Temp mer', 'Temp mar', 'Sea temp')}: ${seaTemp} · ${t('Pression', 'Presión')}: ${pressure}<br>${t('Vent', 'Viento')}: ${wind} (${dir}) · ${t('Rafales', 'Ráfagas')}: ${formatWindKnotsWithBeaufort(entry.weather?.windGust)}<br>${t('Houle', 'Oleaje')}: ${wave} · ${t('Courant', 'Corriente', 'Current')}: ${currentSpeed} (${currentDir}) · ${t('Pluie', 'Lluvia')}: ${rain}</div>`;
        }).join('');

        list.innerHTML =
            `<div class="${nowImpact.className}"><strong>${t('Conditions actuelles', 'Condiciones actuales')}</strong><br>${t('Impact nav', 'Impacto nav')}: ${nowImpact.text}<br>${t('Temp', 'Temp')}: ${nowTemp} · ${t('Temp mer', 'Temp mar', 'Sea temp')}: ${nowSeaTemp} · ${t('Pression', 'Presión')}: ${nowPressure}<br>${t('Vent', 'Viento')}: ${nowWind} · ${t('Rafales', 'Ráfagas')}: ${nowGust}<br>${t('Houle', 'Oleaje')}: ${nowWave}<br>${t('Courant', 'Corriente', 'Current')}: ${nowCurrent} (${nowCurrentDirection})</div>` +
            `<div class="weather-card"><strong>${t('Évolution actuelle → J+3', 'Evolución actual → D+3')}</strong><br>${t('Température', 'Temperatura')}: ${tempEvolution}<br>${t('Temp mer', 'Temp mar', 'Sea temp')}: ${seaTempEvolution}<br>${t('Pression', 'Presión')}: ${pressureEvolution}</div>` +
            forecastHtml;

        status.textContent = `${t('Météo', 'Meteo')}: ${focus.source} (${focus.lat.toFixed(4)}, ${focus.lng.toFixed(4)})`;
    } catch (_error) {
        status.textContent = t('Météo: impossible de récupérer les prévisions.', 'Meteo: no se pueden recuperar las previsiones.');
        list.innerHTML = '';
    }
}

function maybeBootstrapWeatherOutlook() {
    if (weatherOutlookBootstrapped) return;
    weatherOutlookBootstrapped = true;
    void refreshWeatherOutlook();
}

function maybeBootstrapOwmKeyValidation() {
    if (owmKeyValidationBootstrapped) return;
    owmKeyValidationBootstrapped = true;

    const storedOwmKey = getStoredOpenWeatherTileAppId();
    if (!storedOwmKey) return;

    const owmApiKeyStatus = document.getElementById('owmApiKeyStatus');
    if (owmApiKeyStatus) owmApiKeyStatus.textContent = t('Clé OWM: validation en cours...', 'Clave OWM: validación en curso...');

    testOpenWeatherApiKey(storedOwmKey).then(async result => {
        const isobarTileResult = result.ok ? await testOpenWeatherTileAccessAny(storedOwmKey, ['pressure_new', 'pressure']) : null;
        const cloudTileResult = result.ok ? await testOpenWeatherTileAccessAny(storedOwmKey, ['clouds_new', 'clouds', { version: '2.0', code: 'CL' }]) : null;
        const tempTileResult = result.ok ? await testOpenWeatherTileAccessAny(storedOwmKey, ['temp_new', 'temp', { version: '2.0', code: 'TA2' }]) : null;
        const windTileResult = result.ok ? await testOpenWeatherTileAccessAny(storedOwmKey, ['wind_new', 'wind', { version: '2.0', code: 'WND' }]) : null;

        if (owmApiKeyStatus) {
            if (result.ok && isobarTileResult?.ok && cloudTileResult?.ok && tempTileResult?.ok && windTileResult?.ok) {
                owmApiKeyStatus.textContent = `${t('Clé OWM', 'Clave OWM')}: ✅ ${result.message} · ${t('Isobares+Nuages+Temp+Vent OK', 'Isobaras+Nubes+Temp+Viento OK', 'Isobars+Clouds+Temp+Wind OK')}`;
            } else if (result.ok) {
                const detail = [
                    isobarTileResult?.ok ? t('Isobares OK', 'Isobaras OK', 'Isobars OK') : t('Isobares KO', 'Isobaras KO', 'Isobars KO'),
                    cloudTileResult?.ok ? t('Nuages OK', 'Nubes OK', 'Clouds OK') : t('Nuages KO', 'Nubes KO', 'Clouds KO'),
                    tempTileResult?.ok ? t('Temp OK', 'Temp OK', 'Temp OK') : t('Temp KO', 'Temp KO', 'Temp KO'),
                    windTileResult?.ok ? t('Vent OK', 'Viento OK', 'Wind OK') : t('Vent KO', 'Viento KO', 'Wind KO')
                ].join(' · ');
                owmApiKeyStatus.textContent = `${t('Clé OWM', 'Clave OWM')}: ⚠️ ${result.message} · ${detail}`;
            } else {
                owmApiKeyStatus.textContent = `${t('Clé OWM', 'Clave OWM')}: ❌ ${result.message}`;
            }
        }
    }).catch(() => {
        if (owmApiKeyStatus) owmApiKeyStatus.textContent = t('Clé OWM: test impossible.', 'Clave OWM: prueba imposible.');
    });
}

