    const voyageAgendaContent = document.getElementById('voyageAgendaContent');
    if (voyageAgendaContent) {
        voyageAgendaContent.addEventListener('mousedown', event => {
            const resizeHandle = event.target.closest('[data-voyage-resize-handle]');
            if (!resizeHandle || !selectedVoyagePlanId) return;

            const itemElement = resizeHandle.closest('.voyage-calendar-item[data-voyage-map-item-id]');
            const dropZone = resizeHandle.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            const itemId = String(itemElement?.getAttribute('data-voyage-map-item-id') || '');
            const plan = getSelectedVoyagePlan();
            const timelineEntry = computeVoyagePlanTimeline(plan).find(entry => entry.id === itemId && entry.type === 'stop');
            if (!itemElement || !dropZone || !itemId || !timelineEntry?.departure) return;

            event.preventDefault();
            event.stopPropagation();
            activeVoyageMapItemId = itemId;
            activeVoyageCalendarResize = {
                planId: selectedVoyagePlanId,
                itemId,
                startDateTime: timelineEntry.departure,
                dropZone,
                itemElement,
                handleElement: resizeHandle
            };
            itemElement.classList.add('is-resizing');
        });

        document.addEventListener('mousemove', event => {
            if (!activeVoyageCalendarResize) return;
            const previewDateTime = getVoyageCalendarResizeTargetDateTime(activeVoyageCalendarResize.startDateTime, activeVoyageCalendarResize.dropZone, event.clientX);
            const durationDays = getVoyageCalendarDurationDaysFromPointer(activeVoyageCalendarResize.startDateTime, activeVoyageCalendarResize.dropZone, event.clientX);
            const widthPct = getVoyageCalendarResizeWidthPct(activeVoyageCalendarResize.startDateTime, durationDays, activeVoyageCalendarResize.dropZone);
            if (!Number.isFinite(widthPct)) return;
            activeVoyageCalendarResize.itemElement.style.width = `${widthPct.toFixed(2)}%`;
            updateVoyageCalendarHandleLabel(activeVoyageCalendarResize.handleElement, previewDateTime);
        });

        document.addEventListener('mouseup', event => {
            if (!activeVoyageCalendarResize) return;

            const { planId, itemId, startDateTime, dropZone, itemElement } = activeVoyageCalendarResize;
            const durationDays = getVoyageCalendarDurationDaysFromPointer(startDateTime, dropZone, event.clientX);
            const targetDepartureDateTime = getVoyageCalendarResizeTargetDateTime(startDateTime, dropZone, event.clientX);
            activeVoyageCalendarResize = null;
            itemElement.classList.remove('is-resizing');

            if (!Number.isFinite(durationDays) || !(targetDepartureDateTime instanceof Date) || Number.isNaN(targetDepartureDateTime.getTime())) {
                renderVoyageAgendaPanel();
                return;
            }

            updateVoyagePlanItemField(planId, itemId, 'stopDepartureDateTime', formatDateTimeLocalInputValue(targetDepartureDateTime));
            renderVoyageAgendaPanel();
            setVoyagePlanStatus(t('Départ du mouillage mis à jour.', 'Salida del fondeo actualizada.', 'Anchorage departure updated.'));
        });

        voyageAgendaContent.addEventListener('dragstart', event => {
            if (event.target.closest('[data-voyage-resize-handle]') || activeVoyageCalendarResize) {
                event.preventDefault();
                return;
            }
            const agendaEventTarget = event.target.closest('.voyage-calendar-item[data-agenda-event-id]');
            if (agendaEventTarget) {
                const eventId = String(agendaEventTarget.getAttribute('data-agenda-event-id') || '');
                if (!eventId) return;
                draggedAgendaEventId = eventId;
                agendaEventTarget.classList.add('is-dragging');
                if (event.dataTransfer) {
                    event.dataTransfer.effectAllowed = 'move';
                    event.dataTransfer.setData('text/plain', eventId);
                }
                return;
            }
            const itemTarget = event.target.closest('.voyage-calendar-item[data-voyage-map-item-id]');
            if (!itemTarget) return;
            if (itemTarget.getAttribute('draggable') !== 'true') {
                event.preventDefault();
                return;
            }
            const itemId = String(itemTarget.getAttribute('data-voyage-map-item-id') || '');
            if (!itemId) return;
            draggedVoyageCalendarItemId = itemId;
            activeVoyageMapItemId = itemId;
            itemTarget.classList.add('is-dragging');
            if (event.dataTransfer) {
                event.dataTransfer.effectAllowed = 'move';
                event.dataTransfer.setData('text/plain', itemId);
            }
        });

        voyageAgendaContent.addEventListener('dragover', event => {
            const dropZone = event.target.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            if (!dropZone || (!draggedVoyageCalendarItemId && !draggedAgendaEventId)) return;
            event.preventDefault();
            if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
            dropZone.classList.add('is-drop-target');
            if (draggedAgendaEventId) return;
            const previewDateTime = getDateTimeFromVoyageCalendarDropTarget(dropZone, event.clientX);
            const draggedItem = voyageAgendaContent.querySelector(`.voyage-calendar-item[data-voyage-map-item-id="${CSS.escape(draggedVoyageCalendarItemId)}"]`);
            updateVoyageCalendarHandleLabel(draggedItem?.querySelector('.voyage-calendar-item__drag-handle'), previewDateTime);
        });

        voyageAgendaContent.addEventListener('dragleave', event => {
            const dropZone = event.target.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            if (!dropZone) return;
            const relatedTarget = event.relatedTarget instanceof Element ? event.relatedTarget : null;
            if (relatedTarget && dropZone.contains(relatedTarget)) return;
            dropZone.classList.remove('is-drop-target');
        });

        voyageAgendaContent.addEventListener('dragend', event => {
            draggedVoyageCalendarItemId = '';
            draggedAgendaEventId = '';
            const itemNode = event.target.closest('.voyage-calendar-item');
            itemNode?.classList.remove('is-dragging');
            updateVoyageCalendarHandleLabel(itemNode?.querySelector('.voyage-calendar-item__drag-handle'), getSelectedVoyagePlan() ? computeVoyagePlanTimeline(getSelectedVoyagePlan()).find(entry => entry.id === itemNode?.getAttribute('data-voyage-map-item-id'))?.departure : null);
            voyageAgendaContent.querySelectorAll('.voyage-calendar-week__body.is-drop-target').forEach(node => node.classList.remove('is-drop-target'));
        });

        voyageAgendaContent.addEventListener('drop', event => {
            const dropZone = event.target.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            if (!dropZone || (!draggedVoyageCalendarItemId && !draggedAgendaEventId)) return;
            event.preventDefault();
            dropZone.classList.remove('is-drop-target');

            if (draggedAgendaEventId) {
                const draggedEvent = agendaEvents.find(entry => entry.id === draggedAgendaEventId) || null;
                const droppedDateTime = getDateTimeFromVoyageCalendarDropTarget(dropZone, event.clientX);
                draggedAgendaEventId = '';
                voyageAgendaContent.querySelectorAll('.voyage-calendar-item.is-dragging').forEach(node => node.classList.remove('is-dragging'));
                if (!draggedEvent || !(droppedDateTime instanceof Date) || Number.isNaN(droppedDateTime.getTime())) return;
                const currentStart = parseDateTimeLocalValue(draggedEvent.startDateTime);
                const currentEnd = parseDateTimeLocalValue(draggedEvent.endDateTime);
                if (!(currentStart instanceof Date) || !(currentEnd instanceof Date)) return;
                const durationMs = Math.max(VOYAGE_AGENDA_TIME_STEP_MINUTES * 60 * 1000, currentEnd.getTime() - currentStart.getTime());
                const nextEnd = new Date(droppedDateTime.getTime() + durationMs);
                if (!updateAgendaEventTiming(draggedEvent.id, droppedDateTime, nextEnd)) return;
                renderVoyageAgendaPanel();
                setAgendaEventStatus(t('Évènement déplacé dans l’agenda.', 'Evento movido en el calendario.', 'Event moved in the calendar.'));
                return;
            }

            if (!selectedVoyagePlanId || !draggedVoyageCalendarItemId) return;

            const plan = getSelectedVoyagePlan();
            const draggedItem = plan?.items.find(item => item.id === draggedVoyageCalendarItemId) || null;
            if (!draggedItem || draggedItem.id !== getEditableVoyageRouteItemId(plan)) {
                draggedVoyageCalendarItemId = '';
                return;
            }
            const droppedDateTime = getDateTimeFromVoyageCalendarDropTarget(dropZone, event.clientX);
            const nextValue = formatDateTimeLocalInputValue(droppedDateTime);

            draggedVoyageCalendarItemId = '';
            voyageAgendaContent.querySelectorAll('.voyage-calendar-item.is-dragging').forEach(node => node.classList.remove('is-dragging'));

            if (!nextValue) return;

            updateVoyagePlanItemField(selectedVoyagePlanId, draggedItem.id, 'departureDateTime', nextValue);
            renderVoyageAgendaPanel();
            setVoyagePlanStatus(t('Agenda déplacé: horaires recalculés.', 'Agenda movido: horarios recalculados.', 'Agenda moved: schedule recalculated.'));
        });

        voyageAgendaContent.addEventListener('click', event => {
            const detailTabTarget = event.target.closest('[data-voyage-detail-tab]');
            if (detailTabTarget) {
                setActiveVoyageDetailTab(detailTabTarget.getAttribute('data-voyage-detail-tab') || 'itinerary');
                renderVoyageAgendaPanel();
                return;
            }

            const foodActionTarget = event.target.closest('[data-voyage-food-action]');
            if (foodActionTarget) {
                const action = String(foodActionTarget.getAttribute('data-voyage-food-action') || '');
                const planId = String(foodActionTarget.getAttribute('data-voyage-plan-id') || selectedVoyagePlanId || '');
                const provisioningId = String(foodActionTarget.getAttribute('data-voyage-provisioning-id') || '');
                const budgetId = String(foodActionTarget.getAttribute('data-voyage-budget-id') || '');
                if (action === 'generate-meals' && planId) regenerateVoyageMealPlan(planId);
                if (action === 'generate-provisioning' && planId) regenerateVoyageProvisioning(planId);
                if (action === 'seed-monthly' && planId) seedVoyageMonthlyEssentials(planId);
                if (action === 'add-provisioning' && planId) addVoyageProvisioningItem(planId);
                if (action === 'delete-provisioning' && planId && provisioningId) removeVoyageProvisioningItem(planId, provisioningId);
                if (action === 'add-budget' && planId) addVoyageBudgetItem(planId);
                if (action === 'delete-budget' && planId && budgetId) removeVoyageBudgetItem(planId, budgetId);
                return;
            }

            const voyageDocumentActionTarget = event.target.closest('[data-voyage-document-action]');
            if (voyageDocumentActionTarget) {
                const action = String(voyageDocumentActionTarget.getAttribute('data-voyage-document-action') || '');
                const planId = String(voyageDocumentActionTarget.getAttribute('data-voyage-plan-id') || selectedVoyagePlanId || '');
                const documentId = String(voyageDocumentActionTarget.getAttribute('data-voyage-document-id') || '');
                if (action === 'save-github-settings') saveVoyageDocumentGithubSettingsFromSection();
                if (action === 'upload' && planId) void saveVoyageDocumentFromSection(planId);
                if (action === 'open' && planId && documentId) void openVoyageDocumentForViewing(planId, documentId);
                if (action === 'delete' && planId && documentId) void deleteVoyageDocumentFromSection(planId, documentId);
                return;
            }

            const mapActionTarget = event.target.closest('[data-voyage-map-action]');
            if (mapActionTarget) {
                const action = String(mapActionTarget.getAttribute('data-voyage-map-action') || '');
                if (action === 'toggle-calendar') {
                    isVoyageCalendarVisible = !isVoyageCalendarVisible;
                    renderVoyageAgendaPanel();
                }
                if (action === 'toggle-weather') {
                    isVoyageWeatherVisible = !isVoyageWeatherVisible;
                    renderVoyageAgendaPanel();
                }
                if (action === 'toggle-expand') {
                    isVoyageMapExpanded = !isVoyageMapExpanded;
                    renderVoyageAgendaPanel();
                }
                return;
            }

            const overviewNavTarget = event.target.closest('[data-voyage-overview-nav]');
            if (overviewNavTarget) {
                const action = String(overviewNavTarget.getAttribute('data-voyage-overview-nav') || '');
                if (action === 'prev-week') {
                    voyageOverviewReferenceDate = addDays(voyageOverviewReferenceDate instanceof Date ? voyageOverviewReferenceDate : new Date(), -7);
                }
                if (action === 'today') {
                    voyageOverviewReferenceDate = startOfLocalDay(new Date()) || new Date();
                }
                if (action === 'next-week') {
                    voyageOverviewReferenceDate = addDays(voyageOverviewReferenceDate instanceof Date ? voyageOverviewReferenceDate : new Date(), 7);
                }
                renderVoyageAgendaPanel();
                return;
            }

            const overviewWeekBodyTarget = event.target.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            if (overviewWeekBodyTarget && !event.target.closest('.voyage-calendar-item, button, input, select, textarea, label, a')) {
                const clickedDateTime = getDateTimeFromVoyageCalendarDropTarget(overviewWeekBodyTarget, event.clientX);
                clearAgendaEventCalendarPrefillTimer();
                agendaEventCalendarPrefillTimer = setTimeout(() => {
                    agendaEventCalendarPrefillTimer = null;
                    prefillAgendaEventDraftFromDate(clickedDateTime);
                }, 220);
                return;
            }

            const agendaEventActionTarget = event.target.closest('[data-agenda-event-action]');
            if (agendaEventActionTarget) {
                const action = String(agendaEventActionTarget.getAttribute('data-agenda-event-action') || '');
                const eventId = String(agendaEventActionTarget.getAttribute('data-agenda-event-id') || '');
                if (action === 'edit' && eventId) {
                    selectedAgendaEventId = eventId;
                    clearAgendaEventDraft();
                    renderVoyageAgendaPanel();
                    setAgendaEventStatus(t('Évènement chargé dans l’éditeur.', 'Evento cargado en el editor.', 'Event loaded in the editor.'));
                }
                if (action === 'delete' && eventId) {
                    selectedAgendaEventId = eventId;
                    clearAgendaEventDraft();
                    deleteSelectedAgendaEvent();
                }
                return;
            }

            const agendaEventEditorActionTarget = event.target.closest('[data-agenda-event-editor-action]');
            if (agendaEventEditorActionTarget) {
                const action = String(agendaEventEditorActionTarget.getAttribute('data-agenda-event-editor-action') || '');
                if (action === 'save') upsertAgendaEventFromEditor();
                if (action === 'new') resetAgendaEventEditor();
                if (action === 'delete') deleteSelectedAgendaEvent();
                return;
            }

            const agendaEventDurationTarget = event.target.closest('[data-agenda-event-duration]');
            if (agendaEventDurationTarget) {
                setAgendaEventDefaultDurationMs(agendaEventDurationTarget.getAttribute('data-agenda-event-duration'));
                renderVoyageAgendaPanel();
                setAgendaEventStatus(t('Durée par défaut mise à jour.', 'Duración por defecto actualizada.', 'Default duration updated.'));
                return;
            }

            const agendaEventTimeAdjustTarget = event.target.closest('[data-agenda-event-time-adjust]');
            if (agendaEventTimeAdjustTarget) {
                const prefix = String(agendaEventTimeAdjustTarget.getAttribute('data-agenda-event-time-adjust') || '');
                const deltaMinutes = Number(agendaEventTimeAdjustTarget.getAttribute('data-agenda-event-time-delta') || 0);
                if ((prefix === 'Start' || prefix === 'End') && Number.isFinite(deltaMinutes)) {
                    shiftAgendaEventEditorDateTime(prefix, deltaMinutes);
                }
                return;
            }

            const planActionTarget = event.target.closest('[data-voyage-plan-action]');
            if (planActionTarget) {
                const action = String(planActionTarget.getAttribute('data-voyage-plan-action') || '');
                const planId = String(planActionTarget.getAttribute('data-voyage-plan-id') || '');
                if (action === 'select') {
                    clearVoyagePlanEditorDraft();
                    isVoyageCalendarVisible = false;
                    isVoyageOverviewCalendarVisible = false;
                    selectedVoyagePlanId = planId;
                    activeVoyageMapItemId = '';
                    syncVoyagePlanEditorUi();
                    renderVoyageAgendaPanel();
                    setVoyagePlanStatus(t('Voyage chargé dans l\'éditeur.', 'Viaje cargado en el editor.', 'Trip loaded in editor.'));
                }
                return;
            }

            const itemActionTarget = event.target.closest('[data-voyage-item-action]');
            if (itemActionTarget) {
                const planId = String(itemActionTarget.getAttribute('data-voyage-plan-id') || '');
                const itemId = String(itemActionTarget.getAttribute('data-voyage-item-id') || '');
                const action = String(itemActionTarget.getAttribute('data-voyage-item-action') || '');
                if (planId && itemId) {
                    if (action === 'delete') deleteVoyagePlanItem(planId, itemId);
                    if (action === 'move-up') moveVoyagePlanItem(planId, itemId, 'up');
                    if (action === 'move-down') moveVoyagePlanItem(planId, itemId, 'down');
                    if (action === 'save-stop-waypoint') saveVoyageStopAsWaypoint(planId, itemId);
                }
                return;
            }

            const mapItemTarget = event.target.closest('[data-voyage-map-item-id]');
            if (mapItemTarget && !event.target.closest('button, input, select, textarea, label, a')) {
                const itemId = String(mapItemTarget.getAttribute('data-voyage-map-item-id') || '');
                if (itemId && itemId !== activeVoyageMapItemId) {
                    activeVoyageMapItemId = itemId;
                    renderVoyageAgendaPanel();
                }
                return;
            }

            const actionTarget = event.target.closest('[data-voyage-action]');
            if (!actionTarget) return;

            const routeIndex = Number(actionTarget.getAttribute('data-route-index'));
            if (!Number.isInteger(routeIndex) || routeIndex < 0) return;

            const action = String(actionTarget.getAttribute('data-voyage-action') || '');
            loadRoute(routeIndex);

            if (action === 'open-routing') {
                activateTab('routing');
                void computeRoute();
                return;
            }

            activateTab('routes');
        });

        voyageAgendaContent.addEventListener('dblclick', event => {
            const overviewWeekBodyTarget = event.target.closest('.voyage-calendar-week__body[data-voyage-week-start]');
            if (!overviewWeekBodyTarget || event.target.closest('.voyage-calendar-item, button, input, select, textarea, label, a')) return;
            clearAgendaEventCalendarPrefillTimer();
            const clickedDateTime = getDateTimeFromVoyageCalendarDropTarget(overviewWeekBodyTarget, event.clientX);
            if (createAgendaEventFromDate(clickedDateTime)) {
                event.preventDefault();
            }
        });

        voyageAgendaContent.addEventListener('change', event => {
            if (event.target.id === 'voyageDocumentFileInput') {
                readVoyageDocumentDraftFromDom(selectedVoyagePlanId);
                return;
            }
            const target = event.target.closest('[data-voyage-item-field]');
            if (!target) {
                const mealFieldTarget = event.target.closest('[data-voyage-meal-field]');
                if (mealFieldTarget) {
                    updateVoyageMealEntryField(
                        String(mealFieldTarget.getAttribute('data-voyage-plan-id') || ''),
                        String(mealFieldTarget.getAttribute('data-voyage-meal-id') || ''),
                        String(mealFieldTarget.getAttribute('data-voyage-meal-field') || ''),
                        mealFieldTarget.value
                    );
                    return;
                }

                const provisioningFieldTarget = event.target.closest('[data-voyage-provisioning-field]');
                if (provisioningFieldTarget) {
                    updateVoyageProvisioningItemField(
                        String(provisioningFieldTarget.getAttribute('data-voyage-plan-id') || ''),
                        String(provisioningFieldTarget.getAttribute('data-voyage-provisioning-id') || ''),
                        String(provisioningFieldTarget.getAttribute('data-voyage-provisioning-field') || ''),
                        provisioningFieldTarget instanceof HTMLInputElement && provisioningFieldTarget.type === 'checkbox'
                            ? provisioningFieldTarget.checked
                            : provisioningFieldTarget.value
                    );
                    return;
                }

                const budgetFieldTarget = event.target.closest('[data-voyage-budget-field]');
                if (budgetFieldTarget) {
                    updateVoyageBudgetItemField(
                        String(budgetFieldTarget.getAttribute('data-voyage-plan-id') || ''),
                        String(budgetFieldTarget.getAttribute('data-voyage-budget-id') || ''),
                        String(budgetFieldTarget.getAttribute('data-voyage-budget-field') || ''),
                        budgetFieldTarget.value
                    );
                    return;
                }

                if (event.target.closest('[data-agenda-event-field]')) {
                    if (event.target.id === 'agendaEventStartDateInput' || event.target.id === 'agendaEventStartTimeInput') {
                        syncAgendaEventEndWithStartEditor();
                    }
                    agendaEventDraftState = readAgendaEventEditorDraftFromDom();
                }
                return;
            }
            const field = String(target.getAttribute('data-voyage-item-field') || '');
            const planId = String(target.getAttribute('data-voyage-plan-id') || '');
            const itemId = String(target.getAttribute('data-voyage-item-id') || '');
            if (!field || !planId || !itemId) return;
            updateVoyagePlanItemField(planId, itemId, field, target.value);
            setVoyagePlanStatus(t('Planning mis à jour.', 'Planificación actualizada.', 'Schedule updated.'));
        });

        voyageAgendaContent.addEventListener('input', event => {
            if (event.target.id === 'voyageDocumentTitleInput' || event.target.id === 'voyageDocumentDescriptionInput') {
                readVoyageDocumentDraftFromDom(selectedVoyagePlanId);
                return;
            }
            if (!event.target.closest('[data-agenda-event-field]')) return;
            if (event.target.id === 'agendaEventStartDateInput' || event.target.id === 'agendaEventStartTimeInput') {
                syncAgendaEventEndWithStartEditor();
            }
            agendaEventDraftState = readAgendaEventEditorDraftFromDom();
        });
    }

