function buildMaintenanceBoardsFromCloudRows(schemaRows, pinRows) {
    const safeSchemaRows = Array.isArray(schemaRows) ? schemaRows : [];
    const safePinRows = Array.isArray(pinRows) ? pinRows : [];
    const pinsBySchemaId = new Map();

    safePinRows.forEach((row, index) => {
        const schemaId = String(row?.schema_id || '').trim();
        if (!schemaId) return;
        if (!pinsBySchemaId.has(schemaId)) {
            pinsBySchemaId.set(schemaId, []);
        }

        const pin = {
            id: String(row?.id || `maintenance-ann-${Date.now()}-${index}`),
            xPercent: Number(row?.x_percent),
            yPercent: Number(row?.y_percent),
            colorKey: String(row?.color_key || 'red'),
            statusKey: String(row?.status_key || 'active'),
            legend: String(row?.legend || '').trim(),
            performedDate: String(row?.performed_on || '').trim(),
            createdAt: String(row?.created_at || new Date().toISOString())
        };

        pinsBySchemaId.get(schemaId).push(pin);
    });

    return safeSchemaRows
        .map((row, index) => {
            const boardId = String(row?.id || `maintenance-${Date.now()}-${index}`);
            const board = sanitizeMaintenanceBoard({
                id: boardId,
                name: String(row?.name || ''),
                imageDataUrl: String(row?.image_data_url || ''),
                annotations: pinsBySchemaId.get(boardId) || [],
                creatorEmail: String(row?.creator_email || ''),
                creatorName: String(row?.creator_name || ''),
                createdAt: String(row?.created_at || new Date().toISOString()),
                updatedAt: String(row?.updated_at || new Date().toISOString())
            }, index);

            board.annotations.sort((a, b) => String(a.createdAt || '').localeCompare(String(b.createdAt || '')));
            return board;
        })
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
}

async function pullMaintenanceBoardsFromCloudV2() {
    if (!isCloudReady()) {
        throw new Error('Cloud non pret: impossible de lire maintenance_schemas/maintenance_pins.');
    }

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) {
        throw new Error('creator_email manquant: impossible de lire maintenance_schemas/maintenance_pins.');
    }

    const resolvedProjectIdUuid = await resolveCloudProjectIdUuid();

    let schemasQuery = cloudClient
        .from(CLOUD_MAINTENANCE_SCHEMAS_TABLE)
        .select('*')
        .order('updated_at', { ascending: false });

    let pinsQuery = cloudClient
        .from(CLOUD_MAINTENANCE_PINS_TABLE)
        .select('*')
        .order('created_at', { ascending: true });

    if (isUuidString(resolvedProjectIdUuid)) {
        schemasQuery = schemasQuery.eq('project_id', resolvedProjectIdUuid);
        pinsQuery = pinsQuery.eq('project_id', resolvedProjectIdUuid);
    }

    const [{ data: schemaRows, error: schemaError }, { data: pinRows, error: pinError }] = await Promise.all([
        schemasQuery,
        pinsQuery
    ]);

    if (schemaError) throw schemaError;
    if (pinError) throw pinError;

    return buildMaintenanceBoardsFromCloudRows(schemaRows, pinRows);
}

async function pushMaintenanceBoardsToCloudV2(boards) {
    if (!isCloudReady()) {
        throw new Error('Cloud non pret: impossible d\'inserer maintenance_schemas/maintenance_pins.');
    }

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) {
        throw new Error('creator_email manquant: impossible d\'inserer maintenance_schemas/maintenance_pins.');
    }

    let resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    if (!resolvedProjectIdUuid) {
        throw new Error('project_id introuvable pour maintenance_schemas/maintenance_pins.');
    }
    resolvedProjectIdUuid = await ensureCloudProjectRow(resolvedProjectIdUuid);

    const safeBoards = (Array.isArray(boards) ? boards : [])
        .map((board, index) => sanitizeMaintenanceBoard(board, index));
    const nowIso = new Date().toISOString();

    const { data: existingSchemaRows, error: existingSchemaError } = await cloudClient
        .from(CLOUD_MAINTENANCE_SCHEMAS_TABLE)
        .select('id')
        .eq('project_id', resolvedProjectIdUuid)
        .eq('creator_email', creatorEmail);
    if (existingSchemaError) throw existingSchemaError;

    const localSchemaIds = new Set(safeBoards.map(board => String(board.id || '').trim()).filter(Boolean));
    const remoteSchemaIds = new Set(
        (Array.isArray(existingSchemaRows) ? existingSchemaRows : [])
            .map(row => String(row?.id || '').trim())
            .filter(Boolean)
    );

    const schemaIdsToDelete = [...remoteSchemaIds].filter(schemaId => !localSchemaIds.has(schemaId));
    if (schemaIdsToDelete.length > 0) {
        // Never update schemas: deletion is explicit and cascades to pins.
        const { error: deleteSchemasError } = await cloudClient
            .from(CLOUD_MAINTENANCE_SCHEMAS_TABLE)
            .delete()
            .in('id', schemaIdsToDelete)
            .eq('project_id', resolvedProjectIdUuid)
            .eq('creator_email', creatorEmail);
        if (deleteSchemasError) throw deleteSchemasError;
    }

    const schemaPayload = safeBoards
        .filter(board => {
            const boardId = String(board.id || '').trim();
            return boardId && !remoteSchemaIds.has(boardId);
        })
        .map(board => ({
        id: String(board.id || `maintenance-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`),
        project_id: resolvedProjectIdUuid,
        creator_email: creatorEmail,
        creator_name: board.creatorName || null,
        name: String(board.name || '').trim(),
        image_data_url: String(board.imageDataUrl || ''),
        created_at: board.createdAt || nowIso,
        updated_at: board.updatedAt || nowIso
    }));

    if (schemaPayload.length > 0) {
        const { error: insertSchemasError } = await cloudClient
            .from(CLOUD_MAINTENANCE_SCHEMAS_TABLE)
            .insert(schemaPayload);
        if (insertSchemasError) throw insertSchemasError;
    }

    const localSchemaIdList = [...localSchemaIds];
    if (localSchemaIdList.length > 0) {
        // Pins remain editable: replace pins only for schemas currently in local state.
        const { error: deletePinsError } = await cloudClient
            .from(CLOUD_MAINTENANCE_PINS_TABLE)
            .delete()
            .eq('project_id', resolvedProjectIdUuid)
            .eq('creator_email', creatorEmail)
            .in('schema_id', localSchemaIdList);
        if (deletePinsError) throw deletePinsError;
    }

    const pinPayload = safeBoards.flatMap((board, boardIndex) => {
        const boardId = String(board.id || `maintenance-${Date.now()}-${boardIndex}`);
        return (Array.isArray(board.annotations) ? board.annotations : []).map((annotation, annotationIndex) => {
            const safeX = Number(annotation?.xPercent);
            const safeY = Number(annotation?.yPercent);
            return {
                id: String(annotation?.id || `maintenance-ann-${Date.now()}-${boardIndex}-${annotationIndex}`),
                schema_id: boardId,
                project_id: resolvedProjectIdUuid,
                creator_email: creatorEmail,
                creator_name: board.creatorName || null,
                x_percent: Number.isFinite(safeX) ? Math.max(0, Math.min(100, safeX)) : 0,
                y_percent: Number.isFinite(safeY) ? Math.max(0, Math.min(100, safeY)) : 0,
                color_key: getMaintenanceColorMeta(annotation?.colorKey).key,
                status_key: normalizeMaintenanceTaskStatus(annotation?.statusKey),
                legend: String(annotation?.legend || '').trim(),
                performed_on: String(annotation?.performedDate || '').trim() || null,
                created_at: String(annotation?.createdAt || nowIso),
                updated_at: board.updatedAt || nowIso
            };
        });
    });

    if (!pinPayload.length) {
        return true;
    }

    const { error: insertPinsError } = await cloudClient
        .from(CLOUD_MAINTENANCE_PINS_TABLE)
        .insert(pinPayload);
    if (insertPinsError) throw insertPinsError;

    return true;
}

async function pushRoutesToCloudV2(routes, options = {}) {
    if (!isCloudReady()) return false;

    const { pruneMissing = true } = options || {};

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) return false;

    let resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    if (!resolvedProjectIdUuid) {
        throw new Error('project_id introuvable');
    }

    resolvedProjectIdUuid = await ensureCloudProjectRow(resolvedProjectIdUuid);

    const safeRoutes = Array.isArray(routes)
        ? routes.map((route, index) => sanitizeSavedRoute(route, index))
        : [];

    const { data: existingRouteRows, error: existingRouteError } = await cloudClient
        .from(CLOUD_ROUTES_TABLE)
        .select('id,name')
        .eq('creator_email', creatorEmail);

    if (existingRouteError) throw existingRouteError;

    const canonicalRouteName = value => String(value || '').trim().toLowerCase();
    const existingRows = Array.isArray(existingRouteRows) ? existingRouteRows : [];
    const existingById = new Map();
    const existingByName = new Map();
    const duplicateRouteIdsToDelete = [];

    existingRows.forEach(row => {
        const id = String(row?.id || '').trim();
        if (!id) return;
        existingById.set(id, {
            id,
            name: String(row?.name || '').trim()
        });
        const key = canonicalRouteName(row?.name);
        if (!key) return;

        if (!existingByName.has(key)) {
            existingByName.set(key, {
                id,
                name: String(row?.name || '').trim()
            });
            return;
        }

        // Keep first match and clean duplicated names for deterministic update-by-name behavior.
        duplicateRouteIdsToDelete.push(id);
    });

    const localRouteIds = new Set();

    for (const route of safeRoutes) {
        const routeName = String(route?.name || '').trim();
        if (!routeName) {
            throw new Error('Nom de route vide: synchronisation cloud refusée.');
        }
        const routeNameKey = canonicalRouteName(routeName);
        if (!routeNameKey) {
            throw new Error('Nom de route invalide: synchronisation cloud refusée.');
        }
        const localRouteId = isUuidString(route?.id) ? String(route.id) : '';
        const existingRow = (localRouteId && existingById.get(localRouteId))
            || existingByName.get(routeNameKey)
            || null;
        const routeId = existingRow?.id || localRouteId || generateClientUuid();
        localRouteIds.add(routeId);
        const fallbackUpdatedAt = route.updatedAt || new Date().toISOString();
        const baseRoutePayload = {
            name: routeName,
            departure_date: route.date || null,
            departure_time: route.time || null,
            tacking_time_hours: Number.isFinite(route.tackingTimeHours) ? route.tackingTimeHours : null,
            total_distance_nm: Number.isFinite(route.totalDistanceNm) ? route.totalDistanceNm : null,
            creator_email: route.creatorEmail || creatorEmail,
            creator_name: route.creatorName || null,
            legacy_hash: null,
            legacy_payload: JSON.stringify(buildRouteLegacyPayload(route)),
            created_at: route.createdAt || fallbackUpdatedAt,
            updated_at: fallbackUpdatedAt
        };

        const routePayload = {
            id: routeId,
            project_id: resolvedProjectIdUuid,
            ...baseRoutePayload
        };

        if (existingRow) {
            const { error: updateRouteError } = await cloudClient
                .from(CLOUD_ROUTES_TABLE)
                .update({
                    project_id: routePayload.project_id,
                    ...baseRoutePayload
                })
                .eq('id', routeId);

            if (updateRouteError) throw updateRouteError;
        } else {
            const { error: insertRouteError } = await cloudClient
                .from(CLOUD_ROUTES_TABLE)
                .upsert(routePayload, { onConflict: 'id' });
            if (insertRouteError) throw insertRouteError;
            existingById.set(routeId, { id: routeId, name: routeName });
            existingByName.set(routeNameKey, { id: routeId, name: routeName });
        }

        const points = Array.isArray(route.points) ? route.points : [];
        const pointPayload = points
            .map((point, index) => {
                return {
                    route_id: routeId,
                    seq: index,
                    lat: Number(point?.lat),
                    lon: Number(point?.lon ?? point?.lng),
                    created_at: fallbackUpdatedAt
                };
            })
            .filter(point => Number.isFinite(point.lat) && Number.isFinite(point.lon));

        // Safety: avoid destructive wipe of cloud points when local data is unexpectedly empty.
        if (existingRow && pointPayload.length === 0) {
            continue;
        }

        const { error: deleteExistingPointsError } = await cloudClient
            .from(CLOUD_ROUTE_POINTS_TABLE)
            .delete()
            .eq('route_id', routeId);

        if (deleteExistingPointsError) throw deleteExistingPointsError;

        if (!pointPayload.length) continue;

        const pointsResult = await cloudClient
            .from(CLOUD_ROUTE_POINTS_TABLE)
            .insert(pointPayload);
        if (pointsResult.error) throw pointsResult.error;
    }

    const staleRouteIds = existingRows
        .filter(row => {
            const id = String(row?.id || '').trim();
            if (!id) return false;
            return !localRouteIds.has(id);
        })
        .map(row => String(row?.id || '').trim())
        .filter(Boolean);

    const routeIdsToDelete = [...new Set([...duplicateRouteIdsToDelete, ...staleRouteIds])];

    if (pruneMissing && routeIdsToDelete.length > 0) {
        const { error: deleteStalePointsError } = await cloudClient
            .from(CLOUD_ROUTE_POINTS_TABLE)
            .delete()
            .in('route_id', routeIdsToDelete);
        if (deleteStalePointsError) throw deleteStalePointsError;

        const { error: deleteStaleRoutesError } = await cloudClient
            .from(CLOUD_ROUTES_TABLE)
            .delete()
            .in('id', routeIdsToDelete);
        if (deleteStaleRoutesError) throw deleteStaleRoutesError;
    }

    return true;
}

async function renameRouteInCloudByName(oldName, newName) {
    if (!isCloudReady()) return false;

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) return false;

    const canonicalName = value => String(value || '').trim().toLowerCase();
    const oldNameSafe = String(oldName || '').trim();
    const newNameSafe = String(newName || '').trim();
    if (!oldNameSafe || !newNameSafe) return false;
    if (canonicalName(oldNameSafe) === canonicalName(newNameSafe)) return true;

    let resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    if (!resolvedProjectIdUuid) {
        throw new Error('project_id introuvable');
    }
    resolvedProjectIdUuid = await ensureCloudProjectRow(resolvedProjectIdUuid);

    const { data: rows, error } = await cloudClient
        .from(CLOUD_ROUTES_TABLE)
        .select('id,name')
        .eq('creator_email', creatorEmail)
        .eq('project_id', resolvedProjectIdUuid);

    if (error) throw error;

    const safeRows = Array.isArray(rows) ? rows : [];
    const oldKey = canonicalName(oldNameSafe);
    const newKey = canonicalName(newNameSafe);
    const targetRow = safeRows.find(row => canonicalName(row?.name) === oldKey);
    if (!targetRow?.id) return false;

    const duplicateTarget = safeRows.find(row => String(row?.id || '') !== String(targetRow.id || '') && canonicalName(row?.name) === newKey);
    if (duplicateTarget) {
        throw new Error('Une route cloud avec ce nom existe deja.');
    }

    const { error: updateError } = await cloudClient
        .from(CLOUD_ROUTES_TABLE)
        .update({
            name: newNameSafe,
            updated_at: new Date().toISOString()
        })
        .eq('id', String(targetRow.id));

    if (updateError) throw updateError;
    return true;
}

function buildVoyagePlansFromCloudRows(planRows, itemRows, crewAssignmentRows = []) {
    const itemsByPlanId = new Map();
    const crewIdsByPlanId = new Map();

    (Array.isArray(itemRows) ? itemRows : []).forEach((row, index) => {
        const planId = String(row?.voyage_plan_id || '').trim();
        if (!planId) return;
        if (!itemsByPlanId.has(planId)) {
            itemsByPlanId.set(planId, []);
        }
        itemsByPlanId.get(planId).push({
            seq: Number(row?.seq),
            item: sanitizeVoyagePlanItem({
                id: String(row?.id || `voyage-item-${Date.now()}-${index}`),
                type: String(row?.item_type || 'route').trim(),
                routeId: row?.route_id,
                departureDateTime: row?.departure_date_time,
                startDateTime: row?.start_date_time,
                stopDepartureDateTime: row?.stop_departure_date_time,
                stopName: row?.stop_name,
                durationDays: row?.duration_days,
                waypointPhotoId: row?.waypoint_photo_id,
                waypointLat: row?.waypoint_lat,
                waypointLng: row?.waypoint_lng,
                notes: row?.notes
            }, index)
        });
    });

    (Array.isArray(crewAssignmentRows) ? crewAssignmentRows : []).forEach(row => {
        const planId = String(row?.voyage_plan_id || '').trim();
        const crewMemberId = String(row?.equipage_id || '').trim();
        if (!planId || !crewMemberId) return;
        if (!crewIdsByPlanId.has(planId)) {
            crewIdsByPlanId.set(planId, []);
        }
        crewIdsByPlanId.get(planId).push(crewMemberId);
    });

    return (Array.isArray(planRows) ? planRows : [])
        .map((row, index) => sanitizeVoyagePlan({
            id: String(row?.id || `voyage-plan-${Date.now()}-${index}`),
            name: row?.name,
            description: row?.description,
            status: row?.status,
            mealPlan: row?.meal_plan,
            provisioningItems: row?.provisioning_items,
            budgetItems: row?.budget_items,
            crewMemberIds: Array.from(new Set(crewIdsByPlanId.get(String(row?.id || '').trim()) || [])),
            items: (itemsByPlanId.get(String(row?.id || '').trim()) || [])
                .sort((a, b) => {
                    const aSeq = Number.isFinite(a.seq) ? a.seq : 0;
                    const bSeq = Number.isFinite(b.seq) ? b.seq : 0;
                    return aSeq - bSeq;
                })
                .map(entry => entry.item),
            createdAt: row?.created_at,
            updatedAt: row?.updated_at
        }, index))
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
}

function mergeVoyagePlansPreservingDirtyLocal(localList, cloudList) {
    const planKey = (plan) => {
        const id = String(plan?.id || '').trim();
        if (id) return `id:${id}`;
        return `name:${String(plan?.name || '').trim().toLowerCase()}`;
    };
    const mergedByKey = new Map();

    (Array.isArray(cloudList) ? cloudList : []).forEach((plan, index) => {
        const safe = sanitizeVoyagePlan(plan, index);
        mergedByKey.set(planKey(safe), safe);
    });

    (Array.isArray(localList) ? localList : []).forEach((plan, index) => {
        const safeLocal = sanitizeVoyagePlan(plan, index);
        const key = planKey(safeLocal);
        const cloudVersion = mergedByKey.get(key);
        if (!cloudVersion) {
            mergedByKey.set(key, safeLocal);
            return;
        }

        const localUpdatedMs = Date.parse(String(safeLocal?.updatedAt || safeLocal?.createdAt || ''));
        const cloudUpdatedMs = Date.parse(String(cloudVersion?.updatedAt || cloudVersion?.createdAt || ''));
        const localItemsCount = Array.isArray(safeLocal?.items) ? safeLocal.items.length : 0;
        const cloudItemsCount = Array.isArray(cloudVersion?.items) ? cloudVersion.items.length : 0;
        const cloudLooksCorrupted = cloudItemsCount === 0 && localItemsCount > 0;
        if (cloudLooksCorrupted || (Number.isFinite(localUpdatedMs) && Number.isFinite(cloudUpdatedMs) && localUpdatedMs >= cloudUpdatedMs)) {
            mergedByKey.set(key, safeLocal);
        }
    });

    return Array.from(mergedByKey.values())
        .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')));
}

function mergeVoyagePlanLocalCrewAssignments(baseList, localList) {
    const planKey = (plan) => {
        const id = String(plan?.id || '').trim();
        if (id) return `id:${id}`;
        return `name:${String(plan?.name || '').trim().toLowerCase()}`;
    };

    const localCrewByPlanKey = new Map();
    (Array.isArray(localList) ? localList : []).forEach((plan, index) => {
        const safePlan = sanitizeVoyagePlan(plan, index);
        if (!safePlan.crewMemberIds.length) return;
        localCrewByPlanKey.set(planKey(safePlan), safePlan.crewMemberIds);
    });

    return (Array.isArray(baseList) ? baseList : []).map((plan, index) => {
        const safePlan = sanitizeVoyagePlan(plan, index);
        const localCrewMemberIds = localCrewByPlanKey.get(planKey(safePlan));
        if (!Array.isArray(localCrewMemberIds) || !localCrewMemberIds.length) {
            return safePlan;
        }
        return sanitizeVoyagePlan({ ...safePlan, crewMemberIds: localCrewMemberIds }, index);
    });
}

function mergeCrewDirectoryPreservingDirtyLocal(localList, cloudList) {
    const keyForEntry = (entry) => {
        const id = String(entry?.id || '').trim();
        if (id) return `id:${id}`;
        return `email:${normalizeEmailForCompare(entry?.email || '')}`;
    };

    const mergedByKey = new Map();
    (Array.isArray(cloudList) ? cloudList : []).forEach((entry, index) => {
        const safe = sanitizeCrewMember(entry, index);
        mergedByKey.set(keyForEntry(safe), safe);
    });

    (Array.isArray(localList) ? localList : []).forEach((entry, index) => {
        const safeLocal = sanitizeCrewMember(entry, index);
        const key = keyForEntry(safeLocal);
        const cloudVersion = mergedByKey.get(key);
        if (!cloudVersion) {
            mergedByKey.set(key, safeLocal);
            return;
        }

        const localUpdatedMs = Date.parse(String(safeLocal?.updatedAt || safeLocal?.createdAt || ''));
        const cloudUpdatedMs = Date.parse(String(cloudVersion?.updatedAt || cloudVersion?.createdAt || ''));
        if (Number.isFinite(localUpdatedMs) && Number.isFinite(cloudUpdatedMs) && localUpdatedMs >= cloudUpdatedMs) {
            mergedByKey.set(key, safeLocal);
        }
    });

    return Array.from(mergedByKey.values())
        .sort((a, b) => a.sortLabel.localeCompare(b.sortLabel));
}

function isCloudMissingVoyageStatusColumnError(error) {
    const message = String(error?.message || error?.details || error?.hint || '').toLowerCase();
    return message.includes('status') && (message.includes('column') || message.includes('schema cache') || message.includes('could not find'));
}

function isCloudMissingVoyageFoodColumnError(error) {
    const message = String(error?.message || error?.details || error?.hint || '').toLowerCase();
    return ['meal_plan', 'provisioning_items', 'budget_items'].some(column => message.includes(column))
        && (message.includes('column') || message.includes('schema cache') || message.includes('could not find'));
}

function isCloudMissingCrewDietaryProfileColumnError(error) {
    const message = String(error?.message || error?.details || error?.hint || '').toLowerCase();
    return message.includes('dietary_profile')
        && (message.includes('column') || message.includes('schema cache') || message.includes('could not find'));
}

function buildCrewDirectoryFromCloudRows(rows) {
    return (Array.isArray(rows) ? rows : [])
        .map((row, index) => sanitizeCrewMember({
            id: String(row?.id || generateClientUuid()),
            nom: row?.nom,
            prenom: row?.prenom,
            email: row?.email,
            telephone: row?.telephone,
            commentaire: row?.commentaire,
            dietaryProfile: row?.dietary_profile,
            creatorEmail: row?.creator_email,
            creatorName: row?.creator_name,
            createdAt: row?.created_at,
            updatedAt: row?.updated_at
        }, index))
        .sort((a, b) => a.sortLabel.localeCompare(b.sortLabel));
}

async function pullCrewDirectoryFromCloudV2() {
    if (!isCloudReady()) return [];

    const resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    let query = cloudClient
        .from(CLOUD_CREW_TABLE)
        .select('*')
        .order('nom', { ascending: true })
        .order('prenom', { ascending: true });

    if (isUuidString(resolvedProjectIdUuid)) {
        query = query.eq('project_id', resolvedProjectIdUuid);
    }

    const { data, error } = await query;
    if (error) throw error;
    return buildCrewDirectoryFromCloudRows(data || []);
}

async function pullVoyagePlansFromCloudV2() {
    if (!isCloudReady()) return [];

    const resolvedProjectIdUuid = await resolveCloudProjectIdUuid();

    let plansQuery = cloudClient
        .from(CLOUD_VOYAGE_PLANS_TABLE)
        .select('*')
        .order('updated_at', { ascending: false });

    if (isUuidString(resolvedProjectIdUuid)) {
        plansQuery = plansQuery.eq('project_id', resolvedProjectIdUuid);
    }

    const { data: planRows, error: planError } = await plansQuery;

    if (planError) throw planError;
    if (!Array.isArray(planRows) || planRows.length === 0) return [];

    const planIds = planRows
        .map(row => String(row?.id || '').trim())
        .filter(Boolean);

    let itemsQuery = cloudClient
        .from(CLOUD_VOYAGE_PLAN_ITEMS_TABLE)
        .select('*')
        .in('voyage_plan_id', planIds)
        .order('seq', { ascending: true });

    if (isUuidString(resolvedProjectIdUuid)) {
        itemsQuery = itemsQuery.eq('project_id', resolvedProjectIdUuid);
    }

    const { data: itemRows, error: itemError } = await itemsQuery;

    if (itemError) throw itemError;

    let crewAssignmentsQuery = cloudClient
        .from(CLOUD_VOYAGE_CREW_TABLE)
        .select('*')
        .in('voyage_plan_id', planIds);

    if (isUuidString(resolvedProjectIdUuid)) {
        crewAssignmentsQuery = crewAssignmentsQuery.eq('project_id', resolvedProjectIdUuid);
    }

    const { data: crewAssignmentRows, error: crewAssignmentsError } = await crewAssignmentsQuery;
    if (crewAssignmentsError) throw crewAssignmentsError;

    return buildVoyagePlansFromCloudRows(planRows, itemRows || [], crewAssignmentRows || []);
}

async function pushCrewDirectoryToCloudV2(entries) {
    if (!isCloudReady()) return false;

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) return false;

    let resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    if (!resolvedProjectIdUuid) {
        throw new Error('project_id introuvable pour equipage.');
    }
    resolvedProjectIdUuid = await ensureCloudProjectRow(resolvedProjectIdUuid);

    const creator = getCreatorPatch();
    const safeEntries = (Array.isArray(entries) ? entries : []).map((entry, index) => sanitizeCrewMember(entry, index));

    const { error: deleteError } = await cloudClient
        .from(CLOUD_CREW_TABLE)
        .delete()
        .eq('creator_email', creatorEmail)
        .eq('project_id', resolvedProjectIdUuid);
    if (deleteError) throw deleteError;

    if (!safeEntries.length) return true;

    const payload = safeEntries.map(entry => ({
        id: String(entry.id || generateClientUuid()),
        project_id: resolvedProjectIdUuid,
        creator_email: creatorEmail,
        creator_name: creator.creatorName || null,
        nom: String(entry.nom || '').trim(),
        prenom: String(entry.prenom || '').trim(),
        email: normalizeEmailForCompare(entry.email || ''),
        telephone: normalizePhoneValue(entry.telephone || ''),
        commentaire: String(entry.commentaire || '').trim(),
        ...(cloudCrewHasDietaryProfileColumn ? { dietary_profile: sanitizeCrewDietaryProfile(entry.dietaryProfile || {}) } : {}),
        created_at: entry.createdAt || new Date().toISOString(),
        updated_at: entry.updatedAt || new Date().toISOString()
    }));

    let { error: insertError } = await cloudClient
        .from(CLOUD_CREW_TABLE)
        .insert(payload);
    if (insertError && cloudCrewHasDietaryProfileColumn && isCloudMissingCrewDietaryProfileColumnError(insertError)) {
        cloudCrewHasDietaryProfileColumn = false;
        ({ error: insertError } = await cloudClient
            .from(CLOUD_CREW_TABLE)
            .insert(payload.map(({ dietary_profile, ...rest }) => rest)));
    }
    if (insertError) throw insertError;
    return true;
}

async function pushVoyagePlansToCloudV2(plans) {
    if (!isCloudReady()) return false;

    const creatorEmail = getCurrentCloudUserEmail();
    if (!creatorEmail) return false;

    let resolvedProjectIdUuid = await resolveCloudProjectIdUuid();
    if (!resolvedProjectIdUuid) {
        throw new Error('project_id introuvable pour voyage_plans.');
    }
    resolvedProjectIdUuid = await ensureCloudProjectRow(resolvedProjectIdUuid);

    const creator = getCreatorPatch();
    const safePlans = (Array.isArray(plans) ? plans : [])
        .map((plan, index) => sanitizeVoyagePlan(plan, index));

    const { data: existingPlanRows, error: existingPlanRowsError } = await cloudClient
        .from(CLOUD_VOYAGE_PLANS_TABLE)
        .select('id')
        .eq('creator_email', creatorEmail)
        .eq('project_id', resolvedProjectIdUuid);
    if (existingPlanRowsError) throw existingPlanRowsError;

    const existingPlanIds = (Array.isArray(existingPlanRows) ? existingPlanRows : [])
        .map(row => String(row?.id || '').trim())
        .filter(Boolean);

    if (existingPlanIds.length > 0) {
        const { error: deleteItemsError } = await cloudClient
            .from(CLOUD_VOYAGE_PLAN_ITEMS_TABLE)
            .delete()
            .eq('creator_email', creatorEmail)
            .eq('project_id', resolvedProjectIdUuid)
            .in('voyage_plan_id', existingPlanIds);
        if (deleteItemsError) throw deleteItemsError;
    }

    const { error: deletePlansError } = await cloudClient
        .from(CLOUD_VOYAGE_PLANS_TABLE)
        .delete()
        .eq('creator_email', creatorEmail)
        .eq('project_id', resolvedProjectIdUuid);
    if (deletePlansError) throw deletePlansError;

    const { error: deleteCrewLinksError } = await cloudClient
        .from(CLOUD_VOYAGE_CREW_TABLE)
        .delete()
        .eq('creator_email', creatorEmail)
        .eq('project_id', resolvedProjectIdUuid);
    if (deleteCrewLinksError) throw deleteCrewLinksError;

    if (!safePlans.length) return true;

    const nowIso = new Date().toISOString();
    const buildPlanPayload = (includeStatus = true, includeFoodColumns = true) => safePlans.map(plan => ({
        id: String(plan.id || generateClientUuid()),
        project_id: resolvedProjectIdUuid,
        creator_email: creatorEmail,
        creator_name: creator.creatorName || null,
        name: String(plan.name || '').trim(),
        description: String(plan.description || '').trim(),
        ...(includeStatus ? { status: normalizeVoyagePlanStatus(plan.status) } : {}),
        ...(includeFoodColumns ? {
            meal_plan: (plan.mealPlan || []).map((entry, index) => sanitizeVoyageMealEntry(entry, index)),
            provisioning_items: (plan.provisioningItems || []).map((entry, index) => sanitizeVoyageProvisioningItem(entry, index)),
            budget_items: (plan.budgetItems || []).map((entry, index) => sanitizeVoyageBudgetItem(entry, index))
        } : {}),
        created_at: plan.createdAt || nowIso,
        updated_at: plan.updatedAt || nowIso
    }));

    let planPayload = buildPlanPayload(cloudVoyagePlansHasStatusColumn, cloudVoyagePlansHasFoodColumns);

    let { error: insertPlansError } = await cloudClient
        .from(CLOUD_VOYAGE_PLANS_TABLE)
        .insert(planPayload);
    if (insertPlansError && cloudVoyagePlansHasStatusColumn && isCloudMissingVoyageStatusColumnError(insertPlansError)) {
        cloudVoyagePlansHasStatusColumn = false;
        planPayload = buildPlanPayload(false, cloudVoyagePlansHasFoodColumns);
        ({ error: insertPlansError } = await cloudClient
            .from(CLOUD_VOYAGE_PLANS_TABLE)
            .insert(planPayload));
    }
    if (insertPlansError && cloudVoyagePlansHasFoodColumns && isCloudMissingVoyageFoodColumnError(insertPlansError)) {
        cloudVoyagePlansHasFoodColumns = false;
        planPayload = buildPlanPayload(cloudVoyagePlansHasStatusColumn, false);
        ({ error: insertPlansError } = await cloudClient
            .from(CLOUD_VOYAGE_PLANS_TABLE)
            .insert(planPayload));
    }
    if (insertPlansError) throw insertPlansError;

    const itemPayload = safePlans.flatMap(plan => (Array.isArray(plan.items) ? plan.items : []).map((item, index) => {
        const safeItem = sanitizeVoyagePlanItem(item, index);
        return {
            id: String(safeItem.id || generateClientUuid()),
            voyage_plan_id: String(plan.id || ''),
            project_id: resolvedProjectIdUuid,
            creator_email: creatorEmail,
            creator_name: creator.creatorName || null,
            seq: index,
            item_type: safeItem.type,
            route_id: safeItem.routeId || null,
            departure_date_time: safeItem.departureDateTime || null,
            start_date_time: safeItem.startDateTime || null,
            stop_departure_date_time: safeItem.stopDepartureDateTime || null,
            stop_name: safeItem.stopName || '',
            duration_days: Number.isFinite(safeItem.durationDays) ? safeItem.durationDays : 0,
            waypoint_photo_id: safeItem.waypointPhotoId || null,
            waypoint_lat: Number.isFinite(safeItem.waypointLat) ? safeItem.waypointLat : null,
            waypoint_lng: Number.isFinite(safeItem.waypointLng) ? safeItem.waypointLng : null,
            notes: safeItem.notes || '',
            created_at: plan.createdAt || nowIso,
            updated_at: plan.updatedAt || nowIso
        };
    }));

    if (itemPayload.length) {
        const { error: insertItemsError } = await cloudClient
            .from(CLOUD_VOYAGE_PLAN_ITEMS_TABLE)
            .insert(itemPayload);
        if (insertItemsError) throw insertItemsError;
    }

    const validCrewMemberIds = new Set(crewDirectory.map(entry => String(entry?.id || '').trim()).filter(Boolean));
    const crewLinkPayload = safePlans.flatMap(plan => (Array.isArray(plan.crewMemberIds) ? plan.crewMemberIds : [])
        .map(id => String(id || '').trim())
        .filter(id => validCrewMemberIds.has(id))
        .map(id => ({
            id: generateClientUuid(),
            project_id: resolvedProjectIdUuid,
            creator_email: creatorEmail,
            creator_name: creator.creatorName || null,
            voyage_plan_id: String(plan.id || ''),
            equipage_id: id,
            commentaire: '',
            created_at: plan.createdAt || nowIso,
            updated_at: plan.updatedAt || nowIso
        })));

    if (crewLinkPayload.length) {
        const { error: insertCrewLinksError } = await cloudClient
            .from(CLOUD_VOYAGE_CREW_TABLE)
            .insert(crewLinkPayload);
        if (insertCrewLinksError) throw insertCrewLinksError;
    }

    return true;
}

async function pullRoutesFromCloud(options = {}) {
    if (!isCloudReady()) return getSavedRoutes();

    const {
        allowMaintenanceOverwrite = false,
        includeNavLog = true,
        includeEngineLog = true,
        includeEngineSound = includeEngineLog,
        includeWaypointPhotos = true,
        includeArrivalAnalyses = true,
        includeAgendaEvents = true,
        includeVoyagePlans = true,
        includeCrewDirectory = true
    } = options || {};
    const cloudNavEntriesFromTable = includeNavLog
        ? await pullNavLogEntriesFromCloudTable()
        : null;
    const cloudEngineEntriesFromTable = includeEngineLog
        ? await pullEngineLogEntriesFromCloudTable()
        : null;
    const cloudEngineSoundSnapshotsFromTable = includeEngineSound
        ? await pullEngineSoundSnapshotsFromCloudTable()
        : null;
    const cloudWaypointPhotosV2 = includeWaypointPhotos
        ? await pullWaypointPhotosFromCloudV2()
        : null;
    const cloudArrivalAnalysesV2 = includeArrivalAnalyses
        ? await pullArrivalAnalysisEntriesFromCloudV2()
        : null;
    const cloudAgendaEventsV2 = includeAgendaEvents
        ? await pullAgendaEventsFromCloudV2()
        : null;
    const cloudCrewDirectoryV2 = includeCrewDirectory
        ? await pullCrewDirectoryFromCloudV2()
        : null;
    const cloudVoyagePlansV2 = includeVoyagePlans
        ? await pullVoyagePlansFromCloudV2()
        : null;

    let cloudMaintenanceBoardsV2 = null;
    let cloudMaintenanceExpensesV2 = null;
    let cloudMaintenanceSuppliersV2 = null;
    if (allowMaintenanceOverwrite) {
        cloudMaintenanceBoardsV2 = await pullMaintenanceBoardsFromCloudV2();
        cloudMaintenanceExpensesV2 = await pullMaintenanceExpensesFromCloudV2();
        cloudMaintenanceSuppliersV2 = await pullMaintenanceSuppliersFromCloudV2();
    }

    const localRoutesBeforePull = [...getSavedRoutes()];
    const localRouteCommentsBeforePull = [...getRouteExternalComments()];
    const localWaypointPhotosBeforePull = waypointPhotoEntries
        .map(normalizeWaypointPhotoEntry)
        .filter(Boolean);
    const localArrivalAnalysesBeforePull = [...arrivalAnalysisEntries];
    const localAgendaEventsBeforePull = agendaEvents.map((entry, index) => sanitizeAgendaEvent(entry, index));
    const localCrewDirectoryBeforePull = crewDirectory.map((entry, index) => sanitizeCrewMember(entry, index));
    const localVoyagePlansBeforePull = voyagePlans.map((plan, index) => sanitizeVoyagePlan(plan, index));
    const localMaintenanceBoardsBeforePull = maintenanceBoards.map((board, index) => sanitizeMaintenanceBoard(board, index));
    const localMaintenanceExpensesBeforePull = maintenanceExpenses.map((entry, index) => sanitizeMaintenanceExpense(entry, index));
    const localMaintenanceSuppliersBeforePull = maintenanceSuppliers.map((entry, index) => sanitizeMaintenanceSupplier(entry, index));
    const localNavEntriesBeforePull = sanitizeNavLogEntriesList(navLogEntries);
    const localEngineEntriesBeforePull = sanitizeEngineLogEntriesList(engineLogEntries);
    const localEngineSoundSnapshotsBeforePull = sanitizeEngineSoundSnapshotsList(engineSoundSnapshots);
    let shouldPromoteLocalAgendaEventsToCloud = false;
    let shouldPromoteLocalVoyagePlansToCloud = false;
    const cloudRoutesV2 = await pullRoutesFromCloudV2();
    const cloudPolarProfilesFromCloud = await pullPolarProfilesFromCloudTable().catch(() => null);
    const effectiveRoutes = Array.isArray(cloudRoutesV2) ? cloudRoutesV2 : [];
    const cloudRouteCommentsV2 = await pullRouteCommentsFromCloudV2(effectiveRoutes.map(route => route?.id));
    const suspiciousCloudRouteShrink = !routesCloudDirty
        && localRoutesBeforePull.length >= 6
        && effectiveRoutes.length > 0
        && effectiveRoutes.length <= Math.floor(localRoutesBeforePull.length / 2);

    if (suspiciousCloudRouteShrink) {
        setSavedRoutes(localRoutesBeforePull);
        setRouteExternalComments(resolveRouteCommentsToApply(cloudRouteCommentsV2, localRoutesBeforePull), { persistLocal: true });
        updateCloudDataSourceStatus('cache local protégé', localRoutesBeforePull.length, waypointPhotoEntries.length);
        setCloudStatus(t(
            `Alerte: le cloud ne renvoie plus que ${effectiveRoutes.length} route(s) au lieu de ${localRoutesBeforePull.length}. Le cache local a été conservé pour éviter une suppression massive.`,
            `Alerta: la nube solo devuelve ${effectiveRoutes.length} ruta(s) en lugar de ${localRoutesBeforePull.length}. Se conserva la caché local para evitar un borrado masivo.`,
            `Warning: the cloud returned only ${effectiveRoutes.length} route(s) instead of ${localRoutesBeforePull.length}. The local cache was preserved to avoid a mass deletion.`
        ), true);
        return localRoutesBeforePull;
    }

    const preservedLocalCollections = [];
    const preserveLocalCollectionWhenCloudEmpty = (cloudList, localList, label) => {
        if (!Array.isArray(cloudList)) return cloudList;
        if (cloudList.length > 0 || !Array.isArray(localList) || localList.length === 0) {
            return cloudList;
        }
        preservedLocalCollections.push(label);
        return localList;
    };

    const effectiveWaypointPhotos = preserveLocalCollectionWhenCloudEmpty(cloudWaypointPhotosV2, localWaypointPhotosBeforePull, 'waypointPhotos');
    const effectiveMaintenanceBoards = preserveLocalCollectionWhenCloudEmpty(cloudMaintenanceBoardsV2, localMaintenanceBoardsBeforePull, 'maintenanceBoards');
    const effectiveMaintenanceExpenses = preserveLocalCollectionWhenCloudEmpty(cloudMaintenanceExpensesV2, localMaintenanceExpensesBeforePull, 'maintenanceExpenses');
    const effectiveMaintenanceSuppliers = preserveLocalCollectionWhenCloudEmpty(cloudMaintenanceSuppliersV2, localMaintenanceSuppliersBeforePull, 'maintenanceSuppliers');
    const effectiveNavEntries = preserveLocalCollectionWhenCloudEmpty(cloudNavEntriesFromTable, localNavEntriesBeforePull, 'navLog');
    const effectiveEngineEntries = preserveLocalCollectionWhenCloudEmpty(cloudEngineEntriesFromTable, localEngineEntriesBeforePull, 'engineLog');
    const effectiveEngineSoundSnapshots = preserveLocalCollectionWhenCloudEmpty(cloudEngineSoundSnapshotsFromTable, localEngineSoundSnapshotsBeforePull, 'engineSound');

    const mergeRoutesPreservingDirtyLocal = (localList, cloudList) => {
        const routeKey = (route) => {
            const id = String(route?.id || '').trim();
            if (isUuidString(id)) return `id:${id}`;
            return `name:${String(route?.name || '').trim().toLowerCase()}`;
        };
        const mergedByName = new Map();

        (Array.isArray(cloudList) ? cloudList : []).forEach((route, index) => {
            const safe = sanitizeSavedRoute(route, index);
            mergedByName.set(routeKey(safe), safe);
        });

        (Array.isArray(localList) ? localList : []).forEach((route, index) => {
            const safeLocal = sanitizeSavedRoute(route, index);
            const key = routeKey(safeLocal);
            const cloudVersion = mergedByName.get(key);
            if (!cloudVersion) {
                mergedByName.set(key, safeLocal);
                return;
            }

            const localUpdatedMs = Date.parse(String(safeLocal?.updatedAt || safeLocal?.createdAt || ''));
            const cloudUpdatedMs = Date.parse(String(cloudVersion?.updatedAt || cloudVersion?.createdAt || ''));
            const localPointsCount = Array.isArray(safeLocal?.points) ? safeLocal.points.length : 0;
            const cloudPointsCount = Array.isArray(cloudVersion?.points) ? cloudVersion.points.length : 0;
            const localLooksCorrupted = localPointsCount === 0 && cloudPointsCount > 0;

            if (!localLooksCorrupted && Number.isFinite(localUpdatedMs) && Number.isFinite(cloudUpdatedMs) && localUpdatedMs >= cloudUpdatedMs) {
                mergedByName.set(key, safeLocal);
            }
        });

        return Array.from(mergedByName.values()).sort((a, b) => {
            const aMs = Date.parse(String(a?.updatedAt || a?.createdAt || ''));
            const bMs = Date.parse(String(b?.updatedAt || b?.createdAt || ''));
            const safeA = Number.isFinite(aMs) ? aMs : 0;
            const safeB = Number.isFinite(bMs) ? bMs : 0;
            return safeB - safeA;
        });
    };

    const resolveCrewDirectoryToApply = (cloudList) => {
        const safeCloudList = Array.isArray(cloudList) ? cloudList : [];
        if (!safeCloudList.length && localCrewDirectoryBeforePull.length > 0) {
            // Do not wipe a local crew directory just because the cloud table is currently empty.
            return localCrewDirectoryBeforePull;
        }
        if (crewDirectoryCloudDirty) {
            return mergeCrewDirectoryPreservingDirtyLocal(localCrewDirectoryBeforePull, safeCloudList);
        }
        return safeCloudList;
    };

    const resolveAgendaEventsToApply = (cloudList) => {
        const safeCloudList = Array.isArray(cloudList) ? cloudList : [];
        if (!safeCloudList.length && localAgendaEventsBeforePull.length > 0) {
            // First sync after creating the cloud table: preserve local events and promote them to cloud.
            if (!agendaEventsCloudDirty) {
                agendaEventsCloudDirty = true;
                agendaEventsCloudRevision += 1;
            }
            shouldPromoteLocalAgendaEventsToCloud = true;
            return localAgendaEventsBeforePull;
        }
        if (agendaEventsCloudDirty) {
            return mergeAgendaEventsPreservingDirtyLocal(localAgendaEventsBeforePull, safeCloudList);
        }
        return safeCloudList;
    };

    const resolveVoyagePlansToApply = (cloudList) => {
        const safeCloudList = Array.isArray(cloudList) ? cloudList : [];
        const localHasItems = localVoyagePlansBeforePull.some(plan => Array.isArray(plan?.items) && plan.items.length > 0);
        const localHasCrewLinks = localVoyagePlansBeforePull.some(plan => Array.isArray(plan?.crewMemberIds) && plan.crewMemberIds.length > 0);
        const cloudHasPlans = safeCloudList.length > 0;
        const cloudHasItems = safeCloudList.some(plan => Array.isArray(plan?.items) && plan.items.length > 0);
        const cloudHasCrewLinks = safeCloudList.some(plan => Array.isArray(plan?.crewMemberIds) && plan.crewMemberIds.length > 0);
        if (!safeCloudList.length && localVoyagePlansBeforePull.length > 0) {
            // Preserve local voyages if the cloud table is empty or not yet populated.
            if (!voyagePlansCloudDirty) {
                voyagePlansCloudDirty = true;
                voyagePlansCloudRevision += 1;
            }
            shouldPromoteLocalVoyagePlansToCloud = true;
            return localVoyagePlansBeforePull;
        }
        if (cloudHasPlans && !cloudHasItems && localHasItems) {
            // voyage_plans exists but voyage_plan_items is empty: keep the richer local version and repair cloud.
            if (!voyagePlansCloudDirty) {
                voyagePlansCloudDirty = true;
                voyagePlansCloudRevision += 1;
            }
            shouldPromoteLocalVoyagePlansToCloud = true;
            return mergeVoyagePlansPreservingDirtyLocal(localVoyagePlansBeforePull, safeCloudList);
        }
        if (cloudHasPlans && !cloudHasCrewLinks && localHasCrewLinks) {
            // voyage_plans/items exist but voyage_equipage is empty: keep local crew links and repair cloud.
            if (!voyagePlansCloudDirty) {
                voyagePlansCloudDirty = true;
                voyagePlansCloudRevision += 1;
            }
            shouldPromoteLocalVoyagePlansToCloud = true;
            return mergeVoyagePlanLocalCrewAssignments(safeCloudList, localVoyagePlansBeforePull);
        }
        if (voyagePlansCloudDirty) {
            return mergeVoyagePlanLocalCrewAssignments(
                mergeVoyagePlansPreservingDirtyLocal(localVoyagePlansBeforePull, safeCloudList),
                localVoyagePlansBeforePull
            );
        }
        return safeCloudList;
    };

    const resolveRouteCommentsToApply = (cloudList, routeList) => {
        const validRouteIds = new Set((Array.isArray(routeList) ? routeList : []).map(route => String(route?.id || '').trim()).filter(Boolean));
        const filterForRoutes = (list) => (Array.isArray(list) ? list : []).filter(entry => validRouteIds.has(String(entry?.routeId || '')));
        const safeCloudList = filterForRoutes(cloudList);
        const safeLocalList = filterForRoutes(localRouteCommentsBeforePull);

        if (!safeCloudList.length && safeLocalList.length > 0) {
            routeCommentsCloudDirty = true;
            return safeLocalList;
        }

        if (routeCommentsCloudDirty) {
            const mergedByRouteId = new Map();
            safeCloudList.forEach(entry => mergedByRouteId.set(String(entry.routeId || ''), sanitizeRouteExternalComment(entry)));
            safeLocalList.forEach(entry => {
                const safeLocal = sanitizeRouteExternalComment(entry);
                const key = String(safeLocal?.routeId || '');
                const cloudVersion = mergedByRouteId.get(key);
                if (!safeLocal) return;
                if (!cloudVersion) {
                    mergedByRouteId.set(key, safeLocal);
                    return;
                }
                const localUpdatedMs = Date.parse(String(safeLocal?.updatedAt || safeLocal?.createdAt || ''));
                const cloudUpdatedMs = Date.parse(String(cloudVersion?.updatedAt || cloudVersion?.createdAt || ''));
                if (Number.isFinite(localUpdatedMs) && Number.isFinite(cloudUpdatedMs) && localUpdatedMs >= cloudUpdatedMs) {
                    mergedByRouteId.set(key, safeLocal);
                }
            });
            return Array.from(mergedByRouteId.values()).filter(Boolean);
        }

        return safeCloudList;
    };

    if (routesCloudDirty && localRoutesBeforePull.length > 0) {
        // Prevent transient UI rollback while local changes are waiting for cloud sync.
        const merged = mergeRoutesPreservingDirtyLocal(localRoutesBeforePull, effectiveRoutes);
        setSavedRoutes(merged);
        setRouteExternalComments(resolveRouteCommentsToApply(cloudRouteCommentsV2, merged), { persistLocal: true });
        updateCloudDataSourceStatus('local (non synchronisé)', merged.length, waypointPhotoEntries.length);

        if (includeWaypointPhotos && Array.isArray(effectiveWaypointPhotos)) {
            setWaypointPhotoEntries(effectiveWaypointPhotos, { persistLocal: true, refreshUi: true });
        }
        if (includeArrivalAnalyses && Array.isArray(cloudArrivalAnalysesV2)) {
            const mergedArrivalAnalyses = arrivalAnalysesCloudDirty
                ? mergeArrivalAnalysisEntriesPreservingDirtyLocal(localArrivalAnalysesBeforePull, cloudArrivalAnalysesV2)
                : cloudArrivalAnalysesV2;
            setArrivalAnalysisEntries(mergedArrivalAnalyses, { persistLocal: true, refreshUi: true });
        }
        if (includeAgendaEvents && Array.isArray(cloudAgendaEventsV2)) {
            const mergedAgendaEvents = resolveAgendaEventsToApply(cloudAgendaEventsV2);
            setAgendaEvents(mergedAgendaEvents, { persistLocal: true, markCloudDirty: false });
            if (shouldPromoteLocalAgendaEventsToCloud) {
                tryFlushPendingCloudDataPush();
            }
            renderVoyageAgendaPanel();
        }
        if (includeCrewDirectory && Array.isArray(cloudCrewDirectoryV2)) {
            const mergedCrewDirectory = resolveCrewDirectoryToApply(cloudCrewDirectoryV2);
            setCrewDirectory(mergedCrewDirectory, { persistLocal: true, markCloudDirty: false });
        }
        if (includeVoyagePlans && Array.isArray(cloudVoyagePlansV2)) {
            const mergedVoyagePlans = resolveVoyagePlansToApply(cloudVoyagePlansV2);
            setVoyagePlans(mergedVoyagePlans, { persistLocal: true, markCloudDirty: false });
            if (shouldPromoteLocalVoyagePlansToCloud) {
                tryFlushPendingCloudDataPush();
            }
            syncVoyagePlanEditorUi();
            renderVoyageAgendaPanel();
        }
        if (allowMaintenanceOverwrite) {
            setMaintenanceBoards(effectiveMaintenanceBoards, { persistLocal: true, refreshUi: true, syncCloud: false });
            setMaintenanceExpenses(effectiveMaintenanceExpenses, { refreshUi: true });
            const preserveSupplierEditor = isMaintenanceSupplierEditorFocused();
            setMaintenanceSuppliers(effectiveMaintenanceSuppliers, { refreshUi: !preserveSupplierEditor });
        }

        if (Array.isArray(effectiveNavEntries)) {
            navLogEntries = effectiveNavEntries;
            saveArrayToStorage(NAV_LOG_STORAGE_KEY, navLogEntries);
            renderNavLogList();
        }

        if (Array.isArray(effectiveEngineEntries)) {
            engineLogEntries = effectiveEngineEntries;
            renderEngineLogList();
        }

        if (Array.isArray(effectiveEngineSoundSnapshots)) {
            engineSoundSnapshots = effectiveEngineSoundSnapshots;
            saveArrayToStorage(ENGINE_SOUND_SNAPSHOTS_STORAGE_KEY, engineSoundSnapshots);
        }

        applySyncedPolarProfiles(cloudPolarProfilesFromCloud);
        return merged;
    }

    setSavedRoutes(effectiveRoutes);
    setRouteExternalComments(resolveRouteCommentsToApply(cloudRouteCommentsV2, effectiveRoutes), { persistLocal: true });

    if (includeWaypointPhotos && Array.isArray(effectiveWaypointPhotos)) {
        setWaypointPhotoEntries(effectiveWaypointPhotos, { persistLocal: true, refreshUi: true });
    }
    if (includeArrivalAnalyses && Array.isArray(cloudArrivalAnalysesV2)) {
        const arrivalEntriesToApply = arrivalAnalysesCloudDirty
            ? mergeArrivalAnalysisEntriesPreservingDirtyLocal(localArrivalAnalysesBeforePull, cloudArrivalAnalysesV2)
            : cloudArrivalAnalysesV2;
        setArrivalAnalysisEntries(arrivalEntriesToApply, { persistLocal: true, refreshUi: true });
    }
    if (includeAgendaEvents && Array.isArray(cloudAgendaEventsV2)) {
        const agendaEventsToApply = resolveAgendaEventsToApply(cloudAgendaEventsV2);
        setAgendaEvents(agendaEventsToApply, { persistLocal: true, markCloudDirty: false });
        if (shouldPromoteLocalAgendaEventsToCloud) {
            tryFlushPendingCloudDataPush();
        }
        renderVoyageAgendaPanel();
    }
    if (includeCrewDirectory && Array.isArray(cloudCrewDirectoryV2)) {
        const crewDirectoryToApply = resolveCrewDirectoryToApply(cloudCrewDirectoryV2);
        setCrewDirectory(crewDirectoryToApply, { persistLocal: true, markCloudDirty: false });
    }
    if (includeVoyagePlans && Array.isArray(cloudVoyagePlansV2)) {
        const voyagePlansToApply = resolveVoyagePlansToApply(cloudVoyagePlansV2);
        setVoyagePlans(voyagePlansToApply, { persistLocal: true, markCloudDirty: false });
        if (shouldPromoteLocalVoyagePlansToCloud) {
            tryFlushPendingCloudDataPush();
        }
        syncVoyagePlanEditorUi();
        renderVoyageAgendaPanel();
    }
    if (allowMaintenanceOverwrite) {
        setMaintenanceBoards(effectiveMaintenanceBoards, { persistLocal: true, refreshUi: true, syncCloud: false });
        setMaintenanceExpenses(effectiveMaintenanceExpenses, { refreshUi: true });
        const preserveSupplierEditor = isMaintenanceSupplierEditorFocused();
        setMaintenanceSuppliers(effectiveMaintenanceSuppliers, { refreshUi: !preserveSupplierEditor });
    }

    if (Array.isArray(effectiveNavEntries)) {
        navLogEntries = effectiveNavEntries;
        saveArrayToStorage(NAV_LOG_STORAGE_KEY, navLogEntries);
        renderNavLogList();
    }

    if (Array.isArray(effectiveEngineEntries)) {
        engineLogEntries = effectiveEngineEntries;
        renderEngineLogList();
    }

    if (Array.isArray(effectiveEngineSoundSnapshots)) {
        engineSoundSnapshots = effectiveEngineSoundSnapshots;
        saveArrayToStorage(ENGINE_SOUND_SNAPSHOTS_STORAGE_KEY, engineSoundSnapshots);
    }

    applySyncedPolarProfiles(cloudPolarProfilesFromCloud);
    if (preservedLocalCollections.length > 0) {
        console.warn('[CEIBO] Preserved local collections after empty cloud pull:', preservedLocalCollections.join(', '));
    }
    updateCloudDataSourceStatus('cloud (routes v2)', effectiveRoutes.length, waypointPhotoEntries.length);

    return effectiveRoutes;
}

async function pushRoutesToCloud(options = {}) {
    if (!isCloudReady()) return false;

    const {
        includeEngineLog = true,
        includeEngineSound = includeEngineLog,
        includeWaypointPhotos = true,
        includeMaintenanceBoards = true,
        includeArrivalAnalyses = true,
        includeAgendaEvents = true,
        includeVoyagePlans = true,
        includeCrewDirectory = true
    } = options || {};

    const routesSnapshot = getSavedRoutes();
    const agendaEventsRevisionAtPushStart = agendaEventsCloudRevision;
    const voyagePlansRevisionAtPushStart = voyagePlansCloudRevision;
    const crewDirectoryRevisionAtPushStart = crewDirectoryCloudRevision;
    const creatorEmail = getCurrentCloudUserEmail();

    if (!creatorEmail) {
        throw new Error(t(
            'Utilisateur cloud non authentifié: synchronisation impossible.',
            'Usuario nube no autenticado: sincronización imposible.',
            'Cloud user not authenticated: sync unavailable.'
        ));
    }

    // Strict mode: if normalized tables fail, report sync failure instead of silently claiming success.
    if (includeCrewDirectory || includeVoyagePlans) {
        if (!await pushCrewDirectoryToCloudV2(crewDirectory)) {
            throw new Error(t(
                'Synchronisation cloud de l\'équipage refusée.',
                'Sincronización nube de la tripulación rechazada.',
                'Cloud crew sync was rejected.'
            ));
        }
    }
    if (includeVoyagePlans) {
        if (!await pushVoyagePlansToCloudV2(voyagePlans)) {
            throw new Error(t(
                'Synchronisation cloud des voyages refusée.',
                'Sincronización nube de viajes rechazada.',
                'Cloud trip sync was rejected.'
            ));
        }
    }
    if (includeEngineLog) {
        await pushEngineLogEntriesToCloudTable();
    }
    if (includeEngineSound) {
        await pushEngineSoundSnapshotsToCloudTable();
    }
    if (!await pushRoutesToCloudV2(routesSnapshot)) {
        throw new Error(t(
            'Synchronisation cloud des routes refusée.',
            'Sincronización nube de rutas rechazada.',
            'Cloud route sync was rejected.'
        ));
    }
    if (!await pushRouteCommentsToCloudV2(getRouteExternalComments(), routesSnapshot.map(route => route?.id))) {
        throw new Error(t(
            'Synchronisation cloud des commentaires de route refusée.',
            'Sincronización nube de comentarios de ruta rechazada.',
            'Cloud route comment sync was rejected.'
        ));
    }
    await pushPolarProfilesToCloudTable().catch(() => {});
    if (includeWaypointPhotos) {
        if (!await pushWaypointPhotosToCloudV2(waypointPhotoEntries)) {
            throw new Error(t(
                'Synchronisation cloud des mouillages refusée.',
                'Sincronización nube de fondeos rechazada.',
                'Cloud waypoint sync was rejected.'
            ));
        }
    }
    if (includeArrivalAnalyses) {
        if (!await pushArrivalAnalysisEntriesToCloudV2(arrivalAnalysisEntries)) {
            throw new Error(t(
                'Synchronisation cloud des analyses d\'arrivée refusée.',
                'Sincronización nube de análisis de llegada rechazada.',
                'Cloud arrival-analysis sync was rejected.'
            ));
        }
    }
    if (includeAgendaEvents) {
        if (!await pushAgendaEventsToCloudV2(agendaEvents)) {
            throw new Error(t(
                'Synchronisation cloud des évènements refusée.',
                'Sincronización nube de eventos rechazada.',
                'Cloud event sync was rejected.'
            ));
        }
    }
    if (includeMaintenanceBoards) {
        await pushMaintenanceBoardsToCloudV2(maintenanceBoards);
    }

    routesCloudDirty = false;
    routeCommentsCloudDirty = false;
    arrivalAnalysesCloudDirty = false;
    if (includeAgendaEvents && agendaEventsCloudRevision === agendaEventsRevisionAtPushStart) {
        agendaEventsCloudDirty = false;
    }
    if (includeVoyagePlans && voyagePlansCloudRevision === voyagePlansRevisionAtPushStart) {
        voyagePlansCloudDirty = false;
    }
    if ((includeCrewDirectory || includeVoyagePlans) && crewDirectoryCloudRevision === crewDirectoryRevisionAtPushStart) {
        crewDirectoryCloudDirty = false;
    }
    cloudLastSeenUpdatedAtMs = Math.max(cloudLastSeenUpdatedAtMs, Date.now());
    return true;
}

function updateCloudFormFromConfig(config) {
    const urlInput = document.getElementById('cloudUrlInput');
    const anonInput = document.getElementById('cloudAnonKeyInput');
    const projectInput = document.getElementById('cloudProjectKeyInput');
    if (urlInput && config?.url) urlInput.value = config.url;
    if (anonInput && config?.anonKey) anonInput.value = config.anonKey;
    if (projectInput && config?.projectKey) projectInput.value = config.projectKey;
}

function readCloudConfigFromForm() {
    const url = String(document.getElementById('cloudUrlInput')?.value || '').trim();
    const anonKey = String(document.getElementById('cloudAnonKeyInput')?.value || '').trim();
    const projectKey = String(document.getElementById('cloudProjectKeyInput')?.value || '').trim();
    return { url, anonKey, projectKey };
}

function getCloudStatusText() {
    return String(document.getElementById('cloudStatus')?.textContent || '').trim();
}

function buildCloudConnectFailureMessage(config) {
    if (!config?.url || !config?.anonKey || !config?.projectKey) {
        return t('Paramètres cloud incomplets (URL / clé anon / project key).', 'Parámetros nube incompletos (URL / clave anon / project key).');
    }

    const status = getCloudStatusText();
    if (status) {
        return `${t('Connexion cloud impossible', 'Conexión nube imposible')}: ${status}`;
    }

    return t('Connexion cloud impossible. Vérifie réseau, URL Supabase et clé anon.', 'Conexión nube imposible. Verifica red, URL Supabase y clave anon.');
}

async function connectCloud(config, { silent = false } = {}) {
    if (!config?.url || !config?.anonKey || !config?.projectKey) {
        stopCloudAutoSync();
        if (cloudLogbookPushTimer) {
            clearTimeout(cloudLogbookPushTimer);
            cloudLogbookPushTimer = null;
        }
        unsubscribeCloudAuthSubscription();
        cloudClient = null;
        cloudConfig = null;
        cloudConnected = false;
        cloudAuthUser = null;
        maintenanceCloudHydratedOnce = false;
        navLogCloudHydratedOnce = false;
        cloudTableStatsRemoteCounts = null;
        cloudTableStatsLastRefreshAtMs = 0;
        updateCloudAuthUi();
        setCloudAuthStatus(t('Paramètres cloud incomplets (URL / clé anon / project key).', 'Parámetros nube incompletos (URL / clave anon / project key).'), true);
        if (!silent) setCloudStatus(t('Mode local (paramètres cloud incomplets)', 'Modo local (parámetros nube incompletos)'));
        return false;
    }

    try {
        const isSameConfig =
            !!cloudClient &&
            !!cloudConfig &&
            cloudConfig.url === config.url &&
            cloudConfig.anonKey === config.anonKey &&
            cloudConfig.projectKey === config.projectKey;

        if (!isSameConfig) {
            cloudResolvedProjectIdUuid = '';
            maintenanceCloudHydratedOnce = false;
            navLogCloudHydratedOnce = false;
            cloudTableStatsRemoteCounts = null;
            cloudTableStatsLastRefreshAtMs = 0;
        }

        if (!isSameConfig) {
            unsubscribeCloudAuthSubscription();

            cloudClient = createClient(config.url, config.anonKey, {
                auth: {
                    persistSession: true,
                    autoRefreshToken: true,
                    detectSessionInUrl: true,
                    storageKey: `ceibo-supabase-${config.projectKey}`
                }
            });

            cloudAuthSubscription = cloudClient.auth.onAuthStateChange((_event, session) => {
                cloudAuthUser = session?.user || null;
                void (async () => {
                    if (cloudAuthUser) {
                        await loadCloudUserProfile();
                        if (isCloudAdmin()) {
                            await fetchCloudManagedUsers();
                        } else {
                            cloudManagedUsers = [];
                        }
                    } else {
                        cloudUserProfile = null;
                        cloudManagedUsers = [];
                    }
                    updateCloudAuthUi();
                    await enforceCloudWhitelistForCurrentUser();
                    await applyAuthGateState({ clearWhenLocked: true });
                })();
            });
        }

        cloudConfig = config;
        saveCloudConfigToStorage(config);
        cloudConnected = true;
        await refreshCloudAuthSession();
        startCloudAutoSync();
        tryFlushPendingCloudLogbookPush();
        tryFlushPendingCloudDataPush();

        if (isCloudReady()) {
            const routes = await pullRoutesFromCloud({
                allowMaintenanceOverwrite: false,
                includeNavLog: false,
                includeEngineLog: false,
                includeWaypointPhotos: true
            });
            refreshSavedList();
            await importBundledDufourPolarProfilesIfNeeded();
            setCloudStatus(t(`Cloud connecté · ${routes.length} route(s) partagée(s)`, `Nube conectada · ${routes.length} ruta(s) compartida(s)`));
            refreshCloudSyncBadgeFromState();
            void refreshNavPublicTrackerShareStatus({ silent: true });
            if (activeCloudSubtab === 'stats') {
                void refreshCloudStatsTableCounts({ force: true });
            }
        } else {
            setCloudStatus(t('Cloud connecté · authentification requise pour la synchro. Mode local actif.', 'Nube conectada · autenticación requerida para la sincronización. Modo local activo.', 'Cloud connected · authentication required for sync. Local mode active.'));
        }

        return true;
    } catch (error) {
        stopCloudAutoSync();
        if (cloudLogbookPushTimer) {
            clearTimeout(cloudLogbookPushTimer);
            cloudLogbookPushTimer = null;
        }
        unsubscribeCloudAuthSubscription();
        cloudClient = null;
        cloudConfig = null;
        cloudConnected = false;
        cloudAuthUser = null;
        maintenanceCloudHydratedOnce = false;
        navLogCloudHydratedOnce = false;
        cloudTableStatsRemoteCounts = null;
        cloudTableStatsLastRefreshAtMs = 0;
        updateCloudAuthUi();
        setCloudAuthStatus(t(`Connexion cloud impossible: ${formatCloudError(error)}`, `Conexión nube imposible: ${formatCloudError(error)}`), true);
        setCloudStatus(t(`Connexion cloud impossible: ${formatCloudError(error)}`, `Conexión nube imposible: ${formatCloudError(error)}`), true);
        return false;
    }
}

function refreshSavedList() {
    const container = document.getElementById('savedRoutesList');
    if (!container) {
        renderVoyageAgendaPanel();
        return;
    }
    
    container.innerHTML = '';
    const saved = getSavedRoutes();
    
    if (saved.length === 0) {
        currentLoadedRouteIndex = -1;
        container.innerHTML = `<div style="padding:8px; opacity:0.7; font-size:12px;">${t('Aucune route sauvegardée', 'No hay rutas guardadas')}</div>`;
        updateRoutingTabAvailability();
        return;
    }

    const routesWithData = saved.map((route, index) => ({
        route,
        index,
        distance: getSavedRouteDistanceNm(route) || 0
    }));

    let filteredRoutes = routesWithData;
    if (routesViewportFilterEnabled && map && typeof map.getBounds === 'function') {
        const visibleBounds = map.getBounds();
        filteredRoutes = filteredRoutes.filter(item => isSavedRouteVisibleInCurrentMapZone(item.route, visibleBounds));
    }
    if (routesSearchTerm.trim()) {
        const searchLower = routesSearchTerm.toLowerCase().trim();
        filteredRoutes = filteredRoutes.filter(item =>
            String(item.route.name || '').toLowerCase().includes(searchLower)
        );
    }

    filteredRoutes.sort((a, b) => compareSavedRoutesByStartCoordinates(a.route, b.route, routesSortOrder));

    // Header with sortable column
    const header = document.createElement('div');
    header.className = 'routes-list-header';
    const sortIcon = routesSortOrder === 'asc' ? '▲' : '▼';
    header.innerHTML = `
        <div class="routes-header-sortable" id="routesHeaderName">${t('Départ GPS', 'Salida GPS', 'Start GPS')} ${sortIcon}</div>
        <div>${t('Distance', 'Distancia')}</div>
        <div></div>
    `;
    container.appendChild(header);

    // Add click handler for sorting
    const nameHeader = document.getElementById('routesHeaderName');
    if (nameHeader) {
        nameHeader.addEventListener('click', () => {
            routesSortOrder = routesSortOrder === 'asc' ? 'desc' : 'asc';
            refreshSavedList();
        });
    }

    if (filteredRoutes.length === 0) {
        container.innerHTML += `<div style="padding:8px; opacity:0.7; font-size:12px;">${t('Aucune route trouvée', 'No se encontraron rutas')}</div>`;
        updateRoutingTabAvailability();
        return;
    }

    filteredRoutes.forEach(({ route, index, distance }) => {
        const row = document.createElement('div');
        row.className = 'route-row';
        if (index === currentLoadedRouteIndex) {
            row.classList.add('route-row--active');
        }

        const btn = document.createElement('div');
        btn.className = 'route-summary-btn';
        const canDeleteRoute = isOwnedByCurrentCloudUser(route?.creatorEmail);
        const routeComment = getRouteExternalCommentByRouteId(route?.id);
        const hasRouteComment = !!String(routeComment?.contentText || '').trim() || !!String(routeComment?.contentHtml || '').trim();
        btn.innerHTML = `
            <div class="route-col route-col--with-meta" title="${escapeHtml(route.name)}">
                <div>${escapeHtml(route.name)}</div>
                ${hasRouteComment ? `<div class="route-col__tagline"><span class="route-comment-indicator" title="${t('Commentaire disponible', 'Comentario disponible', 'Comment available')}">${t('Commentaire', 'Comentario', 'Comment')}</span></div>` : ''}
            </div>
            <div class="route-col route-col--distance">${distance.toFixed(1)} NM</div>
            <div class="route-actions">
                <button type="button" class="route-action-btn route-action-btn--reroute" data-action="reroute" data-index="${index}" title="${t('Routage', 'Navegación')}">⛵</button>
                ${canDeleteRoute ? `<button type="button" class="route-action-btn route-action-btn--delete" data-action="delete" data-index="${index}" title="${t('Supprimer', 'Eliminar')}">🗑️</button>` : ''}
            </div>
        `;

        btn.addEventListener('click', async event => {
            const actionTarget = event.target.closest('[data-action]');
            const action = actionTarget?.dataset?.action;

            if (action === 'delete') {
                event.preventDefault();
                event.stopPropagation();
                deleteRoute(Number(actionTarget.dataset.index));
                return;
            }

            if (action === 'reroute') {
                event.preventDefault();
                event.stopPropagation();
                loadRoute(index);
                const routingTabBtn = document.getElementById('routingTabBtn');
                if (routingTabBtn) routingTabBtn.click();
                await computeRoute();
                return;
            }

            if (!action) {
                loadRoute(index);
            }
        });

        row.appendChild(btn);
        container.appendChild(row);
    });

    updateRoutingTabAvailability();
    renderVoyageAgendaPanel();
}

async function saveRoute() {
    if (routePoints.length === 0) return alert(t('Aucun waypoint à sauvegarder', 'No hay waypoints para guardar'));
    const nameInput = document.getElementById('routeNameInput');
    const rawName = (nameInput?.value || '').trim();
    if (!rawName) {
        return alert(t('Le nom de la route est obligatoire', 'El nombre de la ruta es obligatorio'));
    }

    const saved = [...getSavedRoutes()];
    const canonicalName = value => String(value || '').trim().toLowerCase();
    const name = rawName;
    const nameKey = canonicalName(name);
    const canUpdateLoadedRoute = Number.isInteger(currentLoadedRouteIndex)
        && currentLoadedRouteIndex >= 0
        && currentLoadedRouteIndex < saved.length;

    const targetIndexByName = saved.findIndex(route => canonicalName(route?.name) === nameKey);
    if (canUpdateLoadedRoute && targetIndexByName >= 0 && targetIndexByName !== currentLoadedRouteIndex) {
        alert(t('Une route avec ce nom existe deja.', 'Ya existe una ruta con este nombre.'));
        return;
    }

    // If a route is loaded, always edit that one first (including rename).
    let targetIndex = -1;
    if (canUpdateLoadedRoute) {
        targetIndex = currentLoadedRouteIndex;
    } else if (targetIndexByName >= 0) {
        targetIndex = targetIndexByName;
    }
    const shouldUpdateExisting = targetIndex >= 0;

    const planningValues = getRoutePlanningFormValues();
    const totalDistanceNm = getDraftRouteDistanceNm();

    const activePolarProfile = getActivePolarProfile();
    const payload = {
        id: shouldUpdateExisting && isUuidString(saved[targetIndex]?.id)
            ? String(saved[targetIndex].id)
            : generateClientUuid(),
        name,
        date: departureDate,
        time: departureTime,
        voyageName: planningValues.voyageName,
        voyageLeg: planningValues.voyageLeg,
        agendaDepartureDateTime: planningValues.agendaDepartureDateTime,
        agendaArrivalDateTime: planningValues.agendaArrivalDateTime,
        sharedWith: planningValues.sharedWith,
        agendaNotes: planningValues.agendaNotes,
        tackingTimeHours,
        polarProfileId: String(activePolarProfile?.id || ''),
        polarProfileName: String(activePolarProfile?.name || ''),
        points: routePoints.map(p => ({ lat: p.lat, lon: p.lng ?? p.lon })),
        createdAt: shouldUpdateExisting
            ? String(saved[targetIndex]?.createdAt || '')
            : new Date().toISOString(),
        updatedAt: new Date().toISOString()
    };

    // Add distance if calculated
    if (Number.isFinite(totalDistanceNm)) {
        payload.totalDistanceNm = totalDistanceNm;
    }

    const previousRoute = shouldUpdateExisting ? saved[targetIndex] : null;
    const previousName = String(previousRoute?.name || '').trim();
    const previousNameKey = canonicalName(previousName);
    const pointsEqual = (() => {
        if (!previousRoute) return false;
        const previousPoints = Array.isArray(previousRoute.points) ? previousRoute.points : [];
        const nextPoints = Array.isArray(payload.points) ? payload.points : [];
        if (previousPoints.length !== nextPoints.length) return false;
        for (let i = 0; i < previousPoints.length; i += 1) {
            const prevLat = Number(previousPoints[i]?.lat);
            const prevLon = Number(previousPoints[i]?.lon ?? previousPoints[i]?.lng);
            const nextLat = Number(nextPoints[i]?.lat);
            const nextLon = Number(nextPoints[i]?.lon ?? nextPoints[i]?.lng);
            if (!Number.isFinite(prevLat) || !Number.isFinite(prevLon) || !Number.isFinite(nextLat) || !Number.isFinite(nextLon)) {
                return false;
            }
            if (Math.abs(prevLat - nextLat) > 1e-7 || Math.abs(prevLon - nextLon) > 1e-7) {
                return false;
            }
        }
        return true;
    })();
    const metaEqual = previousRoute
        && String(previousRoute.date || '') === String(payload.date || '')
        && String(previousRoute.time || '') === String(payload.time || '')
        && String(previousRoute.voyageName || '') === String(payload.voyageName || '')
        && String(previousRoute.voyageLeg || '') === String(payload.voyageLeg || '')
        && String(previousRoute.agendaDepartureDateTime || '') === String(payload.agendaDepartureDateTime || '')
        && String(previousRoute.agendaArrivalDateTime || '') === String(payload.agendaArrivalDateTime || '')
        && String(previousRoute.sharedWith || '') === String(payload.sharedWith || '')
        && String(previousRoute.agendaNotes || '') === String(payload.agendaNotes || '')
        && Number(previousRoute.tackingTimeHours) === Number(payload.tackingTimeHours)
        && Number(previousRoute.totalDistanceNm ?? NaN) === Number(payload.totalDistanceNm ?? NaN)
        && String(previousRoute.polarProfileId || '') === String(payload.polarProfileId || '');
    const isSimpleRenameOnly = shouldUpdateExisting
        && pointsEqual
        && !!metaEqual
        && previousNameKey
        && previousNameKey !== nameKey;

    if (shouldUpdateExisting) {
        const withCreator = ensureCreatorOnEditedRecord(payload);
        saved[targetIndex] = {
            ...saved[targetIndex],
            ...withCreator
        };
        currentLoadedRouteIndex = targetIndex;
    } else {
        saved.push(addCreatorToNewRecord(payload));
        currentLoadedRouteIndex = saved.length - 1;
    }

    setSavedRoutes(saved);
    updateRoutingActiveRouteDisplay();
    routesCloudDirty = true;
    updateCloudDataSourceStatus('local (non synchronisé)', saved.length, waypointPhotoEntries.length);

    // Immediate validation for the user: local write is done.
    alert(shouldUpdateExisting
        ? t(`Route mise à jour: ${name}`, `Ruta actualizada: ${name}`)
        : t(`Route sauvegardée: ${name}`, `Ruta guardada: ${name}`));

    refreshSavedList();
    updateVoyagePlanningSummary(payload);

    if (isCloudReady()) {
        setCloudStatus(t('Sauvegarde locale OK, synchro cloud en cours...', 'Guardado local OK, sincronización nube en curso...'));
        void (async () => {
            try {
                const renamedInCloud = isSimpleRenameOnly
                    ? await renameRouteInCloudByName(previousName, name)
                    : false;

                if (!renamedInCloud) {
                    await pushRoutesToCloud({
                        includeEngineLog: false,
                        includeWaypointPhotos: false,
                        includeMaintenanceBoards: false
                    });
                }
                setCloudStatus(t(`Cloud synchronisé · ${saved.length} route(s)`, `Nube sincronizada · ${saved.length} ruta(s)`));
                updateCloudDataSourceStatus('cloud', saved.length, waypointPhotoEntries.length);
            } catch (error) {
                setCloudStatus(t(`Sauvegarde locale OK, synchro cloud échouée: ${formatCloudError(error)}`, `Guardado local OK, sincronización nube fallida: ${formatCloudError(error)}`), true);
                updateCloudDataSourceStatus('cache local (synchro en échec)', saved.length, waypointPhotoEntries.length);
            }
        })();
    }
}

function saveRouteFromRouting() {
    const nameInput = document.getElementById('routeNameInput');
    if (!nameInput) {
        void saveRoute();
        return;
    }

    const currentName = String(nameInput.value || '').trim();
    const saved = getSavedRoutes();
    const hasLoaded = Number.isInteger(currentLoadedRouteIndex)
        && currentLoadedRouteIndex >= 0
        && currentLoadedRouteIndex < saved.length;
    if (hasLoaded) {
        const loadedRoute = saved[currentLoadedRouteIndex] || null;
        if (!isOwnedByCurrentCloudUser(loadedRoute?.creatorEmail)) {
            alert(t('Tu peux consulter cette route mais pas la modifier.', 'Puedes consultar esta ruta pero no modificarla.', 'You can view this route but cannot modify it.'));
            return;
        }
    }

    if (!currentName) {
        const suggestedName = hasLoadedRouteSelection()
            ? String(saved[currentLoadedRouteIndex]?.name || '').trim()
            : '';
        const promptedName = window.prompt(
            t('Nom de la route a sauvegarder:', 'Nombre de la ruta a guardar:', 'Route name to save:'),
            suggestedName || ''
        );

        if (promptedName === null) return;

        const trimmedName = String(promptedName || '').trim();
        if (!trimmedName) {
            alert(t('Le nom de la route est obligatoire', 'El nombre de la ruta es obligatorio', 'Route name is required'));
            return;
        }

        nameInput.value = trimmedName;
        updateRoutingActiveRouteDisplay();
    }

    void saveRoute();
}

function clearCurrentRoute() {
    // remove markers
    markers.forEach(m => map.removeLayer(m));
    markers = [];
    routePoints = [];
    selectedUserWaypointIndex = -1;
    currentLoadedRouteIndex = -1;
    waypointPassageSlots.clear();
    lastRouteBounds = null;
    lastComputedReportData = null;
    clearWaypointWindDirectionLayers();
    clearWaveDirectionSegmentLayers();
    clearGeneratedWaypointMarkers();
    clearArrivalPoiMarkers();
    if (routeLayer) { map.removeLayer(routeLayer); routeLayer = null; }
    const weatherContainer = document.getElementById('waypointWeatherInfo');
    if (weatherContainer) weatherContainer.innerHTML = '';
    const windLegend = document.getElementById('windSpeedLegend');
    if (windLegend) windLegend.innerHTML = '';
    invalidateAiRouteAnalysisState();
    const arrivalSummary = document.getElementById('arrivalSummary');
    if (arrivalSummary) arrivalSummary.textContent = t('Analyse mouillage: en attente', 'Análisis fondeo: en espera');
    const anchorageContainer = document.getElementById('anchorageRecommendations');
    if (anchorageContainer) anchorageContainer.innerHTML = '';
    const restaurants = document.getElementById('nearbyRestaurants');
    if (restaurants) restaurants.innerHTML = '';
    const shops = document.getElementById('nearbyShops');
    if (shops) shops.innerHTML = '';
    updateRoutingActiveRouteDisplay();
    updateSelectedWaypointInfo();
    updateRoutingTabAvailability();
    clearRouteLlmGuide();
}

function reverseCurrentRoute() {
    if (!Array.isArray(routePoints) || routePoints.length < 2) {
        alert(t(
            'Il faut au moins 2 waypoints pour créer une route retour',
            'Se necesitan al menos 2 waypoints para crear una ruta de retorno'
        ));
        return;
    }

    const reversedPoints = routePoints
        .slice()
        .reverse()
        .map(point => ({ lat: Number(point.lat), lng: Number(point.lng ?? point.lon) }))
        .filter(point => Number.isFinite(point.lat) && Number.isFinite(point.lng));

    if (reversedPoints.length < 2) {
        alert(t(
            'Impossible d\'inverser cette route (waypoints invalides)',
            'No se puede invertir esta ruta (waypoints no válidos)'
        ));
        return;
    }

    markers.forEach(marker => {
        if (marker && map?.hasLayer(marker)) {
            map.removeLayer(marker);
        }
    });
    markers = [];
    routePoints = [];
    selectedUserWaypointIndex = -1;

    reversedPoints.forEach(point => {
        addUserWaypoint(L.latLng(point.lat, point.lng), { select: false, invalidate: false });
    });

    const routeNameInput = document.getElementById('routeNameInput');
    if (routeNameInput) {
        const baseName = String(routeNameInput.value || '').trim();
        if (!baseName) {
            routeNameInput.value = t('Route RETOUR', 'Ruta RETOUR');
        } else if (!/\bretour\b/i.test(baseName)) {
            routeNameInput.value = `${baseName} RETOUR`;
        }
    }

    updateRoutingActiveRouteDisplay();

    invalidateComputedRouteDisplay();
    drawRoute(routePoints);
    updateSelectedWaypointInfo();
}

function loadRoute(index) {
    const saved = getSavedRoutes();
    if (!saved || !saved[index]) return alert(t('Aucune route sélectionnée', 'Ninguna ruta seleccionada'));
    const r = saved[index];

    const normalizedPoints = (Array.isArray(r?.points) ? r.points : [])
        .map(pt => ({
            lat: Number(pt?.lat),
            lon: Number(pt?.lon ?? pt?.lng)
        }))
        .filter(pt => Number.isFinite(pt.lat) && Number.isFinite(pt.lon));

    if (normalizedPoints.length === 0) {
        alert(t('Impossible de charger cette route: aucun waypoint valide.', 'No se puede cargar esta ruta: no hay waypoints válidos.'));
        return;
    }

    clearCurrentRoute();
    waypointPassageSlots.clear();
    lastRouteBounds = null;

    normalizedPoints.forEach(pt => {
        const lat = pt.lat;
        const lon = pt.lon;
        const marker = createWaypointMarker([lat, lon]);
        markers.push(marker);
        routePoints.push(marker.getLatLng());
    });

    selectedUserWaypointIndex = -1;
    currentLoadedRouteIndex = index;
    updateSelectedWaypointInfo();

    const nameInput = document.getElementById('routeNameInput');
    if (nameInput) nameInput.value = r.name || '';
    applyRoutePlanningForm(r);
    const routeComment = getRouteExternalCommentByRouteId(r.id);
    setRouteCommentEditorHtml(routeComment?.contentHtml || '');
    setRouteCommentPanelOpen(false);
    setRouteCommentStatus(
        routeComment?.contentHtml
            ? t('Commentaire externe chargé pour cette route.', 'Comentario externo cargado para esta ruta.', 'External comment loaded for this route.')
            : t('Aucun commentaire externe enregistré pour cette route.', 'No hay comentario externo guardado para esta ruta.', 'No external comment saved for this route.')
    );
    if (r?.polarProfileId) {
        setActivePolarProfile(String(r.polarProfileId), { persist: true, syncEditor: true });
    }
    updateRoutingActiveRouteDisplay();
    updateVoyagePlanningSummary(r);

    // restore UI values (keep current selected date)
    departureTime = normalizeHourTime(r.time);
    updateDepartureDateTimeInput();
    tackingTimeHours = r.tackingTimeHours;

    // draw polyline between waypoints
    drawRoute(routePoints);

    // Auto-zoom on loaded route
    if (routePoints.length > 0) {
        const bounds = L.latLngBounds(routePoints);
        if (bounds.isValid()) {
            map.fitBounds(bounds, {
                padding: [50, 50],
                maxZoom: 12,
                animate: true,
                duration: 0.5
            });
        } else {
            map.setView(routePoints[0], Math.max(map.getZoom(), 10));
        }
    }

    updateRoutingTabAvailability();
    isRouteGuideDockVisible = true;
    updateMapWorkspaceLayoutState();
    setRouteLlmGuideStatus(t(`Route sélectionnée: ${String(r?.name || '').trim() || t('sans nom', 'sin nombre', 'unnamed')}. Copie le prompt LLM ou importe directement une réponse du presse-papiers.`, `Ruta seleccionada: ${String(r?.name || '').trim() || t('sin nombre', 'sin nombre', 'unnamed')}. Copia el prompt LLM o importa directamente una respuesta del portapapeles.`, `Selected route: ${String(r?.name || '').trim() || t('unnamed', 'sin nombre', 'unnamed')}. Copy the LLM prompt or import a clipboard response directly.`));
    setRouteLlmGuideAnswer(t('La route est chargée. Le guide IA peut maintenant la relire et suggérer de beaux arrêts proches.', 'La ruta esta cargada. La guia IA puede revisarla y sugerir paradas bonitas cercanas.', 'The route is loaded. The AI guide can now review it and suggest nearby beautiful stops.'));
}

function deleteRoute(index) {
    const saved = [...getSavedRoutes()];
    if (!saved || !saved[index]) return;
    const routeId = String(saved[index]?.id || '').trim();
    saved.splice(index, 1);

    if (currentLoadedRouteIndex === index) {
        currentLoadedRouteIndex = -1;
    } else if (currentLoadedRouteIndex > index) {
        currentLoadedRouteIndex -= 1;
    }

    setSavedRoutes(saved);
    if (routeId) {
        removeRouteExternalCommentByRouteId(routeId);
        routeCommentsCloudDirty = true;
    }
    routesCloudDirty = true;
    updateCloudDataSourceStatus('local (non synchronisé)', saved.length, waypointPhotoEntries.length);

    const finalize = () => refreshSavedList();
    if (isCloudReady()) {
        pushRoutesToCloud({
            includeEngineLog: false,
            includeWaypointPhotos: false,
            includeMaintenanceBoards: false
        })
            .then(() => setCloudStatus(t(`Cloud synchronisé · ${saved.length} route(s)`, `Nube sincronizada · ${saved.length} ruta(s)`)))
            .catch(error => setCloudStatus(t(`Suppression locale OK, synchro cloud échouée: ${formatCloudError(error)}`, `Eliminación local OK, sincronización nube fallida: ${formatCloudError(error)}`), true))
            .finally(finalize);
        return;
    }

    finalize();
}

function sanitizeExportFileNamePart(value, fallback = 'ceibo-export') {
    const cleaned = String(value || '')
        .trim()
        .replace(/[^a-z0-9_-]+/gi, '_')
        .replace(/^_+|_+$/g, '');
    return cleaned || fallback;
}

function downloadTextFile(content, mimeType, fileName) {
    const blob = new Blob([String(content || '')], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
}

function buildRoutesImportExportBundle() {
    return {
        type: 'ceibo-routes-voyages-waypoints-bundle',
        schemaVersion: 1,
        appBuildVersion: APP_BUILD_VERSION,
        exportedAt: new Date().toISOString(),
        routes: getSavedRoutes(),
        voyages: Array.isArray(voyagePlans) ? voyagePlans : [],
        waypoints: Array.isArray(waypointPhotoEntries) ? waypointPhotoEntries : []
    };
}

function exportRoutesVoyagesWaypointsJson() {
    const payload = buildRoutesImportExportBundle();
    const totalEntries = payload.routes.length + payload.voyages.length + payload.waypoints.length;
    if (totalEntries === 0) {
        alert(t('Aucune donnée à exporter.', 'No hay datos para exportar.', 'No data to export.'));
        return false;
    }

    const exportDate = String(payload.exportedAt || '').slice(0, 10) || new Date().toISOString().slice(0, 10);
    const fileName = `${sanitizeExportFileNamePart(`ceibo_routes_voyages_waypoints_${exportDate}`, 'ceibo_routes_voyages_waypoints')}.json`;
    downloadTextFile(JSON.stringify(payload, null, 2), 'application/json', fileName);
    return true;
}

function escapeXml(value) {
    return String(value)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;')
        .replaceAll("'", '&apos;');
}

function routeToGpx(route) {
    const routeName = escapeXml(route.name || 'Route');
    const points = (route.points || [])
        .map(pt => {
            const lat = Number(pt.lat);
            const lon = Number(pt.lon ?? pt.lng);
            if (!Number.isFinite(lat) || !Number.isFinite(lon)) return '';
            return `    <rtept lat="${lat}" lon="${lon}"></rtept>`;
        })
        .filter(Boolean)
        .join('\n');

    return `<?xml version="1.0" encoding="UTF-8"?>\n<gpx version="1.1" creator="CEIBO Router" xmlns="http://www.topografix.com/GPX/1/1">\n  <metadata>\n    <name>${routeName}</name>\n  </metadata>\n  <rte>\n    <name>${routeName}</name>\n${points}\n  </rte>\n</gpx>`;
}

function exportRouteGpx(index) {
    const saved = getSavedRoutes();
    if (!saved || !saved[index]) return alert(t('Aucune route sélectionnée', 'Ninguna ruta seleccionada'));

    const gpx = routeToGpx(saved[index]);
    downloadTextFile(gpx, 'application/gpx+xml', `${sanitizeExportFileNamePart(saved[index].name, 'route')}.gpx`);
}

function parseGpxToRoute(gpxText, fileName = 'Route importée') {
    const parser = new DOMParser();
    const xml = parser.parseFromString(gpxText, 'application/xml');
    const parserError = xml.querySelector('parsererror');
    if (parserError) throw new Error('GPX invalide');

    const routeNameNode =
        xml.querySelector('metadata > name') ||
        xml.querySelector('rte > name') ||
        xml.querySelector('trk > name');

    const routeName = routeNameNode?.textContent?.trim() || fileName.replace(/\.gpx$/i, '');

    const rtePts = Array.from(xml.getElementsByTagName('rtept'));
    const trkPts = Array.from(xml.getElementsByTagName('trkpt'));
    const wpts = Array.from(xml.getElementsByTagName('wpt'));
    const pointNodes = rtePts.length ? rtePts : (trkPts.length ? trkPts : wpts);

    const points = pointNodes
        .map(node => ({
            lat: Number(node.getAttribute('lat')),
            lon: Number(node.getAttribute('lon'))
        }))
        .filter(pt => Number.isFinite(pt.lat) && Number.isFinite(pt.lon));

    if (points.length === 0) throw new Error('Aucun point GPX trouvé');

    return {
        name: routeName,
        date: departureDate,
        time: departureTime,
        voyageName: '',
        voyageLeg: '',
        agendaDepartureDateTime: '',
        agendaArrivalDateTime: '',
        sharedWith: '',
        agendaNotes: '',
        tackingTimeHours,
        points,
        createdAt: new Date().toISOString()
    };
}

function isRoutesImportExportBundle(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
    if (String(value.type || '').trim() === 'ceibo-routes-voyages-waypoints-bundle') return true;
    return Array.isArray(value.routes) || Array.isArray(value.voyages) || Array.isArray(value.waypoints);
}

function prepareImportedRoutes(routesToImport, existingRoutes = []) {
    const existingIds = new Set((Array.isArray(existingRoutes) ? existingRoutes : []).map(route => String(route?.id || '').trim()).filter(Boolean));
    const seenImportedIds = new Set();
    const routeIdMap = new Map();
    const routes = (Array.isArray(routesToImport) ? routesToImport : []).map((route, index) => {
        const safeRoute = sanitizeSavedRoute(route, index);
        const originalId = String(route?.id || safeRoute.id || '').trim();
        let nextId = String(safeRoute.id || '').trim();
        if (!nextId || existingIds.has(nextId) || seenImportedIds.has(nextId)) {
            nextId = generateClientUuid();
        }
        existingIds.add(nextId);
        seenImportedIds.add(nextId);
        if (originalId && originalId !== nextId) {
            routeIdMap.set(originalId, nextId);
        }
        return nextId === safeRoute.id ? safeRoute : { ...safeRoute, id: nextId };
    });

    return { routes, routeIdMap };
}

function prepareImportedWaypointEntries(entriesToImport, existingEntries = []) {
    const existingIds = new Set((Array.isArray(existingEntries) ? existingEntries : []).map(entry => String(entry?.id || '').trim()).filter(Boolean));
    const seenImportedIds = new Set();
    const waypointIdMap = new Map();
    const waypoints = (Array.isArray(entriesToImport) ? entriesToImport : [])
        .map(normalizeWaypointPhotoEntry)
        .filter(Boolean)
        .map(entry => {
            const originalId = String(entry?.id || '').trim();
            let nextId = originalId;
            if (!nextId || existingIds.has(nextId) || seenImportedIds.has(nextId)) {
                nextId = generateClientUuid();
            }
            existingIds.add(nextId);
            seenImportedIds.add(nextId);
            if (originalId && originalId !== nextId) {
                waypointIdMap.set(originalId, nextId);
            }
            return nextId === originalId ? entry : { ...entry, id: nextId };
        });

    return { waypoints, waypointIdMap };
}

function prepareImportedVoyagePlans(plansToImport, existingPlans = [], routeIdMap = new Map(), waypointIdMap = new Map()) {
    const existingPlanIds = new Set((Array.isArray(existingPlans) ? existingPlans : []).map(plan => String(plan?.id || '').trim()).filter(Boolean));
    return (Array.isArray(plansToImport) ? plansToImport : []).map((plan, index) => {
        const safePlan = sanitizeVoyagePlan(plan, index);
        let nextPlanId = String(safePlan.id || '').trim();
        if (!nextPlanId || existingPlanIds.has(nextPlanId)) {
            nextPlanId = generateClientUuid();
        }
        existingPlanIds.add(nextPlanId);

        const seenItemIds = new Set();
        const nextItems = safePlan.items.map((item, itemIndex) => {
            const safeItem = sanitizeVoyagePlanItem(item, itemIndex);
            let nextItemId = String(safeItem.id || '').trim();
            if (!nextItemId || seenItemIds.has(nextItemId)) {
                nextItemId = generateClientUuid();
            }
            seenItemIds.add(nextItemId);

            return {
                ...safeItem,
                id: nextItemId,
                routeId: safeItem.type === 'route'
                    ? String(routeIdMap.get(String(safeItem.routeId || '').trim()) || safeItem.routeId || '').trim()
                    : '',
                waypointPhotoId: safeItem.type === 'stop'
                    ? String(waypointIdMap.get(String(safeItem.waypointPhotoId || '').trim()) || safeItem.waypointPhotoId || '').trim()
                    : ''
            };
        });

        return { ...safePlan, id: nextPlanId, items: nextItems };
    });
}

async function importRoutesVoyagesWaypointsBundle(bundle) {
    const importedRoutesSource = Array.isArray(bundle?.routes) ? bundle.routes : [];
    const importedVoyagesSource = Array.isArray(bundle?.voyages) ? bundle.voyages : [];
    const importedWaypointsSource = Array.isArray(bundle?.waypoints) ? bundle.waypoints : [];

    const { routes: importedRoutes, routeIdMap } = prepareImportedRoutes(importedRoutesSource, getSavedRoutes());
    const { waypoints: importedWaypoints, waypointIdMap } = prepareImportedWaypointEntries(importedWaypointsSource, waypointPhotoEntries);
    const importedVoyages = prepareImportedVoyagePlans(importedVoyagesSource, voyagePlans, routeIdMap, waypointIdMap);

    if (importedRoutes.length > 0) {
        setSavedRoutes(getSavedRoutes().concat(importedRoutes));
    }
    if (importedWaypoints.length > 0) {
        setWaypointPhotoEntries(waypointPhotoEntries.concat(importedWaypoints), { refreshUi: false });
    }
    if (importedVoyages.length > 0) {
        setVoyagePlans(voyagePlans.concat(importedVoyages), { persistLocal: true, markCloudDirty: true });
    }

    if (importedRoutes.length > 0 || importedWaypoints.length > 0 || importedVoyages.length > 0) {
        routesCloudDirty = true;
    }

    refreshSavedList();
    renderVoyageAgendaPanel();
    updateVoyagePlanningSummary();
    updateRoutingTabAvailability();
    updateCloudDataSourceStatus('local (non synchronisé)', getSavedRoutes().length, waypointPhotoEntries.length);

    if (isCloudReady()) {
        await pushRoutesToCloud({
            includeEngineLog: false,
            includeWaypointPhotos: importedWaypoints.length > 0,
            includeMaintenanceBoards: false,
            includeArrivalAnalyses: false,
            includeAgendaEvents: false,
            includeVoyagePlans: importedVoyages.length > 0,
            includeCrewDirectory: false
        });
        setCloudStatus(t(
            `Cloud synchronisé · ${getSavedRoutes().length} route(s) · ${voyagePlans.length} voyage(s) · ${waypointPhotoEntries.length} waypoint(s)`,
            `Nube sincronizada · ${getSavedRoutes().length} ruta(s) · ${voyagePlans.length} viaje(s) · ${waypointPhotoEntries.length} waypoint(s)`,
            `Cloud synced · ${getSavedRoutes().length} route(s) · ${voyagePlans.length} trip(s) · ${waypointPhotoEntries.length} waypoint(s)`
        ));
        updateCloudDataSourceStatus('cloud', getSavedRoutes().length, waypointPhotoEntries.length);
    }

    return {
        routes: importedRoutes.length,
        voyages: importedVoyages.length,
        waypoints: importedWaypoints.length
    };
}

function handleImport(e) {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async function(evt) {
        try {
            const content = String(evt.target.result || '');
            const isLikelyGpx = file.name.toLowerCase().endsWith('.gpx') || content.trim().startsWith('<');

            if (isLikelyGpx) {
                const saved = [...getSavedRoutes()];
                const route = parseGpxToRoute(content, file.name);
                saved.push(route);
                setSavedRoutes(saved);
                routesCloudDirty = true;
            } else {
                const obj = JSON.parse(content);
                if (isRoutesImportExportBundle(obj)) {
                    const importedCounts = await importRoutesVoyagesWaypointsBundle(obj);
                    alert(t(
                        `Import OK: ${importedCounts.routes} route(s), ${importedCounts.voyages} voyage(s), ${importedCounts.waypoints} waypoint(s).`,
                        `Importación OK: ${importedCounts.routes} ruta(s), ${importedCounts.voyages} viaje(s), ${importedCounts.waypoints} waypoint(s).`,
                        `Import OK: ${importedCounts.routes} route(s), ${importedCounts.voyages} trip(s), ${importedCounts.waypoints} waypoint(s).`
                    ));
                    return;
                } else {
                    const saved = [...getSavedRoutes()];
                    if (Array.isArray(obj)) {
                        obj.forEach(o => saved.push(o));
                    } else {
                        saved.push(obj);
                    }
                    setSavedRoutes(saved);
                    routesCloudDirty = true;
                }
            }

            if (isCloudReady()) {
                try {
                    await pushRoutesToCloud({
                        includeEngineLog: false,
                        includeWaypointPhotos: false,
                        includeMaintenanceBoards: false,
                        includeArrivalAnalyses: false,
                        includeAgendaEvents: false,
                        includeVoyagePlans: false,
                        includeCrewDirectory: false
                    });
                    setCloudStatus(t(`Cloud synchronisé · ${getSavedRoutes().length} route(s)`, `Nube sincronizada · ${getSavedRoutes().length} ruta(s)`));
                    updateCloudDataSourceStatus('cloud', getSavedRoutes().length, waypointPhotoEntries.length);
                } catch (error) {
                    setCloudStatus(t(`Import local OK, synchro cloud échouée: ${formatCloudError(error)}`, `Importación local OK, sincronización nube fallida: ${formatCloudError(error)}`), true);
                    updateCloudDataSourceStatus('cache local (synchro en échec)', getSavedRoutes().length, waypointPhotoEntries.length);
                }
            } else {
                updateCloudDataSourceStatus('local (non synchronisé)', getSavedRoutes().length, waypointPhotoEntries.length);
            }
            refreshSavedList();
            updateRoutingTabAvailability();
            alert(t('Import OK', 'Importación OK'));
        } catch (err) {
            const message = String(err?.message || '').trim();
            const looksLikeFormatError = !message
                || message.includes('GPX invalide')
                || message.includes('Aucun point GPX trouvé')
                || message.includes('Unexpected token');
            if (looksLikeFormatError) {
                alert(t('Fichier JSON/GPX invalide', 'Archivo JSON/GPX inválido'));
            } else {
                alert(t(`Import impossible: ${message}`, `Importación imposible: ${message}`, `Import failed: ${message}`));
            }
        }
        finally {
            if (e?.target) e.target.value = '';
        }
    };
    reader.readAsText(file);
}